/*
  Diseases section data.

  This is a SEPARATE feature from Disease Walkthrough (data/walkthrough/*.js) and
  from the per-lecture Learn/Test/Apply objectives in data/*.js. Where those are
  organized by learning objective or by walkthrough case, this catalog is organized
  disease-first: lecture -> disease -> reference content + a comprehensive question
  bank, so a student can track exactly how much of a single disease they've mastered.

  Shape per disease (only `id`, `name`, and `blurb` are filled in for now):
    id:        lowercase-dash, STABLE once questions/progress exist against it
    name:      display name
    blurb:     one-line identifying summary (shown on the disease picker card)
    sections:  [] -- rich reference content, added lecture-by-lecture
    questions: [] -- { prompt, choices, correct, explanation } comprehensive MC bank,
               added lecture-by-lecture once that lecture's sections are written

  Every disease below was confirmed against the actual lecture slides and the
  course's official learning objectives -- nothing here is invented. A disease that
  is AIDS-defining but already has a full card elsewhere (e.g. Toxoplasmosis, MAC)
  is NOT duplicated under HIV and AIDS; only diseases with no existing card live there.
*/
(function () {
  "use strict";

  // Content helpers -- keep authored HTML consistent with the existing
  // Learn-card visual language (.learn-table, .box-hy, .box-mnemonic).
  function Tbl(headers, rows) {
    return '<table class="learn-table"><tr>' + headers.map(function (h) { return "<th>" + h + "</th>"; }).join("") + "</tr>" + rows.map(function (row) { return "<tr>" + row.map(function (cell) { return "<td>" + cell + "</td>"; }).join("") + "</tr>"; }).join("") + "</table>";
  }
  function HY(text) { return '<div class="box-hy"><span class="lbl">High yield</span><strong>' + text + "</strong></div>"; }
  function Mn(label, text) { return '<div class="box-mnemonic"><span class="lbl">' + label + '</span><strong>' + text + "</strong></div>"; }
  function S(id, title, html) { return { id: id, title: title, html: html }; }
  function Q(section, prompt, choices, correct, explanation) {
    return { section: section, prompt: prompt, choices: choices, correct: correct, explanation: explanation };
  }

  function D(id, name, blurb, sections, questions) {
    var withIds = (questions || []).map(function (question, index) {
      return { id: id + "|" + index, section: question.section, prompt: question.prompt, choices: question.choices, correct: question.correct, explanation: question.explanation };
    });
    return { id: id, name: name, blurb: blurb, sections: sections || [], questions: withIds };
  }
  function L(id, title, diseases) {
    return { id: id, title: title, diseases: diseases };
  }

  window.DISEASES = {
    lectures: [
      L("germs-and-worms", "Germs and Worms", [
        D("staph-aureus", "Staphylococcus aureus (incl. MRSA)", "Coagulase-positive gram-positive cocci causing skin/soft tissue, cardiopulmonary, and musculoskeletal infections; MRSA needs non-beta-lactam oral options.", [
          S("overview", "Organism & Colonization", Tbl(["", ""], [
            ["Organism", "Gram-positive coccus. The only <strong>coagulase-POSITIVE</strong> staphylococcus -- this is what separates it from S. epidermidis and S. saprophyticus (both coagulase-negative)"],
            ["Colonization", "Anterior nares of ~30% of healthy adults; skin of ~20%"]
          ]) + HY("Coagulase status is THE lab test that separates S. aureus from the coagulase-negative staphylococci.")),
          S("presentation", "Clinical Presentation by System", Tbl(["System", "Infections"], [
            ["Skin", "Purulent cellulitis, surgical wound infection (onset within 48 hours), impetigo, abscesses, folliculitis, furuncle/carbuncle, toxic shock syndrome, staphylococcal scalded skin syndrome, IV catheter infection, hidradenitis suppurativa, mastitis"],
            ["Cardiopulmonary", "Staphylococcal pneumonia (risk of empyema), infective endocarditis"],
            ["CNS", "Meningitis, brain abscess, epidural abscess"],
            ["Musculoskeletal", "Osteomyelitis, septic arthritis, prosthetic joint infection"],
            ["GI", "Staphylococcal enterotoxin B food poisoning"]
          ]) + HY("Surgical wound infection with onset within 48 hours is a classic S. aureus clue.")),
          S("diagnosis-treatment", "Diagnosis & Treatment", "<p>Culture specimens should be obtained <strong>before</strong> starting or altering antibiotics. Antibiotic choice/dose depends on site of infection, severity, and organism sensitivity.</p>"),
          S("mrsa", "MRSA (Methicillin-Resistant S. aureus)", "<p>Multi-drug-resistant strain, first described in 1961 after methicillin's introduction. <strong>~7% of the US population is colonized</strong>. Colonization <strong>increases risk of staphylococcal infection following invasive medical or surgical procedures</strong>; hospitals may screen with a nasal swab.</p>" + Tbl(["Setting", "Options"], [
            ["Oral -- mild/moderate infection", "TMP-SMX, Clindamycin, Doxycycline, Minocycline"],
            ["Parenteral -- moderate/severe infection", "Vancomycin, Linezolid/Tedizolid, Daptomycin"]
          ]) + Mn("Abscess rule", "If an abscess is present, it should ideally be incised and drained (I&D) regardless of antibiotic choice."))
        ], [
          Q("overview", "What lab feature distinguishes Staphylococcus aureus from S. epidermidis and S. saprophyticus?", ["S. aureus is coagulase-positive; the other two are coagulase-negative", "S. aureus is gram-negative; the other two are gram-positive", "S. aureus grows anaerobically only", "S. aureus lacks a cell wall"], 0, "The coagulase test is the key distinguishing feature: only S. aureus is coagulase-positive."),
          Q("overview", "Approximately what proportion of healthy adults carry S. aureus in the anterior nares?", ["~30%", "~90%", "~5%", "Essentially 0%"], 0, "Staphylococci are carried in the anterior nares of about 30% of healthy adults and on the skin of about 20%."),
          Q("presentation", "A surgical wound infection caused by Staphylococcus aureus classically develops within what timeframe after the procedure?", ["48 hours", "5-7 days", "2-3 weeks", "Onset is never before 1 month"], 0, "S. aureus surgical wound infections classically present within 48 hours of the procedure -- a fast onset that helps distinguish it from other causes of post-surgical infection."),
          Q("presentation", "Which of the following is a musculoskeletal manifestation of S. aureus infection?", ["Osteomyelitis and septic arthritis", "Erythema migrans", "Lockjaw", "Ground itch"], 0, "S. aureus is a major cause of osteomyelitis, septic arthritis, and prosthetic joint infections."),
          Q("diagnosis-treatment", "When should culture specimens be obtained relative to starting antibiotics for a suspected S. aureus infection?", ["Before starting or altering the antibiotic regimen", "Only after 3 days of empiric therapy", "Antibiotics should never be delayed for cultures", "Cultures are not useful for staphylococcal infections"], 0, "Culture specimens should be obtained before starting or altering antibiotics whenever possible."),
          Q("mrsa", "Approximately what percentage of the US population is colonized with MRSA?", ["~7%", "~50%", "~1%", "~25%"], 0, "About 7% of the US population is colonized with MRSA."),
          Q("mrsa", "MRSA colonization specifically increases the risk of staphylococcal infection in which setting?", ["Following invasive medical or surgical procedures", "During normal, uncomplicated pregnancy", "Only in patients with no healthcare exposure", "Only in outdoor recreational settings"], 0, "MRSA colonization increases the risk of staphylococcal infection following invasive medical or surgical procedures."),
          Q("mrsa", "Which of the following is an appropriate ORAL option for a mild-moderate MRSA skin infection?", ["Trimethoprim-sulfamethoxazole", "Vancomycin", "Daptomycin", "Ceftriaxone"], 0, "TMP-SMX, clindamycin, doxycycline, and minocycline are the oral options for mild-moderate MRSA infections; vancomycin/linezolid/daptomycin are reserved for moderate-severe (parenteral) disease."),
          Q("mrsa", "A patient has a fluctuant MRSA skin abscess. In addition to antibiotics, what procedure should ideally be performed?", ["Incision and drainage (I&D)", "Emergent surgical debridement of muscle", "Amputation", "No procedure -- antibiotics alone are sufficient"], 0, "If an abscess is present, it should ideally be incised and drained in addition to appropriate antibiotic therapy.")
        ]),

        D("staph-epidermidis", "Staphylococcus epidermidis", "Coagulase-negative skin flora that turns pathogenic on prosthetic joints, valves, and central lines.", [
          S("overview", "Overview", "<p>Coagulase-negative staphylococcus. Classically associated with <strong>IV catheter infections</strong> -- it is normal skin flora that becomes pathogenic when introduced onto indwelling devices/lines.</p>")
        ], [
          Q("overview", "Staphylococcus epidermidis is classically associated with which type of infection?", ["IV catheter infections", "UTI in young women", "Bacillary dysentery", "Rheumatic fever"], 0, "S. epidermidis, a coagulase-negative staphylococcus, is classically associated with IV catheter infections."),
          Q("overview", "Is Staphylococcus epidermidis coagulase-positive or coagulase-negative?", ["Coagulase-negative", "Coagulase-positive", "It varies by strain", "Coagulase status is not applicable to this organism"], 0, "S. epidermidis is coagulase-negative, distinguishing it from S. aureus.")
        ]),

        D("staph-saprophyticus", "Staphylococcus saprophyticus", "Coagulase-negative staph classically causing UTIs in young, sexually active women.", [
          S("overview", "Overview", "<p>Coagulase-negative staphylococcus. Classically associated with <strong>urinary tract infection in women</strong>.</p>")
        ], [
          Q("overview", "Staphylococcus saprophyticus is a classic cause of which condition?", ["UTI in women", "IV catheter infection", "Osteomyelitis", "Toxic shock syndrome"], 0, "S. saprophyticus is a coagulase-negative staph classically causing UTIs in women."),
          Q("overview", "How does Staphylococcus saprophyticus compare to S. aureus on coagulase testing?", ["S. saprophyticus is coagulase-negative; S. aureus is coagulase-positive", "Both are coagulase-positive", "Both are coagulase-negative", "S. saprophyticus is coagulase-positive; S. aureus is coagulase-negative"], 0, "S. saprophyticus, like S. epidermidis, is coagulase-negative -- only S. aureus is coagulase-positive.")
        ]),

        D("group-a-strep", "Group A Streptococcus (Strep pyogenes)", "Cause of strep pharyngitis and rheumatic fever; penicillin is first-line, with alternatives for penicillin allergy.", [
          S("overview", "Organism & Presentation", "<p><em>Streptococcus pyogenes</em>, also called \"Group A beta-hemolytic strep.\" The <strong>most common cause of bacterial pharyngitis in pediatrics</strong> (\"strep throat\"), and associated with <strong>rheumatic fever</strong> as a sequela.</p>"),
          S("treatment", "Treatment", HY("Penicillin is the drug of choice for strep throat.") + Tbl(["Situation", "Regimen"], [
            ["Standard", "Penicillin VK (oral), or Amoxicillin (also acceptable), or Benzathine penicillin (single-dose IM)"],
            ["True/contraindicated penicillin allergy", "Erythromycin or Clindamycin preferred"],
            ["Mild allergy", "A cephalosporin may also be considered"]
          ]))
        ], [
          Q("overview", "Group A Streptococcus (Strep pyogenes) is classified by which hemolysis pattern on blood agar?", ["Beta-hemolytic (complete lysis)", "Alpha-hemolytic (partial, greenish lysis)", "Gamma-hemolytic (nonhemolytic)", "Hemolysis pattern is not used to classify GAS"], 0, "Group A Streptococcus is a beta-hemolytic strep -- it completely lyses red blood cells on blood agar, which along with its Lancefield group A antigen is how it's classified."),
          Q("overview", "GAS is the most common cause of which condition in pediatric patients?", ["Bacterial pharyngitis (strep throat)", "Otitis media", "Bacterial pneumonia", "Meningitis"], 0, "GAS is the most common cause of bacterial pharyngitis in pediatrics."),
          Q("overview", "What serious sequela is associated with untreated or inadequately treated GAS pharyngitis?", ["Rheumatic fever", "Hemolytic uremic syndrome", "Guillain-Barre syndrome", "Toxic epidermal necrolysis"], 0, "Rheumatic fever is a recognized sequela of Group A Streptococcus infection."),
          Q("treatment", "What is the drug of choice for strep throat?", ["Penicillin", "Azithromycin", "Ciprofloxacin", "Vancomycin"], 0, "Penicillin is the drug of choice for GAS pharyngitis (as penicillin VK orally, amoxicillin, or single-dose IM benzathine penicillin)."),
          Q("treatment", "Which IM formulation of penicillin can be given as a single dose for strep throat?", ["Benzathine penicillin", "Penicillin VK", "Piperacillin", "Oxacillin"], 0, "Benzathine penicillin is given as a single-dose intramuscular injection."),
          Q("treatment", "A patient has a TRUE, contraindicated allergy to penicillin. What is preferred for treating their strep throat?", ["Erythromycin or clindamycin", "A cephalosporin", "Amoxicillin", "Benzathine penicillin at a lower dose"], 0, "For a true/contraindicated penicillin allergy, erythromycin or clindamycin is preferred; a cephalosporin is only considered for a mild allergy given some cross-reactivity risk."),
          Q("treatment", "A patient has only a MILD penicillin allergy. What alternative may also be considered?", ["A cephalosporin", "Erythromycin only, never a cephalosporin", "No antibiotic is safe for this patient", "IV vancomycin"], 0, "For a mild allergy, a cephalosporin may also be considered as an option.")
        ]),

        D("strep-pneumoniae", "Streptococcus pneumoniae", "Gram-positive diplococcus causing pneumonia, otitis media, sinusitis, and meningitis; vaccine-preventable.", [
          S("overview", "Organism & Presentation", "<p><strong>Gram-positive, encapsulated diplococci.</strong> Commonly inhabits the human respiratory tract; in winter/early spring may be cultured from up to <strong>half the population</strong>.</p>" + Tbl(["Presentation", "Detail"], [
            ["Pneumonia", "Most common cause of bacterial pneumonia (\"pneumococcal pneumonia\")"],
            ["Otitis media", "Causes ~50% of cases in infants/children"],
            ["Sinusitis", "Infection of the paranasal sinuses"]
          ])),
          S("risk-prevention", "Risk Factors & Prevention", HY("Encapsulation is why splenectomy/asplenia is a major risk factor -- the spleen normally clears encapsulated organisms.") + "<p>Other risk factors: influenza infection, alcoholism, smoking, COPD/asthma, immunocompromised state.</p><p><strong>Prevention:</strong> pneumococcal vaccination in adults plus routine childhood vaccination, which leads to herd immunity. (Treatment is covered in the pharmacology lecture.)</p>")
        ], [
          Q("overview", "What is the characteristic microscopic appearance of Streptococcus pneumoniae?", ["Gram-positive encapsulated diplococci", "Gram-negative diplococci", "Gram-positive rods in chains", "Gram-negative rods"], 0, "S. pneumoniae is a gram-positive, encapsulated diplococcus."),
          Q("overview", "Streptococcus pneumoniae is the most common cause of which condition?", ["Bacterial pneumonia", "Viral pneumonia", "Bacillary dysentery", "Toxic shock syndrome"], 0, "S. pneumoniae is the most common cause of bacterial pneumonia (\"pneumococcal pneumonia\")."),
          Q("overview", "Approximately what percentage of otitis media cases in infants/children are caused by S. pneumoniae?", ["~50%", "~5%", "~95%", "Essentially none"], 0, "S. pneumoniae causes approximately 50% of otitis media cases in infants and children."),
          Q("risk-prevention", "Why does splenectomy or impaired splenic function increase risk of severe S. pneumoniae infection?", ["The spleen normally clears encapsulated organisms, and S. pneumoniae is encapsulated", "S. pneumoniae only infects splenic tissue directly", "The spleen produces the antibody that neutralizes pneumococcal toxin", "It does not increase risk -- this is a common misconception"], 0, "S. pneumoniae's polysaccharide capsule requires splenic clearance; asplenia/splenectomy is a risk factor for all encapsulated organisms, including pneumococci."),
          Q("risk-prevention", "Which of the following is a recognized risk factor for pneumococcal disease?", ["COPD/asthma", "Recent tick bite", "Barefoot walking in contaminated soil", "Eating undercooked poultry"], 0, "Influenza infection, alcoholism, smoking, COPD/asthma, splenectomy, and immunocompromise are all risk factors for pneumococcal disease."),
          Q("risk-prevention", "How does pneumococcal vaccination affect unvaccinated members of a population?", ["Routine vaccination leads to herd immunity, indirectly protecting unvaccinated individuals", "It has no effect on unvaccinated individuals", "It only protects the vaccinated individual and never the broader population", "It increases the unvaccinated population's risk of infection"], 0, "Pneumococcal vaccination in adults and routine vaccination of children leads to herd immunity.")
        ]),

        D("n-meningitidis", "Neisseria meningitidis", "Gram-negative diplococcus causing fulminant meningococcemia/meningitis; treated with ceftriaxone, vaccine-preventable.", [
          S("overview", "Presentation", "<p>Small gram-negative cocci, often in chains or pairs. An important cause of <strong>meningitis, bacteremia, and other serious infections</strong> in children and adults, with <strong>high mortality if untreated</strong>. Known as \"meningococcal,\" causing \"meningococcal meningitis.\"</p>" + HY("Presentation: sudden onset of fever, headache, neck stiffness, and a rash of non-blanching petechiae/purpura.")),
          S("treatment-prevention", "Treatment & Prevention", "<p>Antibiotics must be started <strong>as soon as possible</strong> with supportive care -- a <strong>third-generation cephalosporin</strong> (e.g., cefotaxime or ceftriaxone).</p><p><strong>Prevention:</strong> vaccine typically given at <strong>11-12 years of age</strong> with a <strong>booster at 16 years</strong>.</p>")
        ], [
          Q("overview", "What is the characteristic rash of meningococcemia/meningococcal meningitis?", ["Non-blanching petechiae/purpura", "A blanching maculopapular rash", "An expanding annular lesion with central clearing", "A vesicular rash in a dermatomal distribution"], 0, "N. meningitidis classically causes a non-blanching petechial/purpuric rash."),
          Q("overview", "What is the classic symptom onset pattern of meningococcal meningitis?", ["Sudden onset of fever, headache, neck stiffness, and rash", "Gradual onset over several weeks with low-grade fever", "Painless rash without systemic symptoms", "Chronic, indolent symptoms over months"], 0, "N. meningitidis classically presents with sudden onset of fever, headache, neck stiffness, and rash."),
          Q("overview", "What is the clinical significance of untreated N. meningitidis infection?", ["High mortality if untreated", "It is typically self-limited and rarely dangerous", "It only causes mild upper respiratory symptoms", "It resolves without treatment in immunocompetent hosts"], 0, "N. meningitidis is an important cause of serious infection with high mortality if untreated."),
          Q("treatment-prevention", "What is the antibiotic of choice for suspected N. meningitidis infection?", ["A third-generation cephalosporin (cefotaxime or ceftriaxone)", "Penicillin VK", "Azithromycin", "Metronidazole"], 0, "A third-generation cephalosporin such as cefotaxime or ceftriaxone is the treatment of choice, started as soon as possible."),
          Q("treatment-prevention", "How urgently should antibiotics be started for suspected N. meningitidis infection?", ["As soon as possible, given the high mortality if untreated", "Only after confirmatory culture results return", "Within 48-72 hours is generally acceptable", "Antibiotics can be deferred if the patient appears well"], 0, "Given the high mortality of untreated disease, antibiotics need to be initiated as soon as possible along with supportive care."),
          Q("treatment-prevention", "At what age is the meningococcal vaccine typically first given, and when is the booster?", ["11-12 years, with a booster at 16 years", "At birth, with a booster at 5 years", "18 years, with no booster needed", "2 years, with a booster at 4 years"], 0, "The meningococcal vaccine is typically given at 11-12 years of age with a booster dose at 16 years.")
        ]),

        D("n-gonorrhoeae", "Neisseria gonorrhoeae", "Sexually transmitted gram-negative diplococcus causing gonorrhea, treated with ceftriaxone.", [
          S("overview", "Presentation & Treatment", "<p>Major cause of sexually transmitted infection; known as \"gonococcal,\" causing gonorrhea.</p>" + HY("Dual therapy: Ceftriaxone 250mg IM once PLUS Azithromycin 1g PO once."))
        ], [
          Q("overview", "What is the recommended treatment regimen for gonorrhea?", ["Ceftriaxone 250mg IM once plus azithromycin 1g PO once", "Ceftriaxone alone, no second agent needed", "Penicillin VK for 10 days", "Metronidazole 500mg PO once"], 0, "Dual therapy is recommended: ceftriaxone 250mg IM as a single dose plus azithromycin 1g PO as a single dose."),
          Q("overview", "Why is dual therapy (two different antibiotics) used for gonorrhea?", ["To provide broader coverage and address resistance concerns with single-agent therapy", "Because ceftriaxone alone is not absorbed orally", "Because azithromycin alone cures gonorrhea but not chlamydia", "Dual therapy is not actually recommended for gonorrhea"], 0, "Gonorrhea is treated with dual therapy (ceftriaxone IM plus azithromycin PO), both given as a single dose."),
          Q("overview", "Neisseria gonorrhoeae is characteristically described as which type of organism?", ["A gram-negative diplococcus", "A gram-positive diplococcus", "A gram-negative bacillus", "An anaerobic spore-former"], 0, "Like N. meningitidis, N. gonorrhoeae is a gram-negative diplococcus (\"gonococcus\").")
        ]),

        D("typhoid-fever", "Typhoid Fever (Salmonella typhi)", "Enteric fever with sustained fever and constitutional symptoms, distinct from non-typhoidal Salmonella.", [
          S("stool-testing", "Stool Testing -- General Approach to Acute Diarrhea", "<p>Most acute diarrheal illness is self-limited (resolves within ~1 week) and managed supportively: fluids, a bland diet (<strong>BRAT</strong> -- bananas, rice, applesauce, toast -- advancing as tolerated, with fatty/dairy foods returning last), and watchful waiting.</p><p>Antibiotics are generally reserved for <strong>severe illness or those at risk for severe illness</strong>; typical empiric choices are a fluoroquinolone (ciprofloxacin) or macrolide (azithromycin).</p>" + HY("Stool culture routinely tests only for Salmonella, Shigella, and Campylobacter -- anything else (E. coli, C. diff, Vibrio) must be specifically requested.") + Tbl(["Test stool if...", ""], [
            ["Severity/risk criteria", ">6 unformed stools/24h, fever >102F, severe abdominal pain, bloody/mucus-containing diarrhea, volume depletion requiring hospitalization, prolonged illness (>1 week)"],
            ["Host/public health criteria", "Immunocompromised, pregnant, food handlers/healthcare/daycare workers"],
            ["Recent abx/hospitalization (past 3 months)", "Test specifically for C. difficile"]
          ]) + "<p>Stool O&P (ova & parasites) detects protozoa/helminths; because organisms are shed intermittently, <strong>3-6 specimens</strong> are needed for an accurate result (vs. stool culture, which rarely needs repeating since bacteria are shed continuously). Molecular/PCR stool testing is increasingly used but <strong>cannot provide antibiotic sensitivity results</strong>.</p>"),
          S("overview", "Organism & Transmission", "<p>Caused by <em>Salmonella typhi</em> or <em>Salmonella paratyphi</em> -- distinct from the non-typhoidal Salmonella species that cause simple gastroenteritis. Shed in feces of <strong>asymptomatic carriers</strong> or in stool/urine of those with active disease; areas of inadequate sanitation have higher incidence via fecal contamination of food/water.</p>"),
          S("presentation-diagnosis", "Presentation & Diagnosis", HY("Prolonged high fever (103-104F for 2-3 weeks) plus a rose-colored papular rash is the classic typhoid picture.") + "<p>Diagnosis: isolation of typhoid bacilli in culture, typically from stool or urine. In the absence of lab workup, diagnosis can be presumed from clinical features plus endemic travel history.</p>"),
          S("treatment-prevention", "Treatment & Prevention", HY("Ceftriaxone is the drug of choice for typhoid fever.") + Tbl(["Vaccine", "Efficacy", "Booster"], [
            ["Live, attenuated oral vaccine", "~70% effective", "Every 5 years"],
            ["Inactivated, injectable vaccine", "~50-70% effective", "Every 2 years"]
          ]) + "<p>Prevention also includes clean drinking water and proper sewage disposal. In the US, vaccination is typically only considered for travelers.</p>")
        ], [
          Q("stool-testing", "What is the standard bland-diet approach recommended during recovery from acute diarrhea?", ["BRAT diet (bananas, rice, applesauce, toast), advancing as tolerated", "Complete fasting until symptoms resolve", "High-fat, high-dairy diet to replace lost calories", "Raw fruits and vegetables only"], 0, "The BRAT diet -- bananas, rice, applesauce, toast -- is the bland-diet approach, with fatty meals and dairy returning last."),
          Q("stool-testing", "Which pathogens does a routine stool culture test for by default?", ["Salmonella, Shigella, and Campylobacter only", "Every possible enteric pathogen automatically", "Only viruses", "Only C. difficile"], 0, "Routine stool culture only covers Salmonella, Shigella, and Campylobacter -- other organisms (E. coli, Vibrio, C. diff) must be specifically requested."),
          Q("stool-testing", "Why are 3-6 stool specimens recommended for O&P testing, rather than just one?", ["Ova and parasites are shed intermittently, so a single specimen has a higher false-negative rate", "Laboratory policy requires multiple specimens regardless of shedding pattern", "A single specimen is actually sufficient and multiple specimens are not needed", "It is done to test for antibiotic sensitivity"], 0, "Because protozoa/helminths are shed intermittently, 3-6 specimens are needed for an accurate O&P result."),
          Q("stool-testing", "What is a key limitation of molecular/PCR stool testing compared to traditional culture?", ["PCR cannot provide antibiotic sensitivity results", "PCR cannot detect any bacterial pathogens", "PCR takes longer than culture to result", "PCR requires 6 specimens like O&P testing"], 0, "Molecular/PCR testing is increasingly used but cannot provide sensitivity results, unlike culture and sensitivity (C&S) testing."),
          Q("stool-testing", "A patient was hospitalized and received antibiotics 6 weeks ago and now presents with diarrhea. What should stool testing specifically target?", ["Clostridioides difficile", "Vibrio cholerae only", "Giardia lamblia only", "No testing is indicated"], 0, "Antibiotic use or hospitalization within the past 3 months should prompt stool testing specifically for C. difficile."),
          Q("overview", "Besides symptomatic patients, who else can shed and transmit typhoid, complicating control efforts?", ["Asymptomatic carriers", "Only patients who have fully recovered and completed antibiotics", "Only healthcare workers who treated a typhoid patient", "Typhoid cannot be transmitted by anyone without active symptoms"], 0, "Typhoid bacilli can be shed in the feces of asymptomatic carriers, not just those with active disease -- a key reason typhoid persists in areas of inadequate sanitation."),
          Q("presentation-diagnosis", "What is the classic clinical picture of typhoid fever?", ["Prolonged high fever (103-104F for 2-3 weeks) with a rose-colored papular rash", "Abrupt watery \"rice-water\" diarrhea without fever", "Perianal itching worse at night", "A pruritic papulovesicular rash at a skin-penetration site"], 0, "Typhoid fever classically presents with sustained high fever (103-104F) for 2-3 weeks and a rose-colored papular rash."),
          Q("treatment-prevention", "What is the drug of choice for typhoid fever?", ["Ceftriaxone", "Metronidazole", "Doxycycline", "Vancomycin"], 0, "Ceftriaxone is the drug of choice for typhoid fever."),
          Q("treatment-prevention", "How do the two typhoid vaccines differ in booster schedule?", ["The oral live vaccine needs a booster every 5 years; the injectable inactivated vaccine every 2 years", "Both need a booster every 5 years", "The oral vaccine never needs a booster; the injectable does every year", "The injectable vaccine needs a booster every 10 years, the oral every year"], 0, "The live attenuated oral vaccine (~70% effective) boosters every 5 years; the inactivated injectable vaccine (~50-70% effective) boosters every 2 years.")
        ]),

        D("nontyphoidal-salmonella", "Non-typhoidal Salmonella", "Foodborne gastroenteritis from poultry/eggs; usually self-limited, antibiotics reserved for severe or invasive disease.", [
          S("overview", "Organism, Source & Presentation", "<p>Caused by <em>S. enteritidis</em>, <em>S. newport</em>, <em>S. typhimurium</em> (acute gastroenteritis) -- distinct from typhoidal Salmonella.</p>" + HY("Eggs are the classic US-outbreak food vehicle -- S. enteritidis can be inside perfect-appearing eggs, so raw/undercooked consumption can cause illness.") + "<p>Other sources: contaminated poultry, milk, mayonnaise (raw eggs).</p><p>Presentation: nausea and crampy abdominal pain leading to diarrhea, fever, sometimes vomiting. Stool is usually <strong>watery</strong>, rarely mucus/blood, sometimes called \"<strong>pea soup</strong>\" stool. Onset 12-48 hours after ingestion; usually self-limited (fever resolves in 72 hours, diarrhea in 4-10 days).</p>"),
          S("treatment", "Treatment & Prevention", "<p>Generally <strong>supportive</strong> (fluids, bland diet, rest). Antibiotics are effective but reserved for severe illness or those at risk for severe illness: fluoroquinolones (ciprofloxacin, levofloxacin), azithromycin, TMP-SMX, or cefixime.</p><p>Prevention: proper food storage (4C), handwashing after raw food contact, pasteurized milk products, adequate cooking temperatures.</p>")
        ], [
          Q("overview", "What food is classically implicated in US non-typhoidal Salmonella outbreaks?", ["Eggs", "Canned vegetables", "Unpasteurized apple cider", "Raw shellfish"], 0, "Eggs -- even perfect-appearing ones -- are the classic US-outbreak food vehicle for S. enteritidis."),
          Q("overview", "What is the characteristic stool description in non-typhoidal Salmonella gastroenteritis?", ["Watery, sometimes called \"pea soup\" stool", "Rice-water stool", "Bloody, mucoid stool with tenesmus", "Frothy, greasy (steatorrheic) stool"], 0, "Stool is usually watery, rarely containing mucus/blood, sometimes described as \"pea soup\" in appearance."),
          Q("overview", "How soon after ingestion do symptoms of non-typhoidal Salmonella gastroenteritis typically begin?", ["12-48 hours", "Immediately, within minutes", "7-10 days", "3-4 weeks"], 0, "Symptom onset is typically 12-48 hours after ingesting contaminated food."),
          Q("overview", "How does non-typhoidal Salmonella gastroenteritis typically resolve?", ["Usually self-limited -- fever resolves in 72 hours, diarrhea in 4-10 days", "It is uniformly fatal without IV ceftriaxone", "It requires 2-3 weeks of high fever, like typhoid fever", "It never resolves without antiparasitic treatment"], 0, "Non-typhoidal Salmonella gastroenteritis is usually self-limited, contrasting with the prolonged 2-3 week fever of typhoid fever."),
          Q("treatment", "What is the mainstay of treatment for most non-typhoidal Salmonella gastroenteritis?", ["Supportive care (fluids, bland diet, rest)", "Ceftriaxone", "Immediate antiparasitic therapy", "Surgical debridement"], 0, "Treatment is generally supportive; antibiotics are reserved for severe illness or those at risk for severe illness."),
          Q("treatment", "Which antibiotic class is an appropriate option for SEVERE non-typhoidal Salmonella infection?", ["Fluoroquinolones (e.g., ciprofloxacin)", "Aminoglycosides only", "Antifungals", "Antivirals"], 0, "Fluoroquinolones, azithromycin, TMP-SMX, or cefixime are options when antibiotics are indicated for severe non-typhoidal Salmonella infection."),
          Q("treatment", "How does recommended treatment for non-typhoidal Salmonella differ from typhoid fever?", ["Non-typhoidal disease is usually managed supportively; typhoid fever gets ceftriaxone as the drug of choice", "Both are always treated with ceftriaxone", "Non-typhoidal disease always requires IV antibiotics; typhoid never does", "There is no difference in management"], 0, "Non-typhoidal Salmonella gastroenteritis is usually self-limited and managed supportively, while typhoid (enteric) fever has ceftriaxone as its specific drug of choice.")
        ]),

        D("e-coli-stec", "E. coli (incl. STEC / O157:H7)", "Enteric and UTI pathogen; the Shiga-toxin strain causes bloody diarrhea and hemolytic uremic syndrome in children.", [
          S("overview", "Sources & Presentation", "<p>Normally inhabits the GI tract; some strains cause illness directly or via <strong>Shiga toxin</strong>. Sources: contaminated meat, unpasteurized milk, fruits/vegetables, household contact with infected persons, petting zoos/animal exhibits.</p>" + Tbl(["Form", "Presentation"], [
            ["Mild AGE", "Abdominal cramps, nausea, vomiting, watery diarrhea, usually self-limited within 7 days"],
            ["STEC (Shiga toxin-producing E. coli)", "Intestinal inflammation/damage from the toxin -- abdominal pain, vomiting, bloody diarrhea"],
            ["E. coli O157:H7", "The particularly virulent STEC strain"]
          ]) + HY("STEC/O157:H7 -> Hemolytic Uremic Syndrome (HUS), the leading cause of acute kidney failure in pediatrics.")),
          S("treatment", "Treatment", "<p>Most diarrheal illness: supportive care (fluids, bland diet, rest); consider an antiemetic (ondansetron or promethazine). IV rehydration if unable to maintain PO intake.</p><p>Severe, bloody, or persistent diarrhea (non-STEC): azithromycin or a fluoroquinolone (ciprofloxacin, levofloxacin) is usually indicated.</p>" + HY("AVOID antibiotics in suspected STEC infection, especially in pediatrics -- they may precipitate HUS."))
        ], [
          Q("overview", "What toxin is responsible for the severe manifestations of STEC (Shiga toxin-producing E. coli)?", ["Shiga toxin", "Tetanospasmin", "Botulinum toxin", "Cholera toxin"], 0, "Shiga toxin causes intestinal inflammation and damage, leading to bloody diarrhea and systemic complications."),
          Q("overview", "STEC/E. coli O157:H7 infection is most strongly associated with which serious complication in children?", ["Hemolytic uremic syndrome (HUS) and acute kidney failure", "Rheumatic fever", "Meningitis", "Toxic shock syndrome"], 0, "STEC/O157:H7 is associated with hemolytic uremic syndrome, the leading cause of acute kidney failure in pediatrics."),
          Q("overview", "Which of the following is a recognized source of E. coli infection?", ["Petting zoos and animal exhibits", "Mosquito bites", "Tick bites", "Sexual contact only"], 0, "E. coli sources include contaminated meat, unpasteurized milk, produce, household contact, and petting zoos/animal exhibits."),
          Q("treatment", "Why should antibiotics generally be AVOIDED in suspected STEC infection, especially in children?", ["They may precipitate hemolytic uremic syndrome", "They have no effect on Shiga toxin-producing strains", "They are contraindicated due to cost", "They cause treatment failure only in adults, not children"], 0, "Antibiotics are avoided in suspected STEC infection because they may precipitate HUS, unlike most other bacterial diarrheas where antibiotics are used for severe disease."),
          Q("treatment", "For SEVERE, bloody, or persistent diarrhea NOT thought to be due to STEC, which antibiotics are usually indicated?", ["Azithromycin or a fluoroquinolone", "Antibiotics are never indicated for any E. coli diarrhea", "Antifungals", "Antivirals"], 0, "Azithromycin or a fluoroquinolone (ciprofloxacin, levofloxacin) is usually indicated for severe, bloody, or persistent non-STEC diarrheal illness."),
          Q("treatment", "What supportive medication class may be considered for nausea/vomiting with E. coli gastroenteritis?", ["Antiemetics (e.g., ondansetron or promethazine)", "Antihistamines", "Beta-blockers", "Antipsychotics"], 0, "An antiemetic such as ondansetron (Zofran) or promethazine (Phenergan) may be considered for supportive care."),
          Q("overview", "A 5-year-old develops bloody diarrhea after a farm petting-zoo visit. Which complication should be anticipated and monitored for?", ["Hemolytic uremic syndrome with acute kidney injury", "Rheumatic heart disease", "Guillain-Barre syndrome", "Reye syndrome"], 0, "Bloody diarrhea in a child after likely STEC exposure (e.g., petting zoo) should raise concern for progression to HUS and acute kidney injury.")
        ]),

        D("shigella", "Shigella (Bacillary Dysentery)", "Highly contagious cause of bloody, mucoid diarrhea from a very small inoculum.", [
          S("overview", "Epidemiology & Presentation", "<p>Causes shigellosis, aka \"<strong>bacillary dysentery</strong>.\" A common cause of bacterial diarrhea especially in developing countries -- the <strong>most common cause of moderate-severe diarrhea among pediatrics in Asia and Africa</strong>. Spread directly by the fecal-oral route and indirectly via contaminated food/objects; <strong>flies serve as mechanical vectors</strong>. Organisms penetrate the lower intestinal mucosa, causing mucus secretion, leukocytic infiltration, edema, and superficial ulceration.</p>" + HY("High fever, abdominal cramps, tenesmus, and mucoid (sometimes bloody) diarrhea is the classic picture.")),
          S("diagnosis-treatment", "Diagnosis & Treatment", "<p>Diagnosis: stool culture with antibiotic susceptibility testing -- increasing antimicrobial resistance makes susceptibility testing important for drug selection.</p><p>Treatment (for those with or at risk for severe/prolonged illness): empiric fluoroquinolone, azithromycin, or a 3rd-generation cephalosporin.</p>")
        ], [
          Q("overview", "What insect can serve as a mechanical vector for Shigella transmission?", ["Flies", "Mosquitoes", "Ticks", "Fleas"], 0, "Flies serve as mechanical vectors for indirect Shigella transmission via contaminated food."),
          Q("overview", "Shigella is the most common cause of moderate-severe diarrhea among pediatric patients in which regions?", ["Asia and Africa", "North America and Europe", "Australia only", "South America only"], 0, "Shigella is the most common cause of moderate-severe pediatric diarrhea in Asia and Africa."),
          Q("overview", "What symptom describes the sensation of incomplete/painful defecation seen in shigellosis?", ["Tenesmus", "Steatorrhea", "Odynophagia", "Dysphagia"], 0, "Tenesmus, along with high fever, abdominal cramps, and mucoid/bloody diarrhea, is classic for Shigella infection."),
          Q("diagnosis-treatment", "Why is antibiotic susceptibility testing particularly important when treating Shigella?", ["Increasing antimicrobial resistance makes susceptibility results important for guiding drug selection", "Shigella cannot be cultured, so susceptibility testing is the only diagnostic option", "Shigella is always resistant to all antibiotics", "Susceptibility testing is not relevant to Shigella treatment"], 0, "Increasing antimicrobial resistance makes susceptibility testing important to guide appropriate drug selection for Shigella."),
          Q("diagnosis-treatment", "Which empiric antibiotic options are appropriate for severe or prolonged shigellosis?", ["Fluoroquinolone, azithromycin, or a 3rd-generation cephalosporin", "Metronidazole alone", "Primaquine", "No antibiotics are ever indicated for Shigella"], 0, "Empiric treatment options for those with or at risk for severe/prolonged shigellosis include a fluoroquinolone, azithromycin, or a 3rd-generation cephalosporin.")
        ]),

        D("cholera", "Cholera (Vibrio cholerae)", "Toxin-mediated profuse watery diarrhea associated with contaminated water/seafood; rehydration is the priority.", [
          S("overview", "Organism, Source & Presentation", "<p>Spread by ingestion of water, <strong>seafood</strong>, and other food contaminated by human excrement. Endemic in parts of Asia, the Middle East, Africa, South and Central America, and the <strong>Gulf Coast of the USA</strong>.</p>" + HY("\"Rice-water\" stool with abrupt, painless, watery diarrhea and vomiting is the classic cholera picture.") + "<p>Loss of isotonic, watery stool rich in sodium, chloride, bicarbonate, and potassium leads to vomiting and muscle cramps, and can rapidly progress to <strong>hypovolemic shock</strong>.</p>"),
          S("treatment", "Treatment", HY("Rehydration is the mainstay of cholera treatment -- rapid correction of hypovolemia and metabolic acidosis, and prevention of hypokalemia, are key.") + "<p>Antimicrobial choice is based on local isolate susceptibility; a <strong>single dose</strong> of ciprofloxacin, doxycycline, or azithromycin may be used as an adjunct.</p>")
        ], [
          Q("overview", "What is the classic stool description in cholera?", ["\"Rice-water\" stool", "\"Pea soup\" stool", "Bloody, mucoid stool", "Steatorrheic (greasy) stool"], 0, "Cholera classically produces \"rice-water\" stool from profuse watery diarrhea."),
          Q("overview", "Besides contaminated water, what food source is classically associated with cholera?", ["Seafood", "Canned goods", "Unpasteurized dairy", "Raw poultry"], 0, "Cholera is spread by ingestion of contaminated water, seafood, and other foods contaminated by human excrement."),
          Q("overview", "Where in the continental United States is Vibrio cholerae endemic?", ["The Gulf Coast", "The Pacific Northwest", "New England", "The Great Lakes region"], 0, "In addition to parts of Asia, the Middle East, Africa, and South/Central America, V. cholerae is endemic along the US Gulf Coast."),
          Q("overview", "Untreated, severe cholera can rapidly progress to which life-threatening complication?", ["Hypovolemic shock", "Hemolytic uremic syndrome", "Toxic shock syndrome", "Meningitis"], 0, "Profound isotonic fluid loss in cholera can rapidly progress to hypovolemic shock if untreated."),
          Q("treatment", "What is the single most important treatment for cholera?", ["Rehydration", "IV ceftriaxone", "Surgical debridement", "Antiparasitic therapy"], 0, "Rehydration -- correcting hypovolemia, metabolic acidosis, and preventing hypokalemia -- is the mainstay of cholera treatment."),
          Q("treatment", "Which antibiotics may be used as a single dose adjunct to rehydration in cholera?", ["Ciprofloxacin, doxycycline, or azithromycin", "Vancomycin", "Primaquine", "Metronidazole only"], 0, "A single dose of ciprofloxacin, doxycycline, or azithromycin (based on local susceptibility) may be used as an adjunct to rehydration.")
        ]),

        D("pseudomonas", "Pseudomonas aeruginosa", "Opportunistic gram-negative rod behind hospital-acquired pneumonia, VAP, UTIs, and many blood isolates.", [
          S("overview", "Epidemiology & Presentation", HY("Classic associations: hospital-acquired/opportunistic infection in debilitated patients, ventilator-associated pneumonia, and bacteremia in burn patients.") + "<p>Opportunistic pathogen, frequently causing hospital-acquired infections, mostly in debilitated/immunocompromised patients. Common cause of infections in ICUs and a frequent cause of ventilator-associated pneumonia (associated with endotracheal intubation/tracheostomy).</p><p>Can involve skin, subcutaneous tissue, bone, ears, eyes, urinary tract, and heart valves. A common cause of UTI. Blood isolates are common in patients with <strong>burns</strong> and underlying malignancy.</p><p>(Treatment is covered in the pharmacology lecture.)</p>")
        ], [
          Q("overview", "Pseudomonas aeruginosa is best characterized as what type of pathogen?", ["An opportunistic pathogen, especially in debilitated/immunocompromised patients", "An obligate intracellular pathogen only", "A pathogen exclusively transmitted person-to-person", "A pathogen that only causes disease in healthy outpatients"], 0, "Pseudomonas is an opportunistic pathogen, frequently causing hospital-acquired infections in debilitated or immunocompromised patients."),
          Q("overview", "Pseudomonas is a frequent cause of pneumonia in which specific hospital setting?", ["Ventilator-associated pneumonia", "Community-acquired pneumonia in healthy young adults", "Aspiration pneumonia in outpatients only", "Pediatric viral pneumonia"], 0, "Pseudomonas is a frequent cause of ventilator-associated pneumonia, associated with endotracheal intubation/tracheostomy."),
          Q("overview", "Bloodstream isolates of Pseudomonas are classically associated with which patient population?", ["Burn patients and those with underlying malignancy", "Healthy pregnant women", "Pediatric patients with no comorbidities", "Patients with recent tick bites"], 0, "Blood isolates of Pseudomonas are common in patients with burns and underlying malignancy."),
          Q("overview", "Which of the following is a common site of Pseudomonas infection?", ["Urinary tract", "Perianal skin only", "The eye only, never other sites", "Exclusively the CNS"], 0, "Pseudomonas can infect skin, subcutaneous tissue, bone, ears, eyes, urinary tract, and heart valves, and is a common cause of UTI."),
          Q("overview", "In which clinical setting is Pseudomonas infection most frequently encountered?", ["ICUs, among debilitated or immunocompromised patients", "Outpatient pediatric clinics", "Uncomplicated community skin infections", "Routine prenatal visits"], 0, "Pseudomonas is a common cause of infections in ICUs and hospital-acquired infections generally.")
        ]),

        D("gas-gangrene", "Gas Gangrene (Clostridium perfringens)", "Rapidly progressive anaerobic myonecrosis with gas in tissue; needs emergent debridement plus antibiotics.", [
          S("overview", "Clostridial Infections -- General", "<p>Clostridia are anaerobic organisms that grow in the complete absence of oxygen, but may produce <strong>spores</strong> that withstand long periods of O2 exposure. Clinically significant Clostridial infections produce a variety of <strong>toxins</strong> that drive the clinical presentation (e.g., the neurotoxins of tetanus and botulism are among the most lethal toxins known); known toxins may be neutralized by antiserum.</p>"),
          S("food-poisoning", "C. perfringens Food Poisoning", "<p>In the GI tract, produces an <strong>enterotoxin</strong> acting on the small intestine, causing mild gastroenteritis. Onset of watery diarrhea/abdominal symptoms <strong>6-24 hours</strong> after ingesting contaminated food (classically <strong>contaminated meat</strong>). Found in feces, soil, air, and water."),
          S("gas-gangrene", "Gas Gangrene", HY("Traumatic gas gangrene is most commonly caused by C. perfringens.") + "<p><strong>Myonecrosis</strong> -- rapidly progressive destruction of muscle and soft tissue.</p><p><strong>Treatment:</strong> urgent surgical debridement plus IV antibiotic therapy.</p>")
        ], [
          Q("overview", "What allows Clostridial species to survive prolonged oxygen exposure despite being obligate anaerobes?", ["Spore formation", "A thick capsule", "Biofilm production", "Pilus-mediated resistance"], 0, "Clostridia grow only in the absence of oxygen but form spores that withstand long periods of O2 exposure."),
          Q("overview", "What class of toxin is responsible for the neurologic manifestations of tetanus and botulism?", ["Neurotoxins -- among the most lethal toxins known to humans", "Enterotoxins", "Hemolysins only", "Endotoxin (LPS)"], 0, "Tetanus and botulism symptoms result from neurotoxins, among the most lethal toxins to humans."),
          Q("food-poisoning", "How soon after ingesting contaminated food does C. perfringens food poisoning typically present?", ["6-24 hours", "Immediately, within minutes", "5-10 days", "3-4 weeks"], 0, "Watery diarrhea and abdominal symptoms begin 6-24 hours after ingesting food contaminated with C. perfringens."),
          Q("food-poisoning", "What food is classically implicated in C. perfringens food poisoning outbreaks?", ["Contaminated meat", "Canned vegetables", "Raw eggs", "Unpasteurized milk"], 0, "C. perfringens food poisoning outbreaks are often caused by contaminated meat."),
          Q("food-poisoning", "What toxin mediates C. perfringens food poisoning?", ["An enterotoxin acting on the small intestine", "A neurotoxin", "Shiga toxin", "Cholera toxin"], 0, "C. perfringens produces an enterotoxin in the GI tract that acts on the small intestine, causing mild gastroenteritis."),
          Q("gas-gangrene", "What is the underlying process in gas gangrene?", ["Myonecrosis -- rapidly progressive destruction of muscle and soft tissue", "Chronic granulomatous inflammation", "Demyelination of peripheral nerves", "Glomerular scarring"], 0, "Gas gangrene is myonecrosis -- rapidly progressive destruction of muscle and soft tissue."),
          Q("gas-gangrene", "What is the appropriate treatment for gas gangrene?", ["Urgent surgical debridement plus IV antibiotics", "Oral antibiotics alone, as an outpatient", "Rehydration alone", "Antitoxin alone, without surgery"], 0, "Gas gangrene requires urgent surgical debridement plus IV antibiotic therapy -- antibiotics alone are not sufficient.")
        ]),

        D("tetanus", "Tetanus (Clostridium tetani)", "Spore-forming anaerobe causing rigid paralysis via tetanospasmin; prevented by Tdap, including in pregnancy.", [
          S("overview", "Organism & Epidemiology", "<p>Found in <strong>soil, especially heavily manured soils</strong>, and in the intestinal tracts/feces of various animals. Still causes ~<strong>50,000 deaths annually worldwide</strong>, with a worldwide mortality rate of <strong>50%</strong>.</p>"),
          S("presentation", "Presentation", HY("The exotoxin causes intermittent tonic spasms of voluntary muscles -- jaw muscle spasm gives tetanus the name \"lockjaw.\"")),
          S("neonatal", "Neonatal Tetanus", "<p>Accounts for about <strong>half of tetanus deaths in developing countries</strong>. Follows infection of the <strong>umbilical stump</strong> in infants born to <strong>nonimmune mothers</strong>.</p>" + Mn("Tdap in pregnancy", "In the US, Tdap is routinely given during pregnancy specifically to provide passive immunity to the newborn and prevent neonatal tetanus.")),
          S("treatment", "Treatment", Tbl(["Component", "Detail"], [
            ["Airway", "Stabilize"],
            ["Unbound toxin", "Neutralize with tetanus immune globulin"],
            ["Immunization", "Tetanus vaccine"],
            ["Muscle spasms", "Benzodiazepines (reduce muscle excitability)"],
            ["Antibiotic", "Metronidazole"]
          ]) + "<p>Prevention: routine childhood immunization plus adult booster doses.</p>")
        ], [
          Q("overview", "Where is Clostridium tetani classically found in the environment?", ["Soil, especially heavily manured soil", "Freshwater lakes only", "Decaying canned food", "Seawater"], 0, "C. tetani is found in soil (especially heavily manured soil) and in the intestinal tracts/feces of various animals."),
          Q("presentation", "What is the origin of the common name \"lockjaw\" for tetanus?", ["Spasm of the jaw muscles from the exotoxin causing tonic muscle spasms", "Paralysis specifically of the tongue", "Loss of the gag reflex", "A rash that forms around the mouth"], 0, "The tetanus exotoxin causes intermittent tonic spasms of voluntary muscles; jaw muscle spasm gives tetanus the name \"lockjaw.\""),
          Q("neonatal", "How does neonatal tetanus typically occur?", ["Infection of the umbilical stump in infants born to nonimmune mothers", "Transplacental transmission during the third trimester", "Ingestion of honey by the infant", "Contaminated infant formula"], 0, "Neonatal tetanus follows infection of the umbilical stump in infants born to nonimmune mothers."),
          Q("neonatal", "Why is Tdap routinely given during pregnancy in the US?", ["To provide passive immunity to the newborn against pertussis and tetanus", "To treat active maternal tetanus infection", "It is not actually recommended during pregnancy", "To prevent postpartum hemorrhage"], 0, "Tdap is routinely given during pregnancy in the US to provide passive immunity to the newborn, helping prevent neonatal tetanus."),
          Q("neonatal", "Neonatal tetanus accounts for approximately what proportion of tetanus deaths in developing countries?", ["About half", "Less than 1%", "Nearly all (>95%)", "About 5%"], 0, "Neonatal tetanus accounts for about half of tetanus deaths in developing countries."),
          Q("treatment", "What agent is used to neutralize unbound tetanus toxin?", ["Tetanus immune globulin", "Trivalent antitoxin", "Tetanus vaccine alone", "Metronidazole"], 0, "Tetanus immune globulin neutralizes unbound toxin; the tetanus vaccine is also given but serves an immunizing role, not toxin neutralization."),
          Q("treatment", "What class of medication is used to manage the muscle spasms of tetanus?", ["Benzodiazepines", "Beta-blockers", "Opioids as first line", "Antihistamines"], 0, "Benzodiazepines reduce muscle excitability and are used to manage tetanus-associated muscle spasms."),
          Q("treatment", "What specific antibiotic is named for tetanus treatment?", ["Metronidazole", "Ceftriaxone", "Doxycycline", "Vancomycin"], 0, "Metronidazole is the antibiotic specifically named for tetanus treatment, alongside airway stabilization, immune globulin, vaccine, and benzodiazepines.")
        ]),

        D("botulism", "Botulism (Clostridium botulinum)", "Toxin-mediated descending flaccid paralysis; classic sources are improperly canned food and honey in infants.", [
          S("overview", "Organism & Foodborne Botulism", "<p>Found in soil, sediments of lakes/ponds, and decaying vegetation.</p>" + HY("Foodborne botulism is technically NOT an infection -- it results from ingestion of preformed toxin in food, especially improperly CANNED foods.") + "<p>The toxin targets different peripheral nervous system cells than tetanus toxin; primary symptom is <strong>weakness or flaccid paralysis</strong> (contrast with tetanus's rigid/spastic paralysis). May cause respiratory failure.</p>"),
          S("infant", "Infant Botulism", "<p>Occurs in infants <strong>5-20 weeks of age</strong> exposed to food contaminated with C. botulinum.</p>" + HY("Unlike foodborne botulism, infant botulism IS a true infection -- C. botulinum establishes itself in the infant bowel before competing intestinal bacteria are established.") + Mn("No honey <12 months", "Infants under 1 year of age should never be given honey, which may contain C. botulinum spores.")),
          S("treatment", "Treatment & Prevention", "<p>Stabilize respiratory impairment. <strong>Trivalent antitoxin (A, B, E)</strong> is available from the CDC through state health departments.</p><p>Prevention: correct food handling/canning/preparation; never eat from bulging food containers (bulging is caused by botulinum gas); no honey for infants under 12 months.</p>")
        ], [
          Q("overview", "Is foodborne botulism technically an infection or an intoxication?", ["An intoxication -- it results from ingesting preformed toxin, not from bacterial infection", "A true infection, like infant botulism", "Neither -- it is an autoimmune process", "It is a viral illness"], 0, "Foodborne botulism is technically not an infection; it results from ingestion of preformed Clostridium toxin in food."),
          Q("overview", "What food source is classically associated with foodborne botulism?", ["Improperly canned foods", "Undercooked poultry", "Contaminated eggs", "Unpasteurized milk"], 0, "Foodborne botulism classically results from ingesting preformed toxin in improperly canned foods."),
          Q("overview", "How does the paralysis of botulism differ from that of tetanus?", ["Botulism causes flaccid paralysis; tetanus causes rigid/spastic (tonic) paralysis", "Both cause identical flaccid paralysis", "Botulism causes spastic paralysis; tetanus causes flaccid paralysis", "Neither causes paralysis"], 0, "Botulinum toxin targets different PNS cells than tetanus toxin, producing weakness/flaccid paralysis rather than tetanus's tonic spasms."),
          Q("infant", "At what age range does infant botulism classically occur?", ["5-20 weeks of age", "Birth to 2 weeks", "2-5 years", "Only in adolescents"], 0, "Infant botulism occurs in infants 5-20 weeks of age exposed to contaminated food/spores."),
          Q("infant", "Why is infant botulism classified as a true infection, unlike foodborne botulism?", ["C. botulinum establishes itself and produces toxin in the infant bowel before competing bacteria are established", "It is caused by a completely different organism", "It only involves preformed toxin, like the foodborne form", "It is caused by direct skin inoculation"], 0, "Unlike foodborne botulism (preformed toxin ingestion), infant botulism is a true infection because the immature infant gut lacks competing bacteria, allowing C. botulinum to colonize and produce toxin in situ."),
          Q("infant", "What specific dietary recommendation prevents infant botulism?", ["No honey for infants under 12 months of age", "Avoid all dairy until 12 months", "No canned foods until 6 months", "Exclusive breastfeeding until 6 months"], 0, "Honey may contain C. botulinum spores and should never be given to infants under 1 year of age."),
          Q("treatment", "What specific antitoxin is available through the CDC/state health departments for botulism?", ["Trivalent antitoxin (types A, B, E)", "Tetanus immune globulin", "Pentavalent antitoxin", "Monoclonal anti-toxin antibody"], 0, "A trivalent antitoxin covering toxin types A, B, and E is available from the CDC through state health departments."),
          Q("treatment", "Why should bulging canned food containers never be eaten?", ["Bulging is caused by gas production from C. botulinum, indicating possible contamination", "Bulging only indicates spoiled flavor, not safety risk", "Bulging indicates the can is overfilled but otherwise safe", "Bulging is unrelated to botulism risk"], 0, "Bulging food containers are a warning sign of botulinum gas production and should never be consumed.")
        ]),

        D("c-diff", "Clostridioides difficile", "Antibiotic-associated colitis from a toxin-producing anaerobic spore-former.", [
          S("overview", "Overview", "<p>Name has changed to <em>Clostridioides difficile</em> (reclassified into a new genus due to genetic differences, though still grouped with the Clostridial infections). Responsible for <strong>15-20% of antibiotic-related cases of diarrhea</strong> and <strong>nearly all cases of pseudomembranous colitis</strong>.</p>" + HY("The precipitating event is disruption of normal colonic microflora, usually from broad-spectrum antibiotic use -- recent antibiotic use should always raise suspicion for C. diff."))
        ], [
          Q("overview", "What is the most common precipitating event for C. difficile infection?", ["Disruption of normal colonic microflora, usually from broad-spectrum antibiotic use", "Contaminated seafood ingestion", "A recent tick bite", "Travel to a malaria-endemic region"], 0, "C. difficile infection is precipitated by disruption of normal colonic microflora, most often from broad-spectrum antibiotic use."),
          Q("overview", "Approximately what proportion of antibiotic-related diarrhea cases are due to C. difficile?", ["15-20%", "Less than 1%", "About 90%", "Essentially 100%"], 0, "C. difficile is responsible for 15-20% of antibiotic-related diarrhea cases and nearly all cases of pseudomembranous colitis."),
          Q("overview", "C. difficile is responsible for nearly all cases of which specific colonic condition?", ["Pseudomembranous colitis", "Ulcerative colitis", "Ischemic colitis", "Microscopic colitis"], 0, "C. difficile causes nearly all cases of pseudomembranous colitis.")
        ]),

        D("malaria", "Malaria (Plasmodium spp.)", "Mosquito-borne protozoan infecting red blood cells; 4 species, cyclic fevers, P. vivax/ovale need primaquine for liver hypnozoites.", [
          S("overview", "Organism, Vector & Epidemiology", Tbl(["", ""], [
            ["Species (4 infect humans)", "P. falciparum (highest mortality), P. vivax, P. ovale, P. malariae"],
            ["Cells targeted", "Erythrocytes (red blood cells)"],
            ["Vector", "Female Anopheles mosquito, active dusk to dawn"],
            ["Burden", "228 million cases worldwide in 2018; ~2,000 cases/year in the US, mostly in travelers"]
          ])),
          S("presentation", "Clinical Presentation", "<p>Incubation: <strong>9-30 days</strong>. Paroxysm: malaise, abrupt chills, fever rising to 39-41C (102-106F), rapid/thready pulse or tachycardia, polyuria, headache, nausea -- then fever falls with <strong>profuse sweating over 2-3 hours</strong>.</p>" + Tbl(["Species", "Paroxysm periodicity"], [
            ["P. vivax, P. falciparum, P. ovale", "~Every 48 hours"],
            ["P. malariae", "~Every 72 hours"]
          ]) + HY("P. vivax and P. ovale can cause relapsing infection from residual liver hypnozoites -- relapse may occur up to 4 years later.") + "<p>If untreated, an attack lasts 2-8 weeks depending on species. Most severe disease (generally P. falciparum) can progress to organ failure, delirium, impaired consciousness, seizures, coma, death. Highest risk for severe malaria: children under 5, pregnant women, and travelers with no previous exposure.</p>"),
          S("treatment", "Treatment", HY("P. vivax or P. ovale infection requires primaquine to eliminate liver hypnozoites -- this is not needed for falciparum or malariae.") + "<p>Most antimalarial drugs target the erythrocyte stage. Chloroquine is used much less now due to resistance by P. falciparum.</p>"),
          S("prevention", "Prevention & Chemoprophylaxis", "<p>Non-pharmacologic: avoid outdoor exposure dusk to dawn, reduce exposed skin, DEET insect repellent, air-conditioned rooms or well-fitted screens, permethrin-treated bed nets.</p>" + Tbl(["Chemoprophylaxis drug", "Key feature"], [
            ["Atovaquone-proguanil", "Fewer side effects, more costly"],
            ["Mefloquine", "More side effects (intense dreams), seizure risk, weekly dosing"],
            ["Doxycycline", "Daily dosing, sun sensitivity, GI upset, cheap"],
            ["Tafenoquine", "Must test for G6PD deficiency first, costly"]
          ]))
        ], [
          Q("overview", "Which of the four human Plasmodium species is associated with the highest mortality?", ["P. falciparum", "P. vivax", "P. ovale", "P. malariae"], 0, "P. falciparum causes the highest mortality among the four human malaria species."),
          Q("overview", "What cell type does Plasmodium target in the human host?", ["Erythrocytes (red blood cells)", "Hepatocytes exclusively, with no RBC involvement", "Neutrophils", "T lymphocytes"], 0, "Malaria parasites are blood parasites that target erythrocytes."),
          Q("overview", "What is the vector for malaria transmission, and when is it most active?", ["The female Anopheles mosquito, active dusk to dawn", "The female Aedes mosquito, active during the day", "The Ixodes tick, active spring through fall", "The tsetse fly, active at midday"], 0, "Malaria is transmitted by the female Anopheles mosquito, which is active from dusk to dawn."),
          Q("presentation", "What is the typical incubation period for malaria?", ["9-30 days", "1-3 days", "6-8 weeks", "6-12 months"], 0, "Malaria has an incubation period of approximately 9-30 days."),
          Q("presentation", "What happens after the fever peak during a malarial paroxysm?", ["The fever falls with profuse sweating over 2-3 hours", "The patient becomes afebrile permanently", "A petechial rash appears", "The patient develops jaundice within minutes"], 0, "After the fever peak, the paroxysm resolves with profuse sweating over 2-3 hours."),
          Q("presentation", "Which species have a paroxysm periodicity of approximately every 48 hours?", ["P. vivax, P. falciparum, and P. ovale", "P. malariae only", "All four species share the same 72-hour periodicity", "None -- periodicity is random for all species"], 0, "P. vivax, P. falciparum, and P. ovale have paroxysms approximately every 48 hours; P. malariae has a 72-hour periodicity."),
          Q("presentation", "Why can P. vivax and P. ovale cause relapsing malaria years after the initial infection?", ["Residual hypnozoites persist dormant in the liver and can reactivate", "The mosquito re-injects new parasites into old bite wounds", "Chronic low-grade parasitemia in RBCs that was never cleared", "Reinfection is the only explanation; these species cannot truly relapse"], 0, "P. vivax and P. ovale form dormant liver hypnozoites that can reactivate and cause relapse up to 4 years after initial infection."),
          Q("presentation", "Which populations are at highest risk for severe malaria?", ["Children under 5, pregnant women, and travelers with no previous exposure", "Healthy young adult men only", "Only the elderly", "Only patients with a prior history of malaria"], 0, "Children under 5, pregnant women, and non-immune travelers are at highest risk for severe malaria."),
          Q("treatment", "Which medication is required to eliminate liver hypnozoites in P. vivax or P. ovale infection?", ["Primaquine", "Chloroquine", "Doxycycline", "Atovaquone-proguanil"], 0, "Primaquine is specifically required to eliminate liver hypnozoites in P. vivax/P. ovale infection; it is not needed for the other species."),
          Q("treatment", "Why is chloroquine used much less commonly for malaria treatment today?", ["Widespread resistance by P. falciparum", "It has been withdrawn from the market entirely", "It only treats P. malariae", "It requires G6PD testing before use"], 0, "Chloroquine use has declined significantly due to resistance by P. falciparum."),
          Q("prevention", "Which malaria chemoprophylaxis drug requires G6PD deficiency testing before use?", ["Tafenoquine", "Doxycycline", "Mefloquine", "Atovaquone-proguanil"], 0, "Tafenoquine requires G6PD deficiency testing before use, as it can cause hemolysis in G6PD-deficient patients."),
          Q("prevention", "Which malaria chemoprophylaxis agent is associated with intense dreams and seizure risk, and is dosed weekly?", ["Mefloquine", "Doxycycline", "Atovaquone-proguanil", "Tafenoquine"], 0, "Mefloquine has more side effects (intense dreams), carries a seizure risk, and is dosed weekly."),
          Q("prevention", "Which malaria chemoprophylaxis agent is taken daily, is inexpensive, but causes sun sensitivity and GI upset?", ["Doxycycline", "Mefloquine", "Atovaquone-proguanil", "Tafenoquine"], 0, "Doxycycline is dosed daily, is cheap, but causes sun sensitivity and GI upset."),
          Q("prevention", "What insecticide is used to treat bed nets for malaria prevention?", ["Permethrin", "DEET", "Picaridin", "Chlorine"], 0, "Bed nets are treated with permethrin for malaria prevention; DEET is used as a topical/skin insect repellent.")
        ]),

        D("amebiasis", "Amebiasis (Entamoeba histolytica)", "Protozoan with trophozoite/cyst forms causing dysentery and liver abscess; treated with metronidazole.", [
          S("overview", "Organism, Forms & Presentation", "<p>Protozoan infection of the lower GI tract causing amoebic dysentery (amoebiasis). Transmitted fecal-orally; increased in developing countries with inadequate sanitation.</p>" + Tbl(["Form", "Characteristics"], [
            ["Trophozoite", "Motile stage; colonizes lumen/mucosa of the large intestine (can invade tissues/organs); predominates in LIQUID stools; dies rapidly outside the body"],
            ["Cyst", "Forms when trophozoites in the colonic lumen encyst and are excreted with feces; predominates in FORMED stools; the infective/transmissible form"]
          ]) + "<p>Most infected persons are <strong>asymptomatic</strong> but chronically pass cysts in stool. Amoebic dysentery: frequent (semi)liquid stools that often contain blood, mucus, and live trophozoites.</p>"),
          S("diagnosis-treatment", "Diagnosis & Treatment", "<p>Diagnosis: finding E. histolytica in stool or tissue; need <strong>3-6 stool specimens</strong> with concentration methods to visualize trophs/cysts.</p>" + HY("Metronidazole is the treatment of choice for amebiasis."))
        ], [
          Q("overview", "Which form of Entamoeba histolytica predominates in liquid stool and is capable of tissue invasion?", ["The trophozoite", "The cyst", "The oocyst", "The schizont"], 0, "The motile trophozoite predominates in liquid stools and can invade tissues/organs; it dies rapidly outside the body."),
          Q("overview", "Which form of Entamoeba histolytica is responsible for transmission between hosts?", ["The cyst, which predominates in formed stool", "The trophozoite, which survives well outside the body", "Both forms transmit equally well", "Neither form is infective -- transmission requires a vector"], 0, "The cyst form, excreted in formed stool, is the infective/transmissible form since trophozoites die rapidly outside the body."),
          Q("overview", "What is the typical clinical status of most persons infected with E. histolytica?", ["Asymptomatic, chronically passing cysts in stool", "Severely symptomatic with dysentery in nearly all cases", "Universally fatal without treatment", "Symptomatic only in children, never adults"], 0, "Most infected persons are asymptomatic but chronically pass cysts in their stool."),
          Q("diagnosis-treatment", "How many stool specimens are typically needed to adequately diagnose amebiasis?", ["3-6 specimens with concentration methods", "A single specimen is always sufficient", "10 or more specimens", "Stool specimens are not useful for this diagnosis"], 0, "3-6 stool specimens with concentration methods are needed to reliably visualize trophozoites/cysts."),
          Q("diagnosis-treatment", "What is the treatment of choice for amebiasis (E. histolytica infection)?", ["Metronidazole", "Tinidazole", "Albendazole", "Primaquine"], 0, "Metronidazole is the treatment of choice for E. histolytica infection (note: tinidazole is the preferred drug for Giardia, a different organism).")
        ]),

        D("giardiasis", "Giardiasis (Giardia lamblia)", "Protozoan associated with mountain stream water causing foul, greasy diarrhea; treated with tinidazole.", [
          S("overview", "Organism, Source & Names", "<p>Pear-shaped, flagellated protozoan. Transmitted fecal-orally; commonly <strong>water-borne</strong> because Giardia is <strong>resistant to chlorine levels in normal tap water</strong> and survives well in <strong>cold mountain streams</strong>.</p>" + Mn("Other names", "Giardiasis is also known as \"backpacker's diarrhea\" or \"beaver fever.\"")),
          S("presentation-diagnosis", "Presentation & Diagnosis", "<p>Variable symptoms: nausea, vomiting, malaise, flatulence, cramping, diarrhea, <strong>steatorrhea</strong>, weight loss.</p><p>Diagnosis: <strong>stool O&P testing</strong>. Cysts occur intermittently in both formed and loose stools; trophozoites only found in diarrhea. Sensitivity of a single stool exam is only <strong>50-70%</strong>, increasing to <strong>85-95% with three serial specimens</strong>.</p>"),
          S("treatment", "Treatment", HY("Tinidazole is the preferred initial drug for giardiasis -- do not confuse with metronidazole, which is the drug of choice for E. histolytica.") + "<p>Antiparasitic treatment is appropriate for symptomatic individuals; some infections are self-limited. Patients should avoid transmission-risk settings (food handling, swimming pools) while infected.</p>")
        ], [
          Q("overview", "Why is Giardia lamblia commonly transmitted through drinking water?", ["It is resistant to chlorine levels used in normal tap water", "It cannot survive in water at all, only in food", "It requires an insect vector present near water sources", "It is destroyed by chlorination but survives freezing"], 0, "Giardia is resistant to chlorine levels found in normal tap water, making water-borne transmission common."),
          Q("overview", "Giardiasis is classically associated with what water source, giving it a common nickname?", ["Cold mountain streams (\"backpacker's diarrhea\")", "Stagnant floodwater", "Chlorinated swimming pools exclusively", "Ocean/seawater"], 0, "Giardia survives well in cold mountain streams, giving rise to the nickname \"backpacker's diarrhea\" (also \"beaver fever\")."),
          Q("presentation-diagnosis", "What type of stool finding is characteristic of giardiasis, reflecting malabsorption?", ["Steatorrhea", "Rice-water stool", "Bloody, mucoid stool", "Rose-colored stool"], 0, "Giardiasis classically causes steatorrhea (fatty, foul-smelling stool) among its variable symptoms."),
          Q("presentation-diagnosis", "How does the sensitivity of stool O&P testing for Giardia change with serial specimens?", ["It increases from 50-70% (single specimen) to 85-95% with three serial specimens", "It remains fixed at 99% regardless of specimen number", "A single specimen is always adequate; more specimens add nothing", "Sensitivity decreases with additional specimens due to degradation"], 0, "A single stool exam has only 50-70% sensitivity for Giardia; three serial specimens increase this to 85-95%."),
          Q("treatment", "What is the preferred initial drug for treating giardiasis?", ["Tinidazole", "Metronidazole", "Albendazole (as monotherapy for adult giardiasis)", "Primaquine"], 0, "Tinidazole is the preferred initial drug for giardiasis -- a common point of confusion with metronidazole, which is used for E. histolytica."),
          Q("treatment", "What behavior should a patient with active giardiasis avoid?", ["Food handling and swimming pools, to avoid transmitting infection to others", "All forms of physical activity", "Drinking any fluids", "Eating any solid food"], 0, "Patients with giardiasis (like anyone with diarrhea) should avoid transmission-risk settings such as food handling and swimming pools.")
        ]),

        D("pinworm", "Pinworm (Enterobius vermicularis)", "The most common helminth infection in the US; perianal itching, diagnosed with the Scotch tape test.", [
          S("overview", "Epidemiology, Life Cycle & Presentation", HY("Enterobius vermicularis is the most common cause of helminth infection in the US.") + "<p>Transmission: finger transfer of ova from the perianal area to fomites (clothing, bedding, furniture, rugs, toys); ova are picked up by a new host, transferred to the mouth, and swallowed. The <strong>female worm migrates to the perianal region, usually at night</strong>, to deposit ova within skinfolds.</p><p>Presentation: intestinal infestation characterized by <strong>perianal itching</strong> (classically worse at night).</p>"),
          S("diagnosis", "Diagnosis -- Scotch Tape Test", "<p>Ova are obtained in the <strong>early morning</strong> (before bathing/defecation) by patting perianal skinfolds with sticky tape, applying the tape sticky-side down on a glass slide, and viewing under a microscope. Repeat on <strong>5 successive mornings if necessary</strong> to rule out infestation.</p>"),
          S("treatment", "Treatment", Tbl(["Drug", "Regimen"], [
            ["Albendazole", "400mg PO once, repeat in 2 weeks"],
            ["Mebendazole", "100mg PO once, repeat in 2 weeks"],
            ["Pyrantel pamoate", "11mg/kg (max 1g) single dose, repeat in 2 weeks -- available OTC in the US"]
          ]) + HY("All three drugs require a repeat dose at 2 weeks, and the entire household must be treated -- contrast with Ascaris, which is single-dose only.") + "<p>All clothing/bedding must be washed.</p>")
        ], [
          Q("overview", "Enterobius vermicularis (pinworm) holds which distinction among helminth infections in the United States?", ["It is the most common helminth infection in the US", "It is the rarest helminth infection in the US", "It is fatal in the majority of untreated cases", "It occurs exclusively in returning international travelers"], 0, "Pinworm is the most common cause of helminth infection in the United States."),
          Q("overview", "How does pinworm ova transmission typically occur?", ["Finger transfer of ova from the perianal area to fomites, then to a new host's mouth", "Skin penetration by larvae in contaminated soil", "Mosquito bite", "Ingestion of undercooked meat"], 0, "Pinworm spreads via finger transfer of ova from the perianal area to fomites (clothing, bedding, toys), then to a new host's mouth."),
          Q("overview", "When does the female pinworm typically migrate to the perianal region to deposit ova?", ["Usually at night", "Only during the day", "Only during menstruation of the host", "Immediately after the host eats"], 0, "The female worm migrates to the perianal region, usually at night, to deposit ova within skinfolds -- explaining the nighttime itching."),
          Q("diagnosis", "How and when should the Scotch tape test be performed for suspected pinworm infection?", ["In the early morning, before bathing or defecation, patting perianal skinfolds with sticky tape", "At night, right before the patient goes to sleep", "Any time of day, with no special timing required", "Only after a bowel movement, using a stool sample"], 0, "The Scotch tape test is performed in the early morning (before bathing/defecation) by patting perianal skinfolds with sticky tape."),
          Q("diagnosis", "If the initial Scotch tape test is negative but pinworm is still suspected, what should be done?", ["Repeat the test on up to 5 successive mornings", "No further testing is ever indicated", "Proceed directly to stool O&P testing instead", "Order a single random stool sample"], 0, "The Scotch tape test should be repeated on 5 successive mornings if necessary to rule out infestation."),
          Q("treatment", "What is a required component of pinworm treatment beyond medicating the patient?", ["Treating the entire household and washing all clothing/bedding", "Isolating the patient from all household members for 6 months", "No additional measures are needed beyond the patient's medication", "Discarding all household furniture"], 0, "All household contacts need treatment, and clothing/bedding must be washed, since pinworm spreads easily among household members."),
          Q("treatment", "How does pinworm drug dosing differ from Ascaris treatment using the same medications?", ["Pinworm treatment requires a repeat dose at 2 weeks; Ascaris treatment is a single dose only", "Pinworm is single-dose only; Ascaris requires a 2-week repeat", "Both require identical 3-day dosing courses", "Different drugs entirely are used for each infection"], 0, "Albendazole, mebendazole, and pyrantel pamoate all require a repeat dose at 2 weeks for pinworm, but only a single dose for Ascaris.")
        ]),

        D("ascariasis", "Ascariasis (Ascaris lumbricoides)", "Large roundworm with a pulmonary migration phase before intestinal maturation.", [
          S("overview", "Epidemiology & Transmission", "<p>One of the most common helminthic infections worldwide -- <strong>~1 billion people infected</strong>. Most common in Asia, Africa, and South America; more common in rainy seasons and areas with poor sanitation/indiscriminate defecation. Transmitted by ingestion of water or food contaminated with Ascaris eggs.</p>"),
          S("presentation", "Life Cycle & Manifestations", "<p>Most patients are <strong>asymptomatic</strong>.</p>" + HY("Larval migration through the lungs can cause fever, coughing, and wheezing -- a distinctive pulmonary phase before the worm matures in the intestine.") + "<p>A large worm burden in the intestine can cause abdominal cramps and, occasionally, <strong>intestinal blockage -- most common in children</strong>. Adult worms may be vomited or passed in stool.</p>"),
          S("treatment", "Treatment", HY("Same three drugs as pinworm, but only a SINGLE dose -- no 2-week repeat is needed.") + "<p>Albendazole, mebendazole, or pyrantel pamoate. In endemic areas, mass treatment programs (\"worm holidays\") are effective. Prevention: improved sanitation and waste removal.</p>")
        ], [
          Q("overview", "Approximately how many people worldwide are infected with Ascaris lumbricoides?", ["~1 billion", "~1 million", "~10,000", "~100 million"], 0, "Ascariasis is one of the most common helminthic infections worldwide, with approximately 1 billion people infected."),
          Q("overview", "How is Ascaris lumbricoides transmitted to humans?", ["Ingestion of water or food contaminated with Ascaris eggs", "Skin penetration by larvae in soil", "Mosquito bite", "Sexual contact"], 0, "Ascariasis is transmitted by ingesting water or food contaminated with Ascaris eggs."),
          Q("presentation", "What pulmonary symptoms can occur during Ascaris larval migration through the lungs?", ["Fever, coughing, and wheezing", "Hemoptysis with pleuritic chest pain only", "Pulmonary edema and ARDS", "Chronic productive cough over years"], 0, "Larval migration through the lungs can cause fever, coughing, and wheezing before the worm matures in the intestine."),
          Q("presentation", "What is a serious intestinal complication of heavy Ascaris worm burden, especially in children?", ["Intestinal blockage", "Hemolytic uremic syndrome", "Toxic megacolon", "Perforation with peritonitis in the majority of cases"], 0, "A large worm burden can cause abdominal cramps and, occasionally, intestinal blockage, most common in children."),
          Q("treatment", "What is the correct dosing regimen for Ascaris treatment with albendazole, mebendazole, or pyrantel pamoate?", ["A single dose only -- no repeat is needed", "The same dose repeated in 2 weeks, as with pinworm", "Daily dosing for 3 months", "Weekly dosing for 6 weeks"], 0, "Unlike pinworm treatment (which requires a repeat dose at 2 weeks), Ascaris treatment with these same drugs is a single dose only."),
          Q("treatment", "What community-level intervention is used to control Ascaris in highly endemic areas?", ["Mass treatment programs (\"worm holidays\")", "Universal surgical removal of adult worms", "Mandatory quarantine of infected individuals", "Insecticide-treated bed nets"], 0, "In endemic areas, mass treatment programs (sometimes called \"worm holidays\") are an effective control strategy.")
        ]),

        D("hookworm", "Hookworm (Ancylostoma duodenale)", "Skin-penetrating helminth causing iron-deficiency anemia and unexplained eosinophilia.", [
          S("overview", "Epidemiology & Transmission", "<p>Common in tropics/subtropics; rare in regions with <strong>less than 40 inches of rainfall/year</strong>. Major morbidity impact is from <strong>anemia</strong>. Larvae hatch from eggs in soil.</p>" + HY("Three conditions are required for transmission: (1) human feces must contaminate soil, (2) soil conditions must support larval survival (moisture, warmth, shade), and (3) contaminated soil must contact human skin (e.g., walking barefoot) -- larvae penetrate the skin; occasionally transmitted orally.")),
          S("presentation", "Clinical Presentation", "<p>Asymptomatic in most cases. When symptomatic: a <strong>pruritic papulovesicular rash (\"ground itch\")</strong> at the site of larval skin penetration; adult worms in the intestine cause colicky epigastric pain, anorexia, flatulence, diarrhea, weight loss.</p><p>Chronic infection leads to <strong>iron-deficiency anemia and hypoproteinemia</strong> -- pallor, dyspnea, weakness, tachycardia, lethargy, impotence, edema.</p>"),
          S("diagnosis", "Diagnosis", Tbl(["Test", "Finding"], [
            ["Stool O&P", "May take up to 38 weeks after skin penetration to become positive -- not helpful before intestinal-tract disease is established"],
            ["CBC", "Unexplained eosinophilia -- always a clue to parasitic infection"],
            ["Endoscopy", "Worms occasionally identified incidentally"]
          ])),
          S("treatment", "Treatment", "<p>General support and correction of anemia may be needed first if infection is heavy/anemia severe, <strong>but antiparasitic treatment is required or the anemia will recur</strong>. Options: albendazole (400mg PO once), mebendazole (100mg BID for 3 days -- more effective than a single 500mg dose), or pyrantel pamoate (11mg/kg/day, max 1g, for 3 days).</p>")
        ], [
          Q("overview", "What three conditions must be met for hookworm transmission to occur?", ["Fecal soil contamination, favorable soil conditions (moisture/warmth/shade), and skin contact with contaminated soil", "Mosquito exposure, warm climate, and standing water", "Contaminated drinking water, poor sanitation, and crowding", "Direct person-to-person contact only"], 0, "Hookworm transmission requires: (1) human feces contaminating soil, (2) soil conditions supporting larval survival, and (3) contaminated soil contacting human skin."),
          Q("overview", "Hookworm infection is rare in regions with less than how much annual rainfall?", ["40 inches", "5 inches", "100 inches", "10 inches"], 0, "Hookworm is rare in regions with less than 40 inches of rainfall per year, since larvae need moist soil to survive."),
          Q("presentation", "What skin finding occurs at the site of larval penetration in hookworm infection?", ["A pruritic papulovesicular rash (\"ground itch\")", "An expanding annular lesion with central clearing", "A rose-colored papular rash", "A vesicular rash in a dermatomal distribution"], 0, "\"Ground itch\" -- a pruritic papulovesicular rash -- occurs at the site of larval skin penetration."),
          Q("presentation", "What is the major systemic complication of chronic hookworm infection?", ["Iron-deficiency anemia and hypoproteinemia", "Hemolytic uremic syndrome", "Toxic megacolon", "Rheumatic heart disease"], 0, "Chronic hookworm infection causes iron-deficiency anemia and hypoproteinemia, the major source of morbidity."),
          Q("diagnosis", "How long after skin penetration may stool O&P testing take to become positive in hookworm infection?", ["Up to 38 weeks", "24-48 hours", "1-2 weeks", "It is positive immediately upon skin penetration"], 0, "Stool O&P may take up to 38 weeks after skin penetration to become positive, since it is not useful until intestinal-tract disease is established."),
          Q("diagnosis", "What CBC finding is a classic clue to hookworm (or other parasitic) infection?", ["Unexplained eosinophilia", "Marked neutrophilia", "Thrombocytosis", "Lymphopenia"], 0, "Unexplained eosinophilia is always a clue to possible parasitic infection, including hookworm."),
          Q("treatment", "Why is antiparasitic treatment required even after correcting anemia in a heavily infected patient?", ["Without treating the underlying infection, the anemia will recur", "Antiparasitic treatment is optional once anemia is corrected", "Anemia correction alone cures the infection", "Antiparasitic drugs have no effect on hookworm-associated anemia"], 0, "General support and anemia correction may come first, but antiparasitic treatment is required or the anemia will recur."),
          Q("treatment", "How does the mebendazole regimen for hookworm compare to a single-dose approach?", ["100mg twice daily for 3 days is more effective than a single 500mg dose", "A single dose is always preferred and more effective", "Mebendazole is not used for hookworm at all", "Mebendazole requires a 2-week repeat, like pinworm treatment"], 0, "Mebendazole 100mg BID for 3 days is more effective for hookworm than a single 500mg dose.")
        ])
      ]),

      L("viral-diseases", "Viral Diseases", [
        D("influenza", "Influenza", "Orthomyxovirus with abrupt fever, myalgias, and cough; type A causes pandemics via antigenic shift. Watch for Reye syndrome with aspirin use in kids.", [
          S("overview", "Organism, Types & Epidemiology", Tbl(["Type", "Key features"], [
            ["Influenza A", "Subtyped by hemagglutinin (H, docks virus to sialic acid receptors -- vaccine target) and neuraminidase (N, releases progeny virus -- antiviral target). Capable of antigenic <strong>shift</strong> (major reassortment -&gt; pandemics, e.g. 1918 H1N1, 2009 H1N1, 2013 H7N9) and drift. Infects humans, birds, and other mammals."],
            ["Influenza B", "Drift only -- causes epidemics, not pandemics; humans only."],
            ["Influenza C", "Drift only, rare, mostly mild respiratory illness in children."]
          ]) + HY("Types A, B, and C are clinically indistinguishable by symptoms alone -- only influenza A undergoes shift and causes pandemics, because it also infects birds and other mammals.") + "<p>Transmission is by respiratory droplet. Incubation is 1-4 days, season runs October-May (peak December-March). Most concerning in pregnant, elderly, and immunocompromised patients; other high-risk groups include severe obesity, asthma/COPD, age &lt;5 or &gt;65, neurologic disorders, and nursing home residents.</p>"),
          S("presentation", "Clinical Presentation", "<p>Classic: <strong>sudden onset</strong> fever/chills (3-5 days), malaise, myalgias, substernal soreness, headache, coryza, nonproductive cough, sore throat, nasal congestion, and GI symptoms.</p>" + HY("Elderly patients often present atypically: lassitude and confusion are the most common findings, with mild pharyngeal injection and a flushed face -- fever and respiratory symptoms are often absent. Don't rely on 'fever + cough' alone to rule out flu in this group.") + "<p>Less common presentations include pneumonia, PE, seizures, encephalopathy, and myocarditis/pericarditis -- viral illness is prothrombotic and proinflammatory.</p>"),
          S("diagnosis", "Diagnosis & Workup", "<p>Primarily a <strong>clinical</strong> diagnosis: flu season + cough + fever &gt;100.4°F is highly predictive in patients over age 4 (less reliable in the elderly, who often lack these findings).</p>" + Tbl(["Test", "Notes"], [
            ["Rapid flu antigen test", "Most commonly used; distinguishes A vs. B; sensitivity only 11-70% (poor), specificity &gt;90%"],
            ["PCR / viral culture", "More accurate but slower"],
            ["CBC / UA", "Nonspecific -- leukopenia or leukocytosis, proteinuria"]
          ])),
          S("treatment", "Antiviral Treatment", "<p>Symptomatic care (antipyretics, rest, fluids) covers most patients. Antivirals give the most benefit if started within <strong>48 hours</strong> of symptom onset, but high-risk patients should still receive them regardless of timing -- benefit is shorter symptom duration and fewer complications, not reliably reduced hospitalization or mortality.</p>" + Tbl(["Drug", "Class / MOA", "Dosing", "Key notes"], [
            ["Oseltamivir (Tamiflu)", "Neuraminidase inhibitor", "75mg PO BID x5 days; prophylaxis 75mg PO daily x7-10 days", "Any age; caution in renal/cardiac/hepatic disease; contraindicated in ESRD without dialysis; rising resistance"],
            ["Zanamivir (Relenza)", "Neuraminidase inhibitor", "10mg (2 inhalations) BID x5 days", "Age &gt;7 years; contraindicated with milk allergy or underlying pulmonary disease/asthma (bronchospasm risk); Tamiflu-resistant strains generally still respond"],
            ["Peramivir (Rapivab)", "Neuraminidase inhibitor", "600mg IV single dose", "Age &gt;18 years only; Tamiflu-resistant strains generally do NOT respond"],
            ["Baloxavir (Xofluza)", "Endonuclease inhibitor -- blocks the PA protein needed for viral transcription", "Single dose: 40mg if 40-&lt;80kg, 80mg if &ge;80kg", "Only for age &gt;12 years AND &gt;40kg; may help Tamiflu-resistant cases but is slightly less effective overall"]
          ]) + Mn("No superior drug", "No antiviral agent has been shown to be better than the others -- choice depends on age, renal/hepatic status, and resistance, not superior efficacy.")),
          S("complications-prevention", "Complications & Prevention", "<p>Bacterial complications follow respiratory epithelial necrosis: sinusitis, otitis media, purulent bronchitis, pneumonia. Suspect secondary bacterial infection if fever recurs or persists beyond 4 days with productive cough and WBC &gt;10,000 -- pneumococcal pneumonia is most common, staphylococcal pneumonia is most serious.</p>" + HY("Reye syndrome: triggered by aspirin use during a viral illness in patients under 18, causing rapid progressive liver failure plus encephalopathy from ammonia buildup, with ~30% mortality. Avoid aspirin-containing products in anyone under 18 with viral symptoms.") + "<p>Seasonal vaccination is the most effective prevention, reducing hospitalization by 61%, and is recommended for everyone over 6 months old.</p>" + Tbl(["Vaccine form", "Notes"], [
            ["IM inactivated", "Deltoid (older children/adults) or anterolateral thigh (young children); SE = local irritation"],
            ["Intranasal live-attenuated (LAIV)", "Age &gt;2 years; contraindicated in asthmatics, those who took antivirals within 48 hours, HIV/immunocompromised patients, pregnancy, children under 2"]
          ]) + "<p>Contraindications for both forms: history of Guillain-Barré syndrome, acute febrile illness. Severe egg allergy is no longer a blanket contraindication with newer formulations.</p>")
        ], [
          Q("overview", "Which influenza type is capable of antigenic shift and therefore causes pandemics?", ["Influenza A", "Influenza B", "Influenza C", "All three types equally"], 0, "Only influenza A undergoes antigenic shift -- major genetic reassortment -- because it also infects birds and other mammals, enabling pandemics like 1918 and 2009 H1N1. B and C undergo drift only and cause epidemics at most."),
          Q("overview", "What does influenza's hemagglutinin (H) surface protein do?", ["Docks the virus onto sialic acid receptors; it is the target of the vaccine", "Releases progeny virus from the infected cell; it is the target of antivirals", "Blocks the host's interferon response", "Encodes the M2 ion channel"], 0, "Hemagglutinin mediates viral attachment and is the antigen vaccines target. Neuraminidase, by contrast, releases budding virus and is the target of antivirals like oseltamivir."),
          Q("overview", "Which patient population is influenza most likely to present atypically, without the classic fever/cough picture?", ["Elderly patients", "School-age children", "Healthy young adults", "Infants under 6 months"], 0, "Elderly patients often present with lassitude and confusion, mild pharyngeal injection, and a flushed face -- fever and respiratory symptoms are frequently absent, making 'fever + cough' unreliable in this group."),
          Q("presentation", "In an elderly patient with confirmed influenza, which classic findings are often ABSENT, unlike in younger patients?", ["Fever and respiratory symptoms", "Confusion and lassitude", "Mild pharyngeal injection", "A flushed face"], 0, "Elderly patients frequently develop influenza WITHOUT mounting a fever or showing respiratory symptoms -- lassitude and confusion are often the dominant findings instead, so their absence should not be used to rule out flu in this group."),
          Q("diagnosis", "What is the main limitation of the rapid flu antigen test?", ["Poor sensitivity (11-70%) despite good specificity", "It cannot distinguish influenza A from B", "It requires 3-5 days to result", "It is not approved for outpatient use"], 0, "The rapid antigen test is fast and can distinguish A from B, but its sensitivity is only 11-70% -- a negative result does not rule out influenza."),
          Q("treatment", "A patient presents on day 4 of flu symptoms but has COPD and is high-risk. Should antivirals still be given?", ["Yes -- high-risk patients should still receive antivirals regardless of the 48-hour window", "No -- antivirals are only effective if started within 48 hours", "No -- COPD is a contraindication to neuraminidase inhibitors", "Only if hospitalized"], 0, "Antiviral benefit is greatest within 48 hours, but high-risk patients should still receive treatment beyond that window because they remain at elevated risk for complications."),
          Q("treatment", "Which influenza antiviral is contraindicated in patients with a milk allergy?", ["Zanamivir (Relenza)", "Oseltamivir (Tamiflu)", "Peramivir (Rapivab)", "Baloxavir (Xofluza)"], 0, "Zanamivir's dry-powder inhaler formulation contains lactose, so it is contraindicated in milk allergy, and caution is needed in patients with underlying asthma/pulmonary disease due to bronchospasm risk."),
          Q("treatment", "Which antiviral is dosed as a single 600mg IV dose and is only approved for adults?", ["Peramivir (Rapivab)", "Oseltamivir (Tamiflu)", "Zanamivir (Relenza)", "Baloxavir (Xofluza)"], 0, "Peramivir is given as one IV dose and is approved only for patients over 18. It also generally does not work against Tamiflu-resistant strains, unlike zanamivir."),
          Q("treatment", "Baloxavir (Xofluza) works by which novel mechanism?", ["Inhibiting the endonuclease activity of the viral PA protein, blocking transcription", "Inhibiting neuraminidase to prevent viral release", "Blocking the M2 ion channel", "Inhibiting viral DNA polymerase"], 0, "Baloxavir is an endonuclease inhibitor, a mechanism distinct from the neuraminidase inhibitors (oseltamivir, zanamivir, peramivir) -- it blocks the PA protein needed for viral transcription."),
          Q("complications-prevention", "A previously healthy 12-year-old is given aspirin for fever during a viral illness and develops rapidly progressive liver failure with encephalopathy. What is this?", ["Reye syndrome", "Fulminant hepatitis A", "Toxic shock syndrome", "Acetaminophen toxicity"], 0, "Reye syndrome follows aspirin use during a viral illness in patients under 18, causing rapid liver failure and encephalopathy from ammonia buildup, with ~30% mortality -- aspirin should be avoided in this age group with viral symptoms."),
          Q("complications-prevention", "A flu patient's fever resolves, then recurs on day 6 with a productive cough and a WBC of 14,000. What should be suspected?", ["Secondary bacterial pneumonia", "Reye syndrome", "Recurrent influenza infection", "A normal post-viral cough"], 0, "Fever recurring or persisting beyond 4 days with productive cough and leukocytosis suggests secondary bacterial infection -- pneumococcal pneumonia is the most common cause, staphylococcal pneumonia the most serious."),
          Q("complications-prevention", "The intranasal live-attenuated influenza vaccine (LAIV) is contraindicated in which patient?", ["A 5-year-old with asthma", "A healthy 8-year-old", "A healthy 30-year-old", "A 25-year-old without comorbidities"], 0, "LAIV is contraindicated in asthmatics (and in pregnancy, HIV/immunocompromise, children under 2, and those who took antivirals within 48 hours) because the live-attenuated virus can trigger bronchospasm/exacerbations in reactive airway disease.")
        ]),
        D("hsv", "Herpes Simplex Virus (HSV-1 / HSV-2)", "Recurrent vesicular mucocutaneous disease; can cause encephalitis, neonatal infection, and Bell's palsy.", [
          S("overview", "Virology & Epidemiology", "<p>Enveloped dsDNA herpesviruses: HHV-1 (HSV-1) and HHV-2 (HSV-2). Historically HSV-1 = 'oral' and HSV-2 = 'genital,' but in practice the clinical lines have blurred and type does not dictate anatomic site. HSV causes <strong>cell lysis</strong> (acute blisters/ulcers/keratitis/encephalitis) -- contrast with EBV/HHV-8, which persist latently and drive malignancy instead.</p>" + Tbl(["Infection pattern", "Detail"], [
            ["Primary", "No pre-existing antibody; HSV-1 is the more common cause"],
            ["Nonprimary", "New type acquired with pre-existing antibody to the other type"],
            ["Recurrent", "Same type, pre-existing antibody; HSV-2 is the more common cause of recurrence, increasing with sexual activity"]
          ]) + HY("HSV-2 and HIV interact bidirectionally: HSV-2 raises HIV acquisition risk about 3-fold, while HIV causes HSV-2 to reactivate and shed more -- suppressing HSV-2 lowers both genital shedding and plasma HIV levels.") + "<p>Transmission is via intimate, not necessarily sexual, contact (e.g. kissing infants, shared secretions in daycare). Asymptomatic shedding is common and is more frequent with HSV-1.</p>"),
          S("presentation", "Site-Based Syndromes", "<p>Classic lesion: <strong>'dew drops on a rose petal'</strong> -- vesicles on an erythematous base. The first eruption is the most painful; untreated vesicles re-epithelialize in 1-2 weeks. Reactivation triggers include stress, fever, sunlight, and immunosuppression.</p>" + Tbl(["Site", "Key features"], [
            ["Mucocutaneous", "Labialis (cold sores); gingivostomatitis (most common presentation in children)"],
            ["Skin", "Herpetic whitlow (fingers/thumb); herpes gladiatorum (wrestlers -- 'mat herpes')"],
            ["Genital", "Urogenital/perigenital/perianal; proctitis more common in MSM; can latent in pre-sacral ganglia causing dysuria, cervicitis, urinary retention"],
            ["Ocular (emergency)", "Keratitis -- monocular; epithelial-only usually heals, but stromal involvement risks uveitis, scarring, blindness. Classic finding: 'herpetic dendrite.' Also blepharitis, retinitis (acute retinal necrosis, shared with VZV)"],
            ["CNS", "Herpes encephalitis -- usually HSV-1, classically <strong>temporal lobe</strong>, presents with headache, fever, behavioral/speech change, seizures. Aseptic meningitis -- usually HSV-2 primary infection, usually in females"],
            ["Neonatal", "Vertical transmission, most commonly via vaginal delivery with 3rd-trimester maternal infection; often asymptomatic (~70%); C-section may be required with active lesions at delivery"]
          ]) + Mn("Bell's palsy", "Linked to HSV (usually HSV-1) though still labeled 'idiopathic' -- an LMN facial paralysis with abrupt onset; ear pain may precede or accompany it. Bilateral Bell's palsy should instead raise suspicion for Lyme disease.")),
          S("diagnosis", "Diagnosis & Workup", "<p>Usually a <strong>clinical</strong> diagnosis (visualization is often sufficient).</p>" + Tbl(["Test", "Use"], [
            ["PCR", "Most sensitive test overall"],
            ["Viral culture + DFA staining", "Acceptable but usually unnecessary"],
            ["Type-specific serology", "Useful for HIV workup, pregnancy, partner counseling, unclear history"],
            ["Tzanck smear", "Shows intranuclear inclusions + multinucleated giant cells -- NOT type-specific, seen in any herpesvirus"],
            ["HSV DNA PCR (CSF)", "For suspected encephalitis -- rapid and specific early, but 25% false-negative rate, especially in children; MRI classically shows increased temporal lobe signal"]
          ])),
          S("treatment", "Treatment", "<p>Both drugs inhibit viral DNA polymerase. Ocular disease is an emergency -- call ophthalmology.</p>" + Tbl(["Drug", "Dosing (immunocompetent)", "Notes"], [
            ["Valacyclovir (Valtrex)", "Initial episode: 1g PO BID x7-10 days. Recurrent: 500mg PO BID x3 days OR 1g PO daily x5 days", "Prodrug of acyclovir; dose-adjust for renal (not hepatic) impairment; better tolerated (BID dosing) but more expensive than acyclovir"],
            ["Acyclovir (Zovirax)", "Initial episode: 200mg PO 5x/day x7-10 days. Recurrent: 400mg PO TID or 800mg PO BID x5 days", "Same MOA and contraindications as valacyclovir; dose-adjust for renal impairment"]
          ]) + "<p>Topical agents are not proven effective. Severe or immunocompromised disease may warrant IV therapy.</p>" + HY("Bell's palsy 'cocktail,' started within 72 hours for best outcome: (1) prednisolone 25mg BID x10 days, (2) an antiviral as above, (3) eye drops + taping the eye shut at night to protect the cornea.")),
          S("high-yield", "High-Yield Distinguishing Facts", Tbl(["Comparison", "Distinguishing point"], [
            ["Bell's palsy vs. stroke", "Bell's palsy (LMN) affects the whole side of the face, forehead included; stroke (UMN) classically spares the forehead due to bilateral cortical innervation"],
            ["Bilateral Bell's palsy", "Think Lyme disease, often with flu-like symptoms"],
            ["Tzanck smear", "Multinucleated giant cells are seen in any herpesvirus (HSV or VZV) -- not specific to HSV"],
            ["HSV encephalitis", "Classic temporal lobe localization on MRI/EEG"],
            ["Congenital HSV vs. CMV/rubella", "HSV is transmitted intrapartum (vertical, during delivery); CMV/rubella are transplacental"]
          ]))
        ], [
          Q("overview", "Which statement about HSV-1 vs. HSV-2 is most accurate in current clinical practice?", ["Clinical lines have blurred -- type does not reliably predict anatomic site", "HSV-1 only ever causes oral lesions", "HSV-2 only ever causes genital lesions", "HSV-1 and HSV-2 cannot cause disease at the other's classic site"], 0, "While HSV-1 was historically 'oral' and HSV-2 'genital,' in practice either type can cause disease at either site, and type no longer reliably predicts anatomic location."),
          Q("overview", "Which infection pattern is HSV-2 the more common cause of?", ["Recurrent infection", "Primary infection", "Neonatal transplacental infection", "Congenital rubella-like syndrome"], 0, "HSV-1 is the more common cause of primary infection overall, but HSV-2 is the more common cause of recurrent infection, and recurrence risk increases with sexual activity."),
          Q("overview", "How does HSV-2 affect HIV risk?", ["It increases HIV acquisition risk roughly 3-fold", "It has no effect on HIV transmission", "It only affects HIV risk in men", "It decreases HIV acquisition risk by reducing genital inflammation"], 0, "HSV-2 and HIV interact bidirectionally -- HSV-2 infection raises HIV acquisition risk about 3-fold, and HIV in turn increases HSV-2 reactivation and shedding."),
          Q("presentation", "A patient with HSV-associated Bell's palsy has facial paralysis that includes the forehead. How does this help distinguish it from a stroke?", ["Bell's palsy is an LMN lesion involving the whole face including the forehead; stroke (UMN) classically spares the forehead", "Bell's palsy never involves the forehead, unlike stroke", "Both conditions spare the forehead equally", "Forehead involvement has no localizing value"], 0, "Bell's palsy is a lower motor neuron (LMN) lesion, so it involves the entire side of the face including the forehead. Stroke is an upper motor neuron (UMN) lesion, and because the forehead receives bilateral cortical innervation, forehead movement is classically spared in a stroke-related facial droop."),
          Q("presentation", "A patient develops bilateral facial palsy along with flu-like symptoms. What should be strongly suspected instead of typical Bell's palsy?", ["Lyme disease", "HSV encephalitis", "Ramsay Hunt syndrome", "Parvovirus B19 infection"], 0, "Bilateral Bell's palsy is an atypical presentation that should raise suspicion for Lyme disease rather than idiopathic/HSV-associated Bell's palsy, which is typically unilateral."),
          Q("presentation", "Which HSV syndrome classically localizes to the temporal lobe on imaging?", ["HSV encephalitis", "HSV aseptic meningitis", "Herpetic whitlow", "Neonatal HSV"], 0, "HSV encephalitis, usually caused by HSV-1, classically shows increased temporal lobe signal on MRI and focal temporal seizure activity on EEG."),
          Q("presentation", "Vertical transmission of HSV to a neonate most commonly occurs via which route?", ["Vaginal delivery when the mother has a 3rd-trimester infection", "Transplacental transmission in the 1st trimester", "Breastfeeding", "Airborne transmission in the nursery"], 0, "Neonatal HSV is most commonly transmitted intrapartum during vaginal delivery when the mother has an active 3rd-trimester infection -- distinct from the transplacental pattern of CMV and rubella."),
          Q("diagnosis", "What is the most sensitive test for diagnosing HSV infection?", ["PCR", "Tzanck smear", "Viral culture", "Type-specific serology"], 0, "PCR is the most sensitive test for HSV and is the preferred method, especially for suspected encephalitis, though CSF PCR still carries a 25% false-negative rate early in encephalitis, especially in children."),
          Q("diagnosis", "A Tzanck smear shows multinucleated giant cells. What does this tell you?", ["The lesion is herpetic, but it cannot distinguish HSV from VZV", "The lesion is definitively HSV-1, not HSV-2", "The lesion is definitively HSV, not VZV", "The test is diagnostic of neonatal HSV specifically"], 0, "Multinucleated giant cells on Tzanck smear confirm a herpetic etiology but are not specific -- they appear in HSV and VZV lesions alike."),
          Q("treatment", "What is the preferred antiviral dosing for an initial genital HSV episode?", ["Valacyclovir 1g PO BID x7-10 days", "Valacyclovir 500mg PO BID x3 days", "Acyclovir 400mg PO TID x5 days", "Acyclovir 800mg PO 5x/day x7 days"], 0, "Initial-episode dosing is valacyclovir 1g PO BID x7-10 days (or acyclovir 200mg PO 5x/day x7-10 days) -- higher and longer than the recurrent-episode regimens."),
          Q("treatment", "A patient with Bell's palsy presents within 48 hours of onset. What is the recommended treatment approach?", ["Prednisolone 25mg BID x10 days, an antiviral, and eye protection (drops + taping shut at night)", "Antiviral therapy alone, no steroids", "High-dose IV acyclovir for all cases", "Observation only, since Bell's palsy always resolves"], 0, "The Bell's palsy 'cocktail,' best started within 72 hours, is prednisolone 25mg BID x10 days plus an antiviral plus eye protection to prevent corneal exposure injury from incomplete eyelid closure."),
          Q("treatment", "A patient with a herpetic corneal dendrite is diagnosed with HSV keratitis. What is the appropriate next step?", ["Emergent ophthalmology referral", "Oral valacyclovir alone with routine follow-up", "Reassurance since epithelial keratitis always resolves without treatment", "Topical antiviral cream only, no referral needed"], 0, "Ocular HSV disease is an emergency -- stromal involvement risks uveitis, scarring, and blindness, so ophthalmology should be involved immediately.")
        ]),
        D("varicella", "Varicella (Chickenpox)", "Primary VZV infection with a pruritic, centrally-starting, multi-stage vesicular rash.", [
          S("overview", "Organism & Epidemiology", "<p>Caused by varicella-zoster virus (VZV, HHV-3) -- the same virus that reactivates as herpes zoster. Generally a childhood disease. Incubation is <strong>10-20 days</strong>. Highly contagious via respiratory droplet (often with cold-like symptoms) and direct cutaneous contact with vesicle fluid.</p>"),
          S("presentation", "Clinical Presentation", "<p>Prodrome: fever (&ge;100.4°F), malaise, nonspecific URI/viral symptoms <strong>before</strong> rash onset.</p><p>Rash progression: macule &rarr; papule &rarr; vesicle (within hours) &rarr; pustule (1-5 days) &rarr; crust (sloughs over ~2 weeks). It is <strong>pruritic</strong>, begins centrally, and spreads peripherally, with truncal predominance.</p>" + HY("The classic distinguishing feature is that multiple rash stages are present simultaneously across the body ('crops,' a polymorphic rash) -- this sets varicella apart from most other viral exanthems, which progress through one stage at a time (e.g. measles, rubella).")),
          S("diagnosis-treatment", "Diagnosis & Treatment", "<p>Typically a clinical diagnosis; DFA staining or PCR of lesion scrapings can confirm. Tzanck smear shows multinucleated giant cells, as with all herpetic eruptions -- not specific to VZV.</p><p>Treatment is primarily <strong>supportive</strong>: isolation until all lesions are crusted, bed rest until afebrile, keep skin clean, groom nails to prevent excoriation (which risks bacterial superinfection), and treat pruritus. Antivirals are given only in select circumstances, not routinely. Prognosis is generally good.</p>"),
          S("complications-prevention", "Complications & Prevention", "<p>Secondary bacterial skin superinfection (group A strep, staph) can cause cellulitis, erysipelas, or scarlet fever. Rare complications include encephalitis, necrotizing pneumonia, and ischemic stroke about 4 months post-rash (reactive vasculitis). In pregnancy, 1st/2nd-trimester infection carries a small risk of congenital malformation, while peripartum infection risks disseminated neonatal disease.</p>" + Tbl(["Prevention measure", "Detail"], [
            ["Vaccination", "Most effective prevention; scheduled at 15 months, then 4-6 years"],
            ["Post-exposure vaccination", "Available for the unvaccinated"],
            ["VariZIG (VZV immunoglobulin)", "Post-exposure prophylaxis for susceptible, exposed patients who cannot receive the vaccine (infants, immunosuppressed)"],
            ["Hospital precautions", "Standard + contact + airborne"]
          ]) + "<p>Vaccine-associated rash, if it occurs, has a notably delayed onset of 15-42 days post-vaccination.</p>")
        ], [
          Q("overview", "What is the incubation period for varicella?", ["10-20 days", "1-4 days", "24-48 hours", "4-6 weeks"], 0, "Varicella has a relatively long incubation period of 10-20 days (about 2-3 weeks) between exposure and rash onset."),
          Q("presentation", "What is the classic distinguishing feature of the varicella rash compared to most other viral exanthems?", ["Multiple rash stages (macule, papule, vesicle, crust) are present simultaneously across the body", "The rash appears only on palms and soles", "The rash is never pruritic", "The rash always starts on the face and never spreads"], 0, "Varicella's rash appears in 'crops' -- new lesions keep forming while older ones crust, so multiple stages coexist at once. This polymorphic pattern distinguishes it from single-stage exanthems like measles or rubella."),
          Q("presentation", "Where does the varicella rash characteristically begin and spread?", ["Begins centrally (trunk) and spreads peripherally", "Begins on the palms and soles and spreads centrally", "Begins behind the ears and spreads down the body", "Begins on the face only and never spreads to the trunk"], 0, "Varicella's rash begins centrally with truncal predominance and spreads peripherally -- a different pattern from measles, which starts at the hairline and spreads downward reaching palms/soles last."),
          Q("diagnosis-treatment", "What is the mainstay of varicella treatment in an otherwise healthy child?", ["Supportive care -- keep skin clean, groom nails, treat pruritus, isolate until crusted", "Routine antiviral therapy for all cases", "Prophylactic antibiotics to prevent bacterial superinfection", "Hospitalization for IV acyclovir"], 0, "Uncomplicated varicella in a healthy child is managed supportively; antivirals are reserved for select circumstances rather than given routinely."),
          Q("complications-prevention", "Why is nail grooming recommended during varicella?", ["To prevent excoriation of lesions, which risks bacterial superinfection", "To prevent spread of the virus through fingernails", "To reduce fever", "To prevent postherpetic neuralgia"], 0, "Scratching pruritic vesicles can excoriate the skin and introduce bacteria, leading to superinfection with organisms like group A strep or staph -- nail grooming reduces this risk."),
          Q("complications-prevention", "What is the varicella vaccination schedule?", ["15 months, then 4-6 years", "Birth, then 2 months", "Single dose at 12 months only", "Annually starting at age 1"], 0, "The varicella vaccine is given in two doses: at 15 months and again at 4-6 years of age.")
        ]),
        D("herpes-zoster", "Herpes Zoster (Shingles)", "Reactivated VZV in a dermatomal distribution; risk rises sharply with age. Watch for postherpetic neuralgia.", [
          S("overview", "Reactivation & Epidemiology", "<p>Herpes zoster results from reactivation of latent VZV from cranial nerve sensory ganglia and dorsal root ganglia. Most common after age 60, with incidence and severity increasing with age -- by age 80, there is a <strong>&gt;50% lifetime risk</strong>.</p>"),
          S("presentation", "Clinical Presentation", "<p><strong>Severe pain often precedes the rash</strong>, and pain is typically more prominent than pruritus. The rash follows a <strong>dermatomal distribution</strong> (except in disseminated disease), most commonly thoracic and lumbar nerve roots.</p>" + Tbl(["Named syndrome", "Key features"], [
            ["Hutchinson's sign", "Lesion on the tip, side, or bridge of the nose, or inner corner of the eye -- heralds CN V1 (ophthalmic trigeminal) involvement and herpes zoster ophthalmicus (risk of keratitis, scarring, vision loss)"],
            ["Ramsay Hunt syndrome", "Facial nerve palsy + geniculate ganglion involvement; lesions over the external ear ± tympanic membrane, vertigo, tinnitus, deafness"]
          ]) + Mn("Bell's palsy vs. Ramsay Hunt", "Bell's palsy = facial palsy with NO rash. Ramsay Hunt = facial palsy WITH ear vesicles and vestibulocochlear symptoms, and it is more severe with a lower recovery rate than Bell's palsy.")),
          S("treatment", "Treatment", Tbl(["Drug", "Dosing (immunocompetent)", "Notes"], [
            ["Valacyclovir", "1g PO TID x7 days", "Drug of choice over acyclovir, mainly for adherence/convenience (TID vs. 5x/day); same dosing for initial and recurrent episodes"],
            ["Acyclovir", "800mg PO 5x/day x7 days", "Alternative to valacyclovir"]
          ]) + "<p>Best started within <strong>72 hours</strong> of onset. Reduces duration of lesions but does not reliably reduce PHN risk. Corticosteroids (prednisone, methylprednisolone, dexamethasone) reduce inflammation and lesion duration but also do not prevent PHN.</p>" + HY("Postherpetic neuralgia (PHN) is treated separately from the acute antiviral course: gabapentin, lidocaine patches, TCAs, and opioids (not first-line) are used; topical creams provide minimal relief.")),
          S("prevention", "Complications & Prevention", "<p>PHN affects about <strong>70%</strong> of patients with zoster, is very debilitating, and risk increases with age (typically &gt;60), female sex, and rash/pain severity. Other complications: zoster ophthalmicus, bacterial superinfection, septic meningitis, encephalitis, acute retinal necrosis.</p>" + HY("Shingrix, the adult herpes zoster vaccine, is no longer a live vaccine. It is given as 2 doses and offered to those over 50, or those over 18 with significant comorbidities. It reduces zoster risk in both immunocompetent and immunocompromised persons and helps prevent PHN.") + "<p>Zoster occurring in a dermatomal distribution in a young, otherwise healthy patient should raise concern for underlying immunosuppression (e.g. HIV).</p>")
        ], [
          Q("overview", "Herpes zoster results from reactivation of latent VZV in which location?", ["Cranial nerve sensory ganglia and dorsal root ganglia", "Peripheral motor neurons only", "The liver, where the virus persists after primary infection", "Circulating B lymphocytes"], 0, "VZV establishes latency in the sensory ganglia (cranial nerve and dorsal root) after primary varicella infection, then reactivates there to cause zoster."),
          Q("presentation", "Which typically comes first in herpes zoster -- pain or rash?", ["Pain often precedes the rash", "The rash always precedes pain", "Pain and rash always appear simultaneously", "Neither pain nor rash typically occurs"], 0, "Severe pain frequently precedes the dermatomal rash in herpes zoster, and pain tends to be more prominent than itching throughout the illness."),
          Q("presentation", "A patient has a vesicular lesion on the tip of the nose. What does this finding (Hutchinson's sign) indicate?", ["CN V1 (ophthalmic trigeminal) involvement, warranting urgent ophthalmology referral", "CN VII involvement with facial palsy", "A benign finding requiring no further workup", "Involvement of the geniculate ganglion specifically"], 0, "A lesion on the nose tip, side, bridge, or inner corner of the eye is Hutchinson's sign, indicating trigeminal (CN V1, ophthalmic division) involvement -- it warrants urgent ophthalmology referral given the risk of ocular involvement, including keratitis, scarring, and vision loss."),
          Q("presentation", "A patient has facial nerve palsy along with vesicles over the external ear, vertigo, and tinnitus. What is this?", ["Ramsay Hunt syndrome", "Bell's palsy", "Herpes zoster ophthalmicus", "Trigeminal neuralgia"], 0, "Ramsay Hunt syndrome is facial nerve palsy plus geniculate ganglion involvement, presenting with ear vesicles and vestibulocochlear symptoms (vertigo, tinnitus, deafness) -- distinguishing it from Bell's palsy, which has no rash."),
          Q("presentation", "How does Ramsay Hunt syndrome compare to Bell's palsy in prognosis?", ["Ramsay Hunt is more severe with a lower recovery rate", "Ramsay Hunt has a better recovery rate", "The two conditions have identical prognoses", "Ramsay Hunt always fully resolves within a week"], 0, "Ramsay Hunt syndrome tends to be more severe and has a lower recovery rate compared to Bell's palsy."),
          Q("treatment", "Why is valacyclovir generally preferred over acyclovir for treating herpes zoster?", ["It is dosed TID rather than 5 times a day, improving adherence", "It is the only agent proven to prevent PHN", "Acyclovir is not effective against VZV", "Valacyclovir is safe in renal impairment while acyclovir is not"], 0, "Valacyclovir and acyclovir have comparable efficacy against VZV, but valacyclovir's TID dosing (vs. acyclovir's 5x/day) makes it more convenient and is the main reason it's preferred -- neither reliably prevents PHN."),
          Q("treatment", "Within what timeframe should zoster antiviral therapy ideally begin?", ["72 hours of rash onset", "24 hours of rash onset", "7 days of rash onset", "Timing does not affect outcomes"], 0, "Antiviral therapy for zoster is best started within 72 hours of onset to reduce the duration of lesions, though it does not reliably reduce the risk of postherpetic neuralgia."),
          Q("prevention", "What percentage of herpes zoster patients develop postherpetic neuralgia?", ["About 70%", "About 10%", "About 95%", "PHN essentially never occurs"], 0, "PHN is common, affecting roughly 70% of zoster patients, and is more likely with older age, female sex, and greater rash/pain severity."),
          Q("prevention", "Who should be offered the Shingrix herpes zoster vaccine?", ["Adults over 50, or adults over 18 with significant comorbidities", "Only immunocompromised adults over 65", "Children who have not yet had varicella", "Only patients who have already had a zoster episode"], 0, "Shingrix (no longer a live vaccine) is a 2-dose series offered to adults over 50, or those over 18 with significant comorbidities, and reduces zoster risk in both immunocompetent and immunocompromised patients.")
        ]),
        D("ebv", "Epstein-Barr Virus (Infectious Mononucleosis)", "Causes mono and is linked to Burkitt lymphoma, Hodgkin lymphoma, and nasopharyngeal carcinoma.", [
          S("overview", "Virology & Epidemiology", "<p>EBV (HHV-4) is a herpesvirus that persists latently and can drive malignant transformation, in contrast to HSV/VZV's lytic mechanism that causes blisters and ulcers rather than cancer. It is ubiquitous -- over 90% of the population is infected, with lifelong latency. Peak clinical prevalence is ages 12-19 ('kissing disease'). Transmission is mainly via <strong>saliva</strong>, occasionally genital secretions, and patients remain contagious for 6-12 months post-convalescence.</p>"),
          S("presentation", "Clinical Presentation", "<p>Fatigue, malaise, fever, sore throat, anorexia, myalgias. <strong>Tender lymphadenopathy, classically posterior cervical</strong> (vs. anterior cervical in strep pharyngitis). Oral findings: soft palate petechiae, exudative pharyngitis, tonsillitis. <strong>Splenomegaly</strong>, sometimes severe.</p>" + HY("A rash occurs spontaneously in ~15% of mono cases, but in ~90% if the patient is given amoxicillin or ampicillin -- this is not a true penicillin allergy, but a classic tip-off for mono in a patient with pharyngitis.")),
          S("diagnosis", "Diagnosis & Workup", "<p><strong>Monospot</strong> test may be negative for the first 1-2 weeks (low early sensitivity, peaking around week 4) -- repeat if initially negative with high suspicion.</p><p>CBC shows initial granulocytopenia progressing to <strong>lymphocytic leukocytosis with atypical lymphocytes</strong> by about 1 week.</p><p>Serology: <strong>IgM present at onset; IgG appears around week 6 and persists for life.</strong> If both IgM and IgG are absent, reconsider the diagnosis and consider CMV.</p>" + HY("Monospot-negative mono symptoms should raise suspicion for CMV -- the two viruses cause a nearly identical clinical picture, but only EBV reliably turns the monospot positive.")),
          S("treatment-complications", "Treatment & Complications", "<p>Treatment is supportive: acetaminophen and/or NSAIDs (acetaminophen may be avoided given hepatitis risk). <strong>There is no evidence for antivirals or corticosteroids.</strong> Patients should <strong>avoid contact sports/aggressive activity for 4 weeks</strong> to reduce splenic rupture risk, even without detectable splenomegaly. If secondary strep pharyngitis is confirmed, treat with <strong>azithromycin</strong> -- avoid penicillin/ampicillin/amoxicillin due to the delayed hypersensitivity rash.</p>" + HY("EBV latency drives several malignancies: Burkitt lymphoma, B-cell lymphoma, nasopharyngeal carcinoma, and Hodgkin lymphoma. It also causes post-transplant lymphoproliferative disorder when an EBV-naive recipient receives an organ from an EBV-positive donor."))
        ], [
          Q("overview", "How is EBV primarily transmitted?", ["Saliva ('kissing disease')", "Fecal-oral route", "Respiratory droplets only", "Vector-borne (tick or mosquito)"], 0, "EBV is transmitted mainly through saliva, earning mononucleosis its nickname 'the kissing disease,' with peak clinical prevalence in the 12-19 age group."),
          Q("overview", "How does EBV's mechanism of malignancy differ from HSV/VZV?", ["EBV persists latently and drives malignant transformation; HSV/VZV cause lytic cell death (blisters/ulcers) instead", "EBV causes lytic disease while HSV/VZV persist latently and cause cancer", "All herpesviruses cause malignancy equally", "EBV cannot establish latency"], 0, "EBV's defining feature among the herpesviruses discussed is that it persists latently and can drive malignant transformation, unlike HSV/VZV, which cause acute lytic disease (blisters, ulcers, keratitis, encephalitis)."),
          Q("presentation", "Which lymph node chain is classically involved in EBV mononucleosis, helping distinguish it from strep pharyngitis?", ["Posterior cervical", "Anterior cervical", "Inguinal", "Axillary"], 0, "Mono classically causes posterior cervical lymphadenopathy, whereas strep pharyngitis more classically involves the anterior cervical chain."),
          Q("presentation", "A college student with confirmed EBV mononucleosis is given amoxicillin for presumed strep pharyngitis and develops a diffuse rash. What best explains this rash?", ["A virus-drug interaction, not a true penicillin allergy", "A true, dangerous penicillin allergy requiring lifelong avoidance", "Anaphylaxis requiring epinephrine", "An unrelated, coincidental drug reaction"], 0, "About 90% of mono patients develop a rash when given amoxicillin or ampicillin -- this reflects a virus-drug interaction rather than a true allergy, though it remains a classic diagnostic tip-off for mono when the diagnosis isn't yet known."),
          Q("diagnosis", "A mono-suspected patient has a negative monospot on day 3 of illness. What is the best next step?", ["Repeat the monospot later, since early sensitivity is low", "Rule out EBV entirely", "Diagnose CMV without further testing", "Start empiric antivirals"], 0, "The monospot has low sensitivity in the first 1-2 weeks of illness and peaks around week 4, so a negative early test should be repeated if clinical suspicion remains high rather than used to rule out EBV."),
          Q("diagnosis", "What does the presence of EBV IgM without IgG indicate?", ["Acute/recent infection", "Past infection or vaccination", "A false-positive result requiring no follow-up", "Chronic latent infection only"], 0, "IgM appears at symptom onset and indicates acute infection; IgG appears around week 6 and persists for life. If both are absent despite mono-like symptoms, CMV should be considered instead."),
          Q("treatment-complications", "Why should a mono patient avoid contact sports for 4 weeks, even without palpable splenomegaly?", ["To reduce the risk of splenic rupture", "To prevent transmission to teammates", "To avoid triggering a Burkitt lymphoma", "To prevent post-transplant lymphoproliferative disorder"], 0, "EBV mononucleosis carries a risk of splenic enlargement and rupture, which can occur even without detectable splenomegaly on exam -- contact sports should be avoided for about 4 weeks."),
          Q("treatment-complications", "If a mono patient develops confirmed secondary strep pharyngitis, which antibiotic should be used?", ["Azithromycin", "Amoxicillin", "Ampicillin", "Penicillin VK"], 0, "Amoxicillin, ampicillin, and penicillin should be avoided in mono patients due to the high rate of delayed hypersensitivity rash -- azithromycin is used instead if secondary strep is confirmed."),
          Q("treatment-complications", "Which malignancy is classically associated with EBV's oncogenic latency?", ["Burkitt lymphoma", "Kaposi sarcoma", "Cervical cancer", "Merkel cell carcinoma"], 0, "EBV is linked to Burkitt lymphoma, B-cell lymphoma, Hodgkin lymphoma, nasopharyngeal carcinoma, and post-transplant lymphoproliferative disorder, reflecting its latent oncogenic potential.")
        ]),
        D("cmv", "Cytomegalovirus (CMV)", "Mono-like illness in immunocompetent hosts; congenital infection and end-organ disease in the immunosuppressed.", [
          S("overview", "Virology & Epidemiology", "<p>CMV (HHV-5) is generally asymptomatic in immunocompetent hosts but causes more severe disease in the immunocompromised, remaining latent after primary infection. Seroprevalence in developed countries is 60-80%. Transmission occurs via sexual contact, person-to-person contact (daycare, via saliva or urine), blood products/transplantation, and congenitally (birth canal or breast milk).</p>"),
          S("three-syndromes", "Three Clinical Syndromes", Tbl(["Syndrome", "Key features"], [
            ["Perinatal/congenital", "Most commonly from <strong>maternal primary infection</strong> (reactivation transmits less often); a TORCH pathogen. Most neonates are asymptomatic at birth, but &gt;50% of those asymptomatic at birth still develop hearing loss. Symptomatic disease: mental/motor disability, jaundice, hepatosplenomegaly, microcephaly, periventricular CNS calcifications, 'blueberry muffin baby' (also classic for rubella)"],
            ["Immunocompetent", "Mono-like illness -- the <strong>most common cause of a monospot-negative 'mono'</strong> presentation; fever, malaise, myalgias, splenomegaly"],
            ["Immunocompromised", "Greatest risk with transplant graft-vs-host mismatch (donor CMV+, recipient CMV-); risk proportional to degree of immunosuppression; can mimic organ rejection. In HIV, CD4 &lt;50 cells/mcL marks increased mortality risk. CMV pneumonitis in transplant recipients carries 60-80% mortality. CMV retinitis shows 'cheese pizza-pie' retinopathy (white exudate + hemorrhage)"]
          ]) + HY("Distinguish CMV disease (first exposure, systemic/organ invasion) from CMV recurrence (viral replication only) -- this distinction guides treatment vs. prevention strategy in transplant patients.")),
          S("diagnosis", "Diagnosis & Workup", "<p>Pregnant/newborn: if seropositive in the 1st trimester, test for viremia every 3 months; confirm via amniotic fluid or fetal serum IgM or a 4-fold IgG rise.</p><p>Immunocompetent: CBC shows leukopenia progressing to lymphocytosis after 1 week, elevated LFTs, positive CMV IgM.</p><p>Immunocompromised: retinitis requires an ophthalmology exam; a negative test does not rule out infection in HIV patients. Transplant patients use <strong>PCR to guide therapy</strong>, distinguishing disease from infection. <strong>Classic histology: intranuclear 'owl's eye' inclusions</strong> plus intracytoplasmic inclusions.</p>"),
          S("treatment", "Treatment", "<p><strong>Ganciclovir (Cytovene) is the preferred antiviral</strong>, effective for congenital disease, retinitis, colitis, pneumonia, encephalitis, and post-transplant/AIDS-associated disease. It is phosphorylated to a substrate that competitively inhibits dGTP binding to viral DNA polymerase.</p>" + HY("Valacyclovir is significantly LESS effective against CMV -- it requires very high doses that make side effects intolerable, so ganciclovir (or valganciclovir) remains preferred for treatment despite the similar-sounding drug names within the herpesvirus family.") + "<p>In HIV/AIDS, antiretroviral therapy (ART) has a preventive role against CMV disease.</p>")
        ], [
          Q("overview", "What is the seroprevalence of CMV in developed countries?", ["60-80%", "Under 10%", "Nearly 100%", "About 25%"], 0, "CMV seroprevalence in developed countries is 60-80%, increasing with age, lower socioeconomic status, and exposure through childcare settings or multiple sexual partners."),
          Q("three-syndromes", "In congenital CMV, when is transmission to the fetus most likely?", ["With maternal primary infection (vs. reactivation)", "Only with maternal reactivation of latent infection", "Equally likely with primary infection and reactivation", "Only in the 3rd trimester regardless of infection type"], 0, "Congenital CMV transmission is most commonly linked to maternal PRIMARY infection during pregnancy -- reactivation of latent infection is less likely to transmit to the fetus."),
          Q("three-syndromes", "A newborn is asymptomatic at birth but has congenital CMV. What is the most important long-term risk?", ["Hearing loss develops in over 50% even if asymptomatic at birth", "No further monitoring is needed since the infant is asymptomatic", "Guaranteed normal development with no follow-up required", "Risk is limited to the neonatal period only"], 0, "Even neonates who are asymptomatic at birth with congenital CMV have a high risk (&gt;50%) of developing hearing loss later, so audiologic follow-up is essential."),
          Q("three-syndromes", "Why can CMV mononucleosis be mistaken for EBV mononucleosis, delaying the correct diagnosis?", ["It produces a nearly identical clinical picture but does not trigger a positive monospot", "It causes an identical rash pattern to EBV", "Both viruses require the same treatment, making the distinction irrelevant", "CMV mononucleosis is clinically indistinguishable and is also monospot-positive"], 0, "CMV causes a mono-like illness nearly identical to EBV mononucleosis, but it does not turn the monospot test positive -- making it the most common cause of a monospot-negative 'mono' presentation."),
          Q("three-syndromes", "Which CD4 threshold in HIV patients marks increased mortality risk related to CMV?", ["CD4 <50 cells/mcL", "CD4 <500 cells/mcL", "CD4 <200 cells/mcL only if symptomatic", "CD4 count does not correlate with CMV risk"], 0, "A CD4 count below 50 cells/mcL in HIV patients is a marker of increased mortality risk related to disseminated CMV disease."),
          Q("three-syndromes", "What retinal finding is classic for CMV retinitis?", ["'Cheese pizza-pie' retinopathy (white exudate + hemorrhage)", "Cherry-red spot", "Cotton-wool spots only, without hemorrhage", "Flame-shaped hemorrhages without exudate"], 0, "CMV retinitis classically produces a 'cheese pizza-pie' appearance -- combined white exudate and hemorrhage -- along with neovascularization and proliferative lesions."),
          Q("diagnosis", "What is the classic histologic finding in CMV infection?", ["Intranuclear 'owl's eye' inclusions", "Negri bodies", "Councilman bodies", "Multinucleated giant cells only"], 0, "CMV-infected cells classically show intranuclear 'owl's eye' inclusions plus intracytoplasmic inclusions -- a pathognomonic histologic clue."),
          Q("diagnosis", "In transplant patients, what test is used to distinguish CMV disease from asymptomatic infection and guide therapy?", ["PCR", "Monospot", "Tzanck smear", "Rapid antigen test"], 0, "PCR is used in transplant patients to distinguish CMV disease (systemic/organ invasion) from mere infection/recurrence, guiding whether treatment or prevention is the right strategy."),
          Q("treatment", "Why is ganciclovir preferred over valacyclovir for treating CMV?", ["Valacyclovir requires very high, poorly-tolerated doses to be effective against CMV", "Valacyclovir is contraindicated in all CMV patients", "Ganciclovir is the only drug active against any herpesvirus", "Valacyclovir has no activity against any herpesvirus"], 0, "Valacyclovir has significantly weaker activity against CMV, requiring impractically high doses with intolerable side effects, so ganciclovir (or valganciclovir) remains the preferred CMV treatment despite the similar drug-name family.")
        ]),
        D("parvovirus-b19", "Erythrovirus / Parvovirus B19 (Fifth Disease)", "Slapped-cheek rash in children; can cause aplastic crisis and fetal hydrops.", [
          S("overview", "Organism & Epidemiology", "<p>Parvovirus B19 (erythrovirus), family Parvoviridae, infects human erythroid precursor cells. Ubiquitous -- by age 15, 50% of children are IgG positive. Incubation is <strong>4-14 days</strong>. Transmission occurs via respiratory secretions, saliva, transplacental (vertical) spread, and blood products.</p>"),
          S("presentation", "Clinical Presentation by Population", Tbl(["Population", "Presentation"], [
            ["Pediatric ('Fifth disease')", "'Slapped cheek' fiery facial erythema, followed by a lacy, reticular, evanescent rash on the trunk/limbs, with <strong>circumoral pallor</strong>. Fever typically resolves <strong>before</strong> the rash appears -- the opposite timing pattern from measles"],
            ["Adults/immunocompetent", "Can mimic vasculitic syndromes -- non-erosive symmetric polyarthritis resembling SLE, but without a malar rash"],
            ["Immunosuppressed/hematologic", "Transient aplastic crisis and pure red cell aplasia; bone marrow shows absent erythroid precursors with characteristic <strong>giant pronormoblasts</strong>"],
            ["Skin", "Papular purpuric 'glove and sock' syndrome (PPGSS)"]
          ]) + HY("Aplastic crisis with giant pronormoblasts on marrow biopsy is classic in sickle cell or other chronic hemolytic anemia patients infected with parvovirus B19, since their red cells already have a shortened lifespan.")),
          S("diagnosis-treatment", "Diagnosis & Treatment", "<p>Usually a clinical diagnosis. Confirmatory testing: elevated IgM anti-erythrovirus antibody titer, or PCR (serum or bone marrow) -- RT-PCR is preferred in immunocompromised patients. By the time the rash appears, viremia has often cleared, but IgM should still be detectable.</p><p>Treatment is symptomatic for most patients. Aplastic crisis may warrant transfusion. Immunocompromised/HIV patients may be considered for IVIG.</p>" + HY("Chloroquine exacerbates parvovirus-associated anemia and should be avoided in these patients.")),
          S("complications-prevention", "Complications & Prevention", "<p>Cardiac: myocarditis, pericarditis, chronic dilated cardiomyopathy -- <strong>parvovirus B19 is the most common cause of myocarditis in childhood</strong>. Renal: post-infectious glomerulonephritis. Neuro: encephalitis, meningitis, stroke (especially in sickle cell patients with aplastic crisis).</p><p><strong>Pregnancy</strong>: risk of premature labor, <strong>hydrops fetalis</strong>, and fetal loss -- parvovirus is the 'Other' agent in TORCH alongside varicella and syphilis. Infected individuals should avoid contact with pregnant patients. Prognosis is excellent if immunocompetent, more complicated if immunocompromised.</p>")
        ], [
          Q("presentation", "In pediatric Fifth disease, what is the timing relationship between fever and rash?", ["Fever typically resolves before the rash appears", "Fever and rash always appear simultaneously", "Fever appears only after the rash resolves", "Fever persists throughout the entire rash duration"], 0, "Parvovirus B19's fever typically resolves BEFORE the 'slapped cheek' rash appears -- the opposite pattern from measles, where the rash appears while fever is still ongoing."),
          Q("presentation", "Which facial finding classically accompanies the 'slapped cheek' rash of Fifth disease?", ["Circumoral pallor", "A malar 'butterfly' rash", "Koplik spots", "Periorbital edema"], 0, "The classic Fifth disease triad includes slapped-cheek erythema, a lacy reticular rash, and circumoral pallor around the mouth."),
          Q("presentation", "A sickle cell patient with confirmed parvovirus B19-induced aplastic crisis has a marrow biopsy showing giant pronormoblasts with absent erythroid precursors. What cell type does parvovirus B19 directly infect to cause this?", ["Erythroid precursor cells", "Myeloid precursor cells", "Megakaryocytes", "Mature lymphocytes"], 0, "Parvovirus B19 directly infects human erythroid precursor cells, halting red cell production -- this is why patients with an underlying chronic hemolytic condition like sickle cell disease are at high risk for a sudden, severe aplastic crisis."),
          Q("presentation", "A patient with confirmed parvovirus B19 infection develops symmetric polyarthritis resembling SLE. Which finding helps distinguish this from true SLE?", ["Absence of a malar rash", "Presence of a malar rash", "A universally positive ANA", "Erosive joint destruction"], 0, "Parvovirus B19 can mimic a lupus-like polyarthritis, but unlike true SLE, it does not produce a malar rash -- an important distinguishing clue."),
          Q("diagnosis-treatment", "Which drug should be avoided in a patient with parvovirus B19-associated anemia?", ["Chloroquine", "Acetaminophen", "Ganciclovir", "Valacyclovir"], 0, "Chloroquine exacerbates parvovirus-associated anemia and should be avoided in these patients."),
          Q("complications-prevention", "Parvovirus B19 is the most common cause of which pediatric cardiac condition?", ["Myocarditis", "Congenital heart block", "Patent ductus arteriosus", "Rheumatic heart disease"], 0, "Parvovirus B19 is the most common cause of myocarditis in childhood, among its other cardiac complications (pericarditis, chronic dilated cardiomyopathy)."),
          Q("complications-prevention", "What is the major concern if a pregnant patient contracts parvovirus B19?", ["Hydrops fetalis and fetal loss", "Congenital cataracts", "Congenital deafness as the primary risk", "No risk to the fetus -- only the mother is affected"], 0, "Parvovirus B19 in pregnancy risks premature labor, hydrops fetalis, and fetal loss, making it one of the 'Other' TORCH agents alongside varicella and syphilis.")
        ]),
        D("measles", "Measles (Rubeola)", "Highly contagious morbillivirus with Koplik spots and a cephalocaudal rash; vaccine-preventable, very high R0.", [
          S("overview", "Organism & Epidemiology", "<p>Caused by Morbillivirus hominis (family Paramyxoviridae), a single-stranded RNA virus; also called rubeola or 'first disease.' Declining vaccination rates have led to resurgence despite US elimination status declared in 2000. Season is winter/spring, <strong>incubation is about 10 days</strong>, and transmission is highly contagious via droplet/inhalation.</p>" + HY("Patients are contagious through the prodrome and until the rash resolves (no fever for 24 hours). Illness confers permanent immunity.")),
          S("presentation", "Clinical Presentation", "<p>High fever (often &gt;104-105°F) lasting 5-7 days, marked malaise, coryza, dry persistent cough, and conjunctivitis, which can mimic Kawasaki disease -- the rash is the key differentiator.</p>" + HY("Koplik spots: small irregular red lesions with whitish centers on the buccal mucosa opposite the molars, described as 'table salt crystals' -- pathognomonic for measles, appearing BEFORE the rash.") + Tbl(["Rash feature", "Detail"], [
            ["Onset", "2 days after Koplik spots; lasts 3-7 days"],
            ["Appearance", "Brick-red, irregular, maculopapular, blanchable"],
            ["Spread pattern", "Begins behind the ears/hairline of the forehead, spreads downward/outward, reaching palms/soles last, rapidly becoming confluent"]
          ])),
          S("diagnosis", "Diagnosis & Workup", "<p>Primarily clinical. Nonspecific labs: leukopenia (unless secondary bacterial infection), thrombocytopenia, proteinuria; lymphocyte count &lt;2,000/mcL is a poor prognostic sign. IgM/ELISA or a 4-fold rise in hemagglutination inhibition antibody supports diagnosis (IgM can be falsely negative in the first few days). LP is not routine, reserved for suspected encephalitis.</p>"),
          S("treatment-complications", "Treatment & Complications", "<p>Treatment is symptomatic (antipyretics/anti-inflammatories); isolate for 1 week following rash onset, bed rest until afebrile x24 hours.</p>" + HY("Vitamin A (200,000 units/day x2 days) supports GI/respiratory mucosa and reduces pediatric morbidity and mortality (ages 6 months-5 years) -- use with caution, as it is toxic in excess and may reduce antibiotic efficacy.") + "<p>Secondary bacterial infection occurs in ~15% of patients; <strong>otitis media is the most common complication</strong> overall. Neurologic complications include encephalitis (most common in adolescents/young adults) and, rarely, <strong>subacute sclerosing panencephalitis (SSPE)</strong> -- a very late (5-15 years post-infection), progressive degenerative CNS 'slow virus' disease unique to measles.</p>"),
          S("prevention", "Prevention", "<p>The <strong>MMR vaccine</strong> is given at 12-15 months and 4-6 years. It is live attenuated and contraindicated in immunocompromised and pregnant patients, with the exception of asymptomatic HIV patients on ART.</p>")
        ], [
          Q("overview", "What is the incubation period for measles?", ["About 10 days", "1-2 days", "3-4 weeks", "6 months"], 0, "Measles has an incubation period of approximately 10 days before symptom onset."),
          Q("overview", "When are measles patients contagious?", ["Through the prodrome and until the rash resolves (24 hours fever-free)", "Only during the 24 hours before rash onset", "Only while the fever is present, not during the prodrome", "Measles patients are not contagious once the rash appears"], 0, "Measles patients remain contagious throughout the prodromal period and until the rash has resolved with the patient fever-free for 24 hours."),
          Q("presentation", "What are Koplik spots and when do they appear relative to the measles rash?", ["Pathognomonic buccal mucosa lesions ('table salt crystals') that appear BEFORE the rash", "A late rash finding appearing after the skin rash fades", "A nonspecific finding seen equally in rubella and roseola", "Vesicular lesions on the palms and soles"], 0, "Koplik spots are pathognomonic small red lesions with whitish centers on the buccal mucosa, described as looking like table salt crystals, and they appear 2 days BEFORE the skin rash."),
          Q("presentation", "What is the classic spread pattern of the measles rash?", ["Begins behind the ears/hairline, spreads downward, reaching palms/soles last", "Begins on the palms and soles and spreads centrally", "Begins on the trunk and stays truncal", "Appears simultaneously over the entire body"], 0, "The measles rash begins behind the ears and at the hairline, then spreads downward and outward, reaching the palms and soles last as it becomes confluent."),
          Q("presentation", "A child with measles-like symptoms also has conjunctivitis. What should be kept on the differential given the overlapping presentation?", ["Kawasaki disease", "Rubella", "Fifth disease", "Roseola"], 0, "Measles conjunctivitis, fever, and rash can mimic Kawasaki disease -- the specific rash pattern and Koplik spots are the key differentiating features."),
          Q("diagnosis", "What CBC finding in a measles patient is a poor prognostic sign?", ["Lymphocyte count <2,000/mcL", "Lymphocyte count >4,000/mcL", "Platelet count >450,000", "Hemoglobin >14 g/dL"], 0, "A lymphocyte count below 2,000/mcL in measles is associated with a worse prognosis."),
          Q("treatment-complications", "Why is vitamin A given in pediatric measles cases (ages 6 months-5 years)?", ["It supports GI/respiratory mucosa and reduces morbidity and mortality", "It is a direct antiviral against the measles virus", "It prevents Koplik spots from forming", "It shortens the incubation period"], 0, "Vitamin A supplementation (200,000 units/day x2 days) supports mucosal integrity and reduces morbidity (diarrhea, night blindness, xerophthalmia) and mortality in young children with measles, though it must be used cautiously since excess vitamin A is toxic."),
          Q("treatment-complications", "What is the most common complication of measles overall?", ["Otitis media", "Subacute sclerosing panencephalitis (SSPE)", "Encephalitis", "Bronchiectasis"], 0, "Secondary bacterial infection occurs in about 15% of measles patients, and otitis media is the single most common complication overall."),
          Q("treatment-complications", "A patient who had measles as a child develops a progressive neurologic decline 10 years later. What rare late complication should be considered?", ["Subacute sclerosing panencephalitis (SSPE)", "Guillain-Barré syndrome", "Postherpetic neuralgia", "Reye syndrome"], 0, "SSPE is a rare, very late (5-15 years post-infection) progressive degenerative CNS complication unique to measles, caused by persistent 'slow virus' infection."),
          Q("prevention", "The MMR vaccine is contraindicated in which patient, with one notable exception?", ["Immunocompromised patients -- except asymptomatic HIV patients on ART", "Healthy children over age 1", "Patients with a prior egg allergy", "Patients over age 65"], 0, "MMR is a live-attenuated vaccine and is contraindicated in immunocompromised and pregnant patients, but asymptomatic HIV patients on ART are a specific exception who can still receive it.")
        ]),
        D("mumps", "Mumps", "Paramyxovirus causing parotitis, with orchitis as a notable complication.", [
          S("overview", "Organism & Epidemiology", "<p>Family Paramyxoviridae. Extremely contagious with outbreaks in congregate settings (colleges, schools) via respiratory droplet spread. Most common in children but also affects people in their late 20s/early 30s, and is <strong>more serious in adults</strong> (more pronounced malaise, abdominal pain, dehydration). Season is late winter-spring. Infectivity is via saliva and urine. <strong>Incubation is 10-21 days</strong>, and 33% of infections are subclinical.</p>" + HY("Breakthrough cases occur despite vaccination -- 50% of reported cases have documented prior MMR vaccination, reflecting waning immunity rather than vaccine failure alone.")),
          S("presentation", "Clinical Presentation", "<p>Nonspecific prodrome (headache, myalgias, fatigue, anorexia) within 48 hours of salivary gland involvement.</p><p><strong>Parotitis</strong>: facial edema, often grossly asymmetric initially, with bilateral involvement developing in most cases (unilateral only in 25%); swelling resolves in about 1 week.</p>" + Tbl(["Extra-salivary site", "Key features"], [
            ["Orchitis/oophoritis", "Now the <strong>most common extra-salivary site</strong> (surpassing meningitis); testicular swelling/tenderness or lower abdominal pain, usually <strong>unilateral</strong>; sterility is actually rare"],
            ["Meningitis", "Historically the most common extra-salivary site; neck stiffness, headache, lethargy"],
            ["Pancreatitis", "Epigastric pain; mumps is the leading pediatric cause of pancreatitis"]
          ]) + HY("If a mumps patient develops a high fever, this should prompt consideration of extension to meningitis or orchitis/oophoritis.")),
          S("diagnosis-treatment", "Diagnosis & Treatment", "<p>Usually clinical. If testing is desired: salivary duct swab for nucleic acid amplification (preferred). CBC shows mild leukopenia with relative lymphocytosis; <strong>elevated serum amylase</strong> occurs with salivary involvement. If meningitis is suspected, CSF shows lymphocytic pleocytosis with <strong>hypoglycorrhachia</strong> (low glucose -- atypical for a viral cause).</p><p>Treatment is symptomatic (acetaminophen/NSAIDs, warm/cool compresses); isolate until swelling subsides (about 9 days). Full course typically resolves in 2 weeks.</p>"),
          S("complications-prevention", "Complications & Prevention", "<p>Complications are rare and usually follow parotitis. <strong>8th cranial nerve (vestibulocochlear) neuritis can cause unilateral, severe, and permanent deafness</strong> -- a classic mumps complication. Other complications: meningitis, encephalitis, Guillain-Barré, thyroiditis, hepatitis, myocarditis.</p><p>Prevention is the <strong>MMR vaccine</strong>, contraindicated in pregnancy and immunocompromised patients (as with measles), but safe in HIV patients once immune restoration is confirmed on ART.</p>")
        ], [
          Q("overview", "What is the incubation period for mumps?", ["10-21 days", "1-3 days", "24-48 hours", "2-3 months"], 0, "Mumps has an incubation period of 10-21 days, and about a third of infections are subclinical."),
          Q("overview", "What does it mean that 50% of reported mumps cases have documented prior MMR vaccination?", ["Breakthrough infection occurs due to waning immunity, not necessarily vaccine failure", "The MMR vaccine provides no protection against mumps", "These cases represent laboratory testing errors", "Only unvaccinated patients can transmit mumps"], 0, "Despite vaccination, breakthrough mumps cases are common due to waning immunity over time -- this doesn't mean the vaccine doesn't work, just that protection can decrease with time since vaccination."),
          Q("presentation", "What is the most common extra-salivary complication of mumps today?", ["Orchitis/oophoritis", "Meningitis", "Pancreatitis", "Thyroiditis"], 0, "Orchitis/oophoritis has surpassed meningitis as the most common extra-salivary site of mumps involvement, though meningitis was historically the most common."),
          Q("presentation", "A mumps patient develops unilateral testicular swelling and tenderness. What should the patient be counseled about fertility?", ["Sterility from mumps orchitis is actually rare", "Sterility is a near-certain outcome", "Bilateral orchitis is required before fertility is affected", "Fertility counseling is not needed since orchitis never affects fertility"], 0, "Although orchitis is a notable complication of mumps and a common exam topic, sterility as a result is actually rare -- a frequent source of student overestimation."),
          Q("presentation", "A mumps patient develops epigastric pain. What complication should be suspected?", ["Pancreatitis -- mumps is the leading pediatric cause", "Appendicitis", "Cholecystitis", "Peptic ulcer disease"], 0, "Mumps is the leading pediatric cause of pancreatitis, and epigastric pain in a mumps patient should raise this possibility."),
          Q("diagnosis-treatment", "What CSF finding is notable in mumps meningitis, despite it being a viral cause?", ["Hypoglycorrhachia (low CSF glucose)", "Markedly elevated CSF glucose", "Absence of pleocytosis", "Neutrophilic predominance"], 0, "Mumps meningitis classically shows lymphocytic pleocytosis WITH hypoglycorrhachia (low CSF glucose) -- an atypical finding for a viral meningitis, where glucose is usually normal."),
          Q("diagnosis-treatment", "What lab finding accompanies parotid gland involvement in mumps?", ["Elevated serum amylase", "Elevated serum lipase only, with normal amylase", "Elevated troponin", "Elevated CSF protein without pleocytosis"], 0, "Salivary gland involvement in mumps elevates serum amylase, reflecting salivary gland (not just pancreatic) amylase release."),
          Q("complications-prevention", "Which mumps complication classically causes permanent, unilateral hearing loss?", ["8th cranial nerve (vestibulocochlear) neuritis", "7th cranial nerve palsy", "Optic neuritis", "Trigeminal neuralgia"], 0, "Mumps can cause 8th cranial nerve neuritis leading to unilateral, severe, and permanent sensorineural hearing loss -- a classic complication.")
        ]),
        D("rubella", "Rubella (German Measles)", "Mild rash illness in children, but devastating as congenital rubella syndrome in pregnancy.", [
          S("overview", "Organism & Epidemiology", "<p>Family Togaviridae, genus Rubivirus; also called 'German measles' or 'third disease.' Transmission is via inhalation of infected droplets. <strong>Incubation is about 16 days</strong> (range 14-25 days), and patients are transmissible from 1 week before the rash until 15 days after it resolves. One infection confers permanent immunity; rubella is a TORCH pathogen.</p>"),
          S("presentation", "Postnatal Presentation", "<p>Postnatal rubella is innocuous or asymptomatic in about 50% of cases. Findings include fever, malaise, <strong>suboccipital adenitis</strong>, posterior cervical/postauricular lymphadenopathy, and polyarticular arthritis in adults (wrist/fingers/knees). A <strong>fine pink maculopapular rash</strong> spreads face &rarr; trunk &rarr; extremities rapidly (2-3 days) and fades quickly (often within 1 day) -- <strong>much faster than the measles rash</strong>.</p>"),
          S("congenital", "Congenital Rubella Syndrome (CRS)", "<p>CRS is teratogenic and more devastating the earlier in gestation infection occurs -- <strong>80% congenital transmission with 1st-trimester maternal infection</strong>. An infant may appear normal at birth but manifest anomalies later.</p>" + Tbl(["System", "Finding"], [
            ["Ocular", "Early cataracts, glaucoma, microphthalmia"],
            ["Auditory", "Hearing deficits -- <strong>deafness is the most common complication of 2nd-trimester infection</strong>"],
            ["Neurologic", "Psychomotor impairment, which may present later in childhood"],
            ["Cardiac", "<strong>Patent ductus arteriosus</strong>, branch pulmonary artery stenosis"],
            ["Skin", "'Blueberry muffin rash' (also seen in CMV and neuroblastoma)"]
          ]) + HY("Rubella arthritis is actually more pronounced after vaccination than after natural illness -- an immune-mediated phenomenon, not a sign the vaccine caused a worse infection.")),
          S("diagnosis-prevention", "Diagnosis & Prevention", "<p>Rubella is public health-reportable. Definitive diagnosis: elevated <strong>IgM</strong> antibody, a 4-fold rise in <strong>IgG</strong> titer, or viral isolation; false-positive IgM can occur with EBV, CMV, erythrovirus, or rheumatic fever. High-avidity anti-rubella IgG distinguishes remote infection from vaccination. All expectant mothers are tested.</p><p>Prevention is the <strong>MMR vaccine</strong> (live attenuated), given to all infants plus a second dose at school age. Postpartum vaccination is recommended for susceptible females, with a recommendation to <strong>avoid pregnancy for at least 1 month post-vaccination</strong> as a precaution (no confirmed vaccine-associated CRS has been reported, but it remains a theoretical concern).</p>")
        ], [
          Q("overview", "What is the incubation period for rubella?", ["About 16 days", "1-2 days", "6-8 weeks", "3-5 days"], 0, "Rubella has an incubation period of approximately 16 days (range 14-25 days)."),
          Q("presentation", "How does the postnatal rubella rash compare to the measles rash in duration?", ["Rubella's rash fades much faster (often within 1 day) than the measles rash (3-7 days)", "Rubella's rash lasts longer than the measles rash", "Both rashes have identical durations", "Rubella has no rash, only measles does"], 0, "The rubella rash spreads and fades quickly, often resolving within about 1 day, which is a much faster course than the 3-7 day duration typical of the measles rash."),
          Q("presentation", "What lymphadenopathy pattern is classic for postnatal rubella?", ["Suboccipital and posterior cervical/postauricular", "Anterior cervical only", "Generalized lymphadenopathy sparing the head/neck", "Inguinal lymphadenopathy"], 0, "Rubella classically causes suboccipital adenitis along with posterior cervical and postauricular lymphadenopathy."),
          Q("congenital", "What percentage of pregnancies with 1st-trimester maternal rubella infection result in congenital transmission?", ["About 80%", "About 10%", "Nearly 100%", "Less than 5%"], 0, "First-trimester maternal rubella infection carries an approximately 80% risk of congenital transmission -- transmission risk decreases as gestation progresses, though severity concerns remain."),
          Q("congenital", "What is the most common complication of 2nd-trimester congenital rubella infection?", ["Deafness", "Cataracts", "Patent ductus arteriosus", "Microcephaly"], 0, "Hearing deficits, with deafness being the most common complication, are classically associated with 2nd-trimester congenital rubella infection."),
          Q("congenital", "What cardiac defect is classically associated with congenital rubella syndrome?", ["Patent ductus arteriosus", "Tetralogy of Fallot", "Coarctation of the aorta", "Ventricular septal defect"], 0, "Patent ductus arteriosus, along with branch pulmonary artery stenosis, is the classic congenital cardiac lesion associated with congenital rubella syndrome."),
          Q("congenital", "The 'blueberry muffin rash' seen in congenital rubella can also be caused by which of the following?", ["Congenital CMV and metastatic neuroblastoma", "Congenital HSV exclusively", "Congenital syphilis exclusively", "It is unique to congenital rubella and has no other cause"], 0, "The 'blueberry muffin rash' is classic for congenital rubella, but the identical finding also occurs in congenital CMV and metastatic neuroblastoma -- exam questions often test which condition a given vignette is actually describing."),
          Q("diagnosis-prevention", "Why is it recommended to avoid pregnancy for at least 1 month after rubella (MMR) vaccination?", ["A precaution against theoretical risk, though no confirmed vaccine-associated CRS has been reported", "Because vaccine-associated CRS is common and well-documented", "Because the vaccine causes infertility", "Because MMR is not a live vaccine and requires this window regardless"], 0, "Avoiding pregnancy for at least 1 month post-MMR vaccination is a precautionary recommendation since MMR is live-attenuated -- no confirmed cases of vaccine-associated CRS have actually been reported.")
        ]),
        D("coxsackievirus", "Coxsackievirus (Enterovirus)", "Cause of hand-foot-mouth disease and herpangina in children.", [
          S("overview", "Organism & Epidemiology", "<p>Family Picornaviridae, genus Enterovirus; causes hand-foot-mouth disease (HFMD) and herpangina. Most common in children under 5-7 years, with outbreaks in daycares/schools/camps. Season is summer/early autumn. Transmission is primarily <strong>fecal-oral</strong>, also via respiratory secretions. Incubation is 3-5 days.</p>"),
          S("presentation", "HFMD vs. Herpangina", Tbl(["Syndrome", "Presentation"], [
            ["Hand-foot-mouth disease", "Mouth/throat pain (refusal to feed in infants), low-grade fever (&lt;101°F), tongue/buccal mucosa lesions, and a nonpruritic macular/papular/vesicular rash on the hands, feet, buttocks, legs, and arms"],
            ["Herpangina", "High fever (102-104°F), headache, sore throat, myalgias; hyperemic throat with yellowish papulovesicular lesions progressing to ulcers, classically in the <strong>posterior oropharynx</strong>"]
          ]) + Mn("Anterior vs. posterior", "Herpangina lesions are posterior oropharyngeal and classically spare the anterior mouth, distinguishing it from HSV gingivostomatitis, which involves the anterior gums/mouth.")),
          S("diagnosis-treatment", "Diagnosis & Treatment", "<p>Typically a clinical diagnosis. Confirmatory testing (rarely needed, for severe cases): throat/stool/vesicular fluid culture or PCR (preferred).</p>" + HY("Coxsackievirus does NOT respond to acyclovir, because its genome lacks thymidine kinase, the enzyme required to activate acyclovir -- a key pharmacology distinction from the herpesviruses.") + "<p>Treatment is supportive: acetaminophen/ibuprofen, fluids to prevent dehydration. Hospitalization is rare, reserved for dehydration or complications. HFMD resolves in 7-10 days; herpangina fever improves in 2-4 days with throat lesions resolving in 5-6 days.</p>"),
          S("complications", "Complications & Prevention", "<p>Decreased oral intake can lead to dehydration. Rare but serious complications include rhombencephalitis (brainstem encephalitis), acute flaccid paralysis, aseptic meningitis, and myocarditis.</p><p>Prevention relies on good hand hygiene and contact precautions/isolation if hospitalized -- <strong>no vaccine is available in the USA</strong>.</p>")
        ], [
          Q("overview", "What is the primary route of coxsackievirus transmission?", ["Fecal-oral, also respiratory secretions", "Airborne only", "Vector-borne", "Sexual contact only"], 0, "Coxsackievirus is primarily transmitted fecal-orally, though respiratory secretions also play a role, consistent with outbreaks in daycare and school settings."),
          Q("presentation", "Which findings distinguish herpangina from hand-foot-mouth disease?", ["High fever with posterior oropharyngeal ulcers, sparing the anterior mouth", "A rash confined to the hands and feet with no oral lesions", "Low-grade fever with anterior gingival lesions", "Absence of any oral findings"], 0, "Herpangina causes high fever with posterior oropharyngeal papulovesicular lesions progressing to ulcers, while HFMD causes lower-grade fever with a rash on the hands, feet, buttocks, and oral lesions."),
          Q("presentation", "How does herpangina's oral lesion distribution differ from HSV gingivostomatitis?", ["Herpangina is posterior oropharyngeal; HSV gingivostomatitis is anterior/gingival", "Herpangina is anterior; HSV gingivostomatitis is posterior", "Both involve identical distributions", "Neither condition causes oral lesions"], 0, "Herpangina lesions are classically posterior oropharyngeal and spare the anterior mouth, while HSV gingivostomatitis involves the anterior gums and mouth -- a key differentiating point."),
          Q("diagnosis-treatment", "Why is acyclovir ineffective against coxsackievirus?", ["Coxsackievirus's genome lacks thymidine kinase, the enzyme needed to activate acyclovir", "Coxsackievirus is resistant to all antiviral drug classes", "Acyclovir only works against DNA viruses at the receptor level", "Coxsackievirus mutates too quickly for any antiviral to work"], 0, "Acyclovir requires viral thymidine kinase for activation into its active form -- coxsackievirus's genome lacks this enzyme, so acyclovir has no activity against it, unlike the herpesviruses."),
          Q("diagnosis-treatment", "What is the mainstay of treatment for hand-foot-mouth disease?", ["Supportive care with fluids and antipyretics/analgesics", "Oral acyclovir", "IV ganciclovir", "Oseltamivir"], 0, "HFMD and herpangina are managed supportively with fluids to prevent dehydration and acetaminophen/ibuprofen for pain and fever -- there is no effective antiviral."),
          Q("complications", "Which rare but serious neurologic complication is associated with coxsackievirus?", ["Rhombencephalitis (brainstem encephalitis)", "Subacute sclerosing panencephalitis", "Guillain-Barré syndrome as the most common complication", "Postherpetic neuralgia"], 0, "Rhombencephalitis, along with acute flaccid paralysis, aseptic meningitis, and myocarditis, is a rare but serious complication of coxsackievirus infection.")
        ]),
        D("covid-19", "COVID-19 (SARS-CoV-2)", "Coronavirus with a wide clinical spectrum; vaccines and targeted outpatient antivirals both matter here.", [
          S("overview", "Organism & Epidemiology", "<p>SARS-CoV-2 is a betacoronavirus, single-stranded RNA, related to SARS-CoV (2002-2004) and MERS (2012). It binds the <strong>ACE2 receptor</strong> on host cells, primarily lung epithelium and upper airway. Seasonality shows a winter peak with a secondary summer wave. Severe disease risk factors: older age, comorbid conditions, lack of vaccination. Reinfection is common (more likely after 180 days) and tends to be milder.</p><p>Transmission is primarily respiratory/airborne, requiring the 'perfect infectious triad': high viral load in an ill patient, a susceptible contact, and a favorable environment (poor ventilation). Patients are most contagious a few days before symptom onset through about 10 days after. <strong>Incubation is typically 4-5 days, up to 14 days.</strong></p>"),
          S("presentation", "Clinical Presentation", "<p>Respiratory: nasal congestion, cough, sore throat. Also myalgias, headache, diarrhea. Pneumonia presents with fever, productive cough, dyspnea.</p>" + HY("Dysgeusia (taste loss) and anosmia (smell loss) are classic distinguishing symptoms of COVID-19 compared to influenza and other respiratory viruses.")),
          S("diagnosis", "Diagnosis & Workup", Tbl(["Test/finding", "Detail"], [
            ["NAAT/RT-PCR", "Preferred viral test, via nasal swab"],
            ["Antigen test", "Faster, less sensitive alternative"],
            ["CBC with diff", "Leukopenia or leukocytosis possible, but <strong>consistently lymphopenia</strong>"],
            ["Inflammatory markers", "Elevated ferritin, CRP, ESR, procalcitonin, D-dimer"],
            ["CXR", "<strong>Ground-glass opacities</strong>, consolidation with pneumonia"]
          ])),
          S("treatment", "Treatment", "<p>Supportive: antipyretics, antiemetics, fluids, rest.</p>" + HY("Paxlovid (nirmatrelvir/ritonavir), 300mg nirmatrelvir + 100mg ritonavir PO BID x5 days, is indicated for symptom onset less than 5 days ago in patients age &ge;75, immunocompromised, or with multiple comorbidities. Caution: severe hepatic impairment, multiple drug interactions, and renal dosing requirements.") + "<p>Hospitalized/severe disease: consider empiric coverage for influenza and bacterial pneumonia. <strong>Dexamethasone and/or remdesivir</strong> for patients requiring supplemental oxygen or ventilatory support, plus <strong>VTE prophylaxis</strong> (usually LMW heparin) given COVID's hypercoagulable state. Hydroxychloroquine and ivermectin are <strong>not proven effective</strong>.</p>"),
          S("complications-prevention", "Complications & Prevention", "<p>Secondary bacterial/fungal/viral infections can occur (Klebsiella pneumoniae, Streptococcus pneumoniae, Staphylococcus aureus, aspergillosis, EBV).</p>" + HY("Long COVID: symptoms persisting beyond 3 months (WHO) or 4 weeks (CDC) -- fatigue, dyspnea, chest pain, cough, anxiety/depression, memory/concentration deficits, insomnia. Pathophysiology remains poorly understood.") + "<p>Prevention: vaccination (series plus annual booster), ventilation, handwashing, respiratory hygiene, and isolation during peak illness. Monoclonal antibodies are available for severely immunocompromised patients.</p>")
        ], [
          Q("overview", "What host cell receptor does SARS-CoV-2 bind to gain entry?", ["ACE2", "CD4", "Sialic acid receptors", "CCR5"], 0, "SARS-CoV-2 binds the ACE2 receptor, primarily expressed on lung epithelium and upper airway cells, to enter host cells."),
          Q("overview", "How does COVID-19 reinfection typically compare to the initial infection?", ["Reinfection tends to be milder, and is more likely after 180 days", "Reinfection is always more severe than the first infection", "Reinfection cannot occur once a patient has recovered", "Reinfection risk is unrelated to time since the prior infection"], 0, "Reinfection with SARS-CoV-2 is common, becomes more likely after about 180 days from the prior infection, and tends to produce milder illness than the initial infection."),
          Q("presentation", "Which symptom is relatively distinctive for COVID-19 compared to influenza?", ["Anosmia and dysgeusia (loss of smell and taste)", "High fever with abrupt onset", "Myalgias", "Nonproductive cough"], 0, "Anosmia and dysgeusia are relatively distinctive for COVID-19 and are less typical of influenza, helping differentiate the two on clinical grounds."),
          Q("diagnosis", "What CBC finding is consistently seen in COVID-19, unlike the variable pattern seen in influenza?", ["Lymphopenia", "Lymphocytosis", "Eosinophilia", "Thrombocytosis"], 0, "COVID-19 consistently causes lymphopenia, whereas influenza can show either leukopenia or leukocytosis -- lymphopenia is a more reliable COVID-specific CBC clue."),
          Q("diagnosis", "What chest imaging finding is classic for COVID-19 pneumonia?", ["Ground-glass opacities", "Lobar consolidation with air bronchograms only", "Cavitary lesions", "Pleural effusion without parenchymal changes"], 0, "Ground-glass opacities, sometimes with consolidation, are the classic chest imaging finding in COVID-19 pneumonia."),
          Q("treatment", "Which patient meets criteria for Paxlovid (nirmatrelvir/ritonavir) treatment?", ["A 78-year-old with symptom onset 3 days ago", "A healthy 30-year-old with symptom onset 2 days ago", "A 50-year-old with no comorbidities and symptom onset 7 days ago", "Any patient regardless of symptom duration or risk factors"], 0, "Paxlovid is indicated for symptom onset less than 5 days ago in patients who are age 75 or older, immunocompromised, or have multiple comorbidities -- the 78-year-old with 3-day-old symptoms meets these criteria."),
          Q("treatment", "Which medications are given to hospitalized COVID-19 patients requiring supplemental oxygen?", ["Dexamethasone and/or remdesivir", "Hydroxychloroquine and azithromycin", "Ivermectin", "Oseltamivir"], 0, "Dexamethasone and/or remdesivir are used for hospitalized patients needing supplemental oxygen or ventilatory support; hydroxychloroquine and ivermectin are not proven effective."),
          Q("complications-prevention", "Why is VTE prophylaxis routinely given to hospitalized COVID-19 patients?", ["COVID-19 causes a hypercoagulable state", "COVID-19 causes significant thrombocytopenia requiring prophylaxis", "VTE prophylaxis is given to prevent viral spread, not clotting", "COVID-19 has no association with clotting risk"], 0, "COVID-19 is associated with a hypercoagulable state, so VTE prophylaxis (usually with low molecular weight heparin) is standard for hospitalized patients.")
        ])
      ]),

      L("fungal-diseases", "Fungal Diseases, Toxoplasmosis & MAC", [
        D("toxoplasmosis", "Toxoplasmosis", "Intracellular protozoan from cat feces/undercooked meat; distinct disease courses in immunocompetent, congenital, and immunocompromised hosts.", [
          S("overview", "Organism & Transmission", "<p><em>Toxoplasma gondii</em>, an intracellular protozoan parasite. Felines are the only <strong>definitive host</strong> -- the only animal in which T. gondii completes its reproductive cycle -- and shed oocysts in feces for up to 2 weeks after infection. Worldwide distribution; ~11% US seroprevalence (age &gt;6), up to 78% in parts of Brazil.</p>" + Tbl(["Route of infection", ""], [
            ["Ingestion", "Infectious oocysts (soil/water contaminated with feline feces, or contaminated produce)"],
            ["Ingestion", "Tissue cysts in undercooked meat"],
            ["Vertical", "Mother to fetus"],
            ["Iatrogenic", "Organ transplant or blood transfusion from an infected donor"]
          ]) + HY("Cat ownership itself is only weakly associated with infection -- most transmission is from soil/produce/undercooked meat, not direct cat contact. If pregnant, have someone else change the litterbox daily (or wear gloves), don't feed cats raw food, and keep cats indoors.")),
          S("immunocompetent", "Immunocompetent Host", "<p>80-90% are asymptomatic and stay latent lifelong. Acute toxoplasmosis (5-23 days post-exposure) most commonly presents with <strong>nontender cervical lymphadenopathy</strong> (generalized LAD in 20-30%), mild constitutional symptoms, headache, myalgias, pharyngitis, hepatosplenomegaly, and a diffuse non-pruritic maculopapular rash. Rare: pneumonitis, ARDS, myocarditis, pericarditis, polymyositis, hepatitis, posterior uveitis, encephalitis.</p>" + HY("T. gondii is the #1 cause of posterior uveitis in immunocompetent hosts (up to 2% of cases) -- retinochoroiditis presents with floaters ± visual loss (permanent if the macula is involved). It usually resolves spontaneously in 4-8 weeks, but Bactrim x6 weeks reduces lesion size, speeds recovery, and lowers recurrence risk.") + "<p>Most immunocompetent, nonpregnant patients with LAD-only disease need no treatment. Treat if symptoms are severe/prolonged (pneumonitis, myocarditis, meningoencephalitis, posterior uveitis, myositis) with <strong>pyrimethamine (Daraprim) + sulfadiazine + leucovorin calcium</strong>.</p>"),
          S("congenital", "Congenital Toxoplasmosis", "<p>Occurs when the mother acquires infection for the <strong>first time</strong> during pregnancy -- women infected before conception virtually never transmit (maternal IgG is already elevated). Fetal infection follows maternal infection in 30-50% of cases overall.</p>" + Tbl(["Trimester of maternal infection", "Transmission rate", "Severity"], [
            ["1st trimester", "10-25%", "Most severe -- more likely to end in spontaneous abortion"],
            ["2nd trimester", "30-50%", "Intermediate"],
            ["3rd trimester", "60%+", "Least severe -- often normal at birth, subtle findings progress later"]
          ]) + HY("Transmission risk RISES with gestational age, but severity is WORSE the earlier infection occurs -- a classic inverse relationship that's easy to mix up.") + "<p>Early infection can cause spontaneous abortion, stillbirth, or severe neonatal disease (seizures, psychomotor retardation, deafness, hydrocephalus, intracranial calcifications, retinochoroiditis). Late infection often looks normal at birth, then progresses to hepatosplenomegaly/LAD in the first months, followed by CNS and ocular disease later.</p><p><strong>Classic fetal US findings:</strong> intracranial calcifications + cerebral ventricular dilation (often together), hydrocephaly, echogenic bowel, hepatosplenomegaly.</p><p><strong>Diagnosis:</strong> mother -- positive IgM with negative IgG suggests acute infection; amniocentesis for T. gondii PCR offered at &ge;18 weeks with serologic confirmation or abnormal fetal US. Newborn -- positive IgM/IgA, or persistent IgG beyond 12 months (IgG before 12 months may just be maternal transfer). Maternal screening is not routine in the US (risk-based; screen if immunocompromised or high suspicion).</p>" + Tbl(["Gestational age at treatment start", "Regimen"], [
            ["&lt;18 weeks", "Spiramycin (does NOT treat the fetus, only reduces transmission)"],
            ["&ge;18 weeks", "Pyrimethamine-sulfadiazine + folinic acid (leucovorin)"]
          ]) + "<p>If amniotic fluid PCR is positive, continue pyrimethamine-sulfadiazine-folinic acid until delivery. Treatment is offered to both symptomatic AND asymptomatic pregnant women, and should start ASAP since latent cysts aren't drug-susceptible.</p>"),
          S("immunocompromised", "Immunocompromised Host", "<p>Can be an acute infection or <strong>reactivation of latent infection</strong> (mainly in AIDS, cancer, and immunosuppressive drug patients). Toxoplasmosis is the <strong>most common CNS parasitic infection in AIDS patients</strong> not on appropriate prophylaxis.</p><p>In advanced AIDS, <strong>toxoplasmic encephalitis</strong> is the most common presentation: headache, seizure, focal neurologic deficit, altered mental status, fever. Imaging shows <strong>multiple ring-enhancing cerebral lesions</strong> on CT/MRI (MRI preferred).</p>" + HY("Presumptive diagnosis in AIDS (most patients are treated presumptively, not definitively): CD4 <100 + a compatible clinical syndrome + positive T. gondii IgG + consistent ring-enhancing lesions on imaging.") + "<p><strong>Treatment:</strong> pyrimethamine + sulfadiazine + leucovorin (acute dosing x6 weeks, then maintenance to prevent recurrence) plus ART for immune recovery; adjuncts include dexamethasone for cerebral edema and anticonvulsants for seizures.</p><p><strong>Prevention:</strong> all HIV patients are tested for prior T. gondii exposure via IgG at first HIV diagnosis. If IgG-positive but asymptomatic, start primary prophylaxis with <strong>TMP-SMX (Bactrim)</strong> -- this can be discontinued once the patient is on ART with a suppressed viral load and CD4 &gt;200 for &ge;3 months.</p>")
        ], [
          Q("overview", "Which animal is the definitive host for Toxoplasma gondii?", ["Felines (cats)", "Canines (dogs)", "Rodents", "Cattle"], 0, "Cats are the only definitive host -- the only animal in which T. gondii completes its full reproductive cycle -- and shed oocysts in their feces for up to 2 weeks after infection."),
          Q("overview", "Which of the following is a recognized route of T. gondii transmission to humans?", ["Ingestion of tissue cysts in undercooked meat", "Mosquito bite", "Tick bite", "Airborne respiratory transmission"], 0, "T. gondii is transmitted by ingesting infectious oocysts (contaminated soil/water/produce) or tissue cysts in undercooked meat, vertically from mother to fetus, or via organ transplant/blood transfusion -- not by insect vectors or the respiratory route."),
          Q("immunocompetent", "What is the most common presentation of acute toxoplasmosis in an immunocompetent host?", ["Nontender cervical lymphadenopathy", "Painful anterior cervical lymphadenopathy", "Diffuse petechial rash", "Bilateral parotitis"], 0, "The most common finding in acute toxoplasmosis is nontender cervical lymphadenopathy, often with mild constitutional symptoms."),
          Q("immunocompetent", "T. gondii is the leading cause of which ocular condition in immunocompetent hosts?", ["Posterior uveitis (retinochoroiditis)", "Anterior uveitis", "Bacterial conjunctivitis", "Corneal ulceration"], 0, "T. gondii is the #1 cause of posterior uveitis in immunocompetent hosts, presenting with floaters and possible permanent vision loss if the macula is involved."),
          Q("immunocompetent", "What treatment is used to speed recovery and reduce recurrence risk in T. gondii posterior uveitis, even though it often resolves spontaneously?", ["Bactrim (TMP-SMX) x6 weeks", "IV amphotericin B", "Itraconazole x6 months", "No treatment is ever given for ocular toxoplasmosis"], 0, "Although posterior uveitis from toxoplasmosis usually resolves spontaneously in 4-8 weeks, Bactrim x6 weeks reduces lesion size, speeds recovery, and lowers the risk of recurrence."),
          Q("immunocompetent", "What is the regimen for treating severe/prolonged acute toxoplasmosis in an immunocompetent host?", ["Pyrimethamine + sulfadiazine + leucovorin", "Fluconazole alone", "IV amphotericin B alone", "Doxycycline x21 days"], 0, "Pyrimethamine (Daraprim) plus sulfadiazine plus leucovorin calcium is used when treatment is indicated -- most mild, LAD-only cases in immunocompetent nonpregnant patients need no treatment at all."),
          Q("congenital", "Congenital toxoplasmosis transmission occurs almost exclusively when maternal infection happens when?", ["For the first time during pregnancy", "Any time before or during pregnancy equally", "Only if the mother was infected years before conception", "Only during breastfeeding"], 0, "Women infected before conception virtually never transmit to the fetus because their IgG is already elevated -- congenital transmission requires a new (primary) maternal infection during pregnancy."),
          Q("congenital", "How does the risk of fetal transmission change with advancing gestational age at maternal infection, and how does severity change?", ["Transmission risk rises with gestational age, but severity is worse the earlier infection occurs", "Both transmission risk and severity rise together with gestational age", "Both transmission risk and severity fall with advancing gestational age", "Gestational age has no effect on either transmission risk or severity"], 0, "This is a classic inverse relationship: transmission risk increases from about 10-25% in the 1st trimester to over 60% in the 3rd trimester, but earlier infections -- despite being less likely to transmit -- cause more severe disease when they do."),
          Q("congenital", "What ultrasound finding, often occurring together, is classic for congenital toxoplasmosis?", ["Intracranial calcifications with cerebral ventricular dilation", "A single umbilical artery", "Absent nasal bone", "Cystic hygroma"], 0, "Intracranial calcifications together with cerebral ventricular dilation are the classic fetal ultrasound findings for congenital toxoplasmosis, along with hydrocephaly, echogenic bowel, and hepatosplenomegaly."),
          Q("congenital", "What antimicrobial is used to treat maternal toxoplasmosis diagnosed before 18 weeks gestation, and what is its key limitation?", ["Spiramycin, which reduces transmission but does not treat the fetus", "Pyrimethamine-sulfadiazine, which fully treats the fetus", "IV amphotericin B, which is teratogenic", "No treatment is given before 18 weeks"], 0, "Spiramycin is used before 18 weeks gestation to reduce the risk of transmission, but it does not cross to treat an already-infected fetus -- pyrimethamine-sulfadiazine plus folinic acid is used from 18 weeks onward instead."),
          Q("congenital", "How is congenital toxoplasmosis diagnosed in a newborn?", ["Positive IgM or IgA, or persistent IgG beyond 12 months of age", "IgG positivity at any age, including in the first weeks of life", "A single positive IgG test at birth", "Newborn diagnosis is not possible; only maternal testing is used"], 0, "Newborn diagnosis relies on positive IgM or IgA (which don't cross the placenta) or IgG that persists beyond 12 months -- IgG present before 12 months could simply reflect maternal antibody transfer."),
          Q("immunocompromised", "Toxoplasmosis is the most common cause of which condition in AIDS patients not on appropriate prophylaxis?", ["CNS parasitic infection (toxoplasmic encephalitis)", "Fungal meningitis", "Disseminated skin infection", "Endocarditis"], 0, "Toxoplasmosis is the most common CNS parasitic infection in AIDS patients without appropriate prophylaxis, most often presenting as toxoplasmic encephalitis."),
          Q("immunocompromised", "What is the classic imaging finding of toxoplasmic encephalitis in AIDS?", ["Multiple ring-enhancing cerebral lesions on CT/MRI", "A single non-enhancing white matter lesion", "Diffuse cerebral edema without focal lesions", "Periventricular calcifications only"], 0, "Toxoplasmic encephalitis classically shows multiple ring-enhancing lesions on CT or MRI (MRI is the preferred modality)."),
          Q("immunocompromised", "What criteria support a PRESUMPTIVE diagnosis of toxoplasmic encephalitis in an AIDS patient, since most patients are treated presumptively rather than with a definitive biopsy?", ["CD4 <100, a compatible clinical syndrome, positive T. gondii IgG, and consistent ring-enhancing lesions on imaging", "A CD4 count alone, regardless of symptoms or imaging", "A negative T. gondii IgG plus any neurologic symptom", "Imaging findings alone, without any serologic or clinical correlation"], 0, "Presumptive diagnosis combines a low CD4 count (<100), a compatible clinical picture, positive T. gondii IgG (showing prior exposure), and imaging consistent with ring-enhancing lesions -- most AIDS patients are treated on this basis rather than waiting for brain biopsy."),
          Q("immunocompromised", "Which HIV patients should receive primary prophylaxis against toxoplasmosis, and with what drug?", ["IgG-positive but asymptomatic patients, with TMP-SMX (Bactrim)", "All HIV patients regardless of IgG status, with fluconazole", "Only IgG-negative patients, with pyrimethamine", "IgG-positive symptomatic patients only, with itraconazole"], 0, "HIV patients who test IgG-positive for prior T. gondii exposure but are asymptomatic receive primary prophylaxis with TMP-SMX (Bactrim), which can be discontinued once ART has suppressed viral load and CD4 has been above 200 for at least 3 months.")
        ]),
        D("histoplasmosis", "Histoplasmosis", "Dimorphic fungus from bird/bat droppings, endemic to the Ohio and Mississippi River valleys; acute, chronic, and disseminated forms.", [
          S("overview", "Organism, Epidemiology & Pathogenesis", "<p><em>Histoplasma capsulatum</em>, a dimorphic fungus living in soil with heavy bird/bat droppings -- chicken coops, farm buildings, abandoned buildings, bird roosts, <strong>caves</strong>, and wood lots. Exposure activities include excavation, construction, demolition, wood cutting, and spelunking. Most common in the <strong>Midwestern/Central US, Ohio and Mississippi River Valleys</strong>. About 500,000 US cases/year -- the most common cause of hospitalization among endemic mycoses.</p><p>Inhaled spores convert to budding yeast, get engulfed by pulmonary macrophages, and disseminate via lymph nodes then blood over the first 2 weeks. Cellular immunity develops 10-14 days post-infection, forming granulomas that halt infection in immunocompetent hosts.</p>"),
          S("acute-pulmonary", "Acute Pulmonary Histoplasmosis (Most Common Presentation)", "<p>Presents 2-4 weeks post-exposure, lasting 1 week to 6 months. Mild-to-severe flu-like illness or pneumonia: fever, chills, headache, myalgias, anorexia, cough, chest pain. <strong>Almost never fatal.</strong> Often mistaken for CAP and considered only after empiric antibacterial therapy fails.</p><p>CXR: enlarged hilar/mediastinal lymphadenopathy with patchy infiltrates or 1-4cm nodules, or may be normal. Heavy exposure can cause <strong>acute diffuse pulmonary histoplasmosis</strong> with diffuse reticulonodular infiltrates that can progress to respiratory failure or disseminated disease.</p>" + Tbl(["Severity", "Treatment"], [
            ["Asymptomatic or mild (<4 weeks symptoms)", "No treatment"],
            ["Symptomatic >4 weeks, or diffuse infiltrates/dyspnea", "PO itraconazole"],
            ["Severe (dyspnea, hypoxemia, ARDS)", "IV amphotericin B x1-2 weeks, then PO itraconazole x6-12 weeks"]
          ])),
          S("disseminated", "Progressive Disseminated Histoplasmosis", "<p>Fever plus multi-organ involvement -- can simulate septic shock and is rapidly fatal if untreated.</p>" + HY("Histoplasmosis is the most common fungal infection in patients on TNF-alpha inhibitors (infliximab, etanercept, adalimumab). Other risk factors: AIDS with CD4 <200, methotrexate, transplant immunosuppressants, extremes of age, long-term glucocorticoids.") + "<p>Symptoms: fever, cough, dyspnea, weakness, weight loss, altered mental status, skin lesions, arthralgias, GI symptoms. Findings include mucous membrane/oropharyngeal ulcers, GI ulcers/bleeding, hepatosplenomegaly, <strong>adrenal insufficiency (50%)</strong>, pancytopenia, and CNS involvement/meningitis (5-20%). Characteristic skin lesions (nodules, papules, plaques, ulcers, vesicles, pustules) are more frequent in advanced HIV. Imaging shows a miliary pattern.</p><p><strong>Treatment:</strong> IV amphotericin B x1-2 weeks, then itraconazole for a total duration of &ge;1 year, monitoring antigen levels for &ge;1 year after completion. CNS disease needs IV amphotericin B x4-6 weeks then itraconazole &ge;1 year. Adrenal insufficiency requires lifelong hydrocortisone.</p>"),
          S("chronic-pulmonary", "Chronic Pulmonary Histoplasmosis", "<p>Occurs in older patients with underlying chronic lung disease/smoking history. Symptoms: productive cough, dyspnea, chest pain, fatigue, fevers, weight loss, night sweats.</p>" + HY("Chest imaging classically shows progressive fibrotic apical cavitary lesions -- the 'marching cavity' pattern, where cavities enlarge and spread to new areas, sometimes forming bronchopleural fistulae.") + "<p>Treatment: itraconazole for &ge;1 year; 10-20% relapse (usually within 2 years of stopping), so patients are followed &ge;5 years with CXR every 6 months in year 1, then annually.</p>"),
          S("diagnosis", "Diagnosis (All Forms)", "<p><strong>Fungal culture is the gold standard</strong> (downside: up to 1 month for results, often negative in mild disease). Best specimen by form: acute pulmonary -- BAL is most sensitive; disseminated -- blood/bone marrow/BAL; chronic pulmonary -- sputum or BAL.</p><p><strong>Histoplasma antigen testing</strong> (blood, urine, BAL, CSF) is useful in acute severe and disseminated disease. Histopathology classically shows 'budding yeast' on BAL fluid or biopsy.</p>")
        ], [
          Q("overview", "Histoplasmosis is most strongly associated with which US region?", ["Ohio and Mississippi River Valleys", "The Pacific Northwest", "The Southwest desert", "The Gulf Coast exclusively"], 0, "Histoplasma capsulatum is most common in the Midwestern/Central US, particularly the Ohio and Mississippi River Valleys, where soil is heavily contaminated with bird/bat droppings."),
          Q("overview", "What environmental exposure is classically linked to histoplasmosis?", ["Spelunking (cave exploration) or disturbing bird/bat droppings", "Swimming in freshwater lakes", "Handling raw poultry", "Walking barefoot on tropical beaches"], 0, "Histoplasma lives in soil enriched with bird or bat droppings -- caves, chicken coops, and bird roosts are classic exposure sites, especially during excavation, demolition, or spelunking."),
          Q("acute-pulmonary", "Why is acute pulmonary histoplasmosis often initially misdiagnosed?", ["It's often mistaken for community-acquired pneumonia and only considered after empiric antibiotics fail", "It never causes respiratory symptoms, so it's missed entirely", "It always presents with a pathognomonic rash", "It only affects immunocompromised patients so it's not on the differential"], 0, "Acute pulmonary histoplasmosis presents like a flu-like illness or community-acquired pneumonia and is often only suspected after a course of empiric antibacterial therapy fails."),
          Q("acute-pulmonary", "What is the mortality of acute pulmonary histoplasmosis in most cases?", ["Almost never fatal", "Fatal in the majority of cases", "Fatal in about 25% of cases", "Universally fatal without treatment"], 0, "Acute pulmonary histoplasmosis is almost never fatal, in contrast to disseminated disease, which can rapidly progress to death if untreated."),
          Q("acute-pulmonary", "What treatment is appropriate for severe acute pulmonary histoplasmosis with dyspnea, hypoxemia, or ARDS?", ["IV amphotericin B for 1-2 weeks, then PO itraconazole x6-12 weeks", "No treatment -- severe disease is still self-limited", "PO itraconazole alone, with no IV therapy", "IV vancomycin"], 0, "Severe disease with dyspnea, hypoxemia, or ARDS is treated with IV amphotericin B for 1-2 weeks, followed by PO itraconazole for 6-12 weeks."),
          Q("disseminated", "Which class of medication is most strongly linked to progressive disseminated histoplasmosis?", ["TNF-alpha inhibitors (e.g., infliximab, etanercept, adalimumab)", "Beta-blockers", "SSRIs", "Proton pump inhibitors"], 0, "Histoplasmosis is the most common fungal infection seen in patients treated with TNF-alpha inhibitors, making this drug class a key risk factor to recognize."),
          Q("disseminated", "What proportion of patients with disseminated histoplasmosis develop adrenal insufficiency, and what does this require?", ["About 50%, requiring lifelong hydrocortisone", "About 5%, requiring no specific treatment", "Nearly 100%, requiring only a short steroid taper", "Adrenal insufficiency does not occur with histoplasmosis"], 0, "Adrenal insufficiency occurs in about 50% of disseminated histoplasmosis cases and, when present, requires lifelong hydrocortisone replacement."),
          Q("disseminated", "What is the treatment approach for CNS involvement in disseminated histoplasmosis?", ["IV amphotericin B x4-6 weeks, then itraconazole for at least 1 year", "PO itraconazole alone for 2 weeks", "IV amphotericin B for a single dose only", "No treatment -- CNS disease is not treatable"], 0, "CNS histoplasmosis requires a longer amphotericin B course (4-6 weeks IV) before transitioning to itraconazole for at least 1 year, monitoring until CSF/MRI findings clear."),
          Q("chronic-pulmonary", "What is the classic imaging pattern of chronic pulmonary histoplasmosis?", ["Progressive fibrotic apical cavitary lesions (the 'marching cavity' pattern)", "A single calcified granuloma with no cavitation", "Diffuse ground-glass opacities", "A normal chest film despite severe symptoms"], 0, "Chronic pulmonary histoplasmosis produces progressive, fibrotic, apical cavitary lesions that enlarge and spread over time -- described as a 'marching cavity' pattern, which can form bronchopleural fistulae."),
          Q("chronic-pulmonary", "How long should patients with chronic pulmonary histoplasmosis be followed after completing treatment, given the relapse rate?", ["At least 5 years, given a 10-20% relapse rate usually within 2 years", "No follow-up is needed once itraconazole is completed", "Only 3 months of follow-up is required", "Lifelong daily itraconazole is required with no possibility of stopping"], 0, "Chronic pulmonary histoplasmosis has a 10-20% relapse rate, usually within 2 years of stopping treatment, so patients are followed for at least 5 years with periodic chest imaging."),
          Q("diagnosis", "What is the gold standard diagnostic test for histoplasmosis, and what is its main limitation?", ["Fungal culture, which can take up to a month to result", "Rapid antigen testing, which is only 20% sensitive", "Skin biopsy alone, without culture confirmation", "PCR, which is not available for Histoplasma"], 0, "Fungal culture is the gold standard for diagnosing histoplasmosis, but it can take up to a month to result and is often negative in mild disease -- antigen testing is a faster complementary option."),
          Q("diagnosis", "What histopathologic finding is classic for histoplasmosis on biopsy or BAL fluid?", ["Budding yeast", "Septate hyphae with acute-angle branching", "Broad, ribbon-like nonseptate hyphae", "Encapsulated yeast with a thick capsule"], 0, "Histoplasma classically appears as small budding yeast forms on histopathology of BAL fluid or tissue biopsy.")
        ]),
        D("coccidioidomycosis", "Coccidioidomycosis (Valley Fever)", "Dimorphic fungus of southwestern US desert soil causing pneumonia, sometimes disseminated disease.", [
          S("overview", "Organism, Epidemiology & Pathogenesis", "<p>Dimorphic fungi <em>Coccidioides immitis</em> / <em>C. posadasii</em>, found in soil in the southwestern US (San Joaquin Valley CA, Arizona, southern Nevada, SW Utah, southern New Mexico, western Texas) plus parts of Mexico/Central/South America. About 150,000 US infections/year; highest incidence in late spring and late fall.</p><p>Inhaled arthroconidia from disturbed soil become spherical, enlarge, and form internal septations; endospores develop and are released when the spherule ruptures -- each endospore can form a new spherule.</p>"),
          S("primary-pulmonary", "Primary Pulmonary Infection", "<p>60% of infections are asymptomatic. The symptomatic ~40% present after several days to 2 weeks with chest pain, cough, and fever as the most common findings.</p>" + Tbl(["Finding", "Detail"], [
            ["'Desert rheumatism'", "Symmetrical arthralgias WITHOUT effusion or erythema -- knees/ankles/wrists"],
            ["Erythema nodosum", "Appears 2-20 days after symptom onset"],
            ["Erythema multiforme", "In a 'necklace' distribution"],
            ["Toxic erythema", "Diffuse sandpaper-like maculopapular rash"]
          ]) + "<p>Also: drenching night sweats, weight loss, fatigue. CXR shows unilateral patchy infiltrates (often upper lobes) with hilar lymphadenopathy, or may be unremarkable.</p>"),
          S("disseminated", "Disseminated Coccidioidomycosis", "<p>Occurs in &lt;1% of individuals.</p>" + HY("Disseminated disease is most common in males, African American or Filipino patients, immunocompromised patients, and pregnancy/postpartum -- a distinct demographic risk pattern worth memorizing.") + "<p>More pronounced respiratory symptoms occur (mediastinal LAD, increased sputum); lung abscess rupture can cause empyema. <strong>Meningitis occurs in 30-50% of disseminated cases</strong>, along with complicated bone/joint/soft tissue infection, subcutaneous abscesses, and verrucous skin lesions. Fungemia causes a diffuse miliary CXR pattern and early death.</p>"),
          S("diagnosis-treatment", "Diagnosis & Treatment", "<p>Labs: moderate leukocytosis plus <strong>eosinophilia</strong>. Serology (IgM/IgG) is commonly used -- IgM rises 1-3 weeks post-infection; a steadily rising IgG suggests dissemination. If meningitis is suspected, LP shows increased WBC/lymphocytosis with reduced glucose.</p>" + Tbl(["Presentation", "Treatment"], [
            ["Asymptomatic (60%)", "No treatment"],
            ["Primary pulmonary, focal pneumonia", "No treatment -- UNLESS immunocompromised, symptoms >2 months, night sweats >3 weeks, weight loss >10%, or steadily rising IgG, then fluconazole or itraconazole x6 months"],
            ["Diffuse pneumonia", "IV amphotericin B until clinical improvement, then fluconazole/itraconazole x6 months-1 year"],
            ["Disseminated (skin/bone/joint)", "Fluconazole or itraconazole for several years"],
            ["Meningitis", "Fluconazole 400-800mg daily or itraconazole, LIFELONG"]
          ]))
        ], [
          Q("overview", "Coccidioidomycosis is most strongly associated with which US region?", ["The southwestern desert (San Joaquin Valley, Arizona, etc.)", "The Ohio and Mississippi River Valleys", "The Pacific Northwest", "New England"], 0, "Coccidioides species live in southwestern US desert soil -- California's San Joaquin Valley, Arizona, Nevada, Utah, New Mexico, and Texas -- giving the disease its 'Valley Fever' nickname."),
          Q("primary-pulmonary", "What proportion of primary coccidioidomycosis infections are asymptomatic?", ["About 60%", "About 10%", "Nearly 100%", "About 25%"], 0, "About 60% of primary Coccidioides infections are asymptomatic; the remaining ~40% develop symptomatic disease after several days to 2 weeks."),
          Q("primary-pulmonary", "What is 'desert rheumatism' in the context of coccidioidomycosis?", ["Symmetrical arthralgias of the knees/ankles/wrists WITHOUT effusion or erythema", "Septic arthritis with joint effusion requiring aspiration", "A chronic erosive polyarthritis identical to rheumatoid arthritis", "Isolated unilateral hip pain"], 0, "'Desert rheumatism' describes the symmetrical arthralgias -- notably without effusion or erythema -- seen in primary pulmonary coccidioidomycosis, distinguishing it from a true inflammatory arthritis."),
          Q("disseminated", "Which patient demographic is at highest risk for disseminated coccidioidomycosis?", ["Males, African American or Filipino patients, immunocompromised patients, and pregnant/postpartum women", "Elderly white women with osteoporosis", "Children under age 5 exclusively", "Only patients with no prior pulmonary exposure"], 0, "Disseminated disease occurs in less than 1% of infections but is disproportionately seen in males, African American or Filipino patients, immunocompromised patients, and those who are pregnant or postpartum."),
          Q("disseminated", "What proportion of disseminated coccidioidomycosis cases involve meningitis?", ["30-50%", "Less than 5%", "Nearly 100%", "About 10%"], 0, "Meningitis occurs in 30-50% of disseminated coccidioidomycosis cases, making it one of the most feared complications of dissemination."),
          Q("diagnosis-treatment", "What CBC finding is classic for coccidioidomycosis?", ["Eosinophilia", "Neutropenia", "Basophilia", "Isolated thrombocytosis"], 0, "Moderate leukocytosis with eosinophilia is a classic lab finding in coccidioidomycosis, alongside IgM/IgG serology."),
          Q("diagnosis-treatment", "What does a steadily RISING IgG titer suggest in coccidioidomycosis?", ["Dissemination", "Resolution of infection", "A false-positive test requiring no further workup", "Reinfection with a different fungal species"], 0, "A steadily rising IgG titer is concerning for dissemination and is one of the criteria that would prompt treatment even in otherwise focal pulmonary disease."),
          Q("diagnosis-treatment", "What is the treatment for coccidioidal meningitis?", ["Fluconazole 400-800mg daily or itraconazole, LIFELONG", "A single dose of IV amphotericin B", "Fluconazole x2 weeks only", "No antifungal treatment -- supportive care only"], 0, "Coccidioidal meningitis requires lifelong azole therapy (fluconazole or itraconazole) -- one of the few fungal infections requiring indefinite treatment."),
          Q("diagnosis-treatment", "Which patient with primary pulmonary coccidioidomycosis should receive antifungal treatment rather than observation?", ["An immunocompromised patient with symptoms persisting over 2 months", "A healthy patient with symptoms resolving in 2 weeks", "An asymptomatic patient found incidentally on imaging", "A patient with mild arthralgias only, resolving spontaneously"], 0, "Focal primary pulmonary disease is typically observed without treatment UNLESS the patient is immunocompromised, has symptoms >2 months, night sweats >3 weeks, weight loss >10%, or a steadily rising IgG -- any of these prompt fluconazole or itraconazole x6 months.")
        ]),
        D("candidiasis", "Candidiasis (Invasive)", "Yeast causing local mucocutaneous disease or, in the immunosuppressed/line-associated, hematogenous multi-organ disease.", [
          S("overview", "Organism & Risk Factors", "<p><em>Candida</em> yeast; <em>C. albicans</em> is the most common cause, with others including C. glabrata, C. krusei, C. parapsilosis, C. tropicalis, and the emerging multidrug-resistant <em>C. auris</em>. Often arises from an imbalance of normal flora and is an increasingly important nosocomial infection.</p><p>Invasive candidiasis spreads hematogenously to multiple viscera, likely starting at mucosal surfaces (from immunosuppression/antibiotics) or entering via central venous catheters. The brain, heart, kidneys, and eyes are most commonly involved, forming micro/macroabscesses in major organs.</p>" + HY("Risk factors for candidemia/disseminated disease: ICU care (especially burn/trauma/neonatal units), immunocompromise, extremes of age, central line placement, broad-spectrum antibiotics, abdominal surgery/GI perforation, and acute renal failure.")),
          S("presentation-diagnosis", "Clinical Clues & Diagnosis", Tbl(["Site", "Finding"], [
            ["Skin", "Erythematous macronodular lesions with painful muscle involvement beneath"],
            ["Eye", "Chorioretinitis"],
            ["Heart", "Valve vegetations"]
          ]) + "<p>There is no single specific test for invasive candidiasis. Blood cultures should be obtained in all suspected cases but are only <strong>50% positive</strong>, and yeast growth takes 1-3 days. High suspicion plus ocular or macronodular skin lesions strongly suggests widespread deep-organ infection.</p>"),
          S("treatment", "Treatment", HY("First-line treatment is an IV echinocandin (caspofungin, micafungin, or anidulafungin). IV fluconazole is an alternative for non-neutropenic, less critically ill patients without recent azole exposure.") + "<p>Continue therapy for 2 weeks after the last positive blood culture and resolution of signs/symptoms.</p>")
        ], [
          Q("overview", "Which organ systems are most commonly involved in hematogenously disseminated candidiasis?", ["Brain, heart, kidneys, and eyes", "Lungs exclusively", "Skin exclusively", "Bone and joints exclusively"], 0, "Disseminated candidiasis most commonly seeds the brain, heart, kidneys, and eyes, forming micro- and macroabscesses in these organs."),
          Q("overview", "Which of the following is a risk factor for candidemia/disseminated candidiasis?", ["Central venous catheter placement", "A recent uncomplicated upper respiratory infection", "Regular outdoor exercise", "A vegetarian diet"], 0, "Central line placement, broad-spectrum antibiotics, ICU care, immunocompromise, and abdominal surgery/GI perforation are all recognized risk factors for candidemia and disseminated disease."),
          Q("presentation-diagnosis", "What eye finding is a clinical clue for disseminated candidiasis?", ["Chorioretinitis", "Acute angle-closure glaucoma", "Papilledema", "Corneal arcus"], 0, "Candida chorioretinitis is a clinical clue for widespread deep-organ (disseminated) infection and should prompt an ophthalmologic exam in suspected cases."),
          Q("presentation-diagnosis", "What is a major limitation of blood cultures in diagnosing invasive candidiasis?", ["They are only about 50% positive even in confirmed cases", "They are 100% sensitive but take 6 weeks to result", "They cannot be drawn in ICU patients", "They are only useful for C. albicans and not other Candida species"], 0, "Blood cultures should be obtained in all suspected cases of invasive candidiasis, but they are only about 50% positive, so a negative culture does not rule out the diagnosis."),
          Q("treatment", "What is first-line treatment for invasive candidiasis?", ["An IV echinocandin (caspofungin, micafungin, or anidulafungin)", "Oral fluconazole in all cases", "IV amphotericin B in all cases", "Oral nystatin"], 0, "IV echinocandins are first-line for invasive candidiasis; IV fluconazole is reserved as an alternative for non-neutropenic, less critically ill patients without recent azole exposure."),
          Q("treatment", "How long should treatment for invasive candidiasis continue?", ["2 weeks after the last positive blood culture and resolution of symptoms", "A fixed 3-day course regardless of clinical response", "Indefinitely, for the rest of the patient's life", "24 hours after the first negative blood culture"], 0, "Treatment continues for 2 weeks after the last positive blood culture and resolution of signs/symptoms, not a fixed short course.")
        ]),
        D("aspergillosis", "Aspergillosis", "Mold with four distinct syndromes: ABPA, allergic sinusitis, chronic pulmonary disease, and invasive disease.", [
          S("overview", "Organism & Risk Factors", "<p><em>Aspergillus</em> is found in indoor/outdoor air, surfaces, and water, especially decomposing plant material, dead leaves, bedding, and hay barns. The lungs, sinuses, and brain are most often involved.</p><p>Risk factors: leukemia, bone marrow/organ transplant, HIV, glucocorticoids, underlying respiratory disease (severe flu, COVID, COPD, asthma), severe liver disease, and immunomodulating drugs (infliximab).</p>"),
          S("abpa", "Allergic Bronchopulmonary Aspergillosis (ABPA)", "<p>Occurs with preexisting asthma or cystic fibrosis: recurrent asthma exacerbations, worsening bronchospasm, coughing fits from mucus plugging, and productive cough of thick brown sputum.</p><p>Diagnosis: CXR shows upper lobe infiltrates plus bronchiectasis; labs show eosinophilia, elevated serum IgE, and Aspergillus-specific IgE (or a positive pinprick skin test).</p>" + HY("Treatment is a combination of prednisone plus itraconazole.")),
          S("allergic-sinusitis", "Allergic Aspergillus Sinusitis", "<p>Inflammation of the sinuses causing drainage, stuffiness, and headache, with nasal polyps and edematous turbinates on exam. Sinus CT shows nasal polyposis with sinus opacification, often with hyperdensities. Labs show elevated total IgE, eosinophils, and Charcot-Leyden crystals.</p><p>Treatment: remove polyps/mucus plus intranasal or systemic glucocorticoids; if persistent, endoscopic sinus surgery plus antifungals.</p>"),
          S("chronic-pulmonary", "Chronic Pulmonary Aspergillosis", "<p>Hallmark: formation and expansion of one or more pulmonary cavities over months to years, usually in preexisting lung damage (TB, NTM, COPD, thoracic surgery, sarcoidosis). Symptoms: months-long weight loss, chronic productive cough, hemoptysis, fatigue, shortness of breath.</p><p>Imaging shows one or more cavities (usually upper lobes) that may contain fungus balls (<strong>aspergillomas</strong>). Labs show elevated Aspergillus IgG.</p><p>Treatment: itraconazole x4-6 months; symptomatic aspergillomas need surgical resection.</p>"),
          S("invasive", "Invasive Aspergillosis", "<p>Most common in profoundly immunodeficient patients (HSCT, prolonged severe neutropenia), but can occur in critically ill immunocompetent patients. Pulmonary disease is most common (80%) -- patchy infiltration progressing to severe necrotizing pneumonia. Invasive sinus disease also occurs.</p><p>Symptoms: cough, fever, chest pain, shortness of breath, trivial hemoptysis. CNS dissemination causes hemorrhagic infarction/abscesses on MRI, with mood changes, seizures, and mental status decline. Other dissemination sites: eyes (endophthalmitis), heart (endocarditis), skin, GI tract.</p><p>Diagnosis: definitive diagnosis requires culture (sputum/BAL) plus tissue invasion on histopathology; serum galactomannan antigen (blood or BAL) also aids diagnosis.</p>" + HY("IV voriconazole is the treatment of choice for most patients with invasive aspergillosis."))
        ], [
          Q("overview", "In which patient population is ABPA classically seen?", ["Patients with preexisting asthma or cystic fibrosis", "Previously healthy patients with no lung disease", "Only patients with prior lung transplant", "Patients with a history of pulmonary embolism"], 0, "ABPA occurs in patients with preexisting asthma or cystic fibrosis, presenting as recurrent asthma exacerbations with thick brown sputum."),
          Q("abpa", "What lab finding, along with eosinophilia, supports a diagnosis of ABPA?", ["Elevated serum IgE and Aspergillus-specific IgE", "Elevated CA-125", "A positive rheumatoid factor", "Elevated troponin"], 0, "ABPA is supported by eosinophilia plus elevated total serum IgE and Aspergillus-specific IgE (or a positive skin prick test), along with upper lobe infiltrates and bronchiectasis on CXR."),
          Q("abpa", "What is the treatment regimen for ABPA?", ["Prednisone plus itraconazole", "IV amphotericin B alone", "Inhaled corticosteroids alone, with no antifungal", "IV voriconazole alone"], 0, "ABPA is treated with a combination of prednisone and itraconazole, addressing both the allergic inflammatory component and the fungal colonization."),
          Q("allergic-sinusitis", "What crystal finding on sinus pathology is characteristic of allergic Aspergillus sinusitis?", ["Charcot-Leyden crystals", "Calcium oxalate crystals", "Uric acid crystals", "Cholesterol crystals"], 0, "Charcot-Leyden crystals, along with elevated total IgE and eosinophils, are characteristic laboratory findings in allergic Aspergillus sinusitis."),
          Q("chronic-pulmonary", "What imaging finding, containing a fungus ball, is classic for chronic pulmonary aspergillosis?", ["An aspergilloma within a pulmonary cavity", "A solitary calcified granuloma", "Diffuse miliary nodules", "A pleural effusion without cavitation"], 0, "Chronic pulmonary aspergillosis causes expanding pulmonary cavities, usually in the upper lobes, which may contain fungus balls called aspergillomas."),
          Q("chronic-pulmonary", "What underlying condition is a prerequisite for most chronic pulmonary aspergillosis?", ["Preexisting lung damage (TB, NTM, COPD, sarcoidosis, or prior thoracic surgery)", "A prior episode of ABPA specifically", "No underlying lung disease is typically present", "Recent international travel"], 0, "Chronic pulmonary aspergillosis usually develops in patients with preexisting structural lung damage from conditions like TB, NTM, COPD, or sarcoidosis."),
          Q("invasive", "Which patient population is at highest risk for invasive aspergillosis?", ["Profoundly immunodeficient patients (HSCT recipients, prolonged severe neutropenia)", "Healthy patients with seasonal allergies", "Patients with well-controlled asthma", "Patients with a remote history of ABPA that resolved"], 0, "Invasive aspergillosis occurs most commonly in profoundly immunodeficient patients such as HSCT recipients and those with prolonged severe neutropenia, though it can rarely occur in critically ill immunocompetent patients."),
          Q("invasive", "What is the treatment of choice for invasive aspergillosis in most patients?", ["IV voriconazole", "PO itraconazole alone", "IV echinocandin as first-line monotherapy", "Oral fluconazole"], 0, "IV voriconazole is the treatment of choice for most patients with invasive aspergillosis."),
          Q("invasive", "What antigen test aids diagnosis of invasive aspergillosis?", ["Serum galactomannan antigen", "Cryptococcal antigen", "Histoplasma antigen", "Beta-hCG"], 0, "Serum (or BAL) galactomannan antigen testing aids the diagnosis of invasive aspergillosis, alongside culture and histopathologic evidence of tissue invasion.")
        ]),
        D("cryptococcosis", "Cryptococcosis", "Encapsulated yeast from soil/pigeon droppings; the leading cause of fungal meningitis, especially in AIDS.", [
          S("overview", "Organism & Epidemiology", "<p>Mainly <em>Cryptococcus neoformans</em>, an encapsulated budding yeast found worldwide in soil, decaying wood, and dried pigeon droppings -- the <strong>#1 cause of fungal meningitis</strong>. It is rarely symptomatic in immunocompetent hosts when inhaled. <em>C. gattii</em> is a closely related species found mainly in the Pacific Northwest US, associated with eucalyptus trees.</p>" + HY("Risk factors for progressive/disseminated disease: AIDS, prolonged glucocorticoids, solid organ transplant, TNF-alpha inhibitor therapy, and hematologic malignancies undergoing treatment.")),
          S("presentation", "Clinical Presentation", Tbl(["Form", "Presentation"], [
            ["Pulmonary", "Cough, shortness of breath, chest pain, increased sputum, fever over several weeks"],
            ["CNS disease", "The predominant presentation of dissemination -- headache, then fever, neck pain, N/V, photophobia, vision deficits, altered mental status, lethargy, cranial nerve paresis"],
            ["C. gattii", "Respiratory symptoms plus neurologic signs from space-occupying CNS lesions (cryptococcoma)"]
          ]) + "<p>Imaging: CXR shows solitary/few well-defined non-calcified pleural nodules. Cerebral cryptococcomas (from C. gattii) are best seen on MRI.</p>"),
          S("diagnosis-treatment", "Diagnosis & Treatment", "<p>Pulmonary disease: culture from sputum/pleural fluid, or serum cryptococcal antigen titer. Meningeal disease: LP is preferred; CSF shows increased opening pressure, variable pleocytosis, increased protein, and decreased glucose, plus positive culture.</p>" + Tbl(["Disease severity", "Treatment"], [
            ["Pulmonary in an immunocompetent host", "PO fluconazole"],
            ["Severe pulmonary, CNS, or disseminated disease", "IV amphotericin B + PO flucytosine, followed by PO fluconazole"]
          ]))
        ], [
          Q("overview", "Cryptococcus is the leading cause of which condition, especially in AIDS?", ["Fungal meningitis", "Bacterial pneumonia", "Infective endocarditis", "Septic arthritis"], 0, "Cryptococcus neoformans is the #1 cause of fungal meningitis worldwide, with AIDS being a major risk factor for progressive/disseminated disease."),
          Q("overview", "Which Cryptococcus species is associated with eucalyptus trees in the Pacific Northwest US?", ["C. gattii", "C. neoformans", "C. albicans", "C. auris"], 0, "C. gattii is closely related to C. neoformans but is found mainly in the Pacific Northwest US in association with eucalyptus trees."),
          Q("presentation", "What is the predominant presentation of disseminated cryptococcal infection?", ["CNS disease (meningitis/meningoencephalitis)", "Cutaneous disease", "Cardiac valve involvement", "GI involvement"], 0, "CNS disease is the predominant presentation of disseminated cryptococcosis, typically beginning with headache and progressing to fever, neck pain, and altered mental status."),
          Q("presentation", "What distinct CNS finding is associated with C. gattii infection?", ["Cryptococcoma (a space-occupying CNS lesion)", "Ring-enhancing lesions identical to toxoplasmosis", "Periventricular calcifications", "Subdural hematoma"], 0, "C. gattii causes cryptococcomas -- space-occupying CNS lesions -- best visualized on MRI, in addition to respiratory symptoms."),
          Q("diagnosis-treatment", "What CSF findings are expected in cryptococcal meningitis?", ["Increased opening pressure, variable pleocytosis, increased protein, decreased glucose", "Normal opening pressure with neutrophilic pleocytosis and normal glucose", "Decreased opening pressure with no pleocytosis", "Elevated glucose with low protein"], 0, "Cryptococcal meningitis classically shows increased opening pressure, variable pleocytosis, increased protein, and decreased glucose on CSF analysis, confirmed with culture."),
          Q("diagnosis-treatment", "What is the treatment for pulmonary cryptococcosis in an immunocompetent host?", ["PO fluconazole", "IV amphotericin B plus flucytosine", "IV voriconazole", "No treatment is ever indicated"], 0, "Mild pulmonary cryptococcosis in an immunocompetent host is treated with PO fluconazole, reserving the more aggressive amphotericin B + flucytosine regimen for severe, CNS, or disseminated disease."),
          Q("diagnosis-treatment", "What is the treatment for cryptococcal meningitis or severe/disseminated disease?", ["IV amphotericin B plus PO flucytosine, followed by PO fluconazole", "PO fluconazole alone from the start", "A single dose of IV amphotericin B", "Oral nystatin"], 0, "Severe pulmonary, CNS, or disseminated cryptococcosis requires induction therapy with IV amphotericin B plus PO flucytosine, followed by consolidation/maintenance PO fluconazole.")
        ]),
        D("mac", "Mycobacterium avium Complex (MAC)", "Nontuberculous mycobacterium causing chronic pulmonary disease or, in advanced AIDS, disseminated infection.", [
          S("overview", "Organism & Pathogenesis", "<p><em>M. avium</em> and <em>M. intracellulare</em> -- the most frequent cause of nontuberculous mycobacteria (NTM) pulmonary disease in the US. Ubiquitous in water/soil (tap water, garden/potting soil, water distribution systems).</p><p>Pulmonary infection occurs via inhalation of aerosols from natural surface water or domestic/institutional hot water systems, and is more common with underlying lung disease (bronchiectasis, COPD, CF). Dissemination is more common in immunosuppressed patients (AIDS) -- mucosal (gut/lung) infection leads to local multiplication, then bloodstream spread to other organs.</p>"),
          S("presentations", "Two Pulmonary Presentations", Tbl(["Form", "Typical patient", "Imaging"], [
            ["Fibrocavitary MAC", "White, middle-aged/older men with smoking history and underlying COPD", "Upper lobe infiltrates and cavitations"],
            ["Fibronodular/bronchiectatic MAC", "Predominantly nonsmoking women over 50 with chronic cough", "Bronchiectasis in mid lung zones"]
          ]) + "<p>Common symptoms over a months-to-years course: chronic nagging cough, sputum production, throat clearing, fatigue; less common: dyspnea, fever, hemoptysis, weight loss.</p>"),
          S("diagnosis-treatment", "Diagnosis & Treatment", HY("In immunocompetent patients, diagnosis rests on culture: a positive culture from &ge;2 separate expectorated sputum samples, OR &ge;1 bronchial wash, OR pleural fluid/other normally sterile site; OR culture from lung biopsy/bronchial wash/sputum plus histopathologic granulomatous inflammation on biopsy.") + "<p>Treatment is a combination of daily <strong>clarithromycin or azithromycin + rifampin or rifabutin + ethambutol</strong>. Surgical resection is an option if disease is confined to one lung and poorly responsive to antimicrobials.</p>")
        ], [
          Q("overview", "MAC is the most frequent cause of which category of pulmonary disease in the US?", ["Nontuberculous mycobacteria (NTM) pulmonary disease", "Community-acquired bacterial pneumonia", "Viral pneumonia", "Fungal pneumonia"], 0, "M. avium and M. intracellulare (MAC) together are the most frequent cause of NTM pulmonary disease in the United States."),
          Q("overview", "Where is MAC commonly found in the environment?", ["Water and soil, including tap water and potting soil", "Only in bird droppings", "Only in decaying vegetation", "Only in animal reservoirs, never in water or soil"], 0, "MAC organisms are ubiquitous in water and soil, including tap water, garden/potting soil, and water distribution systems -- inhaled aerosols are the main route of pulmonary infection."),
          Q("presentations", "Which patient population is classically affected by fibrocavitary MAC?", ["White, middle-aged/older men with smoking history and COPD", "Nonsmoking women over 50", "Young children with cystic fibrosis", "Immunocompetent young adults with no lung disease"], 0, "Fibrocavitary MAC classically affects white, middle-aged or older men with a smoking history and underlying COPD, presenting with upper lobe infiltrates and cavitations."),
          Q("presentations", "Which patient population is classically affected by fibronodular/bronchiectatic MAC?", ["Predominantly nonsmoking women over 50 with chronic cough", "Young men with a heavy smoking history", "Infants with congenital lung disease", "Elderly men with COPD and cavitary disease"], 0, "Fibronodular/bronchiectatic MAC predominantly affects nonsmoking women over 50 with chronic cough, showing bronchiectasis in the mid lung zones rather than upper-lobe cavitation."),
          Q("presentations", "What is the typical time course of MAC pulmonary symptoms?", ["Months to years, with a chronic nagging cough", "Acute onset over 24-48 hours", "A self-limited illness resolving within a week", "Symptoms are always absent until disseminated disease occurs"], 0, "MAC pulmonary disease has an indolent, months-to-years course dominated by chronic cough, sputum production, throat clearing, and fatigue."),
          Q("diagnosis-treatment", "How many separate sputum cultures are needed to diagnose MAC pulmonary disease in an immunocompetent patient (in the absence of a sterile-site or biopsy specimen)?", ["At least 2 separate expectorated sputum samples", "A single sputum sample is always sufficient", "At least 5 separate sputum samples", "Sputum culture is never used for MAC diagnosis"], 0, "Diagnosis in immunocompetent patients requires a positive culture from at least 2 separate expectorated sputum samples (or a single bronchial wash or sterile-site specimen, or biopsy with compatible histopathology)."),
          Q("diagnosis-treatment", "What is the standard multidrug treatment regimen for MAC pulmonary disease?", ["Clarithromycin or azithromycin + rifampin or rifabutin + ethambutol", "A single agent, azithromycin monotherapy", "Isoniazid + rifampin + pyrazinamide + ethambutol (standard TB therapy)", "IV vancomycin alone"], 0, "MAC is treated with a three-drug daily combination: a macrolide (clarithromycin or azithromycin) plus rifampin or rifabutin plus ethambutol -- distinct from standard 4-drug TB therapy."),
          Q("diagnosis-treatment", "When might surgical resection be considered for MAC pulmonary disease?", ["When disease is confined to one lung and poorly responsive to antimicrobials", "As first-line therapy before any antibiotics are tried", "Only in disseminated MAC, never in localized pulmonary disease", "Surgery is never indicated for MAC"], 0, "Surgical resection is an option when MAC disease is confined to one lung and responds poorly to antimicrobial therapy alone.")
        ]),
        D("mucormycosis", "Mucormycosis", "Rare, highly lethal mold infection of the immunocompromised and diabetics, especially in DKA.", [
          S("overview", "Organism, Presentation & Risk Factors", "<p>A rare disease caused by <em>Mucor</em> and <em>Rhizopus</em> species (order Mucorales). Can affect nearly any part of the body; the most common portals of entry are the skin, lungs, and sinuses. Overall mortality is approximately <strong>50%</strong>.</p>" + HY("Key risk factors: immunocompromised patients, diabetics (especially with DKA), IV drug users, and patients with severe skin trauma/burns -- DKA is a classically tested association."))
        ], [
          Q("overview", "Which fungal genera cause mucormycosis?", ["Mucor and Rhizopus", "Aspergillus and Penicillium", "Candida and Cryptococcus", "Histoplasma and Coccidioides"], 0, "Mucormycosis is caused by Mucor and Rhizopus species, both in the order Mucorales -- distinct from the other fungi covered in this lecture."),
          Q("overview", "Which diabetic complication is a classic risk factor for mucormycosis?", ["Diabetic ketoacidosis (DKA)", "Hyperosmolar hyperglycemic state without ketosis", "Diabetic nephropathy", "Diabetic peripheral neuropathy"], 0, "Diabetics, especially those in DKA, are at classically increased risk for mucormycosis, along with other immunocompromised patients, IV drug users, and those with severe skin trauma or burns."),
          Q("overview", "What are the most common portals of entry for mucormycosis?", ["Skin, lungs, and sinuses", "GI tract exclusively", "Bloodstream via mosquito bite", "Genitourinary tract exclusively"], 0, "Mucormycosis most commonly enters through the skin, lungs, or sinuses, though it can affect nearly any part of the body once established."),
          Q("overview", "What is the approximate overall mortality of mucormycosis?", ["About 50%", "About 5%", "Nearly 0%", "Essentially 100%, uniformly fatal"], 0, "Mucormycosis carries a high overall mortality of approximately 50%, reflecting its aggressive, angioinvasive nature.")
        ]),
        D("sporotrichosis", "Sporotrichosis", "\"Rose gardener's disease\" -- cutaneous/lymphatic spread from a soil or plant inoculation injury.", [
          S("overview", "Organism & Presentation", "<p><em>Sporothrix schenckii</em>, a dimorphic fungus found in soil, plants, and decaying organic matter -- known as \"<strong>rose gardener's disease</strong>\" because inoculation classically occurs from a thorn prick or similar plant-related skin break.</p><p>Infection is usually limited to cutaneous/subcutaneous tissue via direct inoculation through a skin break, though it can occasionally involve other sites.</p>" + HY("Infection begins at the inoculation site and spreads along lymphatics, producing a characteristic chain of nodules -- a distinctive spread pattern worth recognizing even without detailed treatment data in this lecture's source material."))
        ], [
          Q("overview", "Sporotrichosis is commonly known by what nickname, reflecting its classic mode of inoculation?", ["Rose gardener's disease", "Farmer's lung", "Valley fever", "Cave disease"], 0, "Sporotrichosis is nicknamed 'rose gardener's disease' because infection classically follows a thorn prick or other plant-related skin injury that inoculates Sporothrix schenckii into the skin."),
          Q("overview", "How does sporotrichosis characteristically spread from its inoculation site?", ["Along lymphatics, producing a chain of nodules", "Hematogenously to the brain within days", "It does not spread beyond the inoculation site under any circumstances", "Via airborne respiratory droplets to close contacts"], 0, "Sporotrichosis spreads along lymphatic channels from the initial inoculation site, producing a characteristic chain of nodules extending proximally.")
        ])
      ]),

      L("tick-borne-illnesses", "Tick Transmitted Illness", [
        D("rmsf", "Rocky Mountain Spotted Fever", "Rickettsial infection with fever, headache, and a rash starting on the wrists/ankles; doxycycline is started empirically.", [
          S("overview", "Organism, Epidemiology & Risk", Tbl(["", ""], [
            ["Organism", "<em>Rickettsia rickettsii</em> -- an obligate intracellular gram-negative bacterium"],
            ["Vectors", "American dog tick (<em>Dermacentor variabilis</em>) in the East; Rocky Mountain wood tick (<em>Dermacentor andersoni</em>) in the West"],
            ["Where", "Highest prevalence in the <strong>southeastern and south-central US</strong> -- not the Rocky Mountain region itself"],
            ["Season", "April through September"],
            ["Risk factors", "Increased age, exposure to dogs, wooded areas or high grasses, Native American ethnicity"],
            ["Transmission time", "Tick must feed on the dermis for <strong>&gt; 6 hours</strong> to transmit infected saliva"],
            ["Untreated fatality", "Up to 73%"]
          ]) + HY("Despite the name, RMSF today is concentrated in the southeastern/south-central US, not the Rocky Mountains -- a classic exam trap.") + "<p>Lymphohematogenous spread infects vascular endothelial cells throughout the body. After about a week, increased vascular permeability causes hypovolemia and tissue/organ ischemia -- this endothelial injury/vasculitis is the mechanistic basis for the rash, edema, and multiorgan dysfunction.</p>" + Mn("No PEP", "Unlike Lyme disease, there is no post-exposure prophylaxis after an RMSF-carrying tick bite.")),
          S("presentation", "Clinical Presentation", "<p>Classic triad: <strong>fever, headache, and rash</strong> in a patient with a tick-bite history.</p><p>Early symptoms (days 1-4): high fever, severe headache, malaise, myalgias, arthralgias, nausea/vomiting, anorexia, insomnia, irritability. Also seen: abdominal pain, edema (especially in children), confusion, seizures.</p>" + Tbl(["Rash feature", "Detail"], [
            ["Onset", "Day 2-6 of fever"],
            ["Early appearance", "Small (1-4mm), flat, pink, blanching, non-itchy macules"],
            ["Early distribution", "Starts on <strong>wrists, forearms, and ankles</strong>, then spreads centrally to the trunk"],
            ["Distinguishing feature", "<strong>Palm and sole involvement</strong> is classic"],
            ["Late appearance", "Macules become <strong>petechial</strong> (red to purple), usually day 6+ -- signals progression to severe disease"]
          ]) + HY("Some patients develop a petechial rash suddenly with no preceding maculopapular phase -- don't wait for the \"classic\" progression to suspect RMSF.") + "<p>Complications from day 5 onward: altered mental status, coma, cerebral edema; pulmonary edema/ARDS; skin necrosis (may require amputation); renal failure.</p>"),
          S("diagnosis", "Diagnosis", "<p><strong>Diagnosis is clinical.</strong> Begin treatment immediately on clinical suspicion -- do not wait for confirmatory testing, since delay increases mortality.</p><p>Confirmatory testing is retrospective: <strong>indirect immunofluorescence assay (IFA)</strong> for IgG antibodies (available commercially and free through most state health departments). IgG typically appears 7-10 days after illness onset; the optimal convalescent titer is drawn 14-21 days after symptom onset. Skin punch biopsy is an alternative.</p>" + Tbl(["Lab", "Finding"], [["WBC", "Usually normal"], ["Platelets", "Thrombocytopenia, worsening as illness progresses"], ["Advanced/severe disease", "Hyponatremia, elevated LFTs/bilirubin, azotemia, prolonged PT/PTT"]])),
          S("treatment", "Treatment & Prevention", HY("Doxycycline is first-line for <em>all</em> RMSF patients, including children and pregnant patients -- the risk of delaying treatment outweighs doxycycline's tooth-staining risk in this life-threatening disease.") + Tbl(["Regimen", "Detail"], [
            ["First-line", "Doxycycline 100mg PO or IV BID x 5-7 days, for all patients regardless of age or pregnancy"],
            ["Critically ill", "Single loading dose of 200mg"],
            ["Alternative", "Chloramphenicol -- less effective than doxycycline; reserved for a severe adverse reaction to doxycycline (e.g. TEN, severe hepatotoxicity)"]
          ]) + "<p>No post-exposure prophylaxis exists for RMSF. Prevention relies on general tick-avoidance measures: permethrin-treated clothing, EPA-registered repellents, daily tick checks, and prompt proper tick removal.</p>")
        ], [
          Q("overview", "What organism causes Rocky Mountain Spotted Fever?", ["Rickettsia rickettsii", "Borrelia burgdorferi", "Ehrlichia chaffeensis", "Francisella tularensis"], 0, "RMSF is caused by Rickettsia rickettsii, an obligate intracellular gram-negative bacterium."),
          Q("overview", "Despite its name, Rocky Mountain Spotted Fever is now most prevalent in which US region?", ["The southeastern and south-central US", "The Rocky Mountain states", "The Pacific Northwest", "New England"], 0, "A classic exam trap: RMSF is concentrated in the southeastern and south-central US today, not the Rocky Mountain region."),
          Q("overview", "Which tick is the primary RMSF vector in the eastern United States?", ["American dog tick (Dermacentor variabilis)", "Black-legged tick (Ixodes scapularis)", "Lone star tick (Amblyomma americanum)", "Rocky Mountain wood tick (Dermacentor andersoni)"], 0, "Dermacentor variabilis is the eastern US vector; Dermacentor andersoni carries RMSF in the western US."),
          Q("overview", "Roughly how long must a tick feed before it can transmit Rickettsia rickettsii?", ["More than 6 hours", "Less than 1 hour", "More than 24 hours", "More than 72 hours"], 0, "RMSF transmission requires the tick to feed on the dermis for more than 6 hours -- a much shorter window than Lyme's 24-36 hour requirement."),
          Q("overview", "What is the underlying pathophysiology that produces RMSF's rash and multiorgan dysfunction?", ["Infection of vascular endothelial cells causing increased vascular permeability", "Direct toxin-mediated neuromuscular blockade", "IgE-mediated mast cell degranulation", "Autoimmune demyelination"], 0, "Rickettsia rickettsii spreads lymphohematogenously and infects vascular endothelial cells, causing vasculitis, increased vascular permeability, hypovolemia, and tissue ischemia."),
          Q("overview", "What post-exposure prophylaxis is recommended after a tick bite in an area where RMSF is endemic?", ["None -- there is no RMSF prophylaxis", "Doxycycline 200mg single dose", "Doxycycline 100mg daily for 10 days", "Chloramphenicol single dose"], 0, "Unlike Lyme disease, there is no post-exposure prophylaxis for RMSF after a tick bite."),
          Q("presentation", "What is the classic triad of Rocky Mountain Spotted Fever?", ["Fever, headache, and rash", "Fever, arthralgia, and lymphadenopathy", "Rash, joint pain, and facial palsy", "Fever, cough, and conjunctivitis"], 0, "The classic RMSF triad is fever, headache, and rash in a patient with tick exposure."),
          Q("presentation", "Around what day of illness does the RMSF rash typically first appear?", ["Day 2-6", "Day 1", "Day 10-14", "It never appears in most patients"], 0, "The rash characteristically appears on day 2-6 of the fever, after the nonspecific prodrome."),
          Q("presentation", "Where does the RMSF rash classically begin, and how does it spread?", ["Wrists, forearms, and ankles, spreading centrally to the trunk", "The trunk, spreading peripherally to the extremities", "The face, spreading down the body", "The soles only, without further spread"], 0, "RMSF's rash starts peripherally on the wrists, forearms, and ankles and spreads centripetally to the trunk -- the opposite pattern of many other rashes."),
          Q("presentation", "Involvement of which two body sites is considered classic and distinguishing for the RMSF rash?", ["Palms and soles", "Scalp and axillae", "Mucous membranes only", "Abdomen and back only"], 0, "Palm and sole involvement is a classic, distinguishing feature of the RMSF rash."),
          Q("presentation", "A patient's RMSF rash changes from blanching macules to non-blanching petechiae. What does this indicate?", ["Progression to severe disease", "Resolution of the infection", "A drug allergy to doxycycline", "Superinfection with Staphylococcus aureus"], 0, "Petechial transformation of the rash, usually by day 6 or later, signals progression to severe disease."),
          Q("presentation", "Which of the following is a recognized complication of severe, advanced RMSF?", ["Cerebral edema and altered mental status", "Chronic arthritis of the knee", "Facial nerve palsy", "Erythema migrans"], 0, "Severe RMSF can progress to CNS complications including altered mental status, coma, and cerebral edema, as well as ARDS, skin necrosis, and renal failure. (The other options are Lyme disease findings.)"),
          Q("diagnosis", "How should suspected RMSF be managed while diagnostic testing is pending?", ["Start doxycycline empirically without waiting for confirmatory testing", "Wait for a positive IFA titer before starting antibiotics", "Wait for skin biopsy results before starting antibiotics", "Start antibiotics only if the classic rash is already present"], 0, "RMSF diagnosis is clinical, and treatment should begin immediately on suspicion -- delaying treatment for confirmatory serology increases mortality."),
          Q("diagnosis", "What is the confirmatory serologic test for RMSF, and when is it optimally drawn?", ["Indirect immunofluorescence assay (IFA) for IgG, optimally at 14-21 days after symptom onset", "Two-tier ELISA/Western blot, at symptom onset", "PCR of peripheral blood on day 1 of illness", "Rapid antigen test at the bedside"], 0, "IFA for IgG antibodies is the confirmatory test; it is retrospective, with IgG typically appearing 7-10 days after onset and an optimal convalescent titer at 14-21 days."),
          Q("diagnosis", "What is the typical white blood cell count and platelet trend in RMSF?", ["Normal WBC with thrombocytopenia that worsens as illness progresses", "Marked leukocytosis with thrombocytosis", "Leukopenia with a normal platelet count", "Eosinophilia with thrombocytopenia"], 0, "RMSF classically shows a normal WBC count with thrombocytopenia that becomes more prevalent and severe as the illness progresses."),
          Q("treatment", "What is the first-line treatment for RMSF, and does this change in children or pregnancy?", ["Doxycycline, used in all patients including children and pregnant patients", "Doxycycline, but avoided in children under 8 and in pregnancy", "Azithromycin, preferred in pregnancy", "Chloramphenicol, first-line in all patients"], 0, "Doxycycline is first-line for every RMSF patient regardless of age or pregnancy, because delaying treatment is more dangerous than doxycycline's tooth-staining risk in this potentially fatal disease."),
          Q("treatment", "When is chloramphenicol used instead of doxycycline for RMSF?", ["Only for a severe adverse reaction to doxycycline, since it is less effective", "As the preferred first-line agent in adults", "As the preferred agent in pregnancy", "Only for outpatient, mild disease"], 0, "Chloramphenicol is reserved as an alternative for patients with a severe adverse reaction to doxycycline (e.g. TEN, severe hepatotoxicity); it is less effective overall."),
          Q("treatment", "What loading dose of doxycycline is used in a critically ill RMSF patient?", ["200mg", "50mg", "500mg", "No loading dose is used"], 0, "A single 200mg loading dose of doxycycline is used in critically ill RMSF patients.")
        ]),
        D("lyme-disease", "Lyme Disease", "Borrelia burgdorferi from Ixodes ticks; staged disease from erythema migrans through disseminated disease to late arthritis/neuro findings.", [
          S("overview", "Organism, Transmission & Tick-Bite Prophylaxis", Tbl(["", ""], [
            ["Organism", "<em>Borrelia burgdorferi</em> (spirochete) -- the most common vector-borne disease in the US"],
            ["Vector", "<em>Ixodes scapularis</em> (black-legged / deer tick)"],
            ["Life cycle", "Larvae take a blood meal and become infected, molt to nymph the following spring, infect secondary hosts, molt to adult in fall (adults prefer white-tailed deer)"],
            ["Who transmits most", "The <strong>nymph</strong> stage -- small size makes it less likely to be noticed and removed before transmission occurs"],
            ["Attachment time needed", "<strong>&ge; 24-36 hours</strong>"],
            ["Season", "Spring through fall (nymphs questing April-July; adults active spring and fall)"],
            ["Setting", "Forestry, high grass, rural areas"]
          ]) + HY("Tick-bite prophylaxis: doxycycline 200mg as a single dose, if the tick was attached/engorged for &gt; 24 hours AND prophylaxis is given within 72 hours of the bite.") + Mn("Contrast with RMSF", "RMSF has no post-exposure prophylaxis at all; Lyme has a specific single-dose regimen with a time window.")),
          S("stage1", "Stage 1 -- Early Localized Disease", "<p>Classic finding: <strong>erythema migrans (EM)</strong>, with or without constitutional symptoms.</p>" + Tbl(["EM feature", "Detail"], [
            ["Timing", "Appears at the bite site 7-10 days after the bite (range 3-30 days)"],
            ["Frequency", "~80% of patients develop EM, but only ~25% recall the tick bite itself"],
            ["Appearance", "Expands slowly over days-weeks, often with central clearing (\"bullseye\"); not all lesions are a perfect circle, and necrotic/vesicular centers are rare"],
            ["Common sites", "Axilla, inguinal region, popliteal fossa, belt line"],
            ["Sensation", "May burn, itch, or feel warm; not classically painful"]
          ]) + "<p>Systemic, viral-syndrome-like symptoms over the first days to couple weeks: fatigue, anorexia, headache, neck stiffness, myalgias/arthralgias, regional lymphadenopathy. High fever is uncommon. Untreated, symptoms and EM resolve in 3-4 weeks.</p>" + HY("Diagnosis of Stage 1 with EM is clinical -- serology is often falsely negative this early and should not be relied on.") + Tbl(["Regimen", "Use"], [["Doxycycline 100mg PO BID x 10 days", "Preferred"], ["Amoxicillin 500mg PO TID x 14 days", "Preferred"], ["Cefuroxime 500mg PO BID x 14 days", "Preferred"], ["Azithromycin 500mg PO daily x 7 days", "Alternative -- preferred choice in pregnancy"]]) + '<p style="color:var(--faint);font-size:12px">Dosing shown is for adults; use weight-based dosing in children.</p>'),
          S("stage2", "Stage 2 -- Early Disseminated Disease", "<p>Occurs weeks to months after the tick bite.</p>" + HY("Multiple annular EM-like lesions indicate spirochetemia (hematogenous spread) -- NOT multiple tick bites. This is a classic distractor.") + "<p>Associated symptoms: constant malaise/fatigue, fever/chills, headache, neck pain, intermittent migratory musculoskeletal pain. Some patients have no antecedent Stage 1 history.</p>" + Tbl(["System", "Findings"], [
            ["Cardiac (4-10% of patients)", "Heart block, myocarditis/pericarditis, atrial or ventricular arrhythmias, palpitations, LV failure, sudden cardiac death"],
            ["Neurologic (10-15% of patients)", "Aseptic meningitis; cranial nerve palsy (<strong>facial nerve/CN VII is most common</strong> -- Bell's palsy); radiculopathy; peripheral neuropathy"]
          ]) + "<p>Patients with EM lesions can still be diagnosed clinically. Without EM, suspected disseminated disease (cardiac/neuro findings) warrants <strong>two-tier serology</strong>: initial ELISA, then confirmatory Western blot (IgM and IgG) if positive or equivocal. A positive immunoblot needs &ge;2 IgM or &ge;5 IgG specific bands. Serology is not helpful with a history of prior Lyme disease, since antibodies persist for years.</p>" + Tbl(["Manifestation", "Treatment"], [
            ["Multiple EM lesions", "Doxycycline 100mg PO BID x 21 days"],
            ["Migratory arthritis", "Doxycycline 100mg PO BID x 30 days"],
            ["Cranial nerve palsy", "Doxycycline 100mg PO BID x 14-21 days"],
            ["Meningitis", "Ceftriaxone 2g IV daily x 14-28 days"],
            ["1st/2nd degree heart block", "Doxycycline 100mg PO BID x 14-21 days"],
            ["3rd degree heart block or myopericarditis", "Ceftriaxone 2g IV daily x 14-21 days"]
          ])),
          S("stage3", "Stage 3 -- Late Disease", "<p>Occurs months to a few years after the tick bite.</p>" + HY("The most common late-stage finding is arthritis, typically of one or a few large weight-bearing joints -- the knee is the most common site.") + "<p>Joint pain and swelling resolve over weeks to months but can recur. Rare neurologic findings: distal paresthesia/spinal radicular pain, or encephalopathy (memory loss, mood or sleep disturbance).</p><p>Serologic testing is warranted; <strong>IgG Western blot is the test of choice</strong> and should be positive, since symptoms have typically been ongoing &ge;8 weeks by this point. Treatment uses the same stage/manifestation-based regimens as early disseminated disease.</p>"),
          S("ptlds-reinfection", "Post-Treatment Syndrome & Reinfection", Tbl(["Concept", "Detail"], [
            ["Post-treatment Lyme disease syndrome", "Nonspecific fatigue, widespread musculoskeletal pain, and cognitive difficulty persisting months-years after treatment, in 5-15% of patients; most improve gradually over 6 months to 1 year"],
            ["Reinfection", "Identified by a <strong>new EM rash</strong> in a patient with a history of prior successfully-treated EM; treated with the same regimen as a primary infection based on presenting stage"],
            ["Reinfection after Lyme arthritis", "Not reported"]
          ])),
          S("prevention", "Prevention", "<p>General tick-avoidance measures: know tick habitats (grassy, brushy, wooded areas, on animals) and walk in the center of trails; treat clothing/gear with <strong>0.5% permethrin</strong>; wear long sleeves/pants and light-colored clothing, tuck pants into socks; use EPA-registered repellents (DEET, picaridin, IR3535, oil of lemon eucalyptus, para-menthane-diol, or 2-undecanone); treat pets with tick preventatives; perform daily tick checks (under arms, in/around ears, inside belly button, behind knees, between legs, around waist, hairline/scalp).</p>" + HY("Correct tick removal: use fine-tipped tweezers, grasp the tick as close to the skin as possible, and pull straight up with steady, even pressure -- never twist, jerk, or crush the tick.") + "<p>Clean the bite site and hands with alcohol or soap and water after removal.</p>")
        ], [
          Q("overview", "Where does Lyme disease rank among vector-borne diseases in the United States?", ["The most common vector-borne disease in the US", "The second most common, after RMSF", "Rare, outside the top 5 most common", "Roughly tied with RMSF for most common"], 0, "Lyme disease, caused by Borrelia burgdorferi, is the most common vector-borne disease in the United States."),
          Q("overview", "What organism causes Lyme disease in the United States?", ["Borrelia burgdorferi", "Rickettsia rickettsii", "Francisella tularensis", "Anaplasma phagocytophilum"], 0, "Lyme disease is caused by the spirochete Borrelia burgdorferi."),
          Q("overview", "Which tick transmits Lyme disease?", ["Ixodes scapularis (black-legged/deer tick)", "Dermacentor variabilis (American dog tick)", "Amblyomma americanum (lone star tick)", "Dermacentor andersoni (Rocky Mountain wood tick)"], 0, "Ixodes scapularis, the black-legged or deer tick, is the vector for Lyme disease."),
          Q("overview", "Which tick life stage most commonly transmits Lyme disease to humans, and why?", ["The nymph, because its small size makes it less likely to be noticed and removed in time", "The larva, because it is the most numerous stage", "The adult, because it feeds the longest", "The egg, through transovarial transmission"], 0, "Nymphs transmit Lyme disease most often because their small size makes them less likely to be noticed and removed before the transmission window elapses."),
          Q("overview", "Approximately how long must an Ixodes tick be attached before Borrelia burgdorferi is typically transmitted?", ["24-36 hours or more", "Less than 1 hour", "6 hours", "Immediately upon attachment"], 0, "Transmission of B. burgdorferi typically requires at least 24-36 hours of tick attachment -- much longer than RMSF's 6-hour threshold."),
          Q("overview", "What tick-bite prophylaxis is recommended for Lyme disease, and under what conditions?", ["Doxycycline 200mg single dose, if the tick was attached >24 hours and prophylaxis is given within 72 hours of the bite", "Doxycycline 100mg daily for 10 days, given anytime after any tick bite", "No prophylaxis exists for Lyme disease", "Amoxicillin 500mg TID for 14 days, started within 24 hours"], 0, "Lyme tick-bite prophylaxis is a single 200mg dose of doxycycline, given when the tick was attached/engorged for more than 24 hours and prophylaxis starts within 72 hours of the bite."),
          Q("stage1", "What is the hallmark finding of early localized (Stage 1) Lyme disease?", ["Erythema migrans (EM)", "Bilateral facial palsy", "Migratory large-joint arthritis", "Heart block"], 0, "Erythema migrans, an expanding annular rash often with central clearing, is the hallmark of early localized Lyme disease."),
          Q("stage1", "About how long after a tick bite does erythema migrans typically appear?", ["7-10 days (range 3-30 days)", "Within 24 hours", "6-8 weeks", "Immediately at the time of the bite"], 0, "EM typically appears 7-10 days after the bite, with a range of 3-30 days."),
          Q("stage1", "What proportion of Lyme disease patients develop EM, and what proportion recall the actual tick bite?", ["About 80% develop EM, but only about 25% recall the bite", "About 25% develop EM, and 80% recall the bite", "Nearly 100% develop EM and recall the bite", "Less than 10% ever develop EM"], 0, "About 80% of patients develop EM, but only about 25% remember being bitten by a tick."),
          Q("stage1", "Where on the body does erythema migrans most commonly occur?", ["Axilla, inguinal region, popliteal fossa, and belt line", "Palms and soles", "Scalp only", "Face and neck only"], 0, "EM most commonly occurs at the axilla, inguinal region, popliteal fossa, and belt line."),
          Q("stage1", "How is early localized Lyme disease (with a typical EM rash) diagnosed?", ["Clinically -- serology is often falsely negative this early", "Only with a positive two-tier ELISA/Western blot", "Only with PCR of the skin lesion", "Only with a positive IgM Western blot"], 0, "Early Stage 1 Lyme disease with EM is a clinical diagnosis; serologic testing is often negative too early in infection to be useful."),
          Q("stage1", "What is the preferred treatment for early localized Lyme disease in a pregnant patient?", ["Azithromycin 500mg PO daily x 7 days", "Doxycycline 100mg PO BID x 10 days", "Ceftriaxone 2g IV daily x 14 days", "Chloramphenicol"], 0, "The slide lists doxycycline, amoxicillin, and cefuroxime as preferred regimens and azithromycin as the alternative regimen -- but specifically calls out azithromycin as the preferred choice in pregnancy."),
          Q("stage1", "Which of the following is an acceptable non-pregnant regimen for early localized Lyme disease?", ["Doxycycline 100mg PO BID x 10 days", "Doxycycline 100mg PO BID x 21 days", "Ceftriaxone 2g IV daily x 14 days", "Streptomycin IM x 10 days"], 0, "Doxycycline 100mg PO BID for 10 days is a preferred regimen for early localized (Stage 1) disease; the 21-day course is used for Stage 2 multiple EM lesions."),
          Q("stage2", "A patient has several separate annular skin lesions resembling erythema migrans. What does this represent?", ["Spirochetemia (hematogenous spread), not multiple tick bites", "Multiple separate tick bites, each causing its own EM", "An allergic reaction to the first EM lesion", "Early Lyme arthritis"], 0, "Multiple EM-like lesions indicate hematogenous spread of spirochetes (spirochetemia) -- a classic point that is often mistaken for multiple bites."),
          Q("stage2", "Approximately what percentage of Lyme disease patients develop cardiac involvement in early disseminated disease?", ["4-10%", "50-60%", "Less than 1%", "90%"], 0, "Cardiac involvement occurs in roughly 4-10% of patients with early disseminated Lyme disease."),
          Q("stage2", "Which cranial nerve palsy is most commonly associated with early disseminated Lyme disease?", ["Facial nerve (CN VII)", "Trigeminal nerve (CN V)", "Vagus nerve (CN X)", "Optic nerve (CN II)"], 0, "Facial nerve (CN VII) palsy, presenting as Bell's palsy, is the most common cranial neuropathy in early disseminated Lyme disease."),
          Q("stage2", "A patient with confirmed Lyme disease develops facial nerve palsy. Which feature of the palsy specifically points toward Lyme disease rather than idiopathic Bell's palsy?", ["Bilateral involvement", "Complete recovery within days", "Sparing of the forehead", "Absence of any preceding illness"], 0, "Bilateral facial palsy is atypical for idiopathic Bell's palsy, which is usually unilateral -- bilateral involvement, especially with a recent flu-like illness in an endemic area, should raise suspicion for an underlying cause such as Lyme disease."),
          Q("stage2", "In a patient without EM but with findings concerning for disseminated Lyme disease, what is the correct diagnostic approach?", ["Two-tier serology: ELISA screen, then Western blot to confirm if positive or equivocal", "Western blot alone, with no ELISA needed", "Skin biopsy of the affected joint", "PCR of cerebrospinal fluid regardless of symptoms"], 0, "Two-tier serologic testing -- an ELISA screen followed by a confirmatory Western blot if positive or equivocal -- is used when EM is absent but disseminated disease is suspected."),
          Q("stage2", "How many specific IgG bands are required for a positive Lyme Western blot?", ["5 or more", "1 or more", "10 or more", "2 or more (this is the IgM threshold, not IgG)"], 0, "A positive immunoblot requires antibodies against 5 or more specific IgG bands (or 2 or more specific IgM bands)."),
          Q("stage2", "What is the appropriate treatment for Lyme meningitis?", ["Ceftriaxone 2g IV daily for 14-28 days", "Doxycycline 100mg PO BID for 10 days", "Azithromycin 500mg PO daily for 7 days", "Amoxicillin 500mg PO TID for 14 days"], 0, "Lyme meningitis, a neurologic manifestation of disseminated disease, is treated with IV ceftriaxone 2g daily for 14-28 days."),
          Q("stage2", "A Lyme disease patient develops 3rd degree heart block. What is the appropriate treatment?", ["Ceftriaxone 2g IV daily x 14-21 days", "Doxycycline 100mg PO BID x 14-21 days", "Observation only, since it will self-resolve", "Amoxicillin 500mg PO TID x 21 days"], 0, "High-grade (3rd degree) heart block or myopericarditis from Lyme disease is treated with IV ceftriaxone, unlike 1st/2nd degree block, which can be treated with oral doxycycline."),
          Q("stage3", "What is the most common manifestation of late (Stage 3) Lyme disease?", ["Arthritis, typically of one or a few large weight-bearing joints", "Cranial nerve palsy", "Erythema migrans", "Heart block"], 0, "Arthritis is the most common late-stage manifestation of Lyme disease."),
          Q("stage3", "Which joint is most commonly affected by late Lyme arthritis?", ["The knee", "The hip", "The wrist", "The shoulder"], 0, "The knee is the most commonly affected joint in late Lyme disease/Lyme arthritis."),
          Q("stage3", "What is the serologic test of choice for diagnosing late Lyme disease?", ["IgG Western blot", "IgM Western blot alone", "ELISA alone, without confirmatory testing", "Rapid antigen test"], 0, "IgG Western blot is the test of choice for late Lyme disease, since by this stage (symptoms ongoing 8+ weeks) the IgG response should be well established."),
          Q("ptlds-reinfection", "How is Lyme disease reinfection typically identified?", ["A new erythema migrans rash in a patient with a history of prior treated EM", "A rise in ESR alone", "Recurrent fatigue without any rash", "A positive PPD"], 0, "Reinfection is almost always recognized by the appearance of a new EM rash in someone who was previously successfully treated for Lyme disease."),
          Q("ptlds-reinfection", "Roughly what percentage of treated Lyme disease patients develop post-treatment Lyme disease syndrome?", ["5-15%", "50-60%", "Less than 1%", "Nearly 100%"], 0, "Post-treatment Lyme disease syndrome -- persistent fatigue, musculoskeletal pain, and cognitive difficulty -- occurs in about 5-15% of treated patients."),
          Q("ptlds-reinfection", "Has Lyme disease reinfection been reported after an episode of Lyme arthritis?", ["No, it has not been reported", "Yes, it is the most common form of reinfection", "Yes, but only in immunocompromised patients", "Reinfection is impossible after any stage of Lyme disease"], 0, "Reinfection has not been reported following Lyme arthritis specifically, unlike reinfection after earlier-stage disease."),
          Q("prevention", "What permethrin concentration is recommended for treating clothing and gear to prevent tick bites?", ["0.5%", "5%", "0.05%", "50%"], 0, "Clothing and gear should be treated with products containing 0.5% permethrin."),
          Q("prevention", "What is the correct technique for removing an attached tick?", ["Grasp it with fine-tipped tweezers close to the skin and pull straight up with steady, even pressure", "Twist the tick counterclockwise while pulling", "Apply heat from a match to make the tick detach", "Crush the tick with your fingers, then pull it off"], 0, "Correct removal uses fine-tipped tweezers to grasp the tick close to the skin, pulling straight up with steady pressure -- never twisting, jerking, or crushing it.")
        ])
      ]),

      L("syphilis", "Syphilis", [
        D("syphilis", "Syphilis", "Treponema pallidum with primary, secondary, latent, and tertiary stages, plus distinct early vs. late neurosyphilis -- each with its own treatment.", [
          S("overview", "Organism, Transmission & Epidemiology", "<p><em>Treponema pallidum</em> -- a slender, corkscrew-shaped, motile spirochete, too thin to see on Gram stain or routine light microscopy; visualized by <strong>darkfield microscopy</strong>.</p><p>Transmitted by direct contact with an infectious lesion (chancre, mucous patch, condyloma lata, or rash) during oral, vaginal, or anal sex -- the organism penetrates intact mucous membranes or microscopic dermal abrasions, then rapidly enters lymphatics/blood. It also readily crosses the placenta (vertical transmission) or can transmit during delivery, causing congenital syphilis.</p>" + HY("The most infectious stages are PRIMARY (chancre) and SECONDARY (rash/mucous patches/condyloma lata) -- these lesions are teeming with spirochetes. Late latent syphilis is NOT sexually transmitted -- only via blood transfusion, organ donation, or transplacentally.") + "<p>Currently a heterosexual epidemic in the US (P&S cases 2019-2023 rose 20.9% in men, 112% in women), though 33% of male infections occur in MSM -- the strongest risk factor in men is sexual contact with other men. Other risk factors: unprotected sex, IV/meth drug use, condomless sex with multiple partners, exchanging sex for drugs/money, incarceration.</p>" + Mn("HIV interaction", "\"STIs travel together\" -- syphilis increases the likelihood of acquiring HIV if exposed, since the chancre's ulcerative lesion breaches the mucosal barrier. In 2023, 41% of MSM with primary/secondary syphilis had diagnosed HIV.")),
          S("primary-secondary", "Primary & Secondary Syphilis (Early)", Tbl(["Stage", "Timing", "Presentation"], [
            ["Primary -- the chancre", "A few days to 3 months after exposure", "Typically PAINLESS; evolves papule -> 1-2cm nonexudative ulcer with raised/rolled margins; usually SOLITARY; persists 3-6 weeks then heals spontaneously (even untreated) leaving a scar. Most common: glans penis (males), vulva/cervix (females). Regional lymphadenopathy: bilateral, painless/minimally tender, firm and rubbery -- epitrochlear nodes are a classic clue."],
            ["Secondary", "4-10 weeks after an untreated chancre", "Systemic symptoms (low-grade fever, malaise, weight loss, myalgias, sore throat, LAD) plus a diffuse, bilateral, symmetric rash on the trunk/extremities that classically involves the PALMS AND SOLES; copper/reddish-brown, macular/papular lesions; mucous patches (whitish mucosal erosions); condyloma lata (painless, grey-white, highly infectious plaques near the chancre -- NOT the same as HPV condyloma acuminata); patchy 'moth-eaten' alopecia."]
          ]) + HY("Both the chancre and the secondary rash are HIGHLY INFECTIOUS -- all these lesions are loaded with spirochetes.")),
          S("early-neuro", "Early Neurosyphilis", "<p>Occurs typically within the <strong>first 6-12 months</strong> of infection, during the primary or secondary stage. Neurosyphilis (early or late) can ONLY be diagnosed by <strong>VDRL performed on CSF</strong> obtained via lumbar puncture.</p>" + Tbl(["Presentation", "Key features"], [
            ["Asymptomatic neurosyphilis", "No CNS symptoms, but abnormal CSF (lymphocytic pleocytosis, elevated protein, reactive CSF-VDRL)"],
            ["Meningitis", "Headache, confusion, nuchal rigidity, N/V, photophobia -- an aseptic meningitis picture"],
            ["Meningovascular syphilis", "Vascular inflammation of brain/meninges/spinal cord vessels -> ischemic infarcts (stroke); often subacute onset (headache, vertigo, insomnia) FOLLOWED BY stroke"],
            ["Ocular", "Anterior, posterior, or panuveitis -- red eye, blurred vision, photophobia, increased IOP"],
            ["Otic (otosyphilis)", "Tinnitus, vertigo, sudden unilateral or bilateral sensorineural hearing loss that CAN BECOME PERMANENT"]
          ]) + HY("Cranial nerve deficits in neurosyphilis most commonly affect the optic, facial, and auditory nerves.")),
          S("late-neuro", "Late Neurosyphilis", "<p>Diagnosed the same way as early neurosyphilis -- CSF VDRL after LP.</p>" + Tbl(["Presentation", "Timing", "Key features"], [
            ["General paresis", "Generally 10-25 years after primary infection", "Progressive DEMENTIA from cerebral atrophy: personality changes, impaired memory/speech, psychosis, tremor, seizures"],
            ["Tabes dorsalis", "Also late (10-25+ years)", "Destruction of the posterior columns and dorsal nerve roots: impaired vibration/proprioception, sensory ataxia, urinary retention/overflow incontinence, lancinating (lightning) pain in the legs/back/face, optic atrophy"]
          ]) + HY("The Argyll-Robertson pupil -- 'accommodates but does not react' to light, the classic 'prostitute's pupil' -- is a shared classic finding of BOTH general paresis and tabes dorsalis.")),
          S("latent-tertiary", "Latent & Tertiary Syphilis (Late)", Tbl(["Stage", "Timing", "Definition/Findings"], [
            ["Early latent", "<1 year since infection", "Asymptomatic PLUS serologic evidence, meeting at least one criterion: documented nontreponemal seroconversion in the past 12 months, symptoms of primary/secondary syphilis in the past 12 months, OR sexual exposure to an infected partner in the past 12 months. 25% have periodic infectious mucocutaneous relapses."],
            ["Late latent", ">1 year since infection", "Asymptomatic, seropositive, does NOT meet any early latent criterion. If duration is UNKNOWN, the patient is PRESUMED late latent (this determines treatment). NOT sexually transmissible."],
            ["Tertiary -- gummas", "1-30 years after primary infection, in ~15-40% of untreated patients", "Granulomatous lesions that ulcerate; classic sites: liver, bones, testes; rarely seen in the US today"],
            ["Tertiary -- cardiovascular syphilis", "&ge;10 years after primary infection; 80-85% of tertiary cases; more common in men", "Inflammatory destruction of the vasa vasorum -> ascending aortic aneurysm ± aortic regurgitation (syphilitic aortitis)"]
          ])),
          S("diagnosis", "Diagnostic Testing", "<p>Two-step approach:</p>" + Tbl(["Step", "Tests", "Purpose"], [
            ["1. Nontreponemal (screening)", "VDRL or RPR -- measure reactivity to a cardiolipin-cholesterol-lecithin antigen", "Low-cost, sensitive screening. Limitation: 20-30% can be falsely NEGATIVE until 2-4 weeks after the chancre appears. False positives: pregnancy, lupus, IV drug use, endocarditis, rickettsial infection. False negatives: advanced HIV/AIDS."],
            ["2. Treponemal (confirmatory)", "TP-EIA or FTA-ABS -- detect antibodies against specific treponemal antigens", "More expensive/specific -- done ONLY if nontreponemal is positive. BOTH must be reactive to diagnose active/prior infection."]
          ]) + HY("Darkfield microscopy of lesion exudate can directly visualize the spirochete from a chancre. Neurosyphilis (early or late) can ONLY be diagnosed by VDRL performed on CSF.")),
          S("treatment", "Treatment by Substage & Monitoring", HY("General rule: IM benzathine penicillin G is the drug of choice for ALL stages EXCEPT neurosyphilis (including ocular/otic disease), which requires IV penicillin.") + Tbl(["Stage", "Regimen"], [
            ["Primary, secondary, or early latent (infection within 1 year)", "Benzathine penicillin G 2.4 million units IM x1 dose. Alternative (e.g. PCN allergy without desensitization): doxycycline 100mg PO BID x2 weeks."],
            ["Late latent and tertiary (cardiac/gummas), including unknown duration (presumed late latent)", "Benzathine penicillin G 2.4 million units IM weekly x3 weeks (3 total doses)"],
            ["Neurosyphilis -- early or late (including ocular disease)", "Hospital admission; IV penicillin G x10-14 days. Ceftriaxone only if desensitization isn't a reasonable option for a penicillin-allergic patient."]
          ]) + "<p>Monitor response with the SAME nontreponemal test (VDRL or RPR) used at diagnosis -- success is a <strong>four-fold decline</strong> in titer (e.g. 1:32 -> 1:8). Early syphilis: recheck titers at 6 and 12 months. Late syphilis: recheck at 6, 12, and 24 months.</p>" + HY("Treponemal tests (FTA-ABS, TP-EIA) usually stay positive FOR LIFE -- they are never used to track treatment response or diagnose reinfection. Only nontreponemal titers (VDRL/RPR) track response and reinfection, via a new four-fold rise.")),
          S("counseling-special", "Counseling, Exposure Management & Special Populations", HY("Jarisch-Herxheimer reaction: an acute, self-limiting febrile illness (headache, myalgias, fever) from endotoxin release as spirochetes lyse, starting WITHIN 24 HOURS of penicillin administration. It is common, expected, treated symptomatically, and is NOT a drug allergy.") + "<p>Exposed partners: treat empirically if condomless contact within the preceding 3 months was with a person diagnosed with primary, secondary, or early latent syphilis, OR with late latent syphilis with a high nontreponemal titer (>1:32). If &gt;90 days since exposure, treat presumptively only if follow-up is uncertain or testing unavailable.</p><p><strong>Pregnancy:</strong> ALL pregnant women require syphilis screening at the first prenatal visit, repeated at 32 weeks and at delivery if high risk -- pregnancy itself is also a cause of a false-positive nontreponemal test.</p><p>Syphilis is a <strong>reportable disease</strong> -- all cases require health department notification, which then performs contact tracing of sexual contacts.</p>")
        ], [
          Q("overview", "How is Treponema pallidum visualized directly, given that it's too thin for Gram stain?", ["Darkfield microscopy", "Standard light microscopy with Gram stain", "Acid-fast (Ziehl-Neelsen) stain", "Silver stain on routine H&E"], 0, "T. pallidum is a slender spirochete too thin to see reliably on routine light microscopy or Gram stain -- darkfield microscopy is used to directly visualize it in lesion exudate."),
          Q("overview", "Which stages of syphilis are the most infectious?", ["Primary (chancre) and secondary (rash/mucous patches/condyloma lata)", "Early latent and late latent", "Tertiary and late neurosyphilis only", "Congenital syphilis only"], 0, "Primary and secondary syphilis lesions are teeming with spirochetes and are highly infectious -- late latent syphilis, by contrast, is not sexually transmissible at all."),
          Q("overview", "What is the strongest risk factor for syphilis in men?", ["Sexual contact with other men", "Age over 40", "Recent international travel", "A history of eczema"], 0, "Sexual contact with other men (MSM) is the strongest risk factor for syphilis in men, and MSM account for 33% of male infections."),
          Q("overview", "Why does syphilis increase the risk of acquiring HIV?", ["The chancre's ulcerative lesion breaches the mucosal barrier, facilitating HIV entry", "Syphilis directly suppresses CD4 count", "Syphilis and HIV are caused by the same organism", "There is no established link between syphilis and HIV risk"], 0, "The open ulcerative chancre breaches the mucosal/dermal barrier, providing a portal of entry that increases the likelihood of acquiring HIV upon exposure -- reflected in the high overlap (41% of MSM with P&S syphilis had HIV in 2023)."),
          Q("primary-secondary", "What are the classic characteristics of the primary syphilis chancre?", ["Painless, solitary, 1-2cm ulcer with raised/rolled margins that heals spontaneously in 3-6 weeks", "Painful, multiple, exudative ulcers that require treatment to resolve", "A pruritic vesicular rash", "A fixed, tender nodule that never ulcerates"], 0, "The classic chancre is painless, usually solitary, a 1-2cm nonexudative ulcer with raised/rolled margins, and heals spontaneously (even without treatment) in 3-6 weeks, leaving a scar."),
          Q("primary-secondary", "What lymph node group is a classic clue for primary syphilis?", ["Epitrochlear nodes", "Supraclavicular nodes", "Popliteal nodes", "Preauricular nodes"], 0, "Bilateral, painless/minimally tender, firm and rubbery regional lymphadenopathy is associated with the chancre, and epitrochlear nodes are a classic clue."),
          Q("primary-secondary", "What distribution is classic for the secondary syphilis rash?", ["Diffuse, bilateral, symmetric, involving the trunk/extremities AND the palms and soles", "Confined to the genital area only", "A single dermatomal band", "Confined to the face and scalp only"], 0, "Secondary syphilis produces a diffuse, bilateral, symmetric rash on the trunk and extremities that classically involves the palms and soles -- a key teaching clue."),
          Q("primary-secondary", "What are condyloma lata, and how do they differ from condyloma acuminata?", ["Painless, grey-white, highly infectious syphilitic plaques -- NOT the HPV genital warts (condyloma acuminata)", "The same lesion as HPV genital warts, just a different name", "A painful vesicular eruption seen in primary syphilis", "A rash confined to the palms and soles only"], 0, "Condyloma lata are flat, moist, grey-white, highly infectious plaques of secondary syphilis -- a classic point of confusion with condyloma acuminata (HPV genital warts), which are a completely different, unrelated lesion."),
          Q("primary-secondary", "What hair finding is associated with secondary syphilis?", ["Patchy 'moth-eaten' alopecia", "Complete, permanent alopecia totalis", "Hirsutism", "Alopecia limited to the eyebrows only, sparing the scalp"], 0, "Secondary syphilis can cause patchy alopecia of the scalp and facial hair (including eyebrows), described as having a 'moth-eaten' appearance."),
          Q("early-neuro", "How is neurosyphilis diagnosed?", ["VDRL performed on CSF obtained via lumbar puncture", "A reactive serum RPR alone", "MRI findings alone, without CSF testing", "A positive darkfield microscopy of a skin lesion"], 0, "Neurosyphilis, whether early or late, can only be diagnosed by VDRL performed on CSF obtained via LP -- serum tests alone are not sufficient."),
          Q("early-neuro", "A patient with early syphilis develops subacute headache, vertigo, and insomnia, followed by an ischemic stroke. What form of early neurosyphilis does this represent?", ["Meningovascular syphilis", "Tabes dorsalis", "General paresis", "Otosyphilis"], 0, "Meningovascular syphilis causes vascular inflammation of brain/meningeal/spinal vessels leading to ischemic infarcts, often with a subacute prodrome of headache, vertigo, and insomnia before the stroke."),
          Q("early-neuro", "Which cranial nerves are most commonly affected in neurosyphilis?", ["Optic, facial, and auditory nerves", "Olfactory and trigeminal nerves", "Vagus and hypoglossal nerves", "Oculomotor and trochlear nerves only"], 0, "The optic, facial, and auditory (vestibulocochlear) nerves are most commonly affected by neurosyphilis, consistent with its ocular and otic (otosyphilis) presentations."),
          Q("early-neuro", "What is a feared, potentially permanent complication of otosyphilis?", ["Sudden sensorineural hearing loss", "Conductive hearing loss from otitis media", "Facial nerve paralysis that always resolves", "Complete anosmia"], 0, "Otosyphilis can cause sudden unilateral or bilateral sensorineural hearing loss, along with tinnitus and vertigo, and this hearing loss can become permanent."),
          Q("late-neuro", "What pupillary finding is classic for late neurosyphilis?", ["Argyll-Robertson pupil -- accommodates but does not react to light", "A fixed, dilated pupil that neither accommodates nor reacts", "Anisocoria with a sluggish but present light reflex", "Miosis that resolves with naloxone"], 0, "The Argyll-Robertson pupil -- which accommodates (constricts with near focus) but does not react to light -- is the classic 'prostitute's pupil' finding shared by both general paresis and tabes dorsalis."),
          Q("late-neuro", "A patient with a history of untreated syphilis develops progressive dementia, personality changes, and seizures 15 years after the initial infection. What is this?", ["General paresis", "Tabes dorsalis", "Meningovascular syphilis", "Early neurosyphilis"], 0, "General paresis is a late neurosyphilis presentation, generally occurring 10-25 years after primary infection, causing progressive dementia from cerebral atrophy along with personality changes, psychosis, tremor, and seizures."),
          Q("late-neuro", "What spinal cord structures are destroyed in tabes dorsalis, and what symptom results?", ["The posterior columns and dorsal nerve roots, causing impaired vibration/proprioception and sensory ataxia", "The anterior horn cells, causing flaccid paralysis", "The corticospinal tracts, causing spastic paralysis", "The dorsal root ganglia only, with no sensory loss"], 0, "Tabes dorsalis destroys the posterior columns and dorsal nerve roots, causing impaired vibration and proprioception, sensory ataxia, bladder dysfunction, lancinating pain, and optic atrophy."),
          Q("latent-tertiary", "If the duration of a patient's syphilis infection is unknown, how should it be classified for treatment purposes?", ["Presumed late latent syphilis", "Presumed early latent syphilis", "Presumed primary syphilis", "Presumed tertiary syphilis, requiring IV penicillin"], 0, "When the timing or duration of infection is unknown, the patient is presumed to have late latent syphilis, which determines the treatment (3 weekly IM penicillin doses rather than a single dose)."),
          Q("latent-tertiary", "Which criterion would classify a patient as having EARLY latent syphilis?", ["Sexual exposure within the previous 12 months to a partner with primary, secondary, or early latent syphilis", "Asymptomatic with seropositivity and no known exposure or symptoms in the past year", "A chancre diagnosed 2 years ago that has since healed", "Any positive treponemal test regardless of timing"], 0, "Early latent syphilis requires meeting at least one of: documented nontreponemal seroconversion within 12 months, symptoms of 1° or 2° syphilis within 12 months, or sexual exposure within 12 months to an infected partner."),
          Q("latent-tertiary", "Where are gummas classically found in tertiary syphilis?", ["Liver, bones, and testes", "Lungs and kidneys", "Brain and spinal cord exclusively", "Only in the oral mucosa"], 0, "Gummas -- granulomatous lesions that ulcerate -- classically occur in the liver, bones, and testes, though they may also appear in skin or other viscera."),
          Q("latent-tertiary", "What is the mechanism and classic cardiovascular consequence of tertiary cardiovascular syphilis?", ["Destruction of the vasa vasorum, leading to ascending aortic aneurysm ± aortic regurgitation", "Direct bacterial invasion of the mitral valve leaflets, causing mitral stenosis", "Coronary artery vasospasm causing recurrent angina", "Pericardial effusion from direct treponemal seeding"], 0, "Cardiovascular syphilis results from inflammatory destruction of the vasa vasorum (small arteries supplying the aorta), leading to ascending aortic aneurysm with possible aortic regurgitation -- syphilitic aortitis."),
          Q("diagnosis", "What is the correct order of syphilis serologic testing?", ["Nontreponemal (VDRL/RPR) screening first, then treponemal (TP-EIA/FTA-ABS) confirmation if positive", "Treponemal testing first, then nontreponemal only if negative", "Both tests are always run simultaneously regardless of results", "Darkfield microscopy replaces the need for any serologic testing"], 0, "The two-step approach starts with a nontreponemal screening test (VDRL or RPR); only if that is positive is a more specific, more expensive treponemal test (TP-EIA or FTA-ABS) performed to confirm."),
          Q("diagnosis", "Why might a nontreponemal test be falsely negative very early in primary syphilis?", ["20-30% remain nonreactive until 2-4 weeks after the chancre appears (antibody formation lag)", "Nontreponemal tests are never accurate in primary syphilis at any point", "The chancre destroys circulating antibodies", "Nontreponemal tests only detect secondary and later stages"], 0, "There is a lag before antibody formation is detectable -- 20-30% of nontreponemal tests are falsely negative until 2-4 weeks after the chancre appears, so a single early negative test doesn't rule out primary syphilis."),
          Q("diagnosis", "Which of the following is a recognized cause of a FALSE POSITIVE nontreponemal (VDRL/RPR) test?", ["Pregnancy", "Recent penicillin treatment for an unrelated infection", "A prior MMR vaccination", "Type 2 diabetes"], 0, "Pregnancy, connective tissue disorders (like lupus), IV drug use, bacterial endocarditis, and rickettsial infections are all recognized causes of a false-positive nontreponemal test -- confirmatory treponemal testing remains essential."),
          Q("treatment", "What is the treatment for primary, secondary, or early latent syphilis?", ["Benzathine penicillin G 2.4 million units IM as a single dose", "Benzathine penicillin G 2.4 million units IM weekly x3 weeks", "IV penicillin G for 10-14 days", "Oral doxycycline is always preferred over penicillin regardless of allergy status"], 0, "A single IM dose of benzathine penicillin G 2.4 million units treats primary, secondary, and early latent (infection within 1 year) syphilis -- doxycycline 100mg PO BID x2 weeks is the alternative for penicillin allergy."),
          Q("treatment", "What is the treatment for late latent syphilis or tertiary syphilis (cardiac/gummas)?", ["Benzathine penicillin G 2.4 million units IM weekly x3 weeks", "A single IM dose of benzathine penicillin G", "IV penicillin G for 10-14 days as an inpatient", "Oral doxycycline alone, with no penicillin option"], 0, "Late latent and tertiary (cardiac/gummas) syphilis require three weekly IM doses of benzathine penicillin G -- three times the duration of early-stage treatment."),
          Q("treatment", "What is required to treat neurosyphilis, and why?", ["Hospital admission for IV penicillin G x10-14 days, since IM penicillin doesn't achieve adequate CSF levels", "The same single IM dose used for primary syphilis", "Oral doxycycline as first-line therapy", "No antibiotics -- only supportive management of CNS symptoms"], 0, "Neurosyphilis (including ocular/otic disease) requires IV penicillin G for 10-14 days as an inpatient, since it requires a different route/regimen than the IM benzathine penicillin used for other stages; ceftriaxone is used only if desensitization isn't feasible for a penicillin-allergic patient."),
          Q("treatment", "How is successful syphilis treatment confirmed on follow-up serology?", ["A four-fold decline in the nontreponemal titer, using the same test type as at diagnosis", "A four-fold decline in the treponemal antibody test", "Any decline at all in either test type is considered success", "Treponemal test reverting to negative within 3 months"], 0, "Treatment success is defined as a four-fold decline in nontreponemal titer (e.g., 1:32 to 1:8), monitored using the SAME test (VDRL or RPR) used at diagnosis since the two aren't interchangeable."),
          Q("treatment", "How is a new (recurrent) syphilis infection diagnosed after prior successful treatment?", ["A previously negative titer becomes newly positive, or a low positive titer shows a new four-fold rise", "Any positive treponemal test at any point after treatment", "A stable, unchanged low titer at 12 months", "Recurrence cannot be diagnosed serologically and requires darkfield microscopy"], 0, "Reinfection is diagnosed by a previously negative post-treatment VDRL/RPR becoming newly positive, or by a new four-fold rise in a low positive titer -- treponemal tests are not used for this since they usually stay positive for life."),
          Q("counseling-special", "What is the Jarisch-Herxheimer reaction, and when does it occur?", ["A self-limiting fever/myalgia/headache reaction within 24 hours of penicillin treatment, from endotoxin release as spirochetes lyse", "A true IgE-mediated penicillin allergy requiring epinephrine", "A delayed hypersensitivity rash appearing 1-2 weeks after treatment", "A sign of treatment failure requiring a change in antibiotic"], 0, "The Jarisch-Herxheimer reaction is an expected, self-limiting febrile illness from endotoxin release as treponemes are killed by penicillin, occurring within the first 24 hours -- it is not a drug allergy and is treated symptomatically."),
          Q("counseling-special", "When should all pregnant women be screened for syphilis?", ["At the first prenatal visit, repeated at 32 weeks and at delivery if high risk", "Only once, at the very first prenatal visit", "Only in the third trimester", "Only if the patient reports symptoms"], 0, "All pregnant women require syphilis screening at the first prenatal visit, with repeat screening at 32 weeks and at delivery if high risk, given the risk of vertical/transplacental transmission causing congenital syphilis."),
          Q("counseling-special", "Under what circumstance should a sexual partner of a syphilis patient be treated empirically?", ["Condomless contact within the preceding 3 months with a person diagnosed with primary, secondary, or early latent syphilis", "Any contact ever, regardless of timing or the index patient's stage", "Only if the partner is already symptomatic", "Only after a confirmed positive treponemal test in the partner"], 0, "Empiric treatment is given for condomless oral/vaginal/anal contact within the preceding 3 months with a person diagnosed with primary, secondary, or early latent syphilis, or with late latent syphilis with a high titer (>1:32)."),
          Q("counseling-special", "What is the reporting requirement for a diagnosed case of syphilis?", ["Syphilis is a reportable disease requiring health department notification and contact tracing", "Reporting is only required for congenital syphilis cases", "Reporting is optional at the provider's discretion", "Only laboratories, not providers, must report syphilis"], 0, "All cases of syphilis require health department notification -- it is a reportable disease, and the health department then conducts contact tracing of sexual contacts.")
        ])
      ]),

      L("sepsis", "Pathophysiology of Sepsis", [
        D("sepsis-septic-shock", "Sepsis / Septic Shock", "Infection with organ dysfunction progressing to pressor-dependent shock; time-to-antibiotics is the top mortality predictor.", [
          S("definitions", "Definitions & Scoring", Tbl(["Term", "Definition"], [
            ["Colonization", "Presence of a potential pathogen without an inflammatory response"],
            ["Infection", "An invading organism causes an inflammatory process in a normally sterile area"],
            ["Virulence", "How easily a pathogen overcomes host defenses"],
            ["Pathogenicity", "How likely an agent is to cause disease"],
            ["Bacteremia", "Viable bacteria growing in the bloodstream, detectable on blood cultures"],
            ["Sepsis", "Infection WITH altered organ function -- oliguria, AKI, coagulopathy, AMS, elevated lactate"],
            ["Septic shock", "Sepsis requiring pressors to maintain organ perfusion: MAP &ge;65 mmHg on pressors AND lactate &gt;2"]
          ]) + HY("SIRS criteria (still used by CMS, phased out of SCCM/ESICM guidelines in 2016) need 2 of 4: HR >90, RR >20 (or pCO2 <32 on ABG), Temp >100.4°F or <96.8°F, WBC >12,000 or <4,000 (or >10% bands).") + Tbl(["qSOFA point (1 each)", "Risk of death"], [
            ["RR &ge;22, altered mentation, SBP &le;100 mmHg", "0-1 points = 3% · 2 points = 18% · 3 points = 24%"]
          ]) + "<p>qSOFA replaced SIRS in the 2016 SCCM/ESICM guidelines and is validated outside the ICU. The SOFA score is a more formal organ-dysfunction scoring tool -- know that it exists and is used, but its calculation is not tested here.</p>"),
          S("pathogenesis", "Pathogenesis", "<p>Acute inflammation starts with an insult (heat, chemical, or infectious). If purely local with no systemic findings, it's just \"infection.\" If untreated/fulminant, it progresses: <strong>SIRS -> sepsis -> septic shock</strong>.</p>" + HY("Endotoxin (gram-negative) or cell wall products (gram-positive) induce pro-inflammatory cytokines -- mainly IL-1 and TNF-alpha -- which activate neutrophils and vascular endothelium, causing endothelial damage and leaky vessels. This drives progressive organ dysfunction DISTANT from the infection site (AKI, AMS) = sepsis.") + "<p>Systemic inflammation also activates coagulation, causing microthrombi, tissue ischemia, and consumption of platelets/clotting factors/natural anticoagulants. Untreated progression leads to vasodilatory shock requiring pressor support = septic shock.</p>"),
          S("shock-stages", "Four Types & Stages of Shock", "<p>Physiologic continuum: inciting event -> SIRS -> pre-shock -> shock -> irreversible end-organ damage/death.</p>" + Tbl(["Stage", "Blood volume loss", "Findings"], [
            ["Preshock ('warm'/compensated)", "~10% loss of effective blood volume", "Tachycardia, mild tachypnea, may have subtle mentation changes but can still converse"],
            ["Shock", "20-25% reduction", "Compensatory mechanisms overwhelmed -- tachycardia, dyspnea, restlessness, diaphoresis, metabolic acidosis, oliguria, cool/clammy skin"],
            ["End-stage shock", "Progressive, irreversible", "Declining urine output -> anuria/AKI (ATN); acidemia decreases cardiac output; restlessness -> agitation -> obtundation -> coma; diminished pulses, mottled skin"]
          ]) + HY("Septic shock is the most common cause of ICU/hospital death and a leading cause of hospital readmissions. Sepsis overall is the #1 cause of hospital admission and biggest single cost to US hospitals (~$24 billion/year).")),
          S("workup", "Workup for the Cause of Sepsis", "<p>A thorough H&P directs testing toward the suspicious site/system.</p>" + HY("Every hospitalized patient with suspected infection should get: skin exam, UA with reflex C&S, CXR, and blood cultures x2 -- drawn 15 minutes apart, aerobic + anaerobic bottles each, from DIFFERENT veins (plus any line/port); 3 sets if high suspicion of fastidious bacteremia. First-round labs: CBC, CMP, serum lactate, UA with reflex C&S, CXR, blood cultures x2.") + Tbl(["Finding", "Significance"], [
            ["Urine nitrites", "Produced by E. coli/Klebsiella reducing nitrates"],
            ["Isolated high urine WBCs", "Strongly suggests infection"],
            ["Urine RBCs", "Glomerulonephritis or GU trauma"],
            ["Urine epithelial cells", "A \"dirty\" sample -- needs recollection"]
          ]) + "<p>Blood cultures cannot be Gram-stained directly; the lab checks daily for growth, and a negative culture is called at 5 days (before that: \"NGTD\" = no growth to date). Faster time-to-positive suggests more severe bacteremia. Procalcitonin elevates with bacterial infection but is nonspecific (also up in cancer, ESRD, any inflammation); serum lactate isn't diagnostic alone but is used to risk-stratify.</p><p>Plain abdominal x-ray is NOT adequate in sepsis -- CT abdomen/pelvis with IV contrast is the broad evaluator (fat stranding, tissue thickening, increased intra-abdominal fluid, abscess). RUQ ultrasound is more accurate than CT specifically for cholecystitis, but is second-line given its narrower coverage.</p>"),
          S("treatment", "Treatment", HY("Time-to-appropriate-antibiotic is the STRONGEST predictor of mortality in sepsis. Inappropriate initial antibiotic selection occurs in ~32% of cases and roughly doubles mortality (34% vs 18%).") + Tbl(["Pseudomonas a concern?", "Empiric regimen"], [
            ["NOT a concern", "Vancomycin + ONE of: 3rd/4th-gen cephalosporin (cefepime, ceftriaxone, cefotaxime), a beta-lactam/beta-lactamase inhibitor (pip-tazo, amp-sulbactam), or a carbapenem"],
            ["IS a concern", "Vancomycin + TWO of: anti-pseudomonal cephalosporin (cefepime), anti-pseudomonal carbapenem, anti-pseudomonal beta-lactam/beta-lactamase inhibitor (pip-tazo), anti-pseudomonal fluoroquinolone (ciprofloxacin), an aminoglycoside, or a monobactam (aztreonam)"]
          ]) + Mn("Comorbidity clues (not absolute rules)", "Alcoholism -> Klebsiella, Strep pneumo. Diabetes -> Pseudomonas, Strep pneumo. Splenic dysfunction -> encapsulated organisms (Strep pneumo, H. flu, N. meningitidis, GBS). Neutropenia -> gram-negative gut rods (E. coli, Klebsiella, Proteus), Pseudomonas.") + Tbl(["Intervention", "Detail"], [
            ["IV fluids", "0.9% NS or LR, 30 mL/kg within the first 3 hours (use ideal body weight if BMI >30); goal MAP &ge;65"],
            ["Pressors", "Norepinephrine (Levophed) is FIRST CHOICE in distributive shock like sepsis; dobutamine is mainly for cardiogenic shock; vasopressin is a second-line adjunct in severe septic shock"],
            ["Blood products", "1 unit PRBCs raises Hgb ~1g/Hct ~3%; FFP (2-4 units) provides coagulation factors for only hours; 1 unit platelets raises count ~6K"],
            ["Oxygenation", "Supplemental O2 if SpO2 <92%; ABG is the best test to assess need for intubation; intubate for hypoxemic/hypercarbic respiratory failure + RR >30, mental status decline, fatigue, or hemodynamic instability"],
            ["Glucose control", "Hyperglycemia worsens outcomes -- sliding-scale insulin, titrate slowly if not eating or renally compromised"],
            ["Steroids", "NOT used to treat infection generally, but have a role in SEPTIC SHOCK to counteract sepsis-induced adrenal suppression; patients on baseline steroids need stress-dose steroids if they develop sepsis"]
          ]))
        ], [
          Q("definitions", "What distinguishes sepsis from simple bacteremia?", ["Sepsis involves altered organ function (oliguria, AKI, coagulopathy, AMS, elevated lactate); bacteremia is just bacteria in the blood", "Sepsis and bacteremia are interchangeable terms", "Bacteremia always progresses to sepsis within hours", "Sepsis requires a positive blood culture, while bacteremia does not"], 0, "Bacteremia is simply viable bacteria detectable in blood cultures. Sepsis specifically requires infection WITH altered organ function -- a distinct, more severe clinical state."),
          Q("definitions", "What two criteria define septic shock?", ["MAP &ge;65 mmHg requiring pressors AND lactate >2", "SBP <90 mmHg alone, regardless of pressor requirement", "A positive blood culture with any degree of hypotension", "SIRS criteria plus a single elevated lactate value"], 0, "Septic shock is defined as sepsis requiring pressors to maintain a MAP of at least 65 mmHg, combined with a lactate greater than 2 -- both criteria are needed."),
          Q("definitions", "How many of the 4 SIRS criteria are needed to meet the definition?", ["2 of 4", "1 of 4", "3 of 4", "All 4"], 0, "SIRS requires meeting 2 of 4 criteria: HR >90, RR >20 (or pCO2 <32), abnormal temperature, or abnormal WBC/bands -- though SIRS has been phased out of SCCM/ESICM guidelines in favor of qSOFA since 2016."),
          Q("definitions", "What replaced SIRS in the 2016 SCCM/ESICM sepsis guidelines?", ["qSOFA", "The Glasgow Coma Scale", "APACHE II", "The SIRS criteria were not replaced"], 0, "qSOFA (quick Sequential Organ Failure Assessment) replaced SIRS in the 2016 guidelines and is validated for use outside the ICU."),
          Q("definitions", "A patient meets all 3 qSOFA criteria (RR &ge;22, altered mentation, SBP &le;100). What is their approximate risk of death?", ["24%", "3%", "50%", "Risk of death cannot be estimated from qSOFA"], 0, "A qSOFA score of 3 (all three criteria present) corresponds to an approximate 24% risk of death, compared to 3% for a score of 0-1 and 18% for a score of 2."),
          Q("pathogenesis", "Which cytokines are the main drivers of the pro-inflammatory cascade in sepsis?", ["IL-1 and TNF-alpha", "IL-10 and TGF-beta", "Erythropoietin and thrombopoietin", "Insulin and glucagon"], 0, "Endotoxin or bacterial cell wall products induce pro-inflammatory cytokines -- mainly IL-1 and TNF-alpha -- which activate neutrophils and vascular endothelium, driving the sepsis cascade."),
          Q("pathogenesis", "How does systemic inflammation in sepsis lead to microthrombi and tissue ischemia?", ["It activates the coagulation cascade, consuming platelets/clotting factors/natural anticoagulants", "It directly lyses red blood cells, causing hemolytic anemia", "It has no effect on coagulation -- thrombosis is unrelated to sepsis", "It only affects the venous, not arterial, circulation"], 0, "Systemic inflammation activates coagulation, causing microthrombi formation, tissue ischemia, and progressive consumption of platelets, clotting factors, and natural anticoagulants."),
          Q("shock-stages", "What best characterizes 'preshock' (compensated shock)?", ["~10% loss of effective blood volume with tachycardia; the patient can still converse", "20-25% blood volume loss with oliguria and cool, clammy skin", "Anuria and mottled skin with diminished pulses", "Complete hemodynamic collapse requiring immediate CPR"], 0, "Preshock represents about 10% loss of effective blood volume with homeostatic compensation -- tachycardia and mild tachypnea, with the patient often still able to converse despite subtle mentation changes."),
          Q("shock-stages", "What findings mark progression from preshock into true 'shock'?", ["20-25% blood volume reduction with restlessness, diaphoresis, metabolic acidosis, and oliguria", "A return to normal vital signs as the body compensates", "10% blood volume loss with mild tachycardia only", "Isolated mild tachypnea with no other findings"], 0, "True shock reflects overwhelmed compensatory mechanisms with a 20-25% reduction in effective blood volume, causing tachycardia, dyspnea, restlessness, diaphoresis, metabolic acidosis, oliguria, and cool/clammy skin."),
          Q("shock-stages", "What is the leading cause of ICU/hospital death related to sepsis?", ["Septic shock", "Febrile neutropenia", "Bacteremia without organ dysfunction", "Colonization progressing directly to death"], 0, "Septic shock is the most common cause of ICU/hospital death and a leading cause of hospital readmissions."),
          Q("workup", "How should blood cultures be drawn in a patient with suspected sepsis?", ["2 sets, 15 minutes apart, aerobic + anaerobic bottles each, from different veins", "A single set is always sufficient regardless of suspicion level", "1 set drawn from the same site twice in a row", "Cultures should never be drawn from an existing line or port"], 0, "Standard practice is 2 sets of blood cultures, drawn 15 minutes apart from different veins, each with aerobic and anaerobic bottles -- 3 sets if there's high suspicion of fastidious bacteremia."),
          Q("workup", "What does the presence of urine nitrites suggest?", ["Infection with a nitrate-reducing organism like E. coli or Klebsiella", "Glomerulonephritis", "A contaminated 'dirty' urine sample", "Diabetic ketoacidosis"], 0, "Nitrites in urine are produced by bacteria (classically E. coli or Klebsiella) that reduce nitrates to nitrites, making this a useful clue for urinary tract infection."),
          Q("workup", "When is a blood culture called negative, absent earlier growth?", ["At 5 days, before which it is reported as 'no growth to date' (NGTD)", "At 24 hours", "At 48 hours", "Blood cultures are never called negative -- they are held indefinitely"], 0, "The lab checks blood cultures daily for growth and calls them negative at 5 days if there's been no growth; before that point, the result is reported as NGTD."),
          Q("workup", "Why is plain abdominal x-ray considered inadequate for evaluating a possible intra-abdominal source of sepsis?", ["It lacks the sensitivity of CT abdomen/pelvis with IV contrast for detecting abscess, fat stranding, or fluid", "It exposes the patient to more radiation than CT", "It cannot be performed in critically ill patients", "It is only useful for detecting free air, never infection"], 0, "Plain abdominal x-ray is not adequate in the sepsis workup -- CT abdomen/pelvis with IV contrast is the broad evaluator, showing fat stranding, tissue thickening, increased fluid, or abscess."),
          Q("treatment", "What is the single strongest predictor of mortality in sepsis?", ["Time to appropriate antibiotic administration", "The specific vasopressor chosen", "The total volume of IV fluids given", "The patient's baseline comorbidity burden"], 0, "Time-to-appropriate-antibiotic is the strongest predictor of mortality in sepsis -- inappropriate initial antibiotic selection occurs in about 32% of cases and roughly doubles mortality."),
          Q("treatment", "What is the recommended empiric antibiotic backbone when Pseudomonas is NOT a concern?", ["Vancomycin plus one of: a 3rd/4th-gen cephalosporin, a beta-lactam/beta-lactamase inhibitor, or a carbapenem", "Vancomycin alone, with no additional gram-negative coverage", "A single fluoroquinolone with no vancomycin", "Two aminoglycosides in combination"], 0, "When Pseudomonas isn't a concern, empiric therapy is vancomycin plus one broad-spectrum gram-negative agent (a 3rd/4th-gen cephalosporin, a beta-lactam/beta-lactamase inhibitor, or a carbapenem)."),
          Q("treatment", "How does the empiric regimen change when Pseudomonas IS a concern?", ["Vancomycin plus TWO anti-pseudomonal agents from different classes, instead of just one", "No change is needed -- the same single-agent regimen is used", "Vancomycin is dropped entirely in favor of an aminoglycoside alone", "Only a fluoroquinolone is needed, with no vancomycin"], 0, "When Pseudomonas is a concern, the regimen escalates to vancomycin plus TWO anti-pseudomonal agents from different classes (e.g., cefepime plus ciprofloxacin), to ensure adequate double coverage."),
          Q("treatment", "What is the recommended IV fluid resuscitation strategy in the first 3 hours of sepsis management?", ["0.9% NS or LR, 30 mL/kg", "5% dextrose in water, 10 mL/kg", "Albumin only, 500 mL total", "No fluids until blood cultures result"], 0, "Initial resuscitation is 0.9% normal saline or lactated Ringer's at 30 mL/kg within the first 3 hours (using ideal body weight if BMI >30), targeting a MAP of at least 65."),
          Q("treatment", "What is the first-choice vasopressor in septic (distributive) shock?", ["Norepinephrine (Levophed)", "Dobutamine", "Vasopressin as monotherapy", "Phenylephrine as first-line in all cases"], 0, "Norepinephrine is the first-choice pressor in distributive shock like sepsis, given its potent alpha/beta agonist vasoconstrictive effect; vasopressin is typically added as a second-line adjunct."),
          Q("treatment", "When are corticosteroids indicated in the management of sepsis?", ["In septic shock, to counteract sepsis-induced adrenal suppression", "Routinely in all sepsis patients from the time of diagnosis", "Only to treat the underlying infection directly", "Steroids are always contraindicated in sepsis"], 0, "Steroids are not used to treat the infection itself, but do have a role in septic shock to counteract sepsis-induced adrenal suppression, and patients on baseline steroids need stress dosing if they develop sepsis.")
        ]),
        D("febrile-neutropenia", "Febrile Neutropenia", "Fever in a neutropenic, often oncology, patient -- a medical emergency requiring antibiotics within an hour of cultures.", [
          S("definitions-risk", "Definitions, Cause & Risk", Tbl(["Term", "Definition"], [
            ["Neutropenic", "ANC <1000 and falling, or ANC <500 (healthy ANC range: 2,500-6,000; calculated as WBC x % neutrophils)"],
            ["Fever", "A single temp &ge;38.3°C (101°F), OR a sustained temp 38.0-38.2°C (100.5°F) still present 1 hour after the initial reading"]
          ]) + "<p>Usually follows chemotherapy or radiation, or is an effect of the cancer itself; can also occur with aplastic anemia or a toxin/drug causing severe neutropenia.</p>" + HY("About 85% of febrile neutropenia is infectious, but a causative organism is only cultured in about 30% of cases -- the remaining ~15% is non-infectious in origin.") + "<p>These patients are at HIGH risk for fungal and bacterial infection, most commonly from the <strong>skin and genital/peri-rectal mucosa</strong>. Typical signs of infection (erythema, purulent drainage) may be ABSENT -- there simply aren't enough neutrophils to generate them.</p>"),
          S("workup-treatment", "Workup, Treatment & Prognosis", HY("Before starting antibiotics, obtain: 2-3 sets of blood cultures (10-15 minutes apart, from peripheral veins plus catheter if central access present), UA with C&S, culture of any wound/catheter discharge, sputum gram stain/culture, stool for C. difficile, plus CXR and pan-culture guided by exam findings.") + "<p>General care: meticulous skin/oral care, avoid rectal manipulation (temps, exams), start a bowel regimen. Neutropenic precautions: gown/glove/mask for providers/visitors, dedicated equipment, meticulous hand hygiene, no flowers/plants, dietary restrictions (no raw foods, unpasteurized dairy, raw/undercooked egg).</p>" + HY("Broad-spectrum empiric antibiotics must be started within 1 HOUR of obtaining cultures. If fever doesn't improve after 4-5 days of appropriate antibiotics, add an empiric antifungal. Strongly consider ID consult plus involving the treating oncologist.") + "<p>G-CSF (filgrastim/Neupogen, pegfilgrastim/Neulasta) stimulates neutrophil production, maturation, migration, and cytotoxicity -- routine use is controversial and reserved for selected patients per heme-onc.</p><p>Prognosis depends on recovery of adequate neutrophil counts and speed of appropriate empiric antibiotics; mortality ranges 4-30%, and cancer treatment is always interrupted until recovery.</p>")
        ], [
          Q("definitions-risk", "What ANC threshold defines neutropenia in this context?", ["ANC <1000 and falling, or ANC <500", "ANC <2500 regardless of trend", "ANC <5000", "ANC <100 only"], 0, "Neutropenia is defined as an ANC less than 1000 and falling, or an ANC less than 500 outright -- compared to a healthy range of 2,500-6,000."),
          Q("definitions-risk", "What temperature reading qualifies as \"fever\" for the definition of febrile neutropenia?", ["A single temp &ge;38.3°C (101°F), or a sustained 38.0-38.2°C still present 1 hour later", "Any temperature above 37.5°C measured once", "A temperature elevation of any degree above the patient's baseline", "Only temperatures &ge;39°C qualify"], 0, "Febrile neutropenia requires either a single temperature of 38.3°C (101°F) or higher, or a sustained temperature of 38.0-38.2°C that persists on recheck 1 hour later."),
          Q("definitions-risk", "In what proportion of febrile neutropenia cases is a causative organism actually cultured?", ["About 30%", "About 85%", "Nearly 100%", "Less than 5%"], 0, "Although about 85% of febrile neutropenia is thought to be infectious in origin, a causative organism is only identified on culture in roughly 30% of cases."),
          Q("definitions-risk", "Why might a neutropenic patient with a skin or soft tissue infection lack the usual signs of erythema or purulent drainage?", ["There aren't enough neutrophils present to generate a typical inflammatory response", "Neutropenic patients are inherently pain-free and cannot perceive infection", "Erythema and purulence only ever occur with viral, not bacterial, infections", "These signs are masked specifically by chemotherapy drugs, not the neutropenia itself"], 0, "Classic signs of infection like erythema and purulent drainage depend on a neutrophil-driven inflammatory response -- with too few neutrophils present, these signs can be absent even with a significant underlying infection."),
          Q("definitions-risk", "What are the most common sources of infection in febrile neutropenia?", ["Skin and genital/peri-rectal mucosa", "Lungs exclusively", "The urinary tract exclusively", "The CNS exclusively"], 0, "The skin and genital/peri-rectal mucosa are the most common sources of infection in febrile neutropenia patients."),
          Q("workup-treatment", "How quickly should broad-spectrum empiric antibiotics be started after cultures are obtained in febrile neutropenia?", ["Within 1 hour", "Within 24 hours", "Within 4-5 days, after culture results are available", "There is no specific time target"], 0, "Febrile neutropenia is a medical emergency -- broad-spectrum empiric antibiotics must be started within 1 hour of obtaining cultures, without waiting for results."),
          Q("workup-treatment", "If fever persists after 4-5 days of appropriate antibiotics in febrile neutropenia, what should be added?", ["An empiric antifungal", "A second antiviral agent", "High-dose corticosteroids", "Nothing -- continue the same antibiotics indefinitely without change"], 0, "Persistent fever despite 4-5 days of appropriate antibiotic therapy should prompt adding an empiric antifungal agent, along with strongly considering an ID consult."),
          Q("workup-treatment", "What is the role of G-CSF (filgrastim/pegfilgrastim) in febrile neutropenia?", ["Stimulates neutrophil production, maturation, migration, and cytotoxicity, though routine use is controversial", "It is a first-line antibiotic replacing broad-spectrum coverage", "It directly kills bacteria and fungi", "It is used only for its antipyretic effect"], 0, "G-CSF agents like filgrastim (Neupogen) and pegfilgrastim (Neulasta) stimulate neutrophil production and function, but their routine use in febrile neutropenia is controversial and reserved for selected patients per hematology-oncology guidance."),
          Q("workup-treatment", "Which dietary restriction is part of neutropenic precautions?", ["Avoiding raw or undercooked foods, unpasteurized dairy, and raw produce", "A strict low-sodium diet", "A gluten-free diet", "No dietary restrictions are needed beyond normal hospital diet"], 0, "Neutropenic precautions include avoiding raw foods, fresh unwashed produce/meat, unpasteurized dairy, deli food, and raw/undercooked eggs, since these carry a higher risk of introducing pathogens to an immunocompromised host."),
          Q("workup-treatment", "What is the reported mortality range for febrile neutropenia?", ["4-30%", "Less than 1%", "50-75%", "Essentially 100% without bone marrow transplant"], 0, "Febrile neutropenia carries a mortality of roughly 4-30%, depending largely on how quickly adequate neutrophil counts recover and how promptly appropriate empiric antibiotics are started.")
        ])
      ]),

      L("global-infections", "Global Infection", [
        D("chikungunya", "Chikungunya Fever", "Mosquito-borne alphavirus causing severe, often prolonged, polyarthralgia.", [
          S("overview", "Organism, Vector & Transmission", "<p>Single-stranded RNA virus, genus <em>Alphavirus</em>, family Togaviridae. Transmitted by <em>Aedes aegypti</em> and <em>Aedes albopictus</em> mosquitoes -- aggressive <strong>daytime</strong> biters. Incubation is 3-7 days; communicable as long as viremia persists (acute illness plus weeks to months).</p>" + HY("Name origin: 'that which bends up' / 'stooped walk' -- reflects the debilitating arthralgia. The CDC is concerned about a potential US epidemic since the same Aedes species are present here and the population is immunologically naive.")),
          S("presentation-treatment", "Presentation, Diagnosis & Treatment", "<p>Usually self-limited within 7 days: acute fever (&gt;39°C/102°F) with severe, bilateral/symmetric polyarthralgia (can be debilitating), headache, myalgias, joint swelling, maculopapular rash, conjunctivitis, nausea/vomiting.</p><p>Diagnosis: RT-PCR (day 1-7 of illness); serology IgM/IgG (&ge;4 days after onset).</p><p>Treatment: none specific -- supportive only (NSAIDs/acetaminophen, hydration, rest). <strong>No vaccine</strong> -- prevention is mosquito avoidance only.</p>" + HY("Chikungunya can cause persistent rheumatologic symptoms, fatigue, and depression for months to years after the acute illness -- mortality itself is rare (mostly older adults)."))
        ], [
          Q("overview", "What kind of mosquito behavior is characteristic of the Aedes species that transmit chikungunya?", ["Aggressive daytime biting", "Exclusively nighttime biting", "They do not bite humans, only animals", "Biting only near standing water, never elsewhere"], 0, "Aedes aegypti and Aedes albopictus, the vectors for chikungunya, are aggressive daytime biters -- a distinguishing behavioral trait from mosquitoes that mainly bite at dusk/night."),
          Q("overview", "What does the name 'chikungunya' reflect about the illness?", ["The debilitating, 'stooped walk'-inducing arthralgia", "A specific geographic region where it was discovered", "The rash's characteristic appearance", "The virus's discovery in a specific animal reservoir"], 0, "'Chikungunya' means 'that which bends up' or reflects a stooped walk, describing the severe, debilitating polyarthralgia that is the hallmark of this disease."),
          Q("presentation-treatment", "What is the classic presentation of chikungunya fever?", ["Acute high fever with severe, bilateral/symmetric polyarthralgia", "Painless genital ulcer with regional lymphadenopathy", "Slapped-cheek facial rash with circumoral pallor", "Gradual-onset low-grade fever with a dry cough"], 0, "Chikungunya classically presents with acute fever (>39°C/102°F) and severe, debilitating, bilateral/symmetric polyarthralgia, often with headache, myalgias, and a maculopapular rash."),
          Q("presentation-treatment", "What long-term complication can follow chikungunya infection?", ["Persistent rheumatologic symptoms, fatigue, and depression for months to years", "Permanent paralysis in the majority of cases", "Chronic renal failure", "Progressive dementia"], 0, "Even after the acute illness resolves within about a week, chikungunya can cause persistent joint symptoms, fatigue, and depression lasting months to years."),
          Q("presentation-treatment", "What is the treatment for chikungunya?", ["Supportive care only -- there is no specific antiviral treatment", "A specific antiviral, oseltamivir", "IV ribavirin", "A single dose of doxycycline"], 0, "There is no chikungunya-specific treatment -- management is supportive with NSAIDs/acetaminophen, hydration, and rest."),
          Q("presentation-treatment", "Is there a vaccine available for chikungunya prevention in this lecture's content?", ["No -- prevention relies on mosquito avoidance only", "Yes, a single-dose live-attenuated vaccine", "Yes, but only for travelers over age 60", "Yes, a two-dose inactivated vaccine"], 0, "There is no chikungunya vaccine -- prevention depends entirely on mosquito avoidance measures (repellent, protective clothing, eliminating standing water, screens/nets).")
        ]),
        D("zika", "Zika Virus", "Mosquito- and sexually-transmitted flavivirus notable for congenital microcephaly.", [
          S("overview", "Organism, Transmission & Presentation", "<p>Arbovirus, genus <em>Flavivirus</em>, family Flaviviridae -- same vector family as chikungunya, dengue, and yellow fever. Primary transmission is via <em>Aedes aegypti</em> mosquito bite (daytime feeder, breeds in standing water); secondary routes include maternal-fetal, sexual (vaginal/anal/oral), blood transfusion, and organ transplantation. Incubation is 2-14 days.</p>" + HY("Only ~20% of infected people develop symptoms, usually mild. The 'Notable 4' (&ge;2 needed to suspect Zika): acute low-grade fever, maculopapular pruritic rash, arthralgia of the small joints of the hands/feet, and nonpurulent conjunctivitis.")),
          S("complications", "Complications", Tbl(["Complication", "Detail"], [
            ["Guillain-Barré syndrome", "2.4 cases per 10,000 Zika infections"],
            ["Neurologic", "Myelitis, meningoencephalitis"],
            ["Congenital microcephaly", "Highest risk with 1st-trimester infection; also miscarriage. Effects: seizures, developmental delay, intellectual disability, movement/balance problems, feeding/hearing/vision problems. Diagnosed by ultrasound between 28-33 weeks gestation"]
          ])),
          S("diagnosis", "Diagnosis", "<p>Workup depends on two questions: is the patient symptomatic, and are they pregnant?</p>" + Tbl(["Scenario", "Workup"], [
            ["Asymptomatic, non-pregnant, exposed", "No mandatory workup; counsel on preventing secondary (sexual) spread"],
            ["Symptomatic, non-pregnant, exposed", "RT-PCR (serum/urine, within 7 days of symptom onset); serology IgM + neutralizing antibody via PRNT for confirmation given flavivirus cross-reactivity"],
            ["Pregnant, exposed", "RT-PCR within 2 weeks of symptom onset/exposure; IgM with reflex PRNT if 2-12 weeks from onset/exposure"]
          ]) + HY("Case definitions: Suspected = signs/symptoms + relevant exposure. Probable = exposure + positive IgM. Confirmed = positive viral RNA or positive PRNT.")),
          S("counseling-prevention", "Treatment, Prevention & Patient Counseling", "<p>Treatment is supportive only (acetaminophen, hydration, rest) -- <strong>avoid NSAIDs until dengue is ruled out</strong> (given symptom overlap and dengue's bleeding risk with NSAIDs). No vaccine currently exists.</p>" + Tbl(["Patient", "Wait before unprotected sex"], [
            ["Symptomatic men with confirmed/suspected Zika", "&ge;6 months after illness onset"],
            ["Symptomatic women with confirmed/suspected Zika", "&ge;8 weeks after illness onset"],
            ["Asymptomatic men/women with Zika exposure", "&ge;8 weeks after exposure"]
          ]) + "<p>Pregnant women/partners and those trying to conceive should avoid/postpone travel to areas with ongoing mosquito transmission. Zika is a reportable illness; pregnant patients are followed in a separate registry.</p>")
        ], [
          Q("overview", "What proportion of Zika-infected individuals develop symptoms?", ["About 20%", "About 80%", "Nearly 100%", "Less than 1%"], 0, "Only about 20% of Zika infections are symptomatic, and when symptoms occur they are usually mild and rarely fatal."),
          Q("overview", "What are the 'Notable 4' findings used to suspect Zika (at least 2 needed)?", ["Acute low-grade fever, maculopapular pruritic rash, arthralgia of small hand/foot joints, and nonpurulent conjunctivitis", "High fever, retro-orbital pain, severe myalgias, and a petechial rash", "Painless genital chancre, regional lymphadenopathy, and fever", "Bilateral facial droop, flu-like illness, and joint pain"], 0, "The 'Notable 4' for Zika are acute low-grade fever, maculopapular pruritic rash, arthralgia (typically mild, small joints), and nonpurulent conjunctivitis -- at least 2 should be present to suspect Zika."),
          Q("overview", "How is Zika primarily transmitted?", ["Aedes aegypti mosquito bite", "Tick bite", "Airborne respiratory droplets", "Contaminated drinking water"], 0, "Zika's primary transmission route is the bite of an infected Aedes aegypti mosquito (with Aedes albopictus as a potential secondary vector); sexual and vertical transmission are important secondary routes."),
          Q("complications", "What neurologic complication occurs in approximately 2.4 per 10,000 Zika infections?", ["Guillain-Barré syndrome", "Stroke", "Multiple sclerosis", "Bell's palsy"], 0, "Guillain-Barré syndrome occurs in about 2.4 cases per 10,000 Zika infections, alongside rarer complications like myelitis and meningoencephalitis."),
          Q("complications", "During which trimester of pregnancy does Zika infection carry the highest risk of congenital microcephaly?", ["1st trimester", "2nd trimester", "3rd trimester", "Risk is equal across all trimesters"], 0, "Congenital microcephaly risk from Zika infection is highest with 1st-trimester maternal infection."),
          Q("complications", "When is fetal ultrasound performed to evaluate for Zika-related microcephaly?", ["Between 28-33 weeks gestation", "In the first trimester only, before 12 weeks", "Immediately at conception", "Only after delivery"], 0, "Ultrasound to evaluate for congenital microcephaly is performed between 28-33 weeks gestation."),
          Q("diagnosis", "What test is used to confirm Zika serology given cross-reactivity with other flaviviruses?", ["PRNT (plaque-reduction neutralization test)", "Western blot", "Rapid antigen test", "Darkfield microscopy"], 0, "Because flaviviruses (Zika, dengue, yellow fever) show antibody cross-reactivity, PRNT is used to confirm neutralizing IgG antibodies specific to Zika."),
          Q("diagnosis", "What workup is recommended for an asymptomatic, non-pregnant patient with Zika exposure?", ["No mandatory workup -- counsel on preventing secondary spread", "Immediate RT-PCR regardless of symptoms", "Mandatory PRNT testing before any counseling", "Admission for observation"], 0, "Asymptomatic, non-pregnant, exposed patients do not require mandatory workup -- the focus is on counseling to prevent secondary (sexual) transmission."),
          Q("diagnosis", "What defines a 'confirmed' case of Zika, per the case definitions used?", ["Positive viral RNA or positive PRNT", "Signs/symptoms plus relevant exposure alone", "Exposure plus a positive IgM alone", "A single positive rapid antigen test"], 0, "A confirmed Zika case requires either positive viral RNA (RT-PCR) or a positive PRNT -- exposure plus positive IgM alone is only 'probable.'"),
          Q("counseling-prevention", "Why should NSAIDs be avoided in a patient with suspected Zika?", ["Until dengue is ruled out, given dengue's bleeding risk with NSAIDs", "NSAIDs directly worsen Zika-associated arthralgia", "NSAIDs are contraindicated in all viral illnesses", "NSAIDs interact with the Zika PRNT test"], 0, "Given significant symptom overlap between Zika and dengue, NSAIDs should be avoided until dengue is ruled out, since NSAIDs increase bleeding risk in dengue."),
          Q("counseling-prevention", "How long should a symptomatic MAN with confirmed/suspected Zika wait before unprotected sex?", ["At least 6 months after illness onset", "At least 8 weeks after illness onset", "At least 2 weeks after illness onset", "No waiting period is recommended for men"], 0, "Symptomatic men are advised to wait at least 6 months after illness onset before unprotected sex, given persistence of Zika virus in semen -- longer than the 8-week window for women."),
          Q("counseling-prevention", "How long should a symptomatic WOMAN with confirmed/suspected Zika wait before unprotected sex?", ["At least 8 weeks after illness onset", "At least 6 months after illness onset", "At least 24 hours after illness onset", "No waiting period is recommended for women"], 0, "Symptomatic women are advised to wait at least 8 weeks after illness onset before unprotected sex -- a shorter window than the 6-month recommendation for men."),
          Q("counseling-prevention", "Is Zika virus infection a reportable illness?", ["Yes -- clinicians report suspected cases, and pregnant patients are followed in a separate registry", "No, reporting is not required", "Only fatal cases require reporting", "Only cases in pregnant women require reporting"], 0, "Zika is a reportable illness; clinicians report suspected cases to the health department, and pregnant Zika patients are followed in a dedicated registry.")
        ]),
        D("dengue", "Dengue Fever", "Flavivirus causing high fever plus retro-orbital pain, with a hemorrhagic/shock form appearing after defervescence.", [
          S("overview", "Organism, Vector & Transmission", "<p>4 serotypes (DENV-1 through -4); arbovirus, genus <em>Flavivirus</em>, family Flaviviridae. Transmitted mainly by female <em>Aedes aegypti</em> -- an infected mosquito can transmit for the rest of its life. Incubation is 4-10 days.</p>" + HY("Infection confers lifelong immunity to that specific serotype, plus TEMPORARY cross-immunity to the other 3 serotypes -- a key reason severe dengue tends to occur on a subsequent infection with a different serotype.")),
          S("presentation", "Presentation -- Dengue Fever vs. Severe Dengue (DHF/DSS)", Tbl(["Form", "Presentation"], [
            ["Dengue Fever", "High fever (104°F) plus &ge;2 of: severe frontal headache, retro-orbital pain, myalgias/arthralgias, N/V, lymphadenopathy, rash. Lasts 2-7 days"],
            ["Dengue Hemorrhagic Fever (Severe Dengue)", "Warning signs 3-7 days after first symptoms, at DEFERVESCENCE (temp drops below 100°F): severe abdominal pain, persistent vomiting, tachypnea, fatigue, restlessness, hemorrhagic manifestations"],
            ["Critical stage (next 24-48h)", "Can be lethal: plasma leaking, fluid accumulation, respiratory distress, severe bleeding, organ impairment; may progress to Dengue Shock Syndrome (DSS)"]
          ]) + HY("The defining warning sign is that severe dengue symptoms begin AS the fever is breaking (defervescence) -- not while the fever is at its peak, which is a common point of confusion.")),
          S("diagnosis-treatment", "Diagnosis & Treatment", "<p>Clinical diagnosis in endemic areas, or lab-based. Labs: leukopenia, increased LFTs, marked thrombocytopenia (&lt;100,000) in DHF. RT-PCR within 7 days of onset; IgM &ge;4 days (confirm with PRNT). Monitor urine output, BP/HR, CBC (platelets, Hct).</p><p>No dengue-specific medication -- treatment priority is maintaining fluid volume: oral rehydration for uncomplicated dengue fever; IV isotonic fluids ± blood products for DHF.</p>")
        ], [
          Q("overview", "How many dengue serotypes exist, and what is their immunologic relationship?", ["4 serotypes; infection gives lifelong immunity to that serotype plus temporary cross-immunity to the others", "1 serotype; infection gives permanent immunity to all future infections", "4 serotypes with no cross-immunity of any kind", "2 serotypes, both providing lifelong cross-protective immunity"], 0, "There are 4 dengue serotypes (DENV-1 to -4). Infection with one confers lifelong immunity to that serotype and only temporary cross-immunity to the others -- important because severe disease is more likely on a later infection with a different serotype."),
          Q("presentation", "What defines classic (uncomplicated) dengue fever?", ["High fever (104°F) plus at least 2 of: severe headache, retro-orbital pain, myalgias, nausea/vomiting, lymphadenopathy, or rash", "Low-grade fever with isolated joint pain and no other symptoms", "A painless genital ulcer with fever", "Sudden jaundice with bleeding diathesis"], 0, "Dengue fever presents with a high fever (104°F) plus at least 2 additional findings from a list including severe frontal headache, retro-orbital pain, myalgias/arthralgias, GI symptoms, lymphadenopathy, or rash."),
          Q("presentation", "When do the warning signs of severe dengue (DHF) classically appear relative to the fever?", ["At defervescence, as the fever breaks (temp drops below 100°F)", "While the fever is at its highest peak", "Only after the fever has been gone for 2 weeks", "Before any fever develops at all"], 0, "A key and often-missed point is that severe dengue warning signs begin AS the fever is breaking (defervescence), not while fever is at its worst -- patients may mistakenly think they're improving."),
          Q("presentation", "What is Dengue Shock Syndrome (DSS)?", ["The most severe progression of dengue hemorrhagic fever, with plasma leaking and shock", "A synonym for uncomplicated dengue fever", "An allergic reaction to dengue vaccination", "A chronic post-dengue fatigue syndrome"], 0, "DSS represents the most severe endpoint of the critical stage of dengue hemorrhagic fever, with plasma leaking, fluid accumulation, and hemodynamic collapse."),
          Q("presentation", "What platelet count threshold is associated with dengue hemorrhagic fever?", ["Marked thrombocytopenia, less than 100,000", "A platelet count that is always normal", "Thrombocytosis above 450,000", "Platelet count is not relevant to dengue diagnosis"], 0, "DHF is associated with marked thrombocytopenia (<100,000), along with leukopenia and elevated LFTs."),
          Q("diagnosis-treatment", "What is the mainstay of dengue treatment?", ["Maintaining fluid volume -- oral rehydration for dengue fever, IV isotonic fluids ± blood products for DHF", "A dengue-specific antiviral medication", "Prophylactic antibiotics to prevent secondary bacterial infection", "Corticosteroids to reduce inflammation"], 0, "There is no dengue-specific medication -- treatment centers on maintaining fluid volume, escalating from oral rehydration in uncomplicated dengue to IV isotonic fluids (and possibly blood products) in DHF."),
          Q("diagnosis-treatment", "What monitoring parameters are important in a dengue patient at risk for progression to DHF?", ["Urine output, BP/HR, and CBC (platelets, hematocrit)", "Daily chest x-rays only", "Weekly stool cultures", "Continuous EEG monitoring"], 0, "Close monitoring of urine output, blood pressure/heart rate, and CBC trends (especially platelets and hematocrit) helps detect early progression to DHF/DSS."),
          Q("diagnosis-treatment", "What vector transmits dengue, and what is notable about its transmission capability?", ["Female Aedes aegypti, which can transmit the virus for the rest of its life once infected", "Any mosquito species indiscriminately", "Male Aedes aegypti exclusively", "The tsetse fly"], 0, "Dengue is transmitted mainly by female Aedes aegypti mosquitoes, and once infected, a mosquito remains capable of transmitting the virus for the rest of its life."),
          Q("diagnosis-treatment", "Is there an established, available dengue vaccine according to this lecture's content?", ["No -- vaccine development is described only as an ongoing effort, not an established available option", "Yes, a single-dose live-attenuated vaccine used worldwide", "Yes, a two-dose inactivated vaccine used only in the US", "Yes, but only for children under age 5"], 0, "This lecture describes dengue vaccine development only as an ongoing effort ('attempts at creating vaccines'), not as an established, currently available chemoprophylaxis option.")
        ]),
        D("ebola", "Ebola", "Filovirus hemorrhagic fever from direct contact with infected body fluids; extremely high fatality.", [
          S("overview", "Organism, Reservoir & Transmission", "<p>Family Filoviridae, genus <em>Ebolavirus</em>; 6 species, including <strong>Zaire ebolavirus (EBOV)</strong> (cause of the 2014-2016 outbreak). Reservoir is unknown -- fruit bats are likely, with primates/pigs as accidental intermediary hosts.</p><p>Transmitted by direct contact (broken skin/mucous membranes) with infected body fluids (blood, urine, saliva, feces, vomit, semen), contaminated objects, or infected animals -- one of the most virulent pathogens known. Incubation is typically 8-10 days (range 2-21 days).</p>" + HY("Healthcare workers and family/friends of infected patients are at highest risk. Virus has been found in semen up to 9 months after recovery.")),
          S("pathogenesis-presentation", "Pathogenesis & Presentation", "<p>The virus migrates from the initial infection site to regional lymph nodes, then to the liver, spleen, and adrenal glands. Hepatocellular necrosis deregulates clotting factors; adrenocortical necrosis and an inflammatory cascade drive organ failure/shock.</p><p>Severe, acute/abrupt onset: sudden fever (&gt;101.5°F), severe headache, myalgias/intense weakness, diarrhea, vomiting, abdominal pain, rash, impaired renal/liver function, and internal/external bleeding (bleeding diathesis). Labs: leukopenia, thrombocytopenia, abnormal LFTs.</p>"),
          S("diagnosis", "Diagnosis", "<p>Isolate the patient and contact public health immediately. RT-PCR at specific labs under FDA EUA -- a positive result is 'presumptive positive' and is referred to the CDC for confirmation; repeat a negative RT-PCR if the initial test was &lt;72 hours from symptom onset. IgM/IgG may help after day 3 or during recovery. Strict shipping/handling protocols are required for samples.</p>"),
          S("treatment-vaccine", "Treatment & Vaccine", "<p>Supportive care: IV fluids, anti-emetic/anti-diarrheal, antipyretic, analgesics, correcting electrolytes, treating co-infections, and possible convalescent plasma/whole blood transfusion from survivors.</p>" + HY("Two Ebola-specific FDA-approved (2020) therapies exist, though not commercially available: REGN-EB3 (triple monoclonal antibody: atoltivimab, maftivimab, odesivimab) and ansuvimab (mAb114, brand name Ebanga).") + "<p><strong>Vaccine: rVSV-ZEBOV</strong>, live-attenuated, ~98% efficacy in recent testing -- given during outbreaks to high-risk individuals, and as pre-exposure prophylaxis for HCWs responding to outbreaks and BSL-4 facility staff.</p><p>Prognosis: up to 90% fatality (47% survival in the 2014-2016 outbreak); death, if it occurs, typically happens 6-16 days after symptom onset. Ebola is a Category A bioterror agent.</p>")
        ], [
          Q("overview", "What is the suspected reservoir for Ebola virus?", ["Fruit bats (likely), with primates/pigs as accidental intermediary hosts", "Rodents, confirmed as the definitive reservoir", "Humans are the only known reservoir", "Mosquitoes serve as both vector and reservoir"], 0, "The Ebola reservoir remains unknown but fruit bats are the leading candidate, with primates and pigs serving as accidental intermediary hosts that can also transmit to humans."),
          Q("overview", "How is Ebola transmitted between humans?", ["Direct contact with infected body fluids through broken skin or mucous membranes", "Airborne respiratory droplets over long distances", "Mosquito bite", "Contaminated drinking water alone"], 0, "Ebola is transmitted by direct contact with infected body fluids (blood, urine, saliva, feces, vomit, semen) through broken skin or mucous membranes, or via contaminated objects -- not through casual airborne spread."),
          Q("overview", "Which population is at highest risk for Ebola infection during an outbreak?", ["Healthcare workers and family/friends of infected patients", "Airline pilots and flight crews", "Office workers in urban settings", "Children under age 2 exclusively"], 0, "Healthcare workers and close family/friends caring for infected patients are at the highest risk of Ebola infection, given the direct-contact transmission route."),
          Q("overview", "How long can Ebola virus persist in a survivor's semen?", ["Up to 9 months", "Only 48 hours", "Up to 2 weeks", "Indefinitely, for the rest of the survivor's life"], 0, "Ebola virus has been detected in semen up to 9 months after recovery, which has implications for counseling survivors about sexual transmission risk."),
          Q("pathogenesis-presentation", "What is the mechanism by which Ebola causes a bleeding diathesis?", ["Hepatocellular necrosis deregulates clotting factors, combined with an inflammatory cascade", "Direct destruction of platelets by the virus alone, with no hepatic involvement", "Autoimmune platelet destruction", "Vitamin K malabsorption from GI involvement"], 0, "Ebola's hepatocellular necrosis deregulates clotting factor production, and combined with adrenocortical necrosis and a systemic inflammatory cascade, this drives the characteristic bleeding diathesis and organ failure."),
          Q("pathogenesis-presentation", "What is the typical onset pattern of Ebola virus disease?", ["Severe, acute/abrupt onset with sudden high fever", "A gradual, insidious onset over several weeks", "An asymptomatic course in the vast majority of cases", "Onset only after a prolonged prodrome of mild symptoms lasting a month"], 0, "Ebola has a severe, acute/abrupt onset -- sudden fever (>101.5°F), severe headache, and rapidly progressive systemic symptoms, unlike the gradual onset of some other infections."),
          Q("diagnosis", "What should be done immediately if Ebola is suspected in a patient?", ["Isolate the patient and contact public health immediately", "Discharge home with outpatient follow-up in 1 week", "Draw routine labs and send the patient to a standard waiting room", "Wait for RT-PCR results before taking any isolation precautions"], 0, "Suspected Ebola requires immediate patient isolation and immediate public health notification, given the high transmissibility and severity of the disease."),
          Q("diagnosis", "What should be done if an initial Ebola RT-PCR is negative but was drawn less than 72 hours from symptom onset?", ["Repeat the RT-PCR, since early testing may be falsely negative", "Consider Ebola definitively ruled out", "No further testing is needed regardless of clinical suspicion", "Switch immediately to serology as the only further test needed"], 0, "A negative RT-PCR obtained less than 72 hours after symptom onset should be repeated, since viral load may not yet be detectable that early in the illness."),
          Q("treatment-vaccine", "What are the two FDA-approved Ebola-specific therapies?", ["REGN-EB3 (a triple monoclonal antibody) and ansuvimab (Ebanga)", "Remdesivir and favipiravir", "Oseltamivir and baloxavir", "Ribavirin and interferon alfa"], 0, "REGN-EB3 (atoltivimab, maftivimab, and odesivimab) and ansuvimab (mAb114, brand name Ebanga) are the two FDA-approved (2020) Ebola-specific monoclonal antibody therapies, though not commercially available."),
          Q("treatment-vaccine", "What vaccine exists for Ebola, and what is its approximate efficacy?", ["rVSV-ZEBOV, live-attenuated, ~98% efficacy", "An inactivated vaccine with ~50% efficacy", "A conjugate vaccine requiring 3 doses over a year", "No Ebola vaccine exists"], 0, "The rVSV-ZEBOV vaccine is a live-attenuated vaccine with approximately 98% efficacy in recent testing, used during outbreaks and as pre-exposure prophylaxis for high-risk healthcare workers and BSL-4 staff."),
          Q("treatment-vaccine", "What is the approximate overall case fatality rate of Ebola virus disease?", ["Up to 90%, though the 2014-2016 outbreak saw 47% survival", "About 5%", "Less than 1%", "Essentially 0% with modern supportive care"], 0, "Ebola case fatality can be as high as 90% depending on the outbreak and strain, though the large 2014-2016 West African outbreak had a 47% survival rate with improved supportive care.")
        ]),
        D("yellow-fever", "Yellow Fever", "Flavivirus with a classic triphasic course; vaccine-preventable and often travel-required.", [
          S("overview", "Organism, Vector & Transmission", "<p>Arbovirus, genus <em>Flavivirus</em>, family Flaviviridae. Endemic to tropical Africa and South America. Transmitted by <em>Aedes</em> and <em>Haemogogus</em> mosquitoes; monkeys and humans serve as hosts. Incubation is 3-6 days.</p>"),
          S("three-phases", "The Three Phases", Tbl(["Phase", "Timing", "Findings"], [
            ["1. Period of viremia", "Initial illness", "Fever/chills/rigors, myalgias with prominent backache, headache, anorexia, N/V; Faget's sign (bradycardia WITH hyperthermia -- a relative bradycardia despite fever)"],
            ["2. Remission", "Day 3-4", "Symptoms/fever abate, viremia terminates, antibodies form; MOST patients recover here -- only ~15% progress to phase 3"],
            ["3. Intoxication ('Severe Yellow Fever')", "Within 48h of remission", "Severe/progressive multi-organ dysfunction: high fever, sudden jaundice, abdominal pain with vomiting, bleeding diathesis, declining renal/liver function"]
          ]) + HY("Faget's sign -- bradycardia despite a high fever -- is a classic finding of phase 1 that distinguishes yellow fever from most febrile illnesses, where fever typically drives tachycardia.")),
          S("diagnosis-treatment-vaccine", "Diagnosis, Treatment & Vaccine", "<p>Presumptive clinical diagnosis in areas of known transmission. RT-PCR up to 4 days after symptom onset (usually positive in phase 1, likely negative by phase 3). IgM/IgG during phase 3 -- caution, IgM may persist 4+ years post-vaccination and cross-reacts with other flaviviruses, so confirm positives with PRNT.</p><p>Treatment is mainly symptomatic/supportive -- no specific antiviral therapy exists.</p>" + HY("The yellow fever vaccine is the MOST IMPORTANT prevention measure: a live-virus vaccine giving 99% immunity within 30 days, with a single dose protecting for at least 10 years (booster every 10 years if continued risk). It is REQUIRED for entry to specific countries (the 'Yellow Book'). In shortages, 1/5th standard dose can be given, protective for at least 1 year.") + "<p>Prognosis: the 3rd phase carries approximately 50% fatality within 14 days -- yellow fever is the classic answer for 'requires documented vaccination for travel to certain countries.'</p>")
        ], [
          Q("overview", "What vectors transmit yellow fever?", ["Aedes and Haemogogus mosquitoes", "Ticks", "Tsetse flies", "Triatomine (kissing) bugs"], 0, "Yellow fever is transmitted by Aedes and Haemogogus mosquitoes, with monkeys and humans serving as hosts in the transmission cycle."),
          Q("three-phases", "What is Faget's sign, and in which phase of yellow fever does it occur?", ["Bradycardia despite hyperthermia, occurring in the period of viremia (phase 1)", "Tachycardia with hypothermia, occurring in phase 3", "A skin rash occurring only in phase 2", "Jaundice occurring in phase 1"], 0, "Faget's sign is relative bradycardia despite a high fever -- an atypical finding since fever usually drives tachycardia -- and it occurs during the initial period of viremia (phase 1)."),
          Q("three-phases", "What happens during the 'remission' phase of yellow fever, and what proportion of patients progress beyond it?", ["Symptoms abate around day 3-4 as viremia terminates; only about 15% progress to severe disease", "All patients progress to the severe phase 3", "Remission means the disease is permanently cured with no further risk", "Remission occurs only in vaccinated patients"], 0, "During remission, fever and symptoms abate around day 3-4 as viremia ends and antibodies form -- most patients recover at this point, with only about 15% progressing to the severe intoxication phase."),
          Q("three-phases", "What characterizes the 'intoxication' (severe yellow fever) phase?", ["Severe multi-organ dysfunction with sudden jaundice and bleeding diathesis, within 48 hours of remission", "A mild return of the initial fever with no new findings", "Isolated joint pain with no systemic involvement", "A phase that always precedes the period of viremia"], 0, "The intoxication phase occurs within 48 hours of remission in about 15% of patients, causing severe progressive multi-organ dysfunction: high fever, sudden jaundice, GI symptoms, and bleeding diathesis."),
          Q("diagnosis-treatment-vaccine", "Why must positive yellow fever IgM/IgG serology be interpreted with caution?", ["IgM can persist 4+ years post-vaccination and cross-reacts with other flaviviruses, requiring PRNT confirmation", "Serology is always falsely negative and should never be used", "IgG appears before IgM in yellow fever, unlike other infections", "Serology is only useful in phase 1, never later"], 0, "Yellow fever IgM can persist for more than 4 years after vaccination, and cross-reactivity with other flaviviruses is common -- positive results should be confirmed with PRNT."),
          Q("diagnosis-treatment-vaccine", "What is the single most important prevention measure for yellow fever?", ["The live-virus vaccine", "Prophylactic doxycycline", "Avoiding all travel to any tropical country", "Daily antipyretics during travel"], 0, "The yellow fever vaccine is described as the most important prevention measure -- a live-virus vaccine that achieves 99% immunity within 30 days and is required for entry into specific countries."),
          Q("diagnosis-treatment-vaccine", "How long does a single dose of yellow fever vaccine protect against infection?", ["At least 10 years, with a booster if continued risk", "Only 3 months", "For life, with no booster ever needed or available", "Only during the calendar year it was given"], 0, "A single dose of yellow fever vaccine protects for at least 10 years, with a booster recommended every 10 years for those with continued risk of exposure."),
          Q("diagnosis-treatment-vaccine", "What is the approximate fatality rate for patients who progress to the 3rd (intoxication) phase of yellow fever?", ["About 50% within 14 days", "About 5%", "Nearly 0%, since most recover fully", "100%, uniformly fatal"], 0, "The intoxication phase of yellow fever carries an approximately 50% fatality rate within 14 days -- a stark contrast to the excellent prognosis of patients who recover after remission.")
        ]),
        D("rabies", "Rabies", "Near-100%-fatal once symptomatic; post-exposure prophylaxis (wound care + vaccine + immunoglobulin) is time-critical.", [
          S("overview", "Organism, Reservoir & Transmission", "<p>RNA virus, family Rhabdoviridae, genus <em>Lyssavirus</em>. Has a predilection for neural tissue, spreading via peripheral nerves to the CNS, and replicates/sheds in highly innervated areas like the salivary glands. Reservoir is zoonotic -- any mammalian species. Transmitted via broken skin or neurologic tissue contact with saliva or CNS tissue (bite/scratch/mucous membrane exposure).</p>" + HY("Incubation is typically 1-3 months but can range up to 8 years -- the longest, most variable incubation period among the diseases covered in this course.") + "<p>Contamination risk increases if: the biting mammal is a known reservoir/vector species, the animal looks sick or behaves abnormally, the wound/mucous membrane was contaminated by saliva, the bite was unprovoked, or the animal is unvaccinated.</p>"),
          S("presentation", "Clinical Presentation", "<p>Once clinical signs appear, the disease is <strong>fatal</strong>. Positive indicators: a nonspecific prodrome before neuro signs, paresthesias at the bite site, CNS signs (confusion, agitation, delirium, abnormal behavior, hallucinations, insomnia, dysphagia, <strong>hydrophobia</strong>), progressive neurologic decline, and a negative workup for other encephalitis causes.</p>" + Tbl(["Form", "Frequency", "Course"], [
            ["Furious rabies", "Most patients", "Death within days from cardiorespiratory arrest"],
            ["Paralytic rabies", "~30%", "Longer course; paralysis starting at the bite/scratch site, progressing to coma"]
          ])),
          S("pep-prognosis", "Post-Exposure Prophylaxis & Prognosis", HY("PEP, if given promptly, is highly effective: immediate wound cleansing with soap and water, the rabies vaccine (4 doses -- day 0, then day 3, 7, and 14), and ONE dose of human rabies immunoglobulin (HRIG) given promptly. There is NO effective treatment once clinical signs develop.") + "<p>Prognosis: near 100% fatality once clinical signs are present -- the <strong>highest case fatality rate of any infectious disease</strong>. Only 2 people have survived without prophylaxis.</p>" + Mn("Reservoir species by region", "In the US, cats outnumber dogs as a rabies source (fewer vaccination laws, more free-roaming, more wildlife contact), and bat rabies is found in all 48 continental states. Globally, dogs remain the most common source of human rabies."))
        ], [
          Q("overview", "What is the typical incubation period for rabies, and how variable can it be?", ["Typically 1-3 months, but can range up to 8 years", "Always exactly 10 days", "24-48 hours, with no variability", "Always longer than 5 years"], 0, "Rabies has a typical incubation period of 1-3 months but can range up to 8 years, making it the longest and most variable incubation period covered in this course."),
          Q("overview", "Which factor increases the risk that an animal bite will transmit rabies?", ["An unprovoked bite from an animal behaving abnormally", "A bite from a known fully-vaccinated pet with normal behavior", "A superficial scratch with no saliva contact", "A bite that occurred more than a year ago"], 0, "Risk factors include the biting animal being a known reservoir/vector species, appearing sick or behaving abnormally, an unprovoked attack, saliva contamination of the wound, and the animal being unvaccinated."),
          Q("presentation", "What happens once clinical signs of rabies appear?", ["The disease is fatal -- no effective treatment exists at that point", "Most patients recover fully with prompt treatment", "Symptoms resolve spontaneously within a few days", "The disease becomes only mildly symptomatic and chronic"], 0, "Once clinical signs of rabies appear, the disease is essentially always fatal, since there is no effective treatment once this stage is reached -- prevention via prompt PEP is critical."),
          Q("presentation", "What classic symptom, related to swallowing, is associated with rabies?", ["Hydrophobia", "Odynophagia from esophagitis", "Painless dysphagia to solids only", "Globus sensation with no true swallowing difficulty"], 0, "Hydrophobia (fear of water, from painful pharyngeal spasms triggered by swallowing) along with dysphagia are classic CNS findings of clinical rabies."),
          Q("presentation", "What distinguishes paralytic rabies from furious rabies?", ["Paralytic rabies has a longer course with paralysis starting at the bite site and progressing to coma, vs. furious rabies' rapid course", "Paralytic rabies is more common and has a better prognosis", "Furious rabies always resolves without treatment", "Paralytic rabies never involves the CNS"], 0, "Paralytic rabies (about 30% of cases) has a longer course with paralysis beginning at the bite/scratch site and progressing to coma, in contrast to the rapid, days-long course of furious rabies (the more common form) ending in cardiorespiratory arrest."),
          Q("pep-prognosis", "What is the complete post-exposure prophylaxis regimen for rabies?", ["Immediate wound cleansing, rabies vaccine (4 doses: day 0, 3, 7, 14), and one dose of HRIG", "A single dose of rabies vaccine only, with no wound care or immunoglobulin", "Wound cleansing alone, with no vaccine needed", "Oral antiviral therapy for 2 weeks"], 0, "Rabies PEP consists of immediate wound cleansing with soap and water, a 4-dose rabies vaccine series (day 0, 3, 7, and 14), and one dose of human rabies immunoglobulin (HRIG) given promptly."),
          Q("pep-prognosis", "How does rabies' case fatality rate compare to other infectious diseases?", ["It has the highest case fatality rate of any infectious disease once clinical signs appear", "It has one of the lowest case fatality rates among viral infections", "Its fatality rate is comparable to the common cold", "Only about 10% of clinically symptomatic cases are fatal"], 0, "Rabies has the highest case fatality rate of any infectious disease once clinical signs develop -- near 100%, with only 2 documented survivors without prophylaxis."),
          Q("pep-prognosis", "In the US, which domestic animal is a more common source of human rabies exposure -- cats or dogs?", ["Cats, due to fewer vaccination laws, more free-roaming behavior, and more wildlife contact", "Dogs, due to more aggressive behavior overall", "Neither -- only wild animals transmit rabies in the US", "Both are equally common, with no meaningful difference"], 0, "In the US, cats outnumber dogs as a rabies source because of fewer vaccination requirements, more free-roaming behavior, and greater wildlife contact -- a reversal of the global pattern, where dogs are the most common source.")
        ]),
        D("mers", "MERS", "Camel-associated coronavirus causing severe respiratory illness, concentrated in the Arabian Peninsula.", [
          S("overview", "Organism, Reservoir & Transmission", "<p>MERS-CoV, a novel respiratory coronavirus first detected in humans in 2012, with several clusters since. Reservoir is zoonotic -- <strong>camels</strong> are the primary animal host, with bats implicated as the ancestral reservoir. Transmission is zoonotic or human-to-human. Incubation is about 5 days (range 2-13 days) for secondary cases; patients are typically hospitalized around day 4 after onset, with death occurring around day 12 if fatal.</p>" + HY("All confirmed cases are linked to the Arabian Peninsula and neighboring countries (Bahrain, Iraq, Iran, Jordan, Kuwait, Lebanon, Oman, Qatar, Saudi Arabia, Syria, UAE, Yemen). Human-to-human transmission has occurred but has not been sustained.")),
          S("presentation-diagnosis-treatment", "Presentation, Diagnosis & Treatment", "<p>Presentation ranges from asymptomatic to mild URI to ARDS to death. Overall case fatality is about 35%, rising to 58% for ICU admissions.</p><p>Diagnosis: CXR shows unilateral/bilateral patchy opacities, interstitial infiltrates, consolidation, or pleural effusions. Labs: leukopenia, lymphopenia, thrombocytopenia, elevated LDH. MERS-CoV rRT-PCR from multiple specimens/sites/times; serologic assay if &gt;14 days from onset.</p><p>Treatment is supportive only (airway management/ventilator support in the ICU) plus isolation and quarantine -- <strong>no vaccine</strong> is available.</p>")
        ], [
          Q("overview", "What is the primary animal reservoir for MERS-CoV?", ["Camels", "Bats exclusively, with no other reservoir", "Civets", "Pigs"], 0, "Camels are the primary animal host/reservoir for MERS-CoV, with bats implicated as the likely ancestral reservoir species."),
          Q("overview", "MERS cases are concentrated in which geographic region?", ["The Arabian Peninsula and neighboring countries", "Sub-Saharan Africa", "Southeast Asia", "South America"], 0, "All confirmed MERS cases have been linked to the Arabian Peninsula and its neighboring countries, reflecting the geographic distribution of the camel reservoir."),
          Q("overview", "Has sustained human-to-human transmission of MERS been documented?", ["Human-to-human transmission has occurred but has not been sustained", "MERS has never been transmitted person-to-person", "MERS spreads efficiently and sustainably person-to-person worldwide", "Only airborne transmission over long distances has been documented"], 0, "MERS has shown human-to-human transmission, particularly in healthcare settings, but this transmission has not been sustained at a population level."),
          Q("presentation-diagnosis-treatment", "What is the overall case fatality rate of MERS, and how does it change for ICU patients?", ["About 35% overall, rising to 58% for ICU admissions", "About 5% overall, with no significant change for ICU patients", "Nearly 100% regardless of care setting", "Fatality is essentially 0% with modern ICU care"], 0, "MERS carries an overall case fatality rate of about 35%, which rises to 58% among patients requiring ICU admission."),
          Q("presentation-diagnosis-treatment", "What lab abnormality pattern is typical in MERS?", ["Leukopenia, lymphopenia, thrombocytopenia, and elevated LDH", "Marked leukocytosis with eosinophilia", "Isolated thrombocytosis with normal LDH", "Polycythemia with normal white count"], 0, "MERS typically shows leukopenia, lymphopenia, thrombocytopenia, and elevated LDH on labs, consistent with a severe viral respiratory illness."),
          Q("presentation-diagnosis-treatment", "Is a vaccine available for MERS prevention?", ["No vaccine is available", "Yes, a single-dose mRNA vaccine", "Yes, a live-attenuated vaccine used regionally", "Yes, but only for camel handlers"], 0, "No MERS vaccine is available -- management relies entirely on supportive care, isolation, and quarantine.")
        ]),
        D("sars", "SARS", "2002-2003 coronavirus outbreak causing severe atypical pneumonia; no cases reported since 2004.", [
          S("overview", "Organism, Reservoir & Transmission", "<p>SARS-CoV (now termed SARS-CoV-1), a coronavirus responsible for the 2002-2003 outbreak that began in Asia and spread to the Americas and Europe. Reservoir is likely bats, with the palm civet as an intermediary host. Transmission is likely close person-to-person contact via respiratory secretions or contaminated objects. Incubation is 2-7 days; patients are most contagious in the 2nd week of illness.</p>"),
          S("presentation-diagnosis", "Presentation & Diagnosis", "<p>Fever (&gt;100.5°F), malaise, headache, myalgias, usually WITHOUT upper respiratory symptoms, followed by lower respiratory symptoms -- nonproductive cough, dyspnea, pleuritic pain -- i.e., a febrile severe lower respiratory illness in a suggestive epidemiologic setting.</p><p>Diagnosis: PCR as early as possible from &ge;2 sites (respiratory tract, stool, serum), repeated in 1 week if symptoms persist; serologic antibody testing is less useful acutely since antibodies take weeks to develop.</p>" + HY("No cases have been reported since 2004 (though re-emergence is theoretically possible). Mostly adults were affected -- no fatal cases and less morbidity occurred in children under 12, while comorbidities worsened outcomes in adults. No specific proven-effective treatment or vaccine exists; management is supportive (including mechanical ventilation) plus isolation and quarantine."))
        ], [
          Q("overview", "What is the likely reservoir and intermediary host for SARS-CoV?", ["Bats (reservoir) with the palm civet as an intermediary host", "Camels as both reservoir and intermediary host", "Rodents as the sole reservoir with no intermediary host", "Birds as the reservoir with pigs as the intermediary host"], 0, "SARS-CoV's likely reservoir is bats, with the palm civet serving as an intermediary host that facilitated spillover to humans."),
          Q("overview", "During which week of illness are SARS patients most contagious?", ["The 2nd week of illness", "The first 24 hours, before symptoms even begin", "Only after full recovery", "Contagiousness is highest immediately at symptom resolution"], 0, "SARS patients are most contagious during the 2nd week of illness, an important point distinguishing its transmission dynamics from some other respiratory viruses."),
          Q("presentation-diagnosis", "What respiratory symptom pattern is notable (by its ABSENCE) in early SARS?", ["Upper respiratory symptoms are usually absent, while lower respiratory symptoms (cough, dyspnea) follow", "Upper respiratory symptoms are always prominent from the start", "Both upper and lower respiratory symptoms are absent throughout the illness", "Only GI symptoms occur, with no respiratory involvement at all"], 0, "A distinguishing feature of SARS is the usual ABSENCE of upper respiratory symptoms early on, with the illness instead progressing to lower respiratory symptoms like nonproductive cough and dyspnea."),
          Q("presentation-diagnosis", "How did SARS severity in children compare to adults?", ["Children under 12 had no fatal cases and less morbidity than adults", "Children had higher mortality than adults", "Severity was identical across all age groups", "Only children were affected during the outbreak"], 0, "SARS mostly affected adults, and among children under 12, there were no fatal cases and generally less morbidity -- comorbidities worsened outcomes in adult patients."),
          Q("presentation-diagnosis", "What is the current status of SARS-CoV-1 (original SARS) circulation?", ["No known cases have been reported since 2004", "It continues to circulate widely worldwide today", "It was eradicated immediately after the 2003 outbreak ended", "It evolved directly into SARS-CoV-2 and no longer exists separately"], 0, "No known SARS-CoV-1 cases have been reported since 2004, though re-emergence remains theoretically possible given its animal reservoir."),
          Q("presentation-diagnosis", "Why is serologic antibody testing less useful for early/acute SARS diagnosis?", ["Antibodies take weeks to develop, limiting usefulness in the acute setting", "Serology is more sensitive than PCR in the first 24 hours", "Antibodies are present before infection even occurs", "Serologic testing is not possible for any coronavirus"], 0, "Serologic testing for SARS is less useful acutely because antibodies typically take weeks into the illness to develop -- PCR from multiple sites is preferred for early diagnosis.")
        ]),
        D("monkeypox", "Monkeypox (Mpox)", "Orthopoxvirus causing a vesiculopustular rash; vaccine and antiviral options exist for severe cases.", [
          S("overview", "Organism, Reservoir & Transmission", "<p>Monkeypox virus -- a DNA virus, genus <em>Orthopoxvirus</em> (same genus as variola/smallpox and vaccinia, and cowpox). <strong>Unrelated to varicella-zoster (chickenpox)</strong> despite the similar-sounding name. Two clades: West African and Congo Basin. Reservoir is rodents and monkeys.</p><p>Transmitted person-to-person, most often via close/intimate contact with lesions, body fluids, respiratory secretions, or contaminated objects; vertical (mother-to-fetus) transmission can occur. Incubation is 3-17 days. Communicable until scabs have fallen off (~2 weeks); condom use is advised for 3 months post-recovery given persistence in semen/vaginal fluids.</p>"),
          S("presentation", "Clinical Presentation", "<p>Symptomatic period lasts 2-4 weeks. Characteristic rash plus lymphadenopathy; the rash appears in crops, with lesions on a given body part evolving together: macular -&gt; papular -&gt; vesicular -&gt; pustular -&gt; scabbing/desquamation. Typical locations: face, mouth, extremities (recent outbreaks show increased oral and anogenital lesions). Fever, chills, headache, malaise, myalgias are typical; respiratory symptoms and rectal symptoms (pain, bleeding) can occur in recent outbreaks.</p>" + Tbl(["Rash stage", "Duration"], [
            ["Macules", "1-2 days"],
            ["Papules", "1-2 days"],
            ["Vesicles", "1-2 days"],
            ["Pustules", "5-7 days (deep-seated, firm, become umbilicated)"],
            ["Scabs", "7-14 days (fall off after ~1 week of crusting)"]
          ])),
          S("treatment-vaccine", "Treatment, Vaccine & Prognosis", "<p>Treatment is mostly supportive (NSAIDs/acetaminophen, hydration, rest); most cases resolve without pharmacotherapy. Antivirals approved for other indications may help severe cases: <strong>tecovirimat (TPOXX)</strong> from the US Strategic National Stockpile, cidofovir (Vistide), brincidofovir (Tembexa), and vaccinia immune globulin IV (VIGIV).</p>" + HY("JYNNEOS vaccine (2 doses) is the preferred option; ACAM2000 (more side effects) is NOT recommended for immunocompromised patients. Indications: close contact/sexual partner of a case, or high-risk sexual behavior (multiple partners, group sex, sex in areas of active transmission).") + "<p>Death is very rare (2022 outbreak mortality 1-10%); most cases are self-limited in 2-4 weeks. Increased severe-illness risk: children under 8, pregnant patients, immunocompromised patients, and those with a history of eczema.</p>")
        ], [
          Q("overview", "Monkeypox virus belongs to which genus, and what other virus shares that genus?", ["Orthopoxvirus, the same genus as variola (smallpox) and vaccinia", "Herpesvirus, the same genus as varicella-zoster", "Flavivirus, the same genus as Zika", "Alphavirus, the same genus as chikungunya"], 0, "Monkeypox is an Orthopoxvirus, the same genus as the smallpox (variola) virus and the vaccinia virus used in smallpox vaccination -- it is NOT related to varicella-zoster (chickenpox) despite name similarity."),
          Q("overview", "What is the reservoir for monkeypox virus?", ["Rodents and monkeys", "Bats exclusively", "Camels", "Humans are the only reservoir"], 0, "Rodents and monkeys serve as the reservoir for monkeypox virus, with person-to-person transmission driving human outbreaks."),
          Q("overview", "Until what point is a monkeypox patient considered communicable?", ["Until scabs have fallen off (about 2 weeks)", "Only during the first 24 hours of fever", "Communicability ends as soon as the rash first appears", "Patients remain communicable for life after infection"], 0, "Monkeypox patients are communicable until their scabs have fallen off, which takes about 2 weeks -- condom use is additionally advised for 3 months post-recovery given viral persistence in semen/vaginal fluids."),
          Q("presentation", "How does the monkeypox rash evolve on a given body part?", ["Macular -> papular -> vesicular -> pustular -> scabbing, with lesions on that body part evolving together", "All stages appear simultaneously across different body parts at random", "The rash skips the vesicular stage entirely", "Pustules appear before papules"], 0, "The monkeypox rash progresses through a defined sequence -- macule to papule to vesicle to pustule to scab -- with lesions on a given body part evolving together in synchrony (unlike varicella's asynchronous 'crops')."),
          Q("presentation", "Which rash stage of monkeypox lasts the longest and is described as deep-seated and firm?", ["Pustules (5-7 days)", "Macules (1-2 days)", "Papules (1-2 days)", "Vesicles (1-2 days)"], 0, "The pustular stage lasts 5-7 days and is notable for deep-seated, firm lesions that become umbilicated -- longer than the 1-2 day macular, papular, or vesicular stages."),
          Q("presentation", "What has been an increasingly common site of monkeypox lesions in recent outbreaks?", ["Oral and anogenital regions", "Exclusively the palms and soles", "Exclusively the scalp", "The lesions are now confined only to the face"], 0, "Recent monkeypox outbreaks have shown an increase in oral and anogenital lesions, along with rectal symptoms (pain, bleeding), reflecting changing transmission patterns."),
          Q("treatment-vaccine", "Which monkeypox vaccine is preferred, and why is the alternative less favored for some patients?", ["JYNNEOS (2 doses) is preferred; ACAM2000 has more side effects and is not recommended for immunocompromised patients", "ACAM2000 is preferred for all patients equally", "Neither vaccine is available for monkeypox", "Only a single-dose inactivated vaccine exists"], 0, "JYNNEOS (2 doses) is the generally preferred monkeypox vaccine; ACAM2000 carries more side effects and is specifically not recommended for immunocompromised patients."),
          Q("treatment-vaccine", "What antiviral, sourced from the US Strategic National Stockpile, may be used for severe monkeypox cases?", ["Tecovirimat (TPOXX)", "Oseltamivir", "Acyclovir", "Remdesivir"], 0, "Tecovirimat (TPOXX), sourced from the Strategic National Stockpile, is an antiviral option (along with cidofovir, brincidofovir, and VIGIV) for severe monkeypox cases, though most cases resolve without pharmacotherapy."),
          Q("treatment-vaccine", "Which patient population has an increased risk of severe monkeypox illness?", ["Children under 8, pregnant patients, immunocompromised patients, and those with a history of eczema", "Healthy adults age 20-40", "Patients with well-controlled hypertension", "Patients with a prior monkeypox vaccination"], 0, "Children under 8, pregnant patients, immunocompromised patients, and those with a history of eczema are at increased risk for severe monkeypox illness.")
        ]),
        D("tularemia", "Tularemia", "Francisella tularensis via ticks or animal contact; 6 clinical forms, streptomycin is the drug of choice.", [
          S("overview", "Organism, Reservoir & Transmission", "<p>Gram-negative bacteria, <em>Francisella tularensis</em>. Vectors are ticks and deer flies; reservoirs include rabbits, muskrats, prairie dogs and other rodents, domestic cats, and pet hamsters.</p>" + HY("As few as fewer than 50 organisms can cause disease -- an extremely low infectious dose. Transmission occurs via bites, skin contact, ingestion of contaminated water, lab exposure, or inhalation of infected aerosols. There is NO person-to-person transmission reported.") + "<p>Incubation is usually 3-5 days, up to 14 days. Found in all US states except Hawaii.</p>"),
          S("presentations", "Six Clinical Presentations", Tbl(["Form", "Route/Features"], [
            ["Ulceroglandular (most common)", "Follows a tick/deer-fly bite or handling an infected animal; ulcer at the entry site plus regional lymphadenopathy (axilla/groin)"],
            ["Glandular", "Same as ulceroglandular but WITHOUT an ulcer"],
            ["Oculoglandular", "Organism enters via the eye (e.g., butchering an infected animal, touching the eye); eye irritation/inflammation plus pre-auricular lymphadenopathy"],
            ["Oropharyngeal", "From contaminated food/water; sore throat, oral ulcers, tonsillitis, cervical lymphadenopathy"],
            ["Pneumonic (most severe)", "From inhaling dusts/aerosols, or untreated disease spreading hematogenously to the lungs; cough, chest pain, SOB"],
            ["Typhoidal", "Systemic febrile illness not fitting the other presentations; inoculation site usually unknown"]
          ])),
          S("diagnosis-treatment", "Diagnosis & Treatment", "<p>Diagnosis: serology (a 4-fold rise in antibody titer from acute to convalescent serum, sent at presentation and repeated 2-4 weeks later). Microbial culture must be done in <strong>BSL-2 labs</strong> (swabs/scrapings of skin lesions, lymph node aspirates, pharyngeal washings, sputum, gastric aspirates). Gram stains/blood cultures are often unremarkable; PCR exists but isn't readily available.</p>" + HY("Streptomycin x10 days is the drug of choice. Isolation is NOT needed, since there's no person-to-person transmission.") + "<p>Tularemia is a Category A bioterrorism risk; the CDC's role includes developing diagnostic tests and a vaccine (not yet established as available) and stockpiling treatment.</p>")
        ], [
          Q("overview", "How many Francisella tularensis organisms can be enough to cause disease?", ["Fewer than 50", "At least 1 million", "At least 10,000", "A minimum of 100,000 is required"], 0, "Tularemia has an extremely low infectious dose -- fewer than 50 organisms can be sufficient to cause disease, contributing to its status as a Category A bioterrorism concern."),
          Q("overview", "Is person-to-person transmission of tularemia reported?", ["No -- there is no reported person-to-person transmission", "Yes, it spreads efficiently through respiratory droplets between people", "Yes, but only through sexual contact", "Only in immunocompromised contacts"], 0, "Tularemia has no reported person-to-person transmission -- it spreads via bites, animal contact, contaminated water, or inhaled aerosols, which is also why isolation is not needed for infected patients."),
          Q("presentations", "What is the most common clinical form of tularemia?", ["Ulceroglandular", "Pneumonic", "Typhoidal", "Oculoglandular"], 0, "Ulceroglandular tularemia, with an ulcer at the bite/entry site plus regional lymphadenopathy, is the most common clinical presentation."),
          Q("presentations", "What distinguishes glandular tularemia from ulceroglandular tularemia?", ["Glandular tularemia has the same presentation but WITHOUT an ulcer at the entry site", "Glandular tularemia always involves the eye", "Glandular tularemia is the most severe form, unlike ulceroglandular", "Glandular tularemia has no lymphadenopathy at all"], 0, "Glandular tularemia mirrors ulceroglandular disease with regional lymphadenopathy, but lacks the characteristic skin ulcer at the entry site."),
          Q("presentations", "Which form of tularemia is considered the most severe?", ["Pneumonic", "Oculoglandular", "Oropharyngeal", "Glandular"], 0, "Pneumonic tularemia, from inhaling infectious aerosols or hematogenous spread to the lungs, is the most severe form, causing severe respiratory illness."),
          Q("presentations", "What lymph node group is associated with oculoglandular tularemia?", ["Pre-auricular nodes", "Inguinal nodes", "Epitrochlear nodes", "Popliteal nodes"], 0, "Oculoglandular tularemia, from ocular entry of the organism, is associated with pre-auricular lymphadenopathy along with eye irritation and inflammation."),
          Q("diagnosis-treatment", "What type of laboratory containment is required for culturing Francisella tularensis?", ["BSL-2 laboratories", "No special containment is needed -- standard open-bench culture is acceptable", "BSL-4 laboratories exclusively", "Culture is never attempted given its extreme danger"], 0, "Francisella tularensis must be cultured in BSL-2 laboratories given its high infectivity and bioterrorism potential."),
          Q("diagnosis-treatment", "What is the drug of choice for tularemia treatment?", ["Streptomycin x10 days", "Azithromycin x5 days", "Metronidazole x14 days", "Vancomycin IV"], 0, "Streptomycin for 10 days is the drug of choice for tularemia treatment.")
        ]),
        D("leprosy", "Leprosy (Hansen's Disease)", "Mycobacterium leprae causing skin and peripheral nerve disease; treated with multidrug therapy (dapsone/rifampicin ± clofazimine).", [
          S("overview", "Organism & Transmission", "<p><em>Mycobacterium leprae</em> (and <em>M. lepromatosis</em>) -- an acid-fast bacillus, obligate intracellular pathogen that replicates slowly (symptoms can take up to 20 years to appear) and survives at lower temperatures (34°C), explaining its predilection for cooler body sites (skin, peripheral nerves, extremities).</p><p>Transmission appears to be respiratory, though not fully understood, and requires repeated contact over a long period. Susceptibility appears genetic -- disease form depends on host immunity, spanning a spectrum from paucibacillary/tuberculoid (PB/TT) to multibacillary/lepromatous (MB/LL). About 95% of people are believed to have natural immunity. It is also a zoonosis, occurring in three-banded armadillos in the US.</p>"),
          S("presentation-nerves", "Presentation & Nerve Involvement", "<p>Chronic hypopigmented-to-erythematous skin lesions with sensory loss/decreased sensation. Tender enlargement of peripheral nerves causes peripheral muscle weakness/wasting:</p>" + Tbl(["Nerve", "Effect"], [
            ["Facial nerve", "Lagophthalmos and subsequent ophthalmic injury"],
            ["Common peroneal nerve", "Foot drop"],
            ["Ulnar and median nerves", "Clawed hands"],
            ["Posterior tibial nerve", "Claw toes and plantar insensitivity"]
          ]) + "<p>Also: lumps/swelling on earlobes or face, systemic nodules, thickened dermis, dry skin, altered sweating, hair loss (notably eyebrows and eyelashes), nasal congestion/disfigurement/perforated septum, and paresthesias with secondary burns/cuts on extremities due to absent pain sensation.</p><p>Skin biopsy is the gold standard for diagnosis where available; in high-prevalence or limited-access areas, clinical symptoms alone suffice.</p>"),
          S("treatment", "Multi-Drug Therapy (MDT)", Tbl(["Regimen", "Drugs", "WHO duration"], [
            ["Paucibacillary/Tuberculoid", "Dapsone 100mg daily + Rifampicin 600mg once/month", "6 months"],
            ["Multibacillary/Lepromatous", "Dapsone 100mg daily + Rifampicin 600mg once/month + Clofazimine 300mg once/month plus 50mg daily", "12 months"]
          ]) + HY("Due to rising Dapsone resistance, the WHO recommended MDT (Dapsone, Rifampicin, Clofazimine) in 1981 -- this remains the standard today. Pediatric dosing requires appropriate reduction.")),
          S("immunologic-reactions", "Immunologic Reactions", "<p>Systemic inflammatory complications causing sudden worsening of manifestations and new lesions; may cause severe nerve injury leading to paralysis/deformity. These can occur before, during, or months-to-years after leprosy treatment -- and are <strong>NOT drug reactions</strong>.</p>" + HY("Management: prednisone 40-60mg daily, tapered over at least 2 weeks (to avoid reaction recurrence). Continue leprosy MDT during steroid treatment, but reduce rifampicin to once monthly instead of daily."))
        ], [
          Q("overview", "Why does M. leprae have a predilection for cooler body sites like the skin and peripheral nerves?", ["It survives best at lower temperatures (34°C)", "It requires high oxygen tension found only in peripheral tissue", "It cannot survive at body core temperature under any circumstances", "It targets only nerve-rich areas regardless of temperature"], 0, "M. leprae survives at lower temperatures (around 34°C), which explains its predilection for cooler body sites like the skin, peripheral nerves, and extremities rather than the warmer core."),
          Q("overview", "What US wildlife species is a recognized zoonotic reservoir for leprosy?", ["Three-banded armadillos", "White-tailed deer", "Raccoons", "Coyotes"], 0, "Leprosy is also a zoonosis in the US, occurring naturally in three-banded armadillos, which can transmit the organism to humans."),
          Q("overview", "What determines whether a leprosy patient develops paucibacillary vs. multibacillary disease?", ["Host immunity -- susceptibility and disease form appear genetically determined", "The specific geographic region of infection alone", "Whether treatment was started within the first week", "The age of the patient at first symptoms exclusively"], 0, "Disease form depends on host immunity, spanning a spectrum from paucibacillary/tuberculoid to multibacillary/lepromatous disease, with susceptibility appearing to have a genetic basis."),
          Q("presentation-nerves", "Facial nerve involvement in leprosy classically causes what finding?", ["Lagophthalmos with subsequent ophthalmic injury", "Foot drop", "Clawed hands", "Claw toes"], 0, "Facial nerve involvement in leprosy causes lagophthalmos (inability to fully close the eyelid), which risks subsequent ophthalmic injury from corneal exposure."),
          Q("presentation-nerves", "Which nerve involvement in leprosy causes clawed hands?", ["Ulnar and median nerves", "Common peroneal nerve", "Posterior tibial nerve", "Facial nerve"], 0, "Involvement of the ulnar and median nerves in leprosy causes the characteristic clawed-hand deformity from peripheral muscle weakness/wasting."),
          Q("presentation-nerves", "What is the gold standard diagnostic test for leprosy where it's available?", ["Skin biopsy", "Blood culture", "CSF analysis via lumbar puncture", "Chest CT"], 0, "Skin biopsy is the gold standard for diagnosing leprosy where available; in high-prevalence or limited-resource settings, clinical symptoms alone are considered sufficient."),
          Q("treatment", "What three drugs make up multibacillary leprosy MDT, and why was this combination adopted?", ["Dapsone, rifampicin, and clofazimine, adopted by WHO in 1981 due to rising dapsone resistance", "Dapsone alone, as monotherapy has always been sufficient", "Rifampicin and isoniazid, the same regimen used for TB", "Azithromycin and doxycycline"], 0, "Multibacillary leprosy is treated with dapsone, rifampicin, and clofazimine -- the WHO adopted this three-drug MDT regimen in 1981 due to rising resistance to dapsone monotherapy, and it remains standard today."),
          Q("treatment", "How does the treatment duration differ between paucibacillary and multibacillary leprosy (WHO regimen)?", ["Paucibacillary is treated for 6 months; multibacillary for 12 months", "Both are treated for an identical 6-month course", "Paucibacillary requires 24 months; multibacillary only 6 months", "Both require lifelong treatment with no defined endpoint"], 0, "The WHO regimen treats paucibacillary (tuberculoid) leprosy for 6 months, while multibacillary (lepromatous) leprosy -- the more severe form -- requires a longer 12-month course."),
          Q("treatment", "How is rifampicin dosed differently in paucibacillary MDT compared to a daily-dosed drug like dapsone?", ["Rifampicin is given once monthly, while dapsone is given daily", "Rifampicin and dapsone are both given once monthly", "Rifampicin is given daily, while dapsone is given once monthly", "Both drugs are given only once for the entire treatment course"], 0, "In the WHO MDT regimen, rifampicin is dosed once monthly while dapsone is dosed daily -- an important distinction in the combination regimen."),
          Q("immunologic-reactions", "Are leprosy 'immunologic reactions' drug reactions to the MDT medications?", ["No -- they are systemic inflammatory complications of the disease itself, not drug reactions", "Yes, they are a direct allergic reaction to dapsone specifically", "Yes, they occur only in patients allergic to rifampicin", "They are caused exclusively by clofazimine toxicity"], 0, "Leprosy immunologic reactions are systemic inflammatory complications of the underlying disease process -- NOT drug reactions -- and can occur before, during, or years after treatment."),
          Q("immunologic-reactions", "How should leprosy MDT be adjusted during treatment of an immunologic reaction with prednisone?", ["Continue MDT, but reduce rifampicin to once monthly instead of daily", "Stop all leprosy medications until the reaction resolves completely", "Increase all MDT drug doses to compensate for the steroid", "Switch entirely from MDT to prednisone monotherapy"], 0, "During treatment of an immunologic reaction, leprosy MDT should be continued, but rifampicin dosing is reduced from daily to once monthly while the patient is on corticosteroids.")
        ]),
        D("yaws", "Yaws", "Non-venereal treponemal infection of the skin and bone in tropical regions; cured with single-dose azithromycin or penicillin.", [
          S("overview", "Organism, Transmission & Presentation", "<p>Spirochete -- <em>Treponema pallidum</em> subspecies <strong>pertenue</strong>. Humans are the only reservoir. Transmitted by direct non-sexual contact with fluid from an infected person's skin lesion; the initial lesion carries the highest bacterial load. Incubation is 9-90 days (average 21 days). Most lesions occur on the limbs.</p>" + Tbl(["Stage", "Timing", "Findings"], [
            ["Early (infectious)", "Initial", "Papilloma at the entry site; high bacterial load for up to 6 months, then natural healing; bone pain/lesions may occur"],
            ["Late (non-infectious)", "&gt;5 years", "Disfigurement of the nose/bones; thickening of the palms and soles (may impair walking)"]
          ])),
          S("treatment", "Diagnosis & Treatment", "<p>Diagnosis is clinical; PCR definitively confirms yaws but is impractical in the field.</p>" + HY("Yaws can be completely cured with ONE DOSE: azithromycin 30 mg/kg PO (max 2g) x1, OR IM benzathine penicillin 1.2 million units (adults) or 600,000 units (children). No vaccine exists -- control relies on mass drug treatment programs.") + "<p>Children are most affected. The majority of cases are reported from Papua New Guinea; yaws is a WHO-targeted neglected tropical disease for eradication.</p>")
        ], [
          Q("overview", "What organism causes yaws, and how is it related to syphilis?", ["Treponema pallidum subspecies pertenue -- a different subspecies from the one causing venereal syphilis", "The identical organism and subspecies that causes venereal syphilis", "An unrelated bacterium that only resembles syphilis symptomatically", "A viral pathogen unrelated to any spirochete"], 0, "Yaws is caused by Treponema pallidum subspecies pertenue -- a distinct subspecies from T. pallidum subspecies pallidum, which causes venereal syphilis -- and yaws is transmitted non-sexually."),
          Q("overview", "How is yaws transmitted?", ["Direct non-sexual contact with fluid from an infected skin lesion", "Sexual contact exclusively", "Mosquito bite", "Contaminated drinking water"], 0, "Yaws spreads through direct non-sexual contact with fluid from an infected person's skin lesion -- the initial lesion carries the highest bacterial load and is most infectious."),
          Q("overview", "What distinguishes early (infectious) yaws from late (non-infectious) yaws?", ["Early yaws features a papilloma at the entry site with high bacterial load; late yaws (>5 years later) causes bone/nose disfigurement and is non-infectious", "Early yaws is always fatal, while late yaws is mild", "There is no meaningful clinical distinction between the stages", "Late yaws is more infectious than early yaws"], 0, "Early yaws presents with an infectious papilloma at the site of entry with a high bacterial load, while late yaws (developing after more than 5 years) causes non-infectious disfigurement of the nose/bones and thickening of the palms/soles."),
          Q("treatment", "How is yaws treated?", ["A single dose of azithromycin or IM benzathine penicillin can completely cure it", "It requires a 14-day course of oral antibiotics", "There is no effective treatment", "It requires lifelong suppressive antibiotic therapy"], 0, "Yaws can be completely cured with a single dose of either azithromycin 30 mg/kg PO (max 2g) or IM benzathine penicillin -- a strikingly simple, highly effective treatment."),
          Q("treatment", "Is there a vaccine for yaws, and what is the primary control strategy instead?", ["No vaccine exists -- control relies on mass drug treatment programs", "Yes, a single-dose vaccine is the primary control strategy", "Yes, but only for children under age 5", "Control relies exclusively on vector control measures"], 0, "There is no yaws vaccine -- the WHO's eradication strategy relies on mass drug treatment programs rather than vaccination.")
        ]),
        D("african-trypanosomiasis", "African Trypanosomiasis (Sleeping Sickness)", "Tsetse fly-borne parasite with subspecies-specific staged treatment (T.b. rhodesiense vs. T.b. gambiense).", [
          S("overview-presentation", "Organism, Transmission & Presentation", "<p>Protozoan parasite, <em>Trypanosoma brucei</em>, with two subspecies of distinct geography/reservoir, both transmitted by the <strong>tsetse fly</strong> (or vertically, mother-to-child). Disease occurs in 2 stages: hemolymphatic, then CNS.</p>" + Tbl(["Subspecies", "Region/Reservoir", "Incubation", "Course"], [
            ["T. b. rhodesiense", "East Africa; reservoir = cattle", "Days to weeks", "RAPID: chancre at bite site, fever/headache/myalgias/LAD within 1-2 weeks, neuro symptoms ~2-3 weeks later, death within MONTHS if untreated"],
            ["T. b. gambiense", "West Africa; reservoir = humans", "Weeks to months", "SLOWER: intermittent fevers/headache/malaise/weight loss, then after 1-2 YEARS -- CNS involvement (personality changes, daytime sleepiness with nighttime disturbance, progressive confusion), death in ~3 YEARS if untreated"]
          ]) + HY("Most US-imported cases are travelers who were on safari in East Africa -- consistent with T. b. rhodesiense exposure. Diagnosis is by microscopic visualization of trypanosomes in chancre fluid, lymph node aspirate, or blood; if positive, CSF is examined to stage disease.")),
          S("treatment", "Staged Treatment by Subspecies", Tbl(["Subspecies", "Hemolymphatic (early) stage", "CNS (late) stage"], [
            ["T. b. rhodesiense", "Suramin", "Melarsoprol"],
            ["T. b. gambiense", "Pentamidine", "Eflornithine"]
          ]) + "<p>No vaccine exists. Prognosis: curable with treatment, but fatal without it.</p>")
        ], [
          Q("overview-presentation", "What insect transmits African trypanosomiasis?", ["The tsetse fly", "The Anopheles mosquito", "The Aedes mosquito", "The triatomine (kissing) bug"], 0, "The tsetse fly transmits both subspecies of Trypanosoma brucei that cause African trypanosomiasis (sleeping sickness)."),
          Q("overview-presentation", "What is the reservoir for T. b. rhodesiense, and how does its disease course compare to T. b. gambiense?", ["Cattle; T. b. rhodesiense causes a rapid course with death within months, vs. T. b. gambiense's slower course over years", "Humans; T. b. rhodesiense has the slower course of the two", "Tsetse flies themselves serve as the reservoir for both subspecies", "Rodents; both subspecies have an identical disease course"], 0, "T. b. rhodesiense's reservoir is cattle (found in East Africa), and it causes rapid progression with death within months if untreated -- much faster than T. b. gambiense (human reservoir, West Africa), which progresses over roughly 3 years."),
          Q("overview-presentation", "A traveler returning from an East African safari develops fever and a chancre at a fly-bite site. Which subspecies is most consistent with this exposure?", ["T. b. rhodesiense", "T. b. gambiense", "Trypanosoma cruzi", "Onchocerca volvulus"], 0, "Most US-imported cases of African trypanosomiasis in travelers are linked to East African safari exposure, consistent with T. b. rhodesiense."),
          Q("overview-presentation", "What CNS findings characterize the late stage of T. b. gambiense infection?", ["Personality changes, daytime sleepiness with nighttime sleep disturbance, and progressive confusion", "Sudden hemorrhagic stroke with no preceding symptoms", "Isolated peripheral neuropathy with no cognitive changes", "Complete recovery of CNS function despite ongoing infection"], 0, "T. b. gambiense's late CNS stage, occurring after 1-2 years, causes personality changes, disrupted sleep-wake cycle (daytime sleepiness, nighttime disturbance -- giving 'sleeping sickness' its name), and progressive confusion."),
          Q("overview-presentation", "How is African trypanosomiasis diagnosed, and how is disease stage determined?", ["Microscopic visualization of trypanosomes in chancre fluid/lymph node aspirate/blood; CSF exam then stages the disease", "A single blood culture, with no further testing needed", "Skin biopsy alone, without microscopy", "PCR of stool samples exclusively"], 0, "Diagnosis relies on microscopic visualization of trypanosomes in chancre fluid, lymph node aspirate, or blood; if positive, CSF is examined for trypanosomes to determine whether CNS involvement (late stage) has occurred."),
          Q("treatment", "What is the treatment for early (hemolymphatic) stage T. b. rhodesiense infection?", ["Suramin", "Melarsoprol", "Pentamidine", "Eflornithine"], 0, "Suramin treats the early hemolymphatic stage of T. b. rhodesiense infection; melarsoprol is reserved for CNS (late-stage) disease with this subspecies."),
          Q("treatment", "What is the treatment for CNS (late-stage) T. b. gambiense infection?", ["Eflornithine", "Suramin", "Melarsoprol", "Pentamidine"], 0, "Eflornithine treats CNS-stage T. b. gambiense infection, while pentamidine is used for the earlier hemolymphatic stage of this subspecies.")
        ]),
        D("chagas-disease", "American Trypanosomiasis (Chagas Disease)", "Kissing-bug-borne parasite with an acute phase and a chronic cardiac/GI phase that can appear years later.", [
          S("overview-acute", "Organism, Transmission & Acute Phase", "<p>Parasite <em>Trypanosoma cruzi</em>, found in Latin America; classified as a Neglected Parasitic Infection (NPI). Transmitted by <strong>triatomine ('kissing') bugs</strong> -- via their <strong>feces</strong>, not the bite itself. Incubation is 1-2 weeks.</p><p>Acute phase (lasts 8-12 weeks): fever, malaise, and a <strong>chagoma</strong> (inflammation at the inoculation site, usually the face); if inoculated via the eye, causes eyelid edema known as <strong>Romaña's sign</strong>. About 1% develop acute myocarditis, pericardial effusion, or meningoencephalitis. An indeterminate stage follows -- a prolonged asymptomatic period with no detectable parasites in blood.</p>" + HY("Romaña's sign (periorbital edema from ocular inoculation) is the classic exam pearl for Chagas disease.")),
          S("chronic-treatment", "Chronic Disease, Diagnosis & Treatment", "<p>Chronic Chagas disease develops in some patients: dilated cardiomyopathy (arrhythmias, heart failure), and chronic GI disease -- esophageal (dysphagia, regurgitation, achalasia, motility abnormalities) and colonic (progressive sigmoid dilation leading to megacolon).</p><p>Suspect in patients with compatible symptoms and significant time spent in Latin America. Acute phase diagnosis: peripheral blood smear (microscopy) or PCR. Chronic phase diagnosis: serology (antibodies).</p>" + HY("Acute phase treatment: benznidazole (drug of choice), twice-daily dosing for 60 days, with many side effects. Chronic phase has no curative antiparasitic regimen described -- management focuses on symptoms/complications (cardiomyopathy, esophageal/colon dilation).") + "<p>No vaccine exists. Chronic cardiac/GI disease is the major long-term morbidity.</p>")
        ], [
          Q("overview-acute", "How is Chagas disease transmitted by the triatomine ('kissing') bug?", ["Via the bug's feces, not the bite itself", "Via the bite/saliva injected during feeding", "Via airborne transmission near bug habitats", "Via ingestion of the bug itself"], 0, "Unlike most vector-borne diseases, Chagas disease is transmitted through triatomine bug feces (often rubbed into the bite wound or mucous membranes during sleep), not through the bite/saliva itself."),
          Q("overview-acute", "What is a chagoma?", ["Inflammation at the site of T. cruzi inoculation, usually on the face", "A late-stage cardiac finding on echocardiogram", "A specific type of colonic dilation seen in chronic Chagas disease", "The name for the triatomine bug's feeding site reaction in an uninfected host"], 0, "A chagoma is localized inflammation at the T. cruzi inoculation site, typically on the face, occurring during the acute phase of Chagas disease."),
          Q("overview-acute", "What is Romaña's sign, and what does it indicate?", ["Eyelid edema, indicating ocular inoculation with T. cruzi", "A cardiac murmur specific to chronic Chagas cardiomyopathy", "A skin rash occurring only in the chronic phase", "Bilateral lower extremity edema from heart failure"], 0, "Romaña's sign -- periorbital/eyelid edema -- occurs when T. cruzi is inoculated via the eye, and is the classic exam pearl for recognizing Chagas disease."),
          Q("chronic-treatment", "What are the major long-term complications of chronic Chagas disease?", ["Dilated cardiomyopathy and chronic GI disease (esophageal and colonic dilation)", "Progressive renal failure exclusively", "Peripheral neuropathy exclusively", "Chronic hepatitis and cirrhosis"], 0, "Chronic Chagas disease's major morbidity is dilated cardiomyopathy (arrhythmias, heart failure) and chronic GI disease, including esophageal dysmotility/achalasia and colonic megacolon."),
          Q("chronic-treatment", "What colonic complication can result from chronic Chagas disease?", ["Megacolon, from progressive sigmoid dilation", "Colonic strictures from fibrosis unrelated to dilation", "Toxic megacolon identical to that seen in C. diff colitis", "Colon cancer as a direct consequence"], 0, "Chronic Chagas disease can cause progressive sigmoid colonic dilation leading to megacolon, one of its characteristic chronic GI complications."),
          Q("chronic-treatment", "What is the drug of choice for acute-phase Chagas disease, and how is it dosed?", ["Benznidazole, twice daily for 60 days", "A single dose of azithromycin", "IV amphotericin B for 2 weeks", "Metronidazole for 10 days"], 0, "Benznidazole is the drug of choice for acute-phase Chagas disease, dosed twice daily for 60 days, though it carries many side effects."),
          Q("chronic-treatment", "Is there a curative antiparasitic regimen for chronic-phase Chagas disease?", ["No -- chronic phase management focuses on treating symptoms/complications rather than a curative antiparasitic regimen", "Yes, the same benznidazole regimen used in acute disease reliably cures chronic disease", "Yes, a single dose of ivermectin cures chronic Chagas disease", "Yes, but only with combination therapy including doxycycline"], 0, "Unlike the acute phase, chronic Chagas disease has no described curative antiparasitic regimen -- management instead focuses on the cardiac and GI complications as they arise.")
        ]),
        D("cysticercosis", "Cysticercosis", "Tapeworm larval tissue infection, notably causing seizures from neurocysticercosis.", [
          S("overview", "Organism, Transmission & Inflammatory Response", "<p>Parasitic tapeworm -- <em>Taenia solium</em> larval cysts (cysticerci); a helminth, most common in Latin America, Asia, and Africa. Reservoir/vector are humans and pigs (free-roaming pigs with contact to human waste). Transmitted fecal-orally by swallowing T. solium eggs found in an infected host's feces. Incubation is weeks to years.</p>" + HY("Note: taeniasis (intestinal infection with the ADULT tapeworm, from eating undercooked pork) is a DISTINCT condition from cysticercosis (larval cyst infection of tissue, from swallowing eggs).") + "<p>Developing cysticerci form a slowly growing mass causing pressure atrophy of surrounding tissue. With minimal numbers of living cysticerci, the host's inflammatory response is usually not activated -- but when cysticerci degenerate/die, an ACUTE inflammatory response occurs.</p>"),
          S("diagnosis-treatment", "Presentation, Diagnosis & Treatment", Tbl(["Location", "Presentation"], [
            ["Muscle", "Often asymptomatic; palpable ± tender subcutaneous lumps"],
            ["Eye", "Focal visual field defects or impaired extraocular movements"],
            ["Brain/spinal cord (neurocysticercosis)", "Seizures (MOST COMMON) and/or headaches; less commonly intracranial hypertension, hydrocephalus, chronic meningitis, cranial nerve abnormalities, confusion, imbalance, stroke, death"]
          ]) + "<p>Diagnosis: MRI/CT with contrast shows a contrast-enhancing ring lesion; enzyme-linked immunoelectrotransfer blot (EITB/immunoblot, a CDC test) confirms. If diagnostic, must rule out taeniasis and evaluate household contacts (shared source).</p>" + HY("Anthelminthic therapy (albendazole 400mg PO BID + dexamethasone 6mg daily x10 days) is standard -- concomitant steroids are needed because larval death from treatment can transiently WORSEN symptoms by provoking inflammation.") + "<p>Neurologic complications also need anticonvulsant therapy, corticosteroids, neurosurgery, or ventricular shunting as needed. Cysticercosis is largely responsible for adult-onset seizures in developing countries and is reportable to the state health department.</p>")
        ], [
          Q("overview", "How does cysticercosis differ from taeniasis, even though both involve Taenia solium?", ["Cysticercosis is larval cyst infection of tissue from swallowing eggs; taeniasis is adult tapeworm intestinal infection from eating undercooked pork", "They are the same condition with two different names", "Taeniasis is the more severe, tissue-invasive form", "Cysticercosis is acquired by eating undercooked pork, while taeniasis is from swallowing eggs"], 0, "Cysticercosis results from swallowing T. solium EGGS, leading to larval cysts in tissue, while taeniasis is intestinal infection with the ADULT tapeworm from eating undercooked pork -- a commonly confused distinction."),
          Q("overview", "When does an acute inflammatory response occur with cysticerci in tissue?", ["When the cysticerci degenerate or die", "Only while the cysticerci are alive and growing", "Inflammation never occurs with cysticercosis", "Only in the muscle, never in the brain"], 0, "While living cysticerci often provoke minimal inflammatory response, an acute inflammatory response is triggered specifically when the cysticerci degenerate or die -- relevant to why treatment can transiently worsen symptoms."),
          Q("diagnosis-treatment", "What is the most common presentation of neurocysticercosis?", ["Seizures", "Sudden hemorrhagic stroke", "Isolated cranial nerve palsy with no other findings", "Chronic headache with no other neurologic findings"], 0, "Seizures are the most common presentation of neurocysticercosis, making it a major cause of adult-onset seizures in developing countries."),
          Q("diagnosis-treatment", "What imaging finding is classic for neurocysticercosis?", ["A contrast-enhancing ring lesion on MRI/CT", "Diffuse cerebral atrophy with no focal lesion", "A hyperdense, non-enhancing mass", "Periventricular calcifications identical to congenital toxoplasmosis"], 0, "Neurocysticercosis classically shows a contrast-enhancing ring lesion on MRI or CT with contrast."),
          Q("diagnosis-treatment", "Why is dexamethasone given alongside albendazole when treating neurocysticercosis?", ["Because larval death from anthelminthic therapy provokes inflammation that can transiently worsen symptoms", "Dexamethasone has direct antiparasitic activity against cysticerci", "To prevent an unrelated drug allergy to albendazole", "Steroids are given only to treat coexisting adrenal insufficiency"], 0, "Anthelminthic therapy kills the cysticerci, and this larval death provokes an inflammatory response that can transiently worsen symptoms -- concomitant corticosteroids (dexamethasone) are given to blunt this reaction."),
          Q("diagnosis-treatment", "What should be evaluated once a case of cysticercosis is diagnosed, given the shared transmission source?", ["Household contacts, and taeniasis should be ruled out in the patient", "Only the patient's travel history over the past 24 hours", "Nothing further -- cysticercosis is not linked to any other condition", "Only pets in the household, not human contacts"], 0, "Once cysticercosis is diagnosed, taeniasis should be ruled out in the patient and household contacts should be evaluated, since they share a common transmission source (fecal-oral spread of T. solium eggs).")
        ]),
        D("onchocerciasis", "Onchocerciasis (River Blindness)", "Blackfly-borne filarial worm causing skin and eye disease; ivermectin kills the microfilariae only.", [
          S("overview", "Organism, Transmission & Inflammatory Response", "<p>Parasitic nematode (roundworm) -- <em>Onchocerca volvulus</em>; a helminth found near streams/rivers in tropical climates (sub-Saharan Africa, the Americas, less commonly the Middle East). Transmitted by multiple bites from infected <strong>Simulium blackflies</strong> (daytime biters) -- many bites over more than 3 months of exposure are needed for transmission. Incubation is 10-20 months. Communicable (from the human host) until the larvae die -- up to 15+ years without treatment.</p>" + HY("Living larvae/adult worms inside nodules can evade the host immune system and cause NO symptoms -- pathology is driven by the immune response to DEAD/DYING larvae (microfilariae), not the living organisms themselves.")),
          S("presentation-diagnosis-treatment", "Presentation, Diagnosis & Treatment", "<p>Can be asymptomatic (living larvae undetected; adults protected within nodules). Otherwise: pruritic rashes, subcutaneous nodules, and vision changes from the immune response to dying larvae -- intense itching leading to chronic skin damage ('<strong>leopard skin</strong>'); thinning of skin with loss of elastic tissue causing '<strong>cigarette-paper</strong>' skin and '<strong>hanging groin</strong>'; reversible corneal lesions that progress to permanent corneal thickening and blindness; optic nerve inflammation causing vision loss (especially peripheral) and blindness.</p><p>Diagnosis gold standard: <strong>skin snip biopsy</strong> (x6 snips). If biopsy is negative but clinical suspicion remains high, Onchocerca-specific serologic testing (research facilities only) or a slit lamp exam for ophthalmologic involvement can be used.</p>" + HY("DOC: ivermectin 150 mcg/kg PO in one dose, every 6 months (same dose adult and pediatric) -- reduces blindness and skin symptoms, and kills only MICROFILARIAE (larvae), NOT adult worms (macrofilariae), though it does sterilize adult female worms. Adjunctive doxycycline 200mg PO daily x6 weeks kills MACROFILARIAE (adult worms) instead.") + "<p>No vaccine exists -- prevention/control is via WHO mass ivermectin administration to affected communities. Onchocerciasis is the second leading infectious cause of blindness worldwide.</p>")
        ], [
          Q("overview", "What vector transmits onchocerciasis, and what is notable about its biting pattern?", ["Simulium blackflies, which are daytime biters requiring many bites over months for transmission", "A single mosquito bite is sufficient for transmission", "Simulium blackflies that bite exclusively at night", "Tsetse flies, the same vector as African trypanosomiasis"], 0, "Onchocerciasis is transmitted by Simulium blackflies, daytime biters that require repeated bites over more than 3 months of exposure to successfully transmit the parasite."),
          Q("overview", "What actually drives the pathology of onchocerciasis -- living or dying larvae?", ["The immune response to dead/dying larvae (microfilariae), not living organisms", "Living larvae directly destroy tissue through mechanical burrowing", "Living adult worms cause all the pathology through toxin release", "Pathology is caused equally by living and dying organisms"], 0, "Living larvae and adult worms inside nodules can evade the host immune system and cause no symptoms -- the pathology of onchocerciasis is driven by the immune response to DEAD/DYING larvae (microfilariae)."),
          Q("presentation-diagnosis-treatment", "What skin finding, described as resembling an animal print, results from chronic onchocerciasis-related itching?", ["'Leopard skin'", "'Blueberry muffin' rash", "'Slapped cheek' appearance", "'Strawberry tongue'"], 0, "Chronic intense itching from the immune response to dying larvae leads to characteristic chronic skin damage described as 'leopard skin.'"),
          Q("presentation-diagnosis-treatment", "What eye complication can progress from reversible corneal lesions in onchocerciasis?", ["Permanent corneal thickening and blindness", "Acute angle-closure glaucoma exclusively", "Retinal detachment with no corneal involvement", "Cataracts as the sole ocular finding"], 0, "Onchocerciasis causes reversible corneal lesions that, without treatment, can progress to permanent corneal thickening and blindness -- giving the disease its 'river blindness' name."),
          Q("presentation-diagnosis-treatment", "What is the gold standard diagnostic test for onchocerciasis?", ["Skin snip biopsy (x6 snips)", "A single blood smear", "Stool O&P testing", "Lumbar puncture with CSF analysis"], 0, "Skin snip biopsy, typically 6 snips, is the gold standard diagnostic test for onchocerciasis, looking for microfilariae in the skin."),
          Q("presentation-diagnosis-treatment", "Why is ivermectin alone not curative for onchocerciasis, and what fills the gap?", ["Ivermectin only kills microfilariae, not adult worms (macrofilariae); doxycycline is added to target the adult worms", "Ivermectin kills adult worms but not larvae, requiring doxycycline for the larvae", "Ivermectin is fully curative on its own with no adjunct needed", "Doxycycline is used instead of ivermectin in all cases, never as an adjunct"], 0, "Ivermectin kills only the microfilariae (larvae), not the adult worms (macrofilariae), though it does sterilize adult female worms -- adjunctive doxycycline targets the macrofilariae directly, filling this treatment gap."),
          Q("presentation-diagnosis-treatment", "How often is the ivermectin dose repeated for onchocerciasis, and is dosing different for children?", ["Every 6 months, at the same dose for adults and children", "Once only, with no repeat dosing ever needed", "Daily for 6 weeks, with a lower pediatric dose", "Annually, with double the dose in adults"], 0, "Ivermectin 150 mcg/kg PO is given once every 6 months, using the same weight-based dose for both adults and children."),
          Q("presentation-diagnosis-treatment", "What is onchocerciasis's global ranking as an infectious cause of blindness?", ["The second leading infectious cause of blindness worldwide", "The leading infectious cause of blindness worldwide", "It is not a significant cause of blindness globally", "It ranks below the top 10 infectious causes of blindness"], 0, "Onchocerciasis is the second leading infectious cause of blindness worldwide, after trachoma, reflecting its major global health impact in endemic regions.")
        ])
      ]),

      L("introduction-infectious-disease", "Introduction to Infectious Disease", [
        D("listeria", "Listeria monocytogenes", "Gram-positive bacillus posing special risk to pregnant and immunocompromised patients.", [
          S("overview", "Organism & Risk", "<p>An uncommon gram-positive bacillus pathogen.</p>" + HY("Pregnant women and immunocompromised patients are at special risk of Listeria infection -- a key high-yield association."))
        ], [
          Q("overview", "What organism classification describes Listeria monocytogenes?", ["Gram-positive bacillus", "Gram-negative coccus", "Acid-fast bacillus", "Obligate intracellular bacterium"], 0, "Listeria monocytogenes is a gram-positive bacillus, classified among the uncommon gram-positive bacterial pathogens."),
          Q("overview", "Which patient populations are at special risk for Listeria infection?", ["Pregnant women and immunocompromised patients", "Healthy young adults with no comorbidities", "Only patients over age 80 with no other risk factors", "Only patients with a recent tick bite"], 0, "Pregnant women and immunocompromised patients are specifically called out as being at special risk of Listeria infection."),
          Q("overview", "Listeria is grouped with which other organisms as an 'uncommon' gram-positive bacterial pathogen in this lecture?", ["Corynebacterium diphtheriae and Bacillus anthracis", "Streptococcus pyogenes and Staphylococcus aureus", "Escherichia coli and Klebsiella pneumoniae", "Mycoplasma pneumoniae and Chlamydia species"], 0, "Listeria monocytogenes, Corynebacterium diphtheriae (diphtheria), and Bacillus anthracis (anthrax) are grouped together as uncommon gram-positive bacillus pathogens in this lecture.")
        ]),
        D("diphtheria", "Diphtheria (Corynebacterium diphtheriae)", "Toxin-mediated infection prevented by childhood toxoid vaccination.", [
          S("overview", "Organism & Prevention", "<p>Caused by <em>Corynebacterium diphtheriae</em>, a gram-positive bacillus.</p>" + HY("Diphtheria is prevented by childhood vaccination with an inactivated toxin (toxoid) -- part of the routine immunization schedule."))
        ], [
          Q("overview", "What organism causes diphtheria?", ["Corynebacterium diphtheriae", "Bordetella pertussis", "Clostridium diphtheriae", "Bacillus diphtheriae"], 0, "Diphtheria is caused by Corynebacterium diphtheriae, a gram-positive bacillus."),
          Q("overview", "How is diphtheria prevented?", ["Childhood vaccination with an inactivated toxin (toxoid)", "There is no available vaccine for diphtheria", "A live-attenuated vaccine given only to high-risk adults", "Prophylactic antibiotics given at birth"], 0, "Diphtheria is prevented by routine childhood vaccination with an inactivated toxin (toxoid), reflecting its toxin-mediated pathology.")
        ]),
        D("anthrax", "Anthrax (Bacillus anthracis)", "Spore-forming gram-positive rod with recognized bioterrorism significance.", [
          S("overview", "Organism & Significance", "<p>Caused by <em>Bacillus anthracis</em>, a spore-forming gram-positive rod.</p>" + HY("Anthrax is recognized for its potential to be weaponized as a biological weapon -- a key reason it's grouped with other bioterrorism-relevant pathogens across this course."))
        ], [
          Q("overview", "What organism causes anthrax?", ["Bacillus anthracis", "Bacillus cereus", "Clostridium anthracis", "Corynebacterium anthracis"], 0, "Anthrax is caused by Bacillus anthracis, a spore-forming gram-positive rod."),
          Q("overview", "Why is anthrax significant beyond its clinical presentation?", ["It can be weaponized as a biological weapon", "It is the most common cause of community-acquired pneumonia", "It is the leading cause of foodborne illness in the US", "It has no clinical or public health significance beyond routine infection"], 0, "Anthrax is specifically recognized for its potential to be enhanced/weaponized as a biological weapon, a key point distinguishing it from other gram-positive bacillus infections.")
        ]),
        D("nocardia-actinomyces", "Nocardia / Actinomyces", "Weakly gram-positive filamentous soil organisms causing indolent abscesses, especially with T-cell dysfunction.", [
          S("overview", "Organism, Risk & Treatment", "<p>Weakly gram-positive, filamentous bacteria, ubiquitous in soil and part of the normal human flora. Slow-growing, and often produce severe infection/abscess especially in persons with <strong>T-cell immune dysfunction</strong>.</p>" + HY("Nocardia and Actinomyces infections often require LONG-TERM treatment to fully eradicate -- a distinguishing management point from most other bacterial infections."))
        ], [
          Q("overview", "What staining characteristic and morphology describe Nocardia/Actinomyces?", ["Weakly gram-positive, filamentous bacteria", "Strongly gram-negative diplococci", "Acid-fast bacilli identical to Mycobacterium", "Gram-positive cocci in clusters"], 0, "Nocardia and Actinomyces are weakly gram-positive, filamentous bacteria that are ubiquitous in soil and part of normal human flora."),
          Q("overview", "Which immune defect particularly predisposes to severe Nocardia/Actinomyces infection?", ["T-cell immune dysfunction", "Isolated B-cell deficiency", "Complement deficiency", "Neutrophil dysfunction exclusively"], 0, "Nocardia and Actinomyces often produce severe infection/abscess especially in patients with T-cell immune dysfunction."),
          Q("overview", "What is notable about the treatment duration needed for Nocardia/Actinomyces infections?", ["Long-term treatment is often required to eradicate the infection", "A single dose is always curative", "Treatment is never indicated since these are normal flora", "Treatment never exceeds 3 days regardless of severity"], 0, "Nocardia and Actinomyces infections often require long-term treatment to fully eradicate, reflecting their slow-growing nature."),
          Q("overview", "Where are Nocardia and Actinomyces normally found?", ["Ubiquitous in soil and as part of normal human flora", "Exclusively in contaminated water sources", "Exclusively in bird and bat droppings", "They exist only within human hosts, with no environmental reservoir"], 0, "Nocardia and Actinomyces are ubiquitous in soil and are also part of the normal flora of humans, which is why disease more often reflects a host immune defect than a unique exposure.")
        ]),
        D("mycoplasma-pneumoniae", "Mycoplasma pneumoniae", "Cell-wall-free bacterium causing atypical \"walking\" pneumonia, mostly under age 35; beta-lactams don't work.", [
          S("overview", "Organism & Presentation", "<p>Tiny bacteria with <strong>no cell wall</strong> -- causes disease without cellular invasion. Causes atypical (\"walking\") pneumonia, responsible for about <strong>10% of community-acquired pneumonia</strong>, most common in persons <strong>under age 35</strong> (crowded settings like dorms and military barracks).</p>" + HY("Related Mycoplasma/Ureaplasma species cause non-gonococcal urethritis.")),
          S("treatment", "Treatment", HY("Because Mycoplasma has NO CELL WALL, beta-lactam antibiotics (which target cell wall synthesis) do NOT work against it. Mycoplasma is instead sensitive to tetracyclines, macrolides, and fluoroquinolones."))
        ], [
          Q("overview", "What structural feature of Mycoplasma pneumoniae explains why it causes disease without cellular invasion?", ["It has no cell wall", "It has an unusually thick capsule", "It is an obligate intracellular organism", "It produces a unique exotoxin unrelated to its structure"], 0, "Mycoplasma pneumoniae is a tiny bacterium with no cell wall, and this structural feature underlies both its disease mechanism and its antibiotic resistance pattern."),
          Q("overview", "What proportion of community-acquired pneumonia is caused by Mycoplasma pneumoniae?", ["About 10%", "About 75%", "Less than 1%", "Nearly 50%"], 0, "Mycoplasma pneumoniae is responsible for approximately 10% of community-acquired pneumonia cases."),
          Q("overview", "Which age group and setting is Mycoplasma pneumoniae infection most associated with?", ["Persons under age 35, in crowded settings like dorms or military barracks", "Adults over age 65 in nursing homes", "Neonates in the NICU", "Only immunocompromised transplant recipients"], 0, "Mycoplasma pneumoniae ('walking pneumonia') is most common in persons under age 35, particularly in crowded congregate settings like dormitories and military barracks."),
          Q("overview", "What condition can related Mycoplasma/Ureaplasma species cause?", ["Non-gonococcal urethritis", "Bacterial meningitis", "Infective endocarditis", "Osteomyelitis"], 0, "Five other species of Mycoplasma and Ureaplasma cause non-gonococcal urethritis, distinct from Mycoplasma pneumoniae's respiratory disease."),
          Q("treatment", "Why are beta-lactam antibiotics ineffective against Mycoplasma pneumoniae?", ["Mycoplasma has no cell wall, and beta-lactams target cell wall synthesis", "Mycoplasma is an obligate intracellular organism that beta-lactams cannot penetrate", "Mycoplasma produces a beta-lactamase enzyme", "Beta-lactams work fine against Mycoplasma; this is a common misconception"], 0, "Beta-lactam antibiotics work by disrupting bacterial cell wall synthesis -- since Mycoplasma has no cell wall at all, this drug class has no target and is ineffective."),
          Q("treatment", "Which antibiotic classes are effective against Mycoplasma pneumoniae?", ["Tetracyclines, macrolides, and fluoroquinolones", "Beta-lactams and cephalosporins", "Aminoglycosides exclusively", "Vancomycin and other glycopeptides"], 0, "Mycoplasma is sensitive to tetracyclines, macrolides, and fluoroquinolones -- antibiotic classes that don't rely on targeting a cell wall.")
        ]),
        D("chlamydia-species", "Chlamydia species", "Obligate intracellular bacteria causing GU infection (trachomatis), atypical pneumonia (pneumoniae), or psittacosis (psittaci).", [
          S("species", "The Three Chlamydia Species", "<p>Obligate intracellular bacteria -- they must live inside host cells to reproduce and obtain energy from the host cell.</p>" + Tbl(["Species", "Disease"], [
            ["C. trachomatis", "GU infections: non-gonococcal urethritis (men), cervicitis/PID (women), proctitis; can also cause neonatal conjunctivitis"],
            ["C. pneumoniae", "Atypical 'walking' pneumonia -- a common atypical CAP pathogen"],
            ["C. psittaci", "'Parrot fever' (psittacosis/ornithosis) -- uncommon, transmitted by inhaling dried bird feces"]
          ])),
          S("treatment", "Treatment", HY("Chlamydia infections are treated with tetracyclines, macrolides, or a respiratory fluoroquinolone (levofloxacin, moxifloxacin)."))
        ], [
          Q("species", "Why are Chlamydia species described as obligate intracellular bacteria?", ["They must live inside host cells to reproduce and obtain energy", "They can only survive outside of any host cell", "They require an insect vector to complete their life cycle", "They lack a cell wall, similar to Mycoplasma"], 0, "Chlamydia species are obligate intracellular bacteria -- they must live inside host cells to reproduce, deriving energy from the host cell itself."),
          Q("species", "Which Chlamydia species causes non-gonococcal urethritis, cervicitis, and neonatal conjunctivitis?", ["C. trachomatis", "C. pneumoniae", "C. psittaci", "All three species cause an identical clinical picture"], 0, "C. trachomatis causes genitourinary infections -- non-gonococcal urethritis in men, cervicitis/PID in women, proctitis, and neonatal conjunctivitis."),
          Q("species", "Which Chlamydia species is a common cause of atypical CAP?", ["C. pneumoniae", "C. trachomatis", "C. psittaci", "None of the three cause pneumonia"], 0, "C. pneumoniae causes atypical 'walking' pneumonia and is a common pathogen in atypical community-acquired pneumonia."),
          Q("species", "What is 'parrot fever,' and how is it transmitted?", ["Psittacosis, caused by C. psittaci, transmitted by inhaling dried bird feces", "A viral illness transmitted by parrot bites", "A fungal infection from exotic bird feathers", "A synonym for C. trachomatis genitourinary infection"], 0, "Parrot fever (psittacosis or ornithosis) is caused by C. psittaci and is an uncommon infection transmitted by inhaling dried bird feces."),
          Q("species", "Which complication can C. trachomatis cause in women beyond urethritis?", ["Cervicitis and pelvic inflammatory disease", "Psittacosis", "Atypical pneumonia exclusively", "Neonatal conjunctivitis only in male infants"], 0, "In women, C. trachomatis causes cervicitis and pelvic inflammatory disease (PID), in addition to proctitis and the risk of neonatal conjunctivitis if transmitted during delivery."),
          Q("treatment", "What antibiotic classes treat Chlamydia infections?", ["Tetracyclines, macrolides, or a respiratory fluoroquinolone", "Beta-lactams exclusively", "Aminoglycosides exclusively", "Antifungal azoles"], 0, "Chlamydia infections are treated with tetracyclines, macrolides, or a respiratory fluoroquinolone (levofloxacin, moxifloxacin) -- consistent with their obligate intracellular nature requiring agents that penetrate host cells."),
          Q("treatment", "Why might a respiratory fluoroquinolone specifically be chosen for a Chlamydia pneumoniae infection?", ["Levofloxacin/moxifloxacin are respiratory fluoroquinolones with activity against atypical pneumonia pathogens", "Fluoroquinolones are the only drug class active against any Chlamydia species", "Respiratory fluoroquinolones only work against C. trachomatis, not C. pneumoniae", "This drug class is contraindicated for any Chlamydia infection"], 0, "Respiratory fluoroquinolones like levofloxacin and moxifloxacin are effective against atypical pneumonia pathogens including C. pneumoniae, making them a reasonable treatment option alongside tetracyclines and macrolides.")
        ]),
        D("leptospirosis", "Leptospirosis", "Zoonotic spirochete from contaminated water or animal urine with protean manifestations.", [
          S("overview", "Organism, Transmission & Presentation", "<p>A spirochete -- thin, spiral-shaped bacteria with specialized motility -- comprising 21 pathogenic species. A common zoonotic infection associated with <strong>contaminated water exposure</strong> (from animal waste/urine).</p>" + HY("Leptospirosis causes protean (highly variable) manifestations: flu-like illness, meningitis, bacteremia, vasculitis, and nephritis -- its presentation can mimic many other conditions."))
        ], [
          Q("overview", "What class of bacteria does Leptospira belong to?", ["Spirochetes", "Gram-positive bacilli", "Obligate intracellular bacteria", "Acid-fast bacilli"], 0, "Leptospira are spirochetes -- thin, spiral-shaped bacteria with specialized motility -- comprising 21 pathogenic species, in the same broad bacterial class as Treponema and Borrelia."),
          Q("overview", "How is leptospirosis typically acquired?", ["Exposure to water contaminated with animal waste/urine", "Direct person-to-person respiratory transmission", "Tick bite", "Undercooked pork consumption"], 0, "Leptospirosis is a common zoonotic infection associated with contaminated water exposure, specifically water contaminated by animal waste or urine."),
          Q("overview", "Why is leptospirosis's presentation described as 'protean'?", ["It can present as flu-like illness, meningitis, bacteremia, vasculitis, or nephritis -- a highly variable clinical picture", "It always presents identically in every patient", "It causes only a single, unmistakable pathognomonic finding", "It is asymptomatic in all cases"], 0, "Leptospirosis has protean (highly variable) manifestations, ranging from a flu-like illness to meningitis, bacteremia, vasculitis, and nephritis, making it a diagnostic challenge.")
        ]),
        D("dermatophyte-infections", "Dermatophyte Infections (Tinea)", "Fungal infection of keratinized skin, hair, and nails -- corporis, pedis, cruris, capitis, unguium.", [
          S("overview", "Organism & Presentations", "<p>A group of fungi that primarily infect keratinized tissue: skin, hair, and nails, producing scaly, pruritic lesions.</p>" + Tbl(["Term", "Site"], [
            ["Tinea corporis", "Body"],
            ["Tinea pedis", "Feet"],
            ["Tinea cruris", "Groin"],
            ["Tinea capitis", "Scalp"],
            ["Tinea unguium", "Nails (onychomycosis)"]
          ])),
          S("treatment", "Treatment of Onychomycosis", HY("Oral terbinafine (Lamisil) is the drug of choice for onychomycosis (tinea unguium), dosed 250mg PO daily. Treatment must continue until the infected portion of the nail fully grows out: fingernails need at least 6 weeks, toenails need at least 12 weeks -- toenails take longer given their slower growth rate."))
        ], [
          Q("overview", "What type of tissue do dermatophytes primarily infect?", ["Keratinized tissue -- skin, hair, and nails", "Deep visceral organs", "The bloodstream, causing fungemia", "The CNS exclusively"], 0, "Dermatophytes are a group of fungi that primarily infect keratinized tissue, namely skin, hair, and nails, producing scaly, pruritic lesions."),
          Q("overview", "What is tinea capitis?", ["Dermatophyte infection of the scalp", "Dermatophyte infection of the feet", "Dermatophyte infection of the groin", "Dermatophyte infection of the nails"], 0, "Tinea capitis refers to dermatophyte infection of the scalp -- each tinea term is named by its Latin body-site suffix."),
          Q("overview", "Tinea unguium is another name for which condition?", ["Onychomycosis (nail infection)", "Athlete's foot", "Jock itch", "Ringworm of the scalp"], 0, "Tinea unguium is the dermatophyte infection of the nails, more commonly known as onychomycosis."),
          Q("treatment", "What is the drug of choice for onychomycosis, and what is its dosing?", ["Oral terbinafine 250mg PO daily", "Topical clotrimazole applied twice daily", "IV amphotericin B", "A single dose of fluconazole"], 0, "Oral terbinafine (Lamisil) 250mg PO daily is the drug of choice for onychomycosis -- its only oral indication."),
          Q("treatment", "Why does toenail onychomycosis require a longer treatment course than fingernail onychomycosis?", ["Toenails grow more slowly, requiring treatment until the infected portion fully grows out (12+ weeks vs. 6+ weeks)", "Toenail infections involve a different, more resistant organism", "Fingernail treatment is actually longer than toenail treatment", "Duration is identical between the two sites"], 0, "Treatment must continue until the infected portion of the nail grows out -- since toenails grow more slowly than fingernails, they require at least 12 weeks of therapy versus at least 6 weeks for fingernails.")
        ]),
        D("blastomycosis", "Blastomycosis", "Dimorphic fungus endemic to the Ohio/Mississippi River valleys and Great Lakes region.", [
          S("overview", "Organism & Geography", "<p>A dimorphic fungus. Endemic to the <strong>Ohio and Mississippi River valleys and the Great Lakes region</strong> -- overlapping Histoplasma's endemic territory.</p>")
        ], [
          Q("overview", "What type of fungus is Blastomyces?", ["A dimorphic fungus", "An obligate mold with no yeast phase", "A dermatophyte", "An encapsulated yeast"], 0, "Blastomyces is a dimorphic fungus, similar in classification to Histoplasma and Coccidioides."),
          Q("overview", "Blastomycosis is endemic to which US regions?", ["The Ohio and Mississippi River valleys and the Great Lakes region", "The southwestern desert", "The Pacific Northwest", "The Gulf Coast exclusively"], 0, "Blastomycosis shares endemic territory with Histoplasma in the Ohio and Mississippi River valleys, extending into the Great Lakes region.")
        ]),
        D("prion-diseases", "Prion Diseases", "Misfolded-protein neurodegenerative disorders -- CJD, variant CJD, fatal familial insomnia, Gerstmann-Straussler-Scheinker syndrome.", [
          S("mechanism", "Mechanism", "<p>A prion is a misfolded protein that can induce normally folded proteins to adopt the same abnormal conformation. As abnormal protein accumulates, neurons become dysfunctional and eventually die.</p>" + HY("Prion diseases are progressive neurodegenerative disorders caused by abnormal protein accumulation, resulting in 'spongiform' degeneration of brain tissue -- a distinctive pathologic hallmark unique to this disease class.")),
          S("disorders-treatment", "Major Human Prion Disorders & Treatment", Tbl(["Disease", "Key association"], [
            ["Creutzfeldt-Jakob disease (CJD)", "Rapidly progressive dementia + myoclonus"],
            ["Variant CJD", "Associated with exposure to BSE ('mad cow disease')"],
            ["Fatal familial insomnia", "Progressive insomnia + autonomic dysfunction"],
            ["Gerstmann-Sträussler-Scheinker syndrome", "Familial, progressive ataxia"]
          ]) + HY("Treatment is primarily supportive, as there is NO curative therapy: symptom management, management of myoclonus, supportive neurologic care, and palliative care."))
        ], [
          Q("mechanism", "What is a prion, and how does it cause disease?", ["A misfolded protein that induces normally folded proteins to adopt the same abnormal conformation, leading to neuronal dysfunction and death", "A virus with an unusually small genome", "A bacterium lacking a cell wall, similar to Mycoplasma", "A fungal spore that germinates within neurons"], 0, "A prion is a misfolded protein that induces normally folded proteins to adopt the same abnormal conformation -- as abnormal protein accumulates, neurons become dysfunctional and die, unlike any conventional infectious agent."),
          Q("mechanism", "What is the characteristic pathologic finding in prion disease brain tissue?", ["'Spongiform' degeneration", "Caseating granulomas", "Amyloid plaques identical to Alzheimer disease", "Diffuse Lewy bodies"], 0, "Prion diseases cause 'spongiform' degeneration of brain tissue -- a distinctive pathologic hallmark that gives this disease class its alternate name, transmissible spongiform encephalopathies."),
          Q("disorders-treatment", "What clinical picture is classic for Creutzfeldt-Jakob disease (CJD)?", ["Rapidly progressive dementia plus myoclonus", "Slowly progressive dementia over 20 years with no motor findings", "Isolated peripheral neuropathy with normal cognition", "Progressive ataxia with no cognitive changes"], 0, "CJD classically presents with rapidly progressive dementia plus myoclonus, distinguishing its aggressive course from most other dementias."),
          Q("disorders-treatment", "Variant CJD is associated with exposure to what?", ["BSE ('mad cow disease')", "HIV", "Contaminated surgical instruments exclusively, with no dietary link", "Tick bites"], 0, "Variant CJD is associated with exposure to bovine spongiform encephalopathy (BSE), commonly known as 'mad cow disease,' typically through contaminated beef products."),
          Q("disorders-treatment", "Which prion disease is characterized by progressive insomnia and autonomic dysfunction?", ["Fatal familial insomnia", "Creutzfeldt-Jakob disease", "Variant CJD", "Gerstmann-Sträussler-Scheinker syndrome"], 0, "Fatal familial insomnia is specifically characterized by progressive insomnia along with autonomic dysfunction, distinguishing it from the dementia-predominant presentations of CJD."),
          Q("disorders-treatment", "What clinical picture is classic for Gerstmann-Sträussler-Scheinker syndrome?", ["Familial, progressive ataxia", "Rapidly progressive dementia with myoclonus", "Isolated progressive insomnia with no motor findings", "Acute-onset psychosis with full recovery"], 0, "Gerstmann-Sträussler-Scheinker syndrome is a familial prion disease characterized by progressive ataxia."),
          Q("disorders-treatment", "Is there a curative therapy for prion diseases?", ["No -- treatment is primarily supportive (symptom management, myoclonus management, palliative care)", "Yes, early antiviral therapy is curative if started within 48 hours", "Yes, a course of antifungal therapy reverses the disease", "Yes, corticosteroids reliably halt disease progression"], 0, "There is no curative therapy for any prion disease -- management is entirely supportive, focusing on symptom management (including myoclonus), supportive neurologic care, and palliative care.")
        ])
      ]),

      L("hiv-aids", "HIV and AIDS", [
        D("hiv-aids", "HIV Infection / AIDS", "Retrovirus destroying CD4 T cells; staged from acute infection through AIDS, defined by CD4 <200 or an AIDS-defining diagnosis.", [
          S("overview", "Organism, Transmission & Epidemiology", "<p>HIV is a human RNA retrovirus. Two species: <strong>HIV-1</strong> (predominant in the US) and <strong>HIV-2</strong> (mainly western Africa, parts of India). It has two copies of single-stranded RNA plus reverse transcriptase in a conical core, with a lipid envelope -- the envelope has the greatest strain variability, which is why a vaccine is so hard to make.</p><p>HIV replicates best inside <strong>activated CD4+ T cells</strong>, hijacking and destroying the exact cells needed to fight it; it can also go latent (no viral protein production, invisible to killer T cells).</p>" + Tbl(["Transmission route", "Key risk detail"], [
            ["Blood transfusion", "~92.5% risk if untreated blood transfused; now ~1:1,000,000 in the US due to universal screening since 1985"],
            ["Sexual contact", "Highest per-act risk: receptive anal (1.38%); heterosexual intercourse is still the dominant mode worldwide; increased by genital ulcerative lesions, uncircumcised partners"],
            ["Injection drug use", "Needle/syringe sharing ~0.62%; risk increases with duration of use and paraphernalia sharing"],
            ["Mother-to-baby (vertical)", "Untreated 15-35%; reduced to <1% with maternal ART, cesarean delivery, and avoiding breastfeeding"]
          ]) + HY("The risk driver common to ALL transmission routes is high viral load -- viral load is highest during acute/early infection, so most transmissions come from recently-infected people.") + "<p>US epidemiology (2022 CDC): 1.2 million living with HIV; 31,800 new diagnoses, most common ages 25-34; 82% of infections in men (67% in MSM); disproportionately affects Black and Hispanic/Latino populations due to social/structural inequities; the South accounts for 49% of new diagnoses.</p>"),
          S("natural-history", "Natural History", Tbl(["Stage", "Timing & Findings"], [
            ["1. Primary infection / Acute HIV", "High viral replication within 4-11 days, sharp T-lymphocyte decline"],
            ["2. Acute Retroviral Syndrome", "50-90% develop a flu-like illness ('worst flu ever') 2-6 weeks post-infection, lasting 7-21 days -- fever, chills, malaise, LAD, myalgias, rash; ~10% develop aseptic meningitis. Marks SEROCONVERSION. Often misdiagnosed as a nonspecific viral illness -- a major missed diagnostic opportunity"],
            ["3. Clinical latency / asymptomatic", "By 6 months, viral load reaches a steady SET POINT (CD8 T cells critical here); patient is infectious but asymptomatic. CD4 gradually declines from 900-2000 baseline to ~500-700 over years. Progression rate to AIDS is DIRECTLY PROPORTIONAL to viral set point (not influenced by sex, mode of infection, or LAD presence)"],
            ["4. Early symptomatic phase", "Increased susceptibility to pulmonary infection/bacteremia (pneumococcal pneumonia, syphilis, active TB, MRSA), mucocutaneous lesions"],
            ["5. Late symptomatic phase", "High OI risk at CD4 <200; prophylaxis initiated. CD4 <50 = profound immunodeficiency; infection therapy only succeeds alongside ART"],
            ["6. AIDS", "See AIDS definition"]
          ]) + HY("About 7% of patients achieve an undetectable viral load without treatment (elite controllers), but this cannot be sustained long-term. A more symptomatic/longer (14+ day) acute retroviral syndrome predicts FASTER progression to AIDS.")),
          S("aids-definition", "AIDS Definition & Staging", HY("AIDS is defined as CD4 count <200 cells/mm3 OR ANY AIDS-defining diagnosis, regardless of CD4 count.") + "<p>Full list of AIDS-defining diagnoses: invasive cervical cancer, HIV encephalopathy, Kaposi's sarcoma, progressive multifocal leukoencephalopathy (PML), extrapulmonary cryptococcus, non-Hodgkin's lymphoma or primary CNS lymphoma, HIV wasting syndrome, Pneumocystis jirovecii pneumonia (PCP), active tuberculosis, candidiasis of the lower respiratory tract or esophagus, disseminated/extrapulmonary histoplasmosis, disseminated/extrapulmonary MAC, disseminated/extrapulmonary coccidioidomycosis, toxoplasmosis of the brain, recurrent pneumonia, recurrent Salmonella sepsis, cryptosporidiosis or isosporiasis, CMV retinitis or CMV disease, and HSV bronchitis/pneumonitis/esophagitis/chronic ulcers.</p>" + Tbl(["CDC Stage", "Criteria"], [
            ["0", "Negative HIV test within 6 months of a positive one"],
            ["I", "HIV of unknown duration, CD4 &ge;500"],
            ["II", "HIV of unknown duration, CD4 200-499"],
            ["III", "HIV of unknown duration, CD4 &lt;200 OR an AIDS-defining diagnosis"],
            ["Unknown", "No recent CD4 count available"]
          ])),
          S("testing", "Testing & Initial Workup", "<p>CDC: all persons 13-64 tested at least once as routine care; annual testing for those with risk factors. USPSTF: screen adults/adolescents with risk factors plus all pregnant women.</p>" + Tbl(["Test", "Detail"], [
            ["Home antibody test", "Finger-stick or oral fluid; antibodies take 3-12 weeks to develop (window period -- false negatives possible); a positive result is only preliminary"],
            ["Screening (4th-gen Ag/Ab)", "Detects HIV-1/HIV-2 antibodies PLUS p24 antigen simultaneously; window period ~14-28 days"],
            ["Confirmatory test", "HIV-1/HIV-2 antibody differentiation immunoassay. If initial ELISA is negative after a known exposure, retest at 3 months"],
            ["HIV RNA (NAT)", "Detects high early RNA levels, but NOT recommended as a screening test (cost without meaningful sensitivity gain)"]
          ]) + HY("Initial workup at diagnosis includes a PPD (5mm or greater is POSITIVE in HIV -- a lower threshold than the general population), T. gondii antibody, RPR/VDRL, CMV serology, gonorrhea/chlamydia NAAT, hepatitis panel, and baseline HIV genotype. Follow-up: HIV specialist visits every 3-4 months with CD4 count and viral load.")),
          S("treatment", "Treatment -- Antiretroviral Therapy (ART)", HY("ART is suppressive, NOT curative -- lifelong, and started at the time of diagnosis regardless of CD4 count. An effective regimen requires at least 3 drugs from at least 2 different classes; the most effective combo is 2 NRTIs plus a 3rd active drug from a different class.") + "<p>Drug classes: reverse transcriptase inhibitors (NRTIs and NNRTIs), protease inhibitors (PIs), fusion inhibitors (multidrug-resistant HIV only), entry inhibitors, and integrase inhibitors (INSTIs, block DNA integration).</p><p>Viral load should become undetectable within 3-6 months of starting ART. Even on effective therapy, viral escape can eventually occur. Prognosis: untreated median survival is 8-10 years; once progressed to AIDS, untreated survival is usually less than 2 years.</p>"),
          S("cd4-prophylaxis", "CD4-Based OI/Malignancy Prediction & Prophylaxis", Tbl(["CD4 range", "Opportunistic infections", "Malignancies"], [
            ["200-500", "Polydermatomal zoster, active TB, recurrent bacterial pneumonia, thrush", "Mucocutaneous Kaposi's sarcoma, oral hairy leukoplakia, invasive cervical cancer"],
            ["100-200", "PCP, disseminated histoplasmosis, PML", "Visceral Kaposi's sarcoma, non-Hodgkin lymphoma"],
            ["&lt;100", "Candida esophagitis, CMV retinitis, disseminated MAC, toxoplasmosis, cryptococcal meningitis, cryptosporidium enteritis", "CNS lymphoma"]
          ]) + HY("Prophylaxis thresholds: CD4 <200 -> PCP prophylaxis (daily Bactrim DS). CD4 <100 -> toxoplasmosis prophylaxis (daily Bactrim DS, only if T. gondii antibody-positive). CD4 <50 -> MAC prophylaxis (azithromycin). Once started, prophylaxis/suppression is lifelong.")),
          S("differentials", "Key Comparison Frameworks", "<p><strong>CAP in HIV</strong> (incidence 3-4x the general population, more often caused by encapsulated organisms like Strep pneumoniae/H. flu): faster onset (1-3 days vs. 3-5), more severe (sepsis/bacteremia common), and diffuse multi-lobar CXR infiltrates rather than a single lobar infiltrate.</p><p><strong>Chronic diarrhea in HIV</strong> -- causes: protozoal (Cryptosporidium, Microsporidium), bacterial (MAC, Salmonella, Campylobacter), viral (CMV), idiopathic ('AIDS enteropathy'), drug-related (ART itself), emerging (C. diff). Workup order: stool pathogen exam first, then O&P for parasites if negative, then colonoscopy ± EGD with biopsy if still unexplained.</p><p><strong>CNS/meningitis differential</strong>: aseptic meningitis (usually viral, may be part of acute retroviral syndrome); chronic meningitis (usually fungal -- Cryptococcus is the most common pathogen); meningoencephalitis (fever + AMS progressing to coma, from CMV/HSV/JC virus); acute bacterial meningitis (less common in HIV, from Strep pneumoniae/N. meningitidis).</p>"),
          S("special-populations", "Special Populations", Tbl(["Population", "Key points"], [
            ["Aging", "54% of people with HIV were &ge;50 in 2022 (expected 73% by 2030); HTN, DM, ESRD, CAD/MI, and fractures occur ~10 years earlier than age-matched controls"],
            ["Children/infants", "Nonspecific findings (LAD, hepatosplenomegaly, thrush, failure to thrive); most common OI is PCP; ART recommended for ALL infants/children regardless of CD4/stage -- untreated progression to AIDS/death occurs before age 5"],
            ["Adolescents/young adults", "~20% of 2022 new US diagnoses were ages 13-24, mostly sexually acquired"],
            ["Pregnancy", "Untreated transmission risk 25-30%, reduced to <1% with ART throughout pregnancy, scheduled cesarean at 38-39 weeks before labor, and avoiding breastfeeding; all in-utero-exposed infants get ART for the first 6 weeks of life"]
          ])),
          S("prevention", "Prevention -- PrEP & PEP", Tbl(["Drug (PrEP)", "Dosing", "Note"], [
            ["TDF/FTC (Truvada)", "PO daily", "First available PrEP; generic available; '2-1-1' on-demand eligible"],
            ["TAF/FTC (Descovy)", "PO daily", "All sexual activity EXCEPT receptive vaginal sex; better bone/renal markers"],
            ["Cabotegravir (Apretude)", "IM q2 months", "Superior to oral Truvada in 2 trials"],
            ["Lenacapavir (Yeztugo)", "SQ q6 months", "Best efficacy to date -- 0 infections among 2,134 participants in the PURPOSE-1 trial"]
          ]) + HY("PrEP reduces sexual transmission risk by 99% and injection-drug-use transmission risk by 74%+. Monitoring: every 3 months (HIV Ag/Ab test, refill, counseling); every 6 months (renal function, STI screening).") + "<p><strong>PEP</strong> is for emergency situations (needlestick, sexual assault, shared injection equipment) and MUST start within 72 hours of exposure (&gt;80% effective). Regimen: 2-3 drugs combined for 28 days. Monitoring: HIV test at 6 weeks post-exposure, repeat at 3 months.</p>")
        ], [
          Q("overview", "Which cell type does HIV preferentially replicate within, and why is this significant?", ["Activated CD4+ T cells -- HIV hijacks and destroys the exact cells needed to fight it", "Neutrophils, which it uses purely as a vehicle for dissemination", "Hepatocytes, explaining its association with liver failure", "Red blood cells, explaining HIV-associated anemia"], 0, "HIV replicates best inside activated CD4+ T cells, which is especially significant because these are the very cells the immune system needs to mount an effective response -- HIV directly undermines its own control."),
          Q("overview", "Why is an HIV vaccine so difficult to develop?", ["The envelope has the greatest strain variability, and HIV mutates constantly during replication", "HIV does not interact with the immune system at all", "HIV is a DNA virus with an unusually stable genome", "No part of the virus is exposed to antibodies"], 0, "The viral envelope shows the greatest strain variability of any HIV component, and the virus mutates constantly during replication -- both factors make it extremely difficult to design a broadly effective vaccine."),
          Q("overview", "What is the common risk driver across ALL HIV transmission routes?", ["High viral load, which is highest during acute/early infection", "Recipient blood type", "Ambient temperature at time of exposure", "The recipient's CD4 count at time of exposure"], 0, "High viral load is the risk driver common to all transmission routes -- since viral load peaks during acute/early infection, most transmissions actually come from recently-infected people who may not yet know their status."),
          Q("overview", "How has blood transfusion transmission risk changed in the US since 1985?", ["It dropped from ~92.5% (untreated blood) to about 1:1,000,000 due to universal antibody screening", "It has remained essentially unchanged since the 1980s", "It increased due to more frequent transfusions", "Transfusion-related transmission was never a significant risk"], 0, "Universal antibody screening since 1985, plus later antigen/viral load testing, reduced transfusion-transmission risk from about 92.5% (if untreated infected blood were transfused) to roughly 1 in 1,000,000 in the US today."),
          Q("natural-history", "What event does Acute Retroviral Syndrome mark, and how commonly does it occur?", ["Seroconversion, occurring in 50-90% of patients as a flu-like illness 2-6 weeks post-infection", "AIDS onset, occurring in nearly 100% of untreated patients", "Elite control, occurring in about 7% of patients", "Viral latency, occurring in all patients equally"], 0, "Acute Retroviral Syndrome marks seroconversion and occurs in 50-90% of patients as a flu-like illness ('worst flu ever') 2-6 weeks post-infection -- it is often misdiagnosed as a nonspecific viral illness, representing a major missed diagnostic opportunity."),
          Q("natural-history", "What determines the rate of progression to AIDS during clinical latency?", ["The viral set point -- progression is directly proportional to it, regardless of sex, mode of infection, or LAD", "The patient's sex assigned at birth", "Whether the patient has persistent generalized lymphadenopathy", "The specific mode of HIV acquisition (sexual vs. blood-borne vs. vertical)"], 0, "Progression rate to AIDS is directly proportional to the viral set point established by about 6 months post-infection -- notably, this is NOT influenced by sex, mode of infection, or the presence of lymphadenopathy."),
          Q("natural-history", "What clinical feature of the acute retroviral illness predicts faster progression to AIDS?", ["A more symptomatic or longer-duration (14+ days) acute syndrome", "A completely asymptomatic acute infection", "A shorter-than-average acute syndrome", "The presence of a rash alone, regardless of duration"], 0, "A more symptomatic and/or longer (at least 14 days) acute retroviral syndrome predicts faster progression to AIDS, reflecting a more vigorous but ultimately less effective initial immune battle."),
          Q("aids-definition", "How is AIDS formally defined?", ["CD4 count <200 cells/mm3 OR any AIDS-defining diagnosis, regardless of CD4 count", "CD4 count <200 cells/mm3 only, with no alternative criterion", "Any positive HIV test regardless of CD4 count or symptoms", "A CD4 percentage below 50%, regardless of absolute count"], 0, "AIDS is defined as CD4 count <200 cells/mm3 OR any AIDS-defining diagnosis (like PCP or Kaposi's sarcoma) occurring at ANY CD4 count -- meeting either criterion is sufficient."),
          Q("aids-definition", "Which CDC HIV stage corresponds to a CD4 count of 200-499 with unknown infection duration?", ["Stage II", "Stage I", "Stage III", "Stage 0"], 0, "CDC Stage II is defined as HIV of unknown duration with CD4 200-499; Stage I requires CD4 &ge;500, and Stage III requires CD4 <200 or an AIDS-defining diagnosis."),
          Q("aids-definition", "What PPD induration size is considered positive in an HIV-positive patient?", ["5mm or greater", "10mm or greater, same as the general population", "15mm or greater", "PPD is never used for HIV patients -- only QuantiFERON is valid"], 0, "A PPD induration of 5mm or greater is considered positive in HIV patients -- a lower threshold than the general population, reflecting their impaired ability to mount a robust delayed-type hypersensitivity response."),
          Q("testing", "What does the 4th-generation combination Ag/Ab screening test detect?", ["HIV-1/HIV-2 antibodies plus the p24 antigen simultaneously", "Only HIV-1 antibodies, with no antigen component", "HIV RNA directly, with no antibody component", "Only the p24 antigen, with no antibody component"], 0, "The 4th-generation combination immunoassay detects HIV-1/HIV-2 antibodies AND the p24 antigen simultaneously, which shortens the window period to about 14-28 days compared to antibody-only tests."),
          Q("testing", "If an initial ELISA is negative shortly after a known HIV exposure, what should be done?", ["Retest at 3 months, given the antibody window period", "No further testing is needed -- a single negative test rules out infection", "Immediately start ART empirically without further testing", "Switch directly to a home antibody test instead"], 0, "Because antibody-based testing has a window period, a negative ELISA shortly after a known exposure should be followed by retesting at 3 months to reliably rule out infection."),
          Q("testing", "Why is HIV RNA (NAT) testing not recommended as a routine screening test?", ["It adds cost without a meaningful sensitivity gain over standard screening", "It cannot detect early infection at all", "It is less accurate than a home antibody test", "It requires a blood draw, unlike other screening methods"], 0, "HIV RNA (NAT) testing can detect high early RNA levels, but it is not recommended for routine screening because its cost isn't justified by a meaningful sensitivity gain over the standard 4th-generation Ag/Ab test."),
          Q("treatment", "Is ART curative, and when should it be started relative to diagnosis?", ["ART is suppressive, not curative, and is started at the time of diagnosis regardless of CD4 count", "ART is curative if started within the first year of infection", "ART is suppressive and should be delayed until CD4 falls below 500", "ART cures HIV but must be taken for at least 10 years"], 0, "ART is suppressive, not curative, and is lifelong -- it is started at the time of diagnosis regardless of the patient's CD4 count, since earlier initiation improves outcomes."),
          Q("treatment", "What defines an effective ART regimen?", ["At least 3 drugs from at least 2 different classes, typically 2 NRTIs plus a 3rd drug from a different class", "A single potent protease inhibitor alone", "Any 2 drugs from the same class", "4 or more drugs from a single class"], 0, "An effective ART regimen requires at least 3 drugs from at least 2 different classes -- the most effective combination is typically 2 NRTIs plus a third active drug from a different class."),
          Q("treatment", "Within what timeframe should viral load become undetectable after starting ART?", ["3-6 months", "24 hours", "2 years", "Viral load never becomes fully undetectable, even with perfect adherence"], 0, "Viral load should become undetectable within 3-6 months of starting an effective ART regimen -- failure to do so raises concern for adherence issues or resistance."),
          Q("cd4-prophylaxis", "At what CD4 range are PCP, disseminated histoplasmosis, and PML classically seen?", ["100-200", "200-500", "Less than 100", "Above 500"], 0, "PCP, disseminated histoplasmosis, and PML are classic opportunistic infections seen in the CD4 100-200 range, along with visceral Kaposi's sarcoma and non-Hodgkin lymphoma as the corresponding malignancies."),
          Q("cd4-prophylaxis", "Which opportunistic infections and malignancy are classically associated with CD4 less than 100?", ["Candida esophagitis, CMV retinitis, disseminated MAC, toxoplasmosis, cryptococcal meningitis, cryptosporidium enteritis, and CNS lymphoma", "Polydermatomal zoster and thrush only", "Active TB and recurrent bacterial pneumonia only", "Mucocutaneous Kaposi's sarcoma only"], 0, "At CD4 less than 100, the classic OIs are Candida esophagitis, CMV retinitis, disseminated MAC, toxoplasmosis, cryptococcal meningitis, and cryptosporidium enteritis, with CNS lymphoma as the associated malignancy."),
          Q("cd4-prophylaxis", "At what CD4 threshold should toxoplasmosis prophylaxis begin, and what additional criterion must be met?", ["CD4 <100, and only if the patient is T. gondii antibody-positive", "CD4 <200, regardless of T. gondii antibody status", "CD4 <50, regardless of T. gondii antibody status", "Toxoplasmosis prophylaxis is never indicated regardless of CD4"], 0, "Toxoplasmosis prophylaxis (daily Bactrim DS) begins at CD4 <100, but only in patients who are T. gondii antibody-positive -- antibody-negative patients aren't at risk for reactivation since they were never infected."),
          Q("cd4-prophylaxis", "At what CD4 threshold does MAC prophylaxis begin, and with what drug?", ["CD4 <50, with azithromycin", "CD4 <200, with azithromycin", "CD4 <100, with TMP-SMX", "MAC prophylaxis is never indicated"], 0, "MAC prophylaxis with azithromycin begins at CD4 <50 -- the lowest of the three prophylaxis thresholds, reflecting MAC's tendency to occur very late in advanced AIDS."),
          Q("differentials", "How does CAP typically differ in HIV patients compared to immunocompetent patients?", ["Faster onset (1-3 days vs. 3-5), more severe with sepsis/bacteremia common, and diffuse multi-lobar CXR infiltrates", "Slower onset and milder severity than in immunocompetent patients", "Identical presentation and CXR findings in both groups", "Always caused by atypical organisms rather than encapsulated bacteria"], 0, "HIV-associated CAP has a faster onset (1-3 days vs. 3-5 in immunocompetent patients), is more severe (sepsis/bacteremia common), and shows diffuse multi-lobar CXR infiltrates rather than a single lobar infiltrate -- and it's more often caused by encapsulated organisms even in younger patients."),
          Q("differentials", "In the workup of chronic diarrhea in an HIV patient, what is the correct order of testing?", ["Stool pathogen exam first, then O&P for parasites if negative, then colonoscopy ± EGD with biopsy if still unexplained", "Colonoscopy first, regardless of stool testing results", "O&P testing alone, with no further workup needed", "Blood cultures alone are sufficient to diagnose the cause"], 0, "The recommended workup order is stool pathogen exam (culture/PCR, C. diff testing) first, then O&P for parasites if that's negative, then colonoscopy ± EGD with biopsy if the cause remains unexplained and persistent."),
          Q("differentials", "What is the most common pathogen causing chronic meningitis in HIV patients?", ["Cryptococcus", "Streptococcus pneumoniae", "Neisseria meningitidis", "HSV"], 0, "Cryptococcus is the most common cause of chronic meningitis in HIV, typically presenting with difficulty concentrating, headache, fever, or altered mental status -- distinct from the acute bacterial meningitis caused by the 'usual suspects' like Strep pneumoniae and N. meningitidis."),
          Q("special-populations", "What is the most common opportunistic infection in HIV-positive children/infants?", ["PCP", "Tuberculosis", "Cryptococcal meningitis", "Toxoplasmosis"], 0, "PCP is the most common opportunistic infection in HIV-positive children and infants, who often present with nonspecific findings like lymphadenopathy, hepatosplenomegaly, thrush, and failure to thrive."),
          Q("special-populations", "Should ART be started in an HIV-positive infant/child based on CD4 count or stage?", ["No -- ART is recommended for ALL infants/children with HIV regardless of CD4 count or stage", "Only once CD4 falls below 200", "Only once the child develops an AIDS-defining illness", "ART is not approved for use in children"], 0, "ART is recommended for all HIV-positive infants, children, and adolescents regardless of CD4 count or disease stage, since untreated progression to AIDS and death occurs before age 5 in this population."),
          Q("special-populations", "How is mother-to-child HIV transmission risk reduced from its untreated baseline?", ["From 25-30% untreated to under 1% with ART throughout pregnancy, scheduled cesarean, and avoiding breastfeeding", "It cannot be meaningfully reduced below 15% with any current intervention", "Only by avoiding breastfeeding alone, with no role for ART or delivery method", "Only by ART during labor and delivery, not throughout pregnancy"], 0, "Untreated mother-to-child transmission risk of 25-30% is reduced to under 1% through a combination of ART throughout pregnancy, scheduled cesarean delivery at 38-39 weeks before labor onset, and avoiding breastfeeding."),
          Q("prevention", "Which PrEP agent has shown the best efficacy to date, based on the PURPOSE-1 trial?", ["Lenacapavir (Yeztugo)", "TDF/FTC (Truvada)", "TAF/FTC (Descovy)", "Cabotegravir (Apretude)"], 0, "Lenacapavir (Yeztugo), dosed subcutaneously every 6 months, showed the best efficacy to date -- 0 infections among 2,134 participants in the PURPOSE-1 trial of cisgender women."),
          Q("prevention", "Which PrEP agent is NOT recommended for patients relying on protection during receptive vaginal sex?", ["TAF/FTC (Descovy)", "TDF/FTC (Truvada)", "Cabotegravir (Apretude)", "Lenacapavir (Yeztugo)"], 0, "TAF/FTC (Descovy) is indicated for all sexual activity EXCEPT receptive vaginal sex -- an important prescribing distinction from the other PrEP agents, which cover all sexual activity types."),
          Q("prevention", "By approximately how much does properly used PrEP reduce sexual HIV transmission risk?", ["99%", "50%", "25%", "PrEP has not been shown to reduce sexual transmission risk"], 0, "PrEP reduces sexual transmission risk by approximately 99% when used properly, and reduces injection-drug-use transmission risk by at least 74%."),
          Q("prevention", "Within what timeframe must PEP be started after a potential HIV exposure, and for how long is it given?", ["Within 72 hours, given as 2-3 drugs combined for 28 days", "Within 30 days, given as a single drug for 7 days", "Within 24 hours only, given for 14 days", "PEP has no defined time window and can be started at any point"], 0, "PEP must start within 72 hours of exposure to be more than 80% effective, and consists of 2-3 combined drugs given for 28 days, with HIV testing at 6 weeks and again at 3 months to rule out seroconversion.")
        ]),
        D("pcp", "Pneumocystis Pneumonia (PCP)", "The most frequent AIDS-defining opportunistic infection in the US, typically at CD4 <200; high-dose Bactrim is treatment of choice.", [
          S("presentation-diagnosis", "Presentation & Diagnosis", "<p>Caused by <em>Pneumocystis jirovecii</em> (a fungus) -- minimal symptoms in healthy hosts, causes pneumonia when immunocompromised. <strong>The most frequent presenting OI of AIDS in the US</strong>, typically occurring at <strong>CD4 &lt;200</strong>.</p><p>About 3 weeks of symptoms before presentation: gradual exertional dyspnea (95%), fever &gt;100.5°F (80-100%), nonproductive cough (95%), fatigue with usual activities, exercise-induced hypoxemia.</p>" + HY("CXR classically shows a subtle bilateral interstitial pattern OR is completely normal -- the patient looks sicker than the CXR suggests. Pleural effusions are unusual. CT shows patchy/nodular ground-glass opacities (not specific).") + "<p>Diagnosis is confirmed by finding the organism in induced sputum or BAL; PCR on induced sputum cannot distinguish colonization from infection.</p>"),
          S("treatment-prophylaxis", "Treatment & Prophylaxis", HY("Do NOT delay treatment to confirm diagnosis -- start on clinical grounds. High-dose IV Bactrim (TMP-SMX) is the treatment of choice for severe disease; oral Bactrim for mild-moderate. Add corticosteroids for moderate/severe disease.") + "<p>After treatment, patients need LIFELONG oral Bactrim prophylaxis regardless of CD4. Primary prophylaxis (daily Bactrim DS) starts once CD4 falls below 200.</p>")
        ], [
          Q("presentation-diagnosis", "What organism causes PCP, and how does it behave differently in healthy vs. immunocompromised hosts?", ["Pneumocystis jirovecii, a fungus that causes minimal symptoms in healthy hosts but pneumonia when immunocompromised", "Pneumocystis carinii, a protozoan that is always symptomatic regardless of immune status", "Pneumocystis jirovecii, a bacterium requiring beta-lactam therapy", "An RNA virus related to influenza"], 0, "Pneumocystis jirovecii is a fungus that causes minimal or no symptoms in immunocompetent hosts but produces pneumonia once cell-mediated immunity is impaired, as in advanced HIV."),
          Q("presentation-diagnosis", "At what CD4 count does PCP typically occur, and how does its frequency compare to other AIDS-defining OIs in the US?", ["Typically at CD4 <200; it is the most frequent presenting OI of AIDS in the US", "Typically at CD4 <50; it is a rare OI in the US", "It occurs at any CD4 count with equal frequency", "It is the least common AIDS-defining OI in the US"], 0, "PCP typically occurs at CD4 <200 and is the single most frequent presenting opportunistic infection of AIDS in the US."),
          Q("presentation-diagnosis", "What triad of symptoms is characteristic of PCP presentation?", ["Gradual exertional dyspnea, fever, and nonproductive cough, each present in the large majority of cases", "Sudden-onset pleuritic chest pain with hemoptysis", "Productive purulent cough with high fever and rigors", "Painless dyspnea with no fever or cough at all"], 0, "PCP classically presents with gradual exertional dyspnea (95%), fever >100.5°F (80-100%), and nonproductive cough (95%), developing over about 3 weeks before presentation."),
          Q("presentation-diagnosis", "What is a classic, often misleading, chest x-ray finding in PCP?", ["The CXR can be completely normal despite significant symptoms -- the patient looks sicker than the CXR", "Lobar consolidation with air bronchograms, identical to typical bacterial pneumonia", "Large pleural effusions are a hallmark finding", "Cavitary lesions are always present"], 0, "A classically misleading finding in PCP is a completely normal CXR (or only a subtle bilateral interstitial pattern) despite the patient appearing quite ill -- pleural effusions are also unusual, unlike many other pneumonias."),
          Q("presentation-diagnosis", "How is PCP definitively diagnosed?", ["Finding the organism in induced sputum or BAL fluid", "Clinical presentation and CXR findings alone, with no microbiologic confirmation ever needed", "Blood culture growing Pneumocystis jirovecii", "Serum galactomannan antigen testing"], 0, "PCP is confirmed by directly identifying the organism in induced sputum or bronchoalveolar lavage (BAL) fluid -- PCR alone cannot distinguish colonization from true infection."),
          Q("treatment-prophylaxis", "Should PCP treatment be delayed pending definitive diagnosis?", ["No -- treatment should start on clinical grounds without delay", "Yes, treatment should always wait for BAL confirmation", "Yes, but only in patients with a normal CXR", "Treatment should be delayed until CD4 count results return"], 0, "Given how rapidly PCP can progress and the risk of respiratory failure, treatment should be started on clinical grounds without waiting to confirm the diagnosis microbiologically."),
          Q("treatment-prophylaxis", "What is the treatment of choice for severe PCP?", ["High-dose IV Bactrim (TMP-SMX)", "Oral fluconazole", "IV vancomycin", "A single dose of azithromycin"], 0, "High-dose IV Bactrim (TMP-SMX) is the treatment of choice for severe PCP; oral Bactrim is used for mild-to-moderate disease."),
          Q("treatment-prophylaxis", "When are corticosteroids added to PCP treatment?", ["For moderate or severe disease", "Never -- steroids are contraindicated in PCP", "Only for mild disease, not moderate/severe", "Only after treatment failure with Bactrim alone"], 0, "Corticosteroids are added for moderate or severe PCP, helping to blunt the inflammatory response that can worsen respiratory status during treatment."),
          Q("treatment-prophylaxis", "After treatment for an episode of PCP, what long-term management is required?", ["Lifelong oral Bactrim prophylaxis, regardless of CD4 count", "No further prophylaxis is needed once symptoms resolve", "Prophylaxis only if CD4 remains below 200 at follow-up", "A one-time repeat course of IV Bactrim 6 months later"], 0, "After treating an episode of PCP, patients require lifelong oral Bactrim prophylaxis regardless of subsequent CD4 count, given the high risk of recurrence.")
        ]),
        D("tuberculosis-hiv", "Tuberculosis (in HIV)", "Can occur at any CD4 count; presentation shifts from typical apical-cavitary to atypical miliary as CD4 falls.", [
          S("presentation", "Epidemiology & Presentation", "<p><strong>The most common presenting OI in the developing world.</strong> About 2 billion people (~30% of the world's population) are infected with TB; 1 in 9 are co-infected with HIV. HIV and TB accelerate each other -- TB speeds HIV progression, and HIV increases the likelihood that exposed patients develop active disease.</p><p>Active TB can occur at CD4 counts well above 200 -- always consider it with pulmonary/systemic complaints. Presentation: productive cough, fevers, night sweats, weight loss, hemoptysis.</p>" + HY("The CXR pattern differs by immune status: early in the HIV course (higher CD4) -> typical reactivation pattern (apical cavitary disease). After CD4 has declined (more immunosuppressed) -> atypical MILIARY pattern (lower lung field disease, few/no cavitations, possible effusions), plus chest lymphadenopathy and extrapulmonary disease.")),
          S("diagnosis-treatment", "Diagnosis, Treatment & Screening", "<p>Active TB: AFB in sputum, confirmed by culture (or lymph node biopsy, thoracentesis, bronchoscopy). Latent TB: <strong>PPD or QuantiFERON-TB (IGRA) only</strong> -- PPD &ge;5mm induration is POSITIVE in HIV (a lower threshold than the general population). QuantiFERON is preferred if there's a history of prior treated TB, prior positive PPD, or BCG vaccination.</p><p>Treatment: standard TB regimens, watching for drug-drug interactions with ART; duration of TB treatment is likely LONGER in HIV; ART must be started if the patient isn't already on it.</p>" + HY("All newly diagnosed HIV patients are screened for latent TB (PPD or QuantiFERON) at diagnosis, with annual symptom screening thereafter. If CD4 <200 and PPD is negative, repeat once CD4 rises above 200. Additional risk factors (active IVDU, endemic-area travel, incarceration, homelessness) warrant annual PPD/QuantiFERON screening."))
        ], [
          Q("presentation", "TB is the most common presenting opportunistic infection in which setting?", ["The developing world", "The United States specifically", "Exclusively in children with HIV", "Only in patients on long-term ART"], 0, "Tuberculosis is the most common presenting opportunistic infection in the developing world, reflecting the enormous global burden of TB infection and its close interaction with HIV."),
          Q("presentation", "Can active TB occur in HIV patients with relatively preserved CD4 counts?", ["Yes -- active TB can occur at CD4 counts well above 200, and should always be considered with pulmonary/systemic complaints", "No -- active TB only occurs once CD4 falls below 200", "No -- active TB only occurs once CD4 falls below 50", "Active TB is exclusively a late-stage AIDS-defining illness with no earlier presentation"], 0, "Unlike many opportunistic infections that require significant immunosuppression, active TB can occur at CD4 counts well above 200, so it must remain on the differential even in earlier-stage HIV."),
          Q("presentation", "How does the chest x-ray pattern of TB change as an HIV patient's CD4 count declines?", ["It shifts from a typical apical-cavitary reactivation pattern to an atypical miliary pattern with fewer/no cavitations", "It remains identical regardless of CD4 count", "It shifts from miliary pattern early to apical-cavitary pattern late", "TB never shows cavitation in HIV patients at any CD4 level"], 0, "Early in the HIV course with higher CD4, TB shows the typical apical-cavitary reactivation pattern; as CD4 declines and immunosuppression worsens, the pattern becomes atypical -- miliary, lower lung field, with few or no cavitations, and more extrapulmonary disease."),
          Q("diagnosis-treatment", "How is latent TB diagnosed in an HIV patient?", ["PPD or QuantiFERON-TB (IGRA) only", "Sputum AFB smear and culture", "Chest CT alone", "Lymph node biopsy is required in all cases"], 0, "Latent TB (as opposed to active disease) is diagnosed using PPD or QuantiFERON-TB (IGRA) testing only -- there is no active organism to culture in latent infection."),
          Q("diagnosis-treatment", "What PPD induration threshold is considered positive for latent TB screening in HIV patients?", ["5mm or greater", "10mm or greater, same as the general population", "15mm or greater", "PPD cannot be used in HIV patients"], 0, "A PPD induration of 5mm or greater is considered positive in HIV patients, a lower threshold than used in the general population given their potentially blunted immune response."),
          Q("diagnosis-treatment", "In which patients is QuantiFERON-TB preferred over PPD for latent TB screening?", ["Those with a history of prior treated TB, prior positive PPD, or BCG vaccination", "All HIV patients regardless of history", "Only patients under age 18", "QuantiFERON is never preferred over PPD in any HIV patient"], 0, "QuantiFERON-TB (IGRA) is preferred over PPD in patients with a history of prior treated TB, a prior positive PPD, or a history of BCG vaccination, since BCG can cause false-positive PPD results."),
          Q("diagnosis-treatment", "How does TB treatment duration in HIV patients compare to HIV-negative patients?", ["TB treatment duration is likely longer in HIV patients", "TB treatment duration is shorter in HIV patients", "Treatment duration is identical regardless of HIV status", "TB treatment is not indicated in HIV-positive patients until ART is completed"], 0, "TB treatment duration is likely longer in HIV-positive patients, and clinicians must watch for drug-drug interactions between TB medications and ART."),
          Q("diagnosis-treatment", "If an HIV patient with CD4 <200 has a negative PPD, what should be done?", ["Repeat the PPD once the CD4 count rises above 200", "Conclude the patient definitively does not have latent TB and stop screening permanently", "No further testing is ever needed regardless of CD4 trend", "Switch immediately to empiric TB treatment despite the negative test"], 0, "A negative PPD in a patient with CD4 <200 may be a false negative due to impaired immune response -- the test should be repeated once the CD4 count rises above 200 to get a more reliable result.")
        ]),
        D("cryptosporidiosis", "Cryptosporidiosis (+ Isosporiasis)", "AIDS-defining protozoal causes of chronic diarrhea.", [
          S("overview", "Overview", "<p>Cryptosporidiosis and isosporiasis are AIDS-defining diagnoses (per the AIDS-defining diagnosis list: 'cryptosporidiosis or isosporiasis'). They are named as protozoal causes of chronic diarrhea in HIV patients, alongside Microsporidium.</p>" + HY("In the diagnostic approach to HIV-associated chronic diarrhea, stool is first examined for bacterial pathogens (culture/PCR, C. diff toxin/PCR); if that workup is negative, O&P testing for parasites (including Cryptosporidium/Isospora) follows; colonoscopy ± EGD with biopsy is reserved for cases that remain unexplained and persistent."))
        ], [
          Q("overview", "Cryptosporidiosis and isosporiasis are classified as what kind of AIDS-defining pathogens?", ["Protozoal causes of chronic diarrhea", "Bacterial causes of pneumonia", "Fungal causes of meningitis", "Viral causes of hepatitis"], 0, "Cryptosporidiosis and isosporiasis are protozoal organisms and are named among the AIDS-defining causes of chronic diarrhea in HIV patients."),
          Q("overview", "In the stepwise workup of chronic HIV-associated diarrhea, when is O&P testing (which would detect Cryptosporidium) performed?", ["After an initial bacterial stool workup (culture/PCR, C. diff testing) is negative", "As the very first test performed, before any bacterial workup", "Only after colonoscopy has already been performed and was unrevealing", "O&P testing is never indicated in the HIV diarrhea workup"], 0, "The stepwise HIV diarrhea workup starts with stool pathogen exam for bacterial causes; O&P testing for parasites (including Cryptosporidium and Isospora) is the next step if that initial workup is negative."),
          Q("overview", "Is cryptosporidiosis considered an AIDS-defining diagnosis?", ["Yes -- it appears explicitly on the AIDS-defining diagnosis list", "No -- it is only associated with mild, self-limited illness in HIV patients", "It is AIDS-defining only if accompanied by weight loss exceeding 20%", "Only disseminated cryptosporidiosis, not the intestinal form, is AIDS-defining"], 0, "Cryptosporidiosis (along with isosporiasis) is explicitly named on the AIDS-defining diagnosis list, regardless of CD4 count at diagnosis.")
        ]),
        D("cmv-disease", "CMV Disease", "AIDS-defining end-organ CMV -- retinitis, colitis/esophagitis, pneumonitis -- distinct from CMV mono in the immunocompetent.", [
          S("overview", "Overview", "<p>CMV disease (\"CMV retinitis or CMV disease\") is an AIDS-defining diagnosis. This is distinct from the general CMV mono-like illness seen in immunocompetent hosts -- in advanced HIV, CMV causes <strong>end-organ disease</strong>:</p>" + Tbl(["Organ", "Disease"], [
            ["Eye", "Retinitis -- vision-threatening"],
            ["GI tract", "Colitis/esophagitis -- contributes to HIV-associated diarrhea and dysphagia/GI symptoms"],
            ["Lungs", "Pneumonitis -- notably in children with HIV"]
          ]) + HY("CMV is also implicated as a cause of viral meningoencephalitis in HIV, alongside HSV and JC virus."))
        ], [
          Q("overview", "How does CMV disease in advanced HIV differ from the general CMV mono-like illness seen in immunocompetent hosts?", ["Advanced HIV causes end-organ disease (retinitis, colitis/esophagitis, pneumonitis) rather than a mono-like syndrome", "There is no meaningful difference between the two presentations", "CMV never causes end-organ disease in HIV patients", "CMV disease in HIV is limited exclusively to the respiratory tract"], 0, "In advanced HIV, CMV shifts from causing a mono-like illness to causing end-organ disease -- specifically retinitis, colitis/esophagitis, and pneumonitis -- which is why it's tracked as its own AIDS-defining entity."),
          Q("overview", "Which organ is affected by CMV disease in a way that is specifically vision-threatening?", ["The eye, via CMV retinitis", "The liver, via CMV hepatitis", "The kidney, via CMV nephritis", "The skin, via CMV dermatitis"], 0, "CMV retinitis is the vision-threatening ocular manifestation of CMV disease in advanced HIV, and is one of the two AIDS-defining CMV presentations named explicitly (the other being general 'CMV disease')."),
          Q("overview", "Besides HSV, what other virus is implicated alongside CMV as a cause of viral meningoencephalitis in HIV?", ["JC virus", "Coxsackievirus", "Parvovirus B19", "Epstein-Barr virus"], 0, "CMV, HSV, and JC virus are all implicated as causes of viral meningoencephalitis in advanced HIV, presenting with fever and altered mental status progressing to coma."),
          Q("overview", "How does CMV disease contribute to the HIV-associated diarrhea picture?", ["CMV colitis/esophagitis is one of the viral causes of chronic diarrhea in HIV", "CMV has no association with GI symptoms in HIV", "CMV causes diarrhea only through a drug interaction with ART", "CMV diarrhea occurs exclusively in HIV-negative transplant patients, not in HIV"], 0, "CMV colitis/esophagitis is specifically named as one of the viral causes in the differential for chronic diarrhea in HIV patients, alongside protozoal and bacterial causes.")
        ]),
        D("pml", "Progressive Multifocal Leukoencephalopathy (PML)", "JC virus demyelinating disease with non-enhancing white matter lesions; usually progressive and fatal.", [
          S("presentation-diagnosis", "Presentation & Diagnosis", "<p>An AIDS-defining diagnosis: a demyelinating disease caused by the <strong>JC virus</strong> -- deep white matter lesions that are <strong>NOT ring-enhancing or space-occupying</strong> (the key distinguishing imaging feature vs. toxoplasmosis or CNS lymphoma). JC virus infection is usually acquired asymptomatically in childhood, then remains latent until severe immunosuppression.</p><p>Presentation: progressive dementia, vision changes, seizure, hemiparesis.</p>" + HY("Diagnosis: stereotactic brain biopsy is the gold standard.")),
          S("prognosis", "Prognosis", HY("Without ART, only 10% survival at 1 year; with ART, 50% survival. PML is generally progressive and fatal -- remyelination does not occur, so any neurologic deficits that develop are permanent."))
        ], [
          Q("presentation-diagnosis", "What virus causes PML, and what is its typical acquisition pattern?", ["JC virus, usually acquired asymptomatically in childhood then remaining latent until severe immunosuppression", "EBV, acquired during adolescence via close contact", "CMV, acquired congenitally in nearly all cases", "HHV-8, acquired through sexual contact in adulthood"], 0, "PML is caused by the JC virus, which is typically acquired asymptomatically in childhood and then remains latent for decades until severe immunosuppression allows reactivation."),
          Q("presentation-diagnosis", "What key imaging feature distinguishes PML lesions from toxoplasmosis or CNS lymphoma?", ["PML lesions are NOT ring-enhancing or space-occupying, unlike the ring-enhancing lesions of toxoplasmosis/CNS lymphoma", "PML lesions are always larger than toxoplasmosis or lymphoma lesions", "PML lesions occur only in the cerebellum, never the cerebral white matter", "PML shows contrast enhancement identical to CNS lymphoma"], 0, "A key distinguishing imaging feature is that PML causes deep white matter lesions that are NOT ring-enhancing or space-occupying, in contrast to the multiple ring-enhancing lesions of toxoplasmosis or the highly ring-enhancing mass(es) of CNS lymphoma."),
          Q("presentation-diagnosis", "What is the gold standard diagnostic test for PML?", ["Stereotactic brain biopsy", "CSF VDRL", "Serum JC virus antibody alone", "A therapeutic trial of anti-toxoplasmosis therapy"], 0, "Stereotactic brain biopsy is the gold standard for diagnosing PML, though imaging findings and clinical context often guide management before biopsy is pursued."),
          Q("presentation-diagnosis", "What clinical findings are characteristic of PML?", ["Progressive dementia, vision changes, seizure, and hemiparesis", "Isolated peripheral neuropathy with no cognitive changes", "Acute meningismus with fever and photophobia", "Rapidly reversible confusion that resolves within 24 hours"], 0, "PML classically presents with progressive dementia, vision changes, seizure, and hemiparesis, reflecting its demyelinating effect on white matter tracts throughout the brain."),
          Q("prognosis", "How does ART affect 1-year survival in PML?", ["Survival improves from about 10% without ART to about 50% with ART", "ART has no effect on PML survival", "ART reduces survival compared to no treatment", "ART cures PML in the majority of treated patients"], 0, "ART substantially improves PML survival -- from about 10% at 1 year without ART to about 50% at 1 year with ART -- though the disease remains generally progressive and fatal even with treatment."),
          Q("prognosis", "Does neurologic function typically recover in PML survivors?", ["No -- remyelination does not occur, so neurologic deficits are permanent", "Yes -- full neurologic recovery is expected in most survivors", "Only motor deficits recover; cognitive deficits are always permanent", "Recovery is complete within 6 months in nearly all cases"], 0, "Remyelination does not occur in PML, so even in patients who survive, any neurologic deficits that developed during the active disease are permanent.")
        ]),
        D("cns-lymphoma", "Primary CNS Lymphoma", "EBV-associated AIDS-defining malignancy at CD4 <100, with ring-enhancing lesions on MRI.", [
          S("presentation", "Epidemiology & Presentation", "<p>An AIDS-defining malignancy, usually at <strong>CD4 &lt;100</strong>, strongly associated with <strong>EBV</strong> co-infection. Occurs at <strong>1000x the rate</strong> of the general population in HIV; more common with higher HIV viral load, lower CD4, and HCV/HBV co-infection.</p><p>Presentation: headache, altered mental status (60%), focal neuro findings, personality/behavioral change, seizures (15%); B symptoms in 80%.</p>"),
          S("imaging", "Imaging & Distinguishing Features", HY("MRI shows 2-6cm, highly ring-enhancing mass(es), usually solid, with edema/mass effect -- contrast with PML's non-enhancing lesions and toxoplasmosis's typically multiple ring-enhancing lesions. The key distinguishing clinical feature from toxoplasmosis is the RESPONSE TO EMPIRIC ANTI-TOXOPLASMOSIS THERAPY: toxoplasmosis improves, while CNS lymphoma does not."))
        ], [
          Q("presentation", "At what CD4 count does primary CNS lymphoma typically occur, and with what viral co-infection is it strongly associated?", ["CD4 <100, strongly associated with EBV", "CD4 <500, associated with HSV", "Any CD4 count, associated with CMV", "CD4 <200, associated with parvovirus B19"], 0, "Primary CNS lymphoma usually occurs at CD4 <100 and is strongly associated with EBV co-infection -- reflecting its status as one of the latest, most advanced-stage AIDS-defining malignancies."),
          Q("presentation", "How does the rate of CNS lymphoma in HIV patients compare to the general population?", ["It occurs at about 1000x the rate of the general population", "It occurs at roughly the same rate as the general population", "It occurs less frequently than in the general population", "It occurs at about 10x the rate of the general population"], 0, "Primary CNS lymphoma occurs at approximately 1000 times the rate seen in the general population among HIV patients, reflecting the profound immunosuppression and EBV association driving its development."),
          Q("presentation", "What proportion of primary CNS lymphoma patients present with B symptoms?", ["80%", "10%", "Nearly 0%", "50%"], 0, "About 80% of primary CNS lymphoma patients present with B symptoms, alongside neurologic findings like altered mental status (60%) and seizures (15%)."),
          Q("imaging", "What is the classic MRI appearance of primary CNS lymphoma?", ["2-6cm, highly ring-enhancing mass(es), usually solid, with edema/mass effect", "Non-enhancing deep white matter lesions with no mass effect", "Diffuse cerebral atrophy with no focal lesion", "Multiple small, punctate, non-enhancing lesions scattered throughout the cortex"], 0, "Primary CNS lymphoma classically shows one or more 2-6cm, highly ring-enhancing masses on MRI, usually solid, with surrounding edema and mass effect."),
          Q("imaging", "How does the MRI appearance of CNS lymphoma differ from PML?", ["CNS lymphoma is highly ring-enhancing, while PML lesions are NOT ring-enhancing or space-occupying", "Both conditions show identical, indistinguishable imaging", "CNS lymphoma shows no enhancement, while PML is ring-enhancing", "Only PML, not CNS lymphoma, ever shows mass effect"], 0, "CNS lymphoma produces highly ring-enhancing, space-occupying mass(es) with edema and mass effect, in direct contrast to PML's non-enhancing, non-space-occupying deep white matter lesions."),
          Q("imaging", "How is CNS lymphoma clinically distinguished from toxoplasmosis when imaging alone is ambiguous?", ["By response to empiric anti-toxoplasmosis therapy -- toxoplasmosis improves, CNS lymphoma does not", "CNS lymphoma is never distinguishable from toxoplasmosis by any means", "By CD4 count alone, since the two conditions occur at completely non-overlapping CD4 ranges", "By checking for fever, since only toxoplasmosis causes fever"], 0, "Since toxoplasmosis and CNS lymphoma can both show ring-enhancing lesions, the classic clinical distinguishing approach is empiric anti-toxoplasmosis therapy: improvement suggests toxoplasmosis, while lack of response raises suspicion for CNS lymphoma and prompts biopsy.")
        ]),
        D("hand", "HIV-Associated Neurocognitive Disorders (HAND)", "A staged spectrum (ANI to MND to HAD) of HIV-driven cognitive decline; a diagnosis of exclusion.", [
          S("staging", "Staging", "<p>HAND is a staged spectrum of cognitive impairment directly from HIV itself -- <strong>not an infection</strong>. It is a diagnosis of exclusion, requiring depression and other causes to be ruled out first.</p>" + Tbl(["Stage", "Criteria"], [
            ["Asymptomatic Neurocognitive Impairment (ANI)", "&ge;1 SD below mean in &ge;2 cognitive domains, NO symptoms/functional impairment"],
            ["Mild Neurocognitive Disorder (MND)", "&ge;1 SD below mean in &ge;2 domains, WITH symptoms/functional impairment"],
            ["HIV-Associated Dementia (HAD)", "&ge;2 SD below mean in &ge;2 domains, WITH impaired ADLs"]
          ])),
          S("workup-treatment", "Presentation, Workup & Treatment", "<p>Presentation: motor dysfunction, ataxia, poor concentration/memory, behavioral changes; more likely with baseline neurocognitive issues and older age.</p>" + HY("Workup: thorough H&P plus imaging to exclude other diagnoses, plus formal neurocognitive testing. MRI shows cortical atrophy; CSF shows high protein and HIV RNA. Treatment is primarily ART initiation."))
        ], [
          Q("staging", "Is HAND itself an infection?", ["No -- it is cognitive impairment directly from HIV itself, a diagnosis of exclusion", "Yes -- it is caused by a specific opportunistic pathogen", "Yes -- it is a form of CMV meningoencephalitis", "Yes -- it is caused by JC virus reactivation"], 0, "HAND is not an infection -- it represents cognitive impairment directly attributable to HIV itself, and diagnosis requires excluding depression and other causes first."),
          Q("staging", "What distinguishes Asymptomatic Neurocognitive Impairment (ANI) from Mild Neurocognitive Disorder (MND)?", ["ANI has no symptoms/functional impairment, while MND has the same cognitive deficit WITH symptoms/functional impairment", "ANI requires a 2 SD deficit, while MND requires only 1 SD", "MND is milder than ANI despite the name", "ANI and MND are identical, differing only in the number of domains affected"], 0, "Both ANI and MND require at least 1 SD below the mean in at least 2 cognitive domains -- the key difference is that ANI has NO symptoms or functional impairment, while MND has symptoms/functional impairment despite the same testing severity."),
          Q("staging", "What defines HIV-Associated Dementia (HAD), the most severe stage of HAND?", ["At least 2 SD below the mean in at least 2 cognitive domains, WITH impaired ADLs", "At least 1 SD below the mean in a single cognitive domain only", "Any cognitive complaint reported by the patient, regardless of testing", "A CD4 count below 50, regardless of cognitive testing results"], 0, "HAD, the most severe HAND stage, requires at least 2 SD below the mean in at least 2 cognitive domains, combined with impaired activities of daily living (ADLs)."),
          Q("workup-treatment", "What CSF finding is associated with HAND?", ["High protein and HIV RNA", "Low glucose with neutrophilic pleocytosis", "Xanthochromia", "A markedly elevated opening pressure with normal protein"], 0, "CSF in HAND classically shows elevated protein and detectable HIV RNA, reflecting ongoing CNS viral activity contributing to the cognitive decline."),
          Q("workup-treatment", "What imaging finding is typical in HAND, and why is imaging obtained?", ["Cortical atrophy; imaging is mainly done to exclude a mass lesion or other structural cause", "Multiple ring-enhancing lesions identical to toxoplasmosis", "Deep white matter lesions identical to PML", "Imaging is never indicated in the workup of HAND"], 0, "MRI in HAND typically shows cortical atrophy, and imaging is primarily obtained to exclude a mass lesion or other structural cause of the cognitive symptoms rather than to confirm HAND itself."),
          Q("workup-treatment", "What is the primary treatment for HAND?", ["ART initiation", "High-dose corticosteroids", "Stereotactic brain biopsy followed by chemotherapy", "Lifelong Bactrim prophylaxis"], 0, "ART initiation is the primary treatment for HAND, since controlling the underlying HIV infection is the main lever available to slow or improve HIV-driven cognitive decline.")
        ]),
        D("kaposi-sarcoma", "Kaposi's Sarcoma", "HHV-8-driven vascular tumor, the most common HIV-associated malignancy.", [
          S("overview", "Organism, Epidemiology & Presentation", "<p>An AIDS-defining malignancy: a vascular tumor caused by <strong>HHV-8 (human herpesvirus 8)</strong>. <strong>The most common tumor in HIV-infected persons.</strong> More frequent in MSM; uncommon in IDU/children/women; incidence has declined significantly with earlier ART.</p><p>Presentation: cutaneous lesions most often on the feet/lower legs, also face/mouth/genitalia -- papular, elliptical, usually linear along skin tension lines, symmetric, often painless/non-pruritic; pink/red/purple/brown depending on vascularity/skin tone; may have lymphedema. Visceral disease most commonly involves the GI tract and respiratory system.</p>" + HY("Treatment is primarily ART to suppress HIV replication -- this alone can prevent progression and new lesion formation."))
        ], [
          Q("overview", "What virus causes Kaposi's sarcoma?", ["HHV-8 (human herpesvirus 8)", "EBV", "HHV-6", "CMV"], 0, "Kaposi's sarcoma is a vascular tumor caused by HHV-8 (human herpesvirus 8), distinct from the other herpesviruses covered elsewhere in this course."),
          Q("overview", "Kaposi's sarcoma holds what distinction among HIV-associated malignancies?", ["It is the most common tumor in HIV-infected persons", "It is the rarest HIV-associated malignancy", "It occurs equally across all HIV risk groups with no demographic pattern", "It only occurs in patients already diagnosed with another AIDS-defining illness"], 0, "Kaposi's sarcoma is the most common tumor seen in HIV-infected persons, and is notably more frequent in MSM while being uncommon in IDU, children, and women."),
          Q("overview", "How has the incidence of Kaposi's sarcoma changed with modern HIV management?", ["It has declined significantly with earlier ART initiation", "It has increased steadily despite ART availability", "It has remained completely unchanged since the 1980s", "It only became recognized as an HIV-associated condition after 2010"], 0, "Kaposi's sarcoma incidence has declined significantly as ART has become available earlier in the course of HIV infection, reflecting better immune preservation."),
          Q("overview", "What is the characteristic appearance and distribution of Kaposi's sarcoma skin lesions?", ["Papular, elliptical, usually linear along skin tension lines, most often on the feet/lower legs, often painless/non-pruritic", "Vesicular lesions on an erythematous base, most often on the trunk", "A single painful ulcer with rolled borders on the genitals", "A diffuse, intensely pruritic maculopapular rash sparing the extremities"], 0, "Kaposi's sarcoma lesions are classically papular and elliptical, arranged along skin tension lines, most often on the feet/lower legs (though also face/mouth/genitalia), and are typically painless and non-pruritic."),
          Q("overview", "What is the primary treatment approach for Kaposi's sarcoma?", ["ART to suppress HIV replication, which can prevent progression and new lesions", "Surgical excision of every lesion, regardless of ART status", "Broad-spectrum antibiotics", "No treatment is available or indicated"], 0, "ART to suppress HIV replication is the primary treatment approach for Kaposi's sarcoma and can by itself prevent disease progression and the development of new lesions.")
        ]),
        D("hiv-nhl", "Non-Hodgkin's Lymphoma (HIV-associated)", "Aggressive, often EBV-related lymphoma occurring with advanced immunosuppression.", [
          S("presentation", "Epidemiology & Presentation", "<p>An AIDS-defining malignancy: about 50% are EBV-related. Occurs most commonly with high viral load plus low CD4 (advanced immunosuppression); more common in males; frequently involves the GI tract or CNS. <strong>70-90% are highly aggressive with a poor prognosis.</strong></p><p>Presentation: B symptoms (fevers, night sweats, unintentional weight loss &ge;10%), diffuse lymphadenopathy, organ-specific symptoms.</p>"),
          S("diagnosis-treatment", "Diagnosis & Treatment", HY("Diagnosis: prompt excisional lymph node biopsy plus usually bone marrow biopsy; staged with contrast CT ± PET/CT ± MRI if brain involvement is suspected. 80% present with STAGE IV disease.") + "<p>Treatment: standard chemotherapy or radiation, usually effective when combined with ART. About 50% achieve long-term survival; deaths split roughly 50/50 between lymphoma progression and HIV-related infection.</p>")
        ], [
          Q("presentation", "What proportion of HIV-associated non-Hodgkin's lymphoma is EBV-related?", ["About 50%", "About 5%", "Nearly 100%", "Essentially 0%"], 0, "Approximately half of HIV-associated non-Hodgkin's lymphoma cases are EBV-related, reflecting the same oncogenic latency mechanism discussed for EBV elsewhere in this course."),
          Q("presentation", "Under what immunologic conditions does HIV-associated NHL most commonly occur?", ["High viral load combined with low CD4 (advanced immunosuppression)", "Low viral load combined with high CD4 (well-controlled HIV)", "It occurs with equal frequency regardless of viral load or CD4", "Only in patients who have never started ART, regardless of CD4"], 0, "HIV-associated NHL occurs most commonly with high viral load and low CD4 -- i.e., advanced, poorly-controlled immunosuppression."),
          Q("presentation", "What proportion of HIV-associated NHL cases are described as highly aggressive with poor prognosis?", ["70-90%", "10-20%", "Less than 5%", "100%, with no exceptions"], 0, "70-90% of HIV-associated NHL cases are highly aggressive with a poor prognosis, reflecting the biology of lymphomas arising in the setting of advanced immunosuppression."),
          Q("diagnosis-treatment", "What is the recommended diagnostic approach for suspected HIV-associated NHL?", ["Prompt excisional lymph node biopsy plus usually bone marrow biopsy", "Fine-needle aspiration alone, without excisional biopsy", "Empiric chemotherapy without tissue diagnosis", "Serologic antibody testing alone"], 0, "Diagnosis requires prompt excisional lymph node biopsy, usually along with bone marrow biopsy, to properly characterize and stage the lymphoma."),
          Q("diagnosis-treatment", "What proportion of HIV-associated NHL patients present with stage IV disease?", ["80%", "20%", "Nearly 0%", "50%"], 0, "About 80% of HIV-associated NHL patients present with stage IV disease, reflecting both the aggressive biology and often delayed recognition of the malignancy."),
          Q("diagnosis-treatment", "What roughly splits the causes of death in HIV-associated NHL patients?", ["Lymphoma progression and HIV-related infection, split about 50/50", "Cardiovascular disease exclusively, unrelated to either lymphoma or HIV", "Treatment-related toxicity alone, with no deaths from the disease itself", "Suicide, accounting for the majority of deaths"], 0, "Deaths in HIV-associated NHL split roughly 50/50 between progression of the lymphoma itself and HIV-related infection, highlighting the importance of concurrent ART alongside cancer treatment.")
        ]),
        D("invasive-cervical-cancer", "Invasive Cervical Cancer (HIV-accelerated)", "HPV-driven cervical cancer that progresses faster and treats less predictably in HIV-positive women.", [
          S("overview", "Overview", "<p>An AIDS-defining malignancy: both CIN and invasive cervical cancer occur at much higher rates in HIV-infected women -- immunosuppression impairs HPV clearance, accelerating progression from CIN to cancer.</p>" + HY("Evaluation/treatment protocols are more aggressive in HIV-positive women at all levels of CIN/cancer. Treatment failure/recurrence is more likely with HIV. ART may cause CIN regression and lower recurrence/failure risk. HPV vaccine response is uncertain in HIV-positive women, but vaccination of the standard population (ages 9-45) is still recommended."))
        ], [
          Q("overview", "Why does cervical cancer progress faster in HIV-positive women?", ["Immunosuppression impairs HPV clearance, accelerating progression from CIN to invasive cancer", "HIV directly infects cervical epithelial cells, causing malignant transformation", "HPV vaccination is contraindicated in HIV-positive women, removing a protective layer", "HIV-positive women are simply screened less often, with no biological acceleration"], 0, "Immunosuppression from HIV impairs the body's ability to clear HPV infection, which accelerates the progression from cervical intraepithelial neoplasia (CIN) to invasive cervical cancer."),
          Q("overview", "How does treatment failure/recurrence risk for cervical cancer compare between HIV-positive and HIV-negative women?", ["Treatment failure/recurrence is more likely in HIV-positive women", "Treatment failure/recurrence is less likely in HIV-positive women", "There is no difference in treatment outcomes based on HIV status", "Recurrence only occurs in HIV-negative women"], 0, "HIV-positive women have a higher likelihood of cervical cancer treatment failure and recurrence compared to HIV-negative women, contributing to the more aggressive evaluation/treatment protocols used in this population."),
          Q("overview", "What effect can ART have on cervical intraepithelial neoplasia (CIN) in HIV-positive women?", ["ART may cause CIN regression and lower recurrence/failure risk", "ART has no effect on CIN whatsoever", "ART accelerates CIN progression to invasive cancer", "ART is contraindicated in women with any degree of CIN"], 0, "ART may cause regression of CIN and lower the risk of recurrence or treatment failure, reinforcing the importance of HIV control alongside gynecologic management."),
          Q("overview", "Is HPV vaccination recommended for HIV-positive women despite uncertain vaccine response?", ["Yes -- vaccination of the standard population (ages 9-45) is still recommended", "No -- HPV vaccination is contraindicated in HIV-positive women", "Only if CD4 is above 500 at the time of vaccination", "Only after a woman has already developed invasive cervical cancer"], 0, "Despite uncertain vaccine response in HIV-positive women, HPV vaccination of the standard population (ages 9-45) is still recommended given its overall benefit.")
        ]),
        D("hivan", "HIV-Associated Nephropathy (HIVAN)", "FSGS causing nephrotic-range proteinuria and rapid progression to ESRD, almost exclusively in Black men with HIV.", [
          S("presentation", "Epidemiology & Presentation", "<p>Occurs <strong>almost exclusively in African American males with HIV</strong>. Usually due to <strong>focal segmental glomerulosclerosis (FSGS)</strong> -- scarring of the glomerular capillary tuft, widening the GBM pores.</p>" + HY("Presentation: nephrotic-range proteinuria plus rapidly progressive renal failure, progressing to ESRD within MONTHS. Key distinguishing UA feature: heavy proteinuria WITHOUT significant hematuria.")),
          S("diagnosis-treatment", "Diagnosis & Treatment", "<p>Diagnosis: renal biopsy is required.</p><p>Treatment: ART; ACE-I/ARB if hypertensive; corticosteroids sometimes added for progressive disease.</p>" + HY("Prognosis remains poor despite aggressive treatment. AKI/CKD in HIV can also result from IVDA or ART nephrotoxicity, not just HIVAN -- a broader differential to keep in mind."))
        ], [
          Q("presentation", "Which patient population is almost exclusively affected by HIV-associated nephropathy (HIVAN)?", ["African American males with HIV", "Hispanic/Latino women with HIV", "Children with vertically-transmitted HIV", "White males over age 60 with HIV"], 0, "HIVAN occurs almost exclusively in African American males with HIV, a striking and highly specific demographic pattern worth remembering."),
          Q("presentation", "What is the underlying renal pathology in most cases of HIVAN?", ["Focal segmental glomerulosclerosis (FSGS)", "Minimal change disease", "Membranous nephropathy", "IgA nephropathy"], 0, "HIVAN is usually due to focal segmental glomerulosclerosis (FSGS) -- scarring of the glomerular capillary tuft that widens GBM pores, leading to heavy proteinuria."),
          Q("presentation", "How quickly can HIVAN progress to end-stage renal disease (ESRD)?", ["Within months", "Over 10-20 years, similar to typical diabetic nephropathy", "It rarely progresses to ESRD at all", "Progression takes decades and is rarely clinically significant"], 0, "HIVAN is notable for its rapid progression -- nephrotic-range proteinuria and rapidly progressive renal failure can lead to ESRD within just months."),
          Q("presentation", "What urinalysis finding helps distinguish HIVAN from many other causes of renal failure?", ["Heavy proteinuria WITHOUT significant hematuria", "Heavy hematuria without any proteinuria", "Both heavy proteinuria and heavy hematuria together", "A completely normal urinalysis despite renal failure"], 0, "A key distinguishing UA feature of HIVAN is heavy proteinuria WITHOUT significant hematuria, which helps differentiate it from glomerulonephritis processes that typically show both."),
          Q("diagnosis-treatment", "What test is required to definitively diagnose HIVAN?", ["Renal biopsy", "Urinalysis alone", "Serum creatinine trend alone, without biopsy", "HIV viral load measurement"], 0, "Renal biopsy is required to definitively diagnose HIVAN and confirm the underlying FSGS pattern."),
          Q("diagnosis-treatment", "What is the cornerstone of HIVAN treatment?", ["ART, plus ACE-I/ARB if hypertensive, with corticosteroids sometimes added for progressive disease", "Corticosteroids alone, with ART deferred until renal function stabilizes", "Immediate dialysis in all cases regardless of renal function trend", "Antibiotics targeting a presumed bacterial cause"], 0, "ART is the cornerstone of HIVAN treatment, with ACE-I/ARB added for hypertension and corticosteroids sometimes used for progressive disease -- though prognosis remains poor despite aggressive treatment.")
        ]),
        D("hiv-wasting-syndrome", "HIV Wasting Syndrome", "AIDS-defining unintentional weight loss (>10%) with diarrhea, fever, or weakness in advanced disease.", [
          S("overview", "Overview", "<p>An AIDS-defining diagnosis: unintentional weight loss <strong>&gt;10%</strong> with diarrhea or fever, plus weakness; occurs in advanced HIV.</p>" + HY("Most patients improve after starting ART."))
        ], [
          Q("overview", "What weight loss threshold, combined with other findings, defines HIV wasting syndrome?", [">10% unintentional weight loss, with diarrhea or fever, plus weakness", ">2% unintentional weight loss with no other required findings", "Any weight loss regardless of percentage, if voluntary", ">25% unintentional weight loss with no other criteria needed"], 0, "HIV wasting syndrome is defined by unintentional weight loss greater than 10%, combined with diarrhea or fever, plus weakness -- occurring in advanced HIV disease."),
          Q("overview", "What is the expected response of HIV wasting syndrome to ART?", ["Most patients improve after starting ART", "ART has no effect on wasting syndrome", "Wasting syndrome worsens after starting ART due to immune reconstitution", "ART only helps if started before any weight loss has occurred"], 0, "Most patients with HIV wasting syndrome improve once ART is started, reflecting the syndrome's close relationship with uncontrolled HIV replication and advanced immunosuppression.")
        ])
      ])
    ]
  };
}());
